# Hace "correr" el degradado del pincel neon: el patron de colores se repite y se desplaza
# sin parar, asi los colores fluyen alrededor de todos los bordes (una sola animacion mueve
# todos los bordes a la vez). -Detener la congela. Devuelve $false si no se pudo animar.
# Devuelve el pincel neon de un elemento en una version NO congelada (WPF congela los pinceles de los recursos y
# un pincel congelado no se puede animar); si esta congelado se clona y se reemplaza en el elemento.
function Global:Obtener-PincelNeon {
    param($Elemento, [string]$Clave = "NeonBrush")
    $p = $Elemento.FindResource($Clave)
    # Si ya se creo el pincel animable de este elemento, se reutiliza (para poder detener la misma animacion).
    if (-not $Global:NeonPorElemento) { $Global:NeonPorElemento = @{} }
    $claveReg = $Clave + "|" + [string][System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($Elemento)
    $previo = $Global:NeonPorElemento[$claveReg]
    if ($previo -and ([object]::ReferenceEquals($previo, $p.PSObject.BaseObject))) { return $previo }
    # Siempre se construye un pincel NUEVO (y su transformacion propia, guardada aparte) para tener la
    # certeza de que nada esta sellado/inmovilizado; la animacion se aplica a ESA transformacion directamente.
    if ($p -is [System.Windows.Media.LinearGradientBrush]) {
        $n = New-Object System.Windows.Media.LinearGradientBrush
        $n.MappingMode = $p.MappingMode
        $n.StartPoint = $p.StartPoint
        $n.EndPoint = $p.EndPoint
        $n.SpreadMethod = $p.SpreadMethod
        foreach ($gs in @($p.GradientStops)) {
            [void]$n.GradientStops.Add((New-Object System.Windows.Media.GradientStop($gs.Color, $gs.Offset)))
        }
        $tr = New-Object System.Windows.Media.TranslateTransform(0, 0)
        $n.RelativeTransform = $tr
        if (-not $Global:NeonTransformes) { $Global:NeonTransformes = @{} }
        $Global:NeonTransformes[[string][System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($n)] = $tr
        $Elemento.Resources[$Clave] = $n.PSObject.BaseObject
        $Global:NeonPorElemento[$claveReg] = $n.PSObject.BaseObject
        return $n
    }
    return $p
}

function Global:Animar-PincelNeon {
    param($Pincel, [switch]$Detener)
    if (-not $Pincel) { return $false }
    try {
        $mov = $null
        if ($Global:NeonTransformes) {
            $mov = $Global:NeonTransformes[[string][System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($Pincel.PSObject.BaseObject)]
        }
        if (-not $mov) { $mov = $Pincel.RelativeTransform }
        if ($Detener) {
            $mov.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $null)
            $mov.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $null)
            return $true
        }
        foreach ($propiedad in @([System.Windows.Media.TranslateTransform]::XProperty, [System.Windows.Media.TranslateTransform]::YProperty)) {
            $flujo = New-Object System.Windows.Media.Animation.DoubleAnimation
            $flujo.From = 0
            $flujo.To = 0.5
            $flujo.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(2500))
            $flujo.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
            $mov.BeginAnimation($propiedad, $flujo)
        }
        return $true
    } catch {
        $Global:ErrorPincelNeon = "$($_.Exception.GetType().Name): $($_.Exception.Message)"
        return $false
    }
}

# Animaciones de entrada reutilizables ---------------------------------------------------

# Hace aparecer una lista de elementos uno tras otro (fundido + deslizamiento), con un pequeño retraso entre cada uno.
function Global:Animar-EntradaElementos {
    param($Elementos, [double]$DesdeX = 0, [double]$DesdeY = 0, [int]$PasoMs = 40, [int]$DuracionMs = 340)
    $i = 0
    $suave = New-Object System.Windows.Media.Animation.CubicEase
    $suave.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
    foreach ($el in @($Elementos)) {
        if (-not ($el -is [System.Windows.UIElement])) { continue }
        try {
            $espera = [TimeSpan]::FromMilliseconds($i * $PasoMs)
            if ($DesdeX -ne 0 -or $DesdeY -ne 0) {
                $mov = $el.RenderTransform -as [System.Windows.Media.TranslateTransform]
                if (-not $mov -and ($el.RenderTransform -eq $null -or $el.RenderTransform -eq [System.Windows.Media.Transform]::Identity)) {
                    $mov = New-Object System.Windows.Media.TranslateTransform
                    $el.RenderTransform = $mov
                }
                if ($mov) {
                    if ($DesdeX -ne 0) {
                        $ax = New-Object System.Windows.Media.Animation.DoubleAnimation
                        $ax.From = $DesdeX; $ax.To = 0
                        $ax.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds($DuracionMs))
                        $ax.BeginTime = $espera; $ax.EasingFunction = $suave
                        $ax.FillBehavior = [System.Windows.Media.Animation.FillBehavior]::Stop
                        $mov.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $ax)
                    }
                    if ($DesdeY -ne 0) {
                        $ay = New-Object System.Windows.Media.Animation.DoubleAnimation
                        $ay.From = $DesdeY; $ay.To = 0
                        $ay.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds($DuracionMs))
                        $ay.BeginTime = $espera; $ay.EasingFunction = $suave
                        $ay.FillBehavior = [System.Windows.Media.Animation.FillBehavior]::Stop
                        $mov.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $ay)
                    }
                }
            }
            $el.Opacity = 0
            $ao = New-Object System.Windows.Media.Animation.DoubleAnimation
            $ao.From = 0; $ao.To = 1
            $ao.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds($DuracionMs))
            $ao.BeginTime = $espera
            $el.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $ao)
        } catch { }
        $i++
    }
}

# Al mostrarse un panel (cambio de seccion): el panel se desvanece hacia arriba y sus hijos entran en cascada.
function Global:Animar-EntradaPanel {
    param($Panel)
    if (-not $Panel) { return }
    try {
        $mov = $Panel.RenderTransform -as [System.Windows.Media.TranslateTransform]
        if (-not $mov) { $mov = New-Object System.Windows.Media.TranslateTransform; $Panel.RenderTransform = $mov }
        $suave = New-Object System.Windows.Media.Animation.CubicEase
        $suave.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
        $ay = New-Object System.Windows.Media.Animation.DoubleAnimation
        $ay.From = 22; $ay.To = 0
        $ay.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(380))
        $ay.EasingFunction = $suave
        $ay.FillBehavior = [System.Windows.Media.Animation.FillBehavior]::Stop
        $mov.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $ay)
        $ao = New-Object System.Windows.Media.Animation.DoubleAnimation
        $ao.From = 0; $ao.To = 1
        $ao.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(320))
        $ao.FillBehavior = [System.Windows.Media.Animation.FillBehavior]::Stop
        $Panel.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $ao)
        if ($Panel -is [System.Windows.Controls.Panel] -and $Panel.Children.Count -gt 1 -and $Panel.Children.Count -le 14) {
            Animar-EntradaElementos -Elementos $Panel.Children -DesdeY 18 -PasoMs 45 -DuracionMs 360
        }
    } catch { }
}

# Engancha la animacion de entrada a todos los paneles de seccion (los llamados Panel*) de una ventana.
function Global:Registrar-AnimacionesPaneles {
    param($Raiz)
    if (-not $Raiz) { return }
    $pila = New-Object 'System.Collections.Generic.Stack[object]'
    $pila.Push($Raiz)
    $enganchados = 0
    while ($pila.Count -gt 0) {
        $nodo = $pila.Pop()
        if ($nodo -is [System.Windows.Controls.Panel] -and $nodo.Name -and $nodo.Name -match '^Panel' -and $nodo.Name -notmatch 'Teclado|Checklist|Lateral') {
            $nodo.Add_IsVisibleChanged({
                param($remitente, $evento)
                if ($evento.NewValue -eq $true) { Animar-EntradaPanel -Panel $remitente }
            })
            $enganchados++
        }
        if ($nodo -is [System.Windows.DependencyObject]) {
            foreach ($hijo in [System.Windows.LogicalTreeHelper]::GetChildren($nodo)) {
                if ($hijo -is [System.Windows.DependencyObject]) { $pila.Push($hijo) }
            }
        }
    }
    return $enganchados
}

# Cambio de pestaña: el contenido sube suavemente y el titulo de la seccion entra desde la izquierda.
function Global:Animar-CambioPestana {
    try {
        $tc = $window.FindName("TabControlPrincipal")
        $titulo = $window.FindName("TxtSeccionActual")
        if ($tc) { Animar-EntradaPanel -Panel $tc }
        if ($titulo) { Animar-EntradaElementos -Elementos @($titulo) -DesdeX -26 -PasoMs 0 -DuracionMs 360 }
    } catch { }
}

# Latido suave continuo (por ejemplo el logo).
function Global:Animar-Respiracion {
    param($Elemento, [double]$Escala = 1.07, [double]$Segundos = 2.2)
    if (-not $Elemento) { return }
    try {
        $esc = New-Object System.Windows.Media.ScaleTransform(1, 1)
        $Elemento.RenderTransformOrigin = [System.Windows.Point]::new(0.5, 0.5)
        $Elemento.RenderTransform = $esc
        $suave = New-Object System.Windows.Media.Animation.SineEase
        $suave.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
        foreach ($eje in @([System.Windows.Media.ScaleTransform]::ScaleXProperty, [System.Windows.Media.ScaleTransform]::ScaleYProperty)) {
            $latido = New-Object System.Windows.Media.Animation.DoubleAnimation
            $latido.From = 1; $latido.To = $Escala
            $latido.Duration = [System.Windows.Duration]::new([TimeSpan]::FromSeconds($Segundos))
            $latido.AutoReverse = $true
            $latido.EasingFunction = $suave
            $latido.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
            $esc.BeginAnimation($eje, $latido)
        }
    } catch { }
}

# Envuelve una ventana (todavia no mostrada) en un marco neon animado y translucido:
# borde de color que gira, halo suave, "aurora" de luces que se mueven detras del contenido
# y una barra de titulo propia (con minimizar/maximizar/cerrar en la ventana principal).
# Todo va dentro de try/catch con marcha atras: si algo falla, la ventana queda como estaba.
function Global:Aplicar-MarcoNeon {
    param($Ventana, [switch]$Principal)
    if (-not $Ventana) { return }
    if ($Ventana.IsVisible -or $Ventana.IsLoaded) { return }
    if (-not $Ventana.Resources.Contains("NeonBrush")) { return }
    $contenidoOriginal = $Ventana.Content
    if (-not $contenidoOriginal) { return }
    $estiloOriginal = $Ventana.WindowStyle
    try {
        $permiteRedim = ($Ventana.ResizeMode -eq [System.Windows.ResizeMode]::CanResize -or $Ventana.ResizeMode -eq [System.Windows.ResizeMode]::CanResizeWithGrip)
        $botonesPrincipal = if ($Principal) { "Visible" } else { "Collapsed" }
        $textoTitulo = [System.Security.SecurityElement]::Escape([string]$Ventana.Title)
        $xamlMarco = @"
<Grid xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
      xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Background="#01000000">
  <Grid.Resources>
    <Style x:Key="BotonBarraNeon" TargetType="Button">
      <Setter Property="Width" Value="38"/>
      <Setter Property="Height" Value="28"/>
      <Setter Property="Margin" Value="3,0,0,0"/>
      <Setter Property="Foreground" Value="#CFE3FF"/>
      <Setter Property="FontSize" Value="13"/>
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="Button">
            <Border x:Name="Fondo" CornerRadius="9" Background="#22FFFFFF" BorderBrush="#4400E5FF" BorderThickness="1">
              <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
            </Border>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Setter TargetName="Fondo" Property="Background" Value="#6600B7FF"/>
                <Setter TargetName="Fondo" Property="BorderBrush" Value="#FF00E5FF"/>
              </Trigger>
              <Trigger Property="IsPressed" Value="True">
                <Setter TargetName="Fondo" Property="Background" Value="#AA00E5FF"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
    <Style x:Key="BotonCerrarNeon" TargetType="Button" BasedOn="{StaticResource BotonBarraNeon}">
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="Button">
            <Border x:Name="Fondo" CornerRadius="9" Background="#22FFFFFF" BorderBrush="#44FFFFFF" BorderThickness="1">
              <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
            </Border>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Setter TargetName="Fondo" Property="Background" Value="#CCFF2B5E"/>
                <Setter TargetName="Fondo" Property="BorderBrush" Value="#FFFF6A8A"/>
              </Trigger>
              <Trigger Property="IsPressed" Value="True">
                <Setter TargetName="Fondo" Property="Background" Value="#FFFF1744"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
  </Grid.Resources>
  <Border x:Name="MnHalo3" Margin="1" CornerRadius="24" BorderThickness="3" BorderBrush="#1200B7FF" IsHitTestVisible="False"/>
  <Border x:Name="MnHalo2" Margin="4" CornerRadius="21" BorderThickness="3" BorderBrush="#2200B7FF" IsHitTestVisible="False"/>
  <Border x:Name="MnHalo1" Margin="7" CornerRadius="19" BorderThickness="3" BorderBrush="#3A9CD0FF" IsHitTestVisible="False"/>
  <Border x:Name="MnMarco" Margin="10" CornerRadius="18" BorderThickness="2.5">
    <Border.Background>
      <LinearGradientBrush StartPoint="0,0" EndPoint="1,1">
        <GradientStop Color="#EA080C16" Offset="0"/>
        <GradientStop Color="#E80D1224" Offset="0.55"/>
        <GradientStop Color="#EA120A24" Offset="1"/>
      </LinearGradientBrush>
    </Border.Background>
    <Grid x:Name="MnInterior">
      <Grid x:Name="MnAurora" ClipToBounds="True" IsHitTestVisible="False">
        <Ellipse x:Name="MnLuzA" Width="460" Height="460" HorizontalAlignment="Left" VerticalAlignment="Top" Margin="-120,-140,0,0">
          <Ellipse.Fill>
            <RadialGradientBrush>
              <GradientStop Color="#3300E5FF" Offset="0"/>
              <GradientStop Color="#0000E5FF" Offset="1"/>
            </RadialGradientBrush>
          </Ellipse.Fill>
          <Ellipse.RenderTransform><TranslateTransform x:Name="MnMoverA"/></Ellipse.RenderTransform>
        </Ellipse>
        <Ellipse x:Name="MnLuzB" Width="520" Height="520" HorizontalAlignment="Right" VerticalAlignment="Bottom" Margin="0,0,-160,-180">
          <Ellipse.Fill>
            <RadialGradientBrush>
              <GradientStop Color="#33DDEEFF" Offset="0"/>
              <GradientStop Color="#00DDEEFF" Offset="1"/>
            </RadialGradientBrush>
          </Ellipse.Fill>
          <Ellipse.RenderTransform><TranslateTransform x:Name="MnMoverB"/></Ellipse.RenderTransform>
        </Ellipse>
        <Ellipse x:Name="MnLuzC" Width="340" Height="340" HorizontalAlignment="Center" VerticalAlignment="Center">
          <Ellipse.Fill>
            <RadialGradientBrush>
              <GradientStop Color="#222F7CF6" Offset="0"/>
              <GradientStop Color="#002F7CF6" Offset="1"/>
            </RadialGradientBrush>
          </Ellipse.Fill>
          <Ellipse.RenderTransform><TranslateTransform x:Name="MnMoverC"/></Ellipse.RenderTransform>
        </Ellipse>
      </Grid>
      <Grid>
        <Grid.RowDefinitions>
          <RowDefinition Height="40"/>
          <RowDefinition Height="*"/>
        </Grid.RowDefinitions>
        <Border Grid.Row="0" Margin="10,0,10,0" BorderThickness="0,0,0,1" BorderBrush="#2200E5FF">
          <Grid ClipToBounds="True">
            <Grid.ColumnDefinitions>
              <ColumnDefinition Width="*"/>
              <ColumnDefinition Width="Auto"/>
            </Grid.ColumnDefinitions>
            <Rectangle Grid.ColumnSpan="2" Height="2" Width="220" HorizontalAlignment="Left" VerticalAlignment="Bottom" IsHitTestVisible="False">
              <Rectangle.Fill>
                <LinearGradientBrush StartPoint="0,0" EndPoint="1,0">
                  <GradientStop Color="#00FFFFFF" Offset="0"/>
                  <GradientStop Color="#FFFFFFFF" Offset="0.5"/>
                  <GradientStop Color="#00FFFFFF" Offset="1"/>
                </LinearGradientBrush>
              </Rectangle.Fill>
              <Rectangle.RenderTransform><TranslateTransform x:Name="MnMoverBrillo" X="-240"/></Rectangle.RenderTransform>
            </Rectangle>
            <StackPanel Orientation="Horizontal" VerticalAlignment="Center" Margin="4,0,0,0">
              <Ellipse x:Name="MnPunto" Width="9" Height="9" Margin="0,0,9,0" Fill="#FF00E5FF" Opacity="0.9"/>
              <TextBlock x:Name="MnTitulo" Text="$textoTitulo" FontSize="13" FontWeight="Bold" VerticalAlignment="Center"/>
            </StackPanel>
            <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center">
              <Button x:Name="MnBtnEfectos" Style="{StaticResource BotonBarraNeon}" Content="✨" ToolTip="Efectos animados: activar / desactivar (modo rendimiento)" Visibility="$botonesPrincipal"/>
              <Button x:Name="MnBtnMin" Style="{StaticResource BotonBarraNeon}" Content="&#x2014;" ToolTip="Minimizar" Visibility="$botonesPrincipal"/>
              <Button x:Name="MnBtnMax" Style="{StaticResource BotonBarraNeon}" Content="&#x25A1;" ToolTip="Maximizar / restaurar" Visibility="$botonesPrincipal"/>
              <Button x:Name="MnBtnCerrar" Style="{StaticResource BotonCerrarNeon}" Content="&#x2715;" ToolTip="Cerrar"/>
            </StackPanel>
          </Grid>
        </Border>
        <Border x:Name="MnZonaCliente" Grid.Row="1" Margin="0,0,0,2" CornerRadius="0,0,16,16"/>
      </Grid>
    </Grid>
  </Border>
</Grid>
"@
        $marco = [Windows.Markup.XamlReader]::Parse($xamlMarco)
        $borde       = $marco.FindName("MnMarco")
        $zona        = $marco.FindName("MnZonaCliente")
        $titulo      = $marco.FindName("MnTitulo")
        $btnCerrar   = $marco.FindName("MnBtnCerrar")
        $btnMin      = $marco.FindName("MnBtnMin")
        $btnMax      = $marco.FindName("MnBtnMax")
        $btnEfectos  = $marco.FindName("MnBtnEfectos")
        $halo1 = $marco.FindName("MnHalo1"); $halo2 = $marco.FindName("MnHalo2"); $halo3 = $marco.FindName("MnHalo3")
        $aurora = $marco.FindName("MnAurora")
        $punto  = $marco.FindName("MnPunto")
        $mA = $marco.FindName("MnMoverA"); $mB = $marco.FindName("MnMoverB"); $mC = $marco.FindName("MnMoverC")
        $mBrillo = $marco.FindName("MnMoverBrillo")
        if (-not ($borde -and $zona -and $titulo -and $btnCerrar -and $aurora -and $mA -and $mB -and $mC)) { throw "Faltan elementos del marco" }

        # El borde y el titulo usan el pincel neon compartido (su giro lo anima Iniciar-EfectosNeon)
        $borde.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, "NeonBrush")
        $titulo.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, "NeonBrush")

        # Particulas: puntitos de luz que suben lentamente por detras del contenido
        $particulas = @()
        try {
            $lienzo = New-Object System.Windows.Controls.Canvas
            $lienzo.IsHitTestVisible = $false
            $conversor = New-Object System.Windows.Media.BrushConverter
            $coloresPunto = @('#FFFFFFFF', '#FF9CD0FF', '#FFBFE3FF', '#FF4FA8FF')
            for ($k = 0; $k -lt 18; $k++) {
                $tamPunto = Get-Random -Minimum 2 -Maximum 6
                $elipse = New-Object System.Windows.Shapes.Ellipse
                $elipse.Width = $tamPunto
                $elipse.Height = $tamPunto
                $elipse.Fill = $conversor.ConvertFromString($coloresPunto[$k % 4])
                $elipse.Opacity = 0
                $elipse.IsHitTestVisible = $false
                $mueve = New-Object System.Windows.Media.TranslateTransform
                $elipse.RenderTransform = $mueve
                [System.Windows.Controls.Canvas]::SetLeft($elipse, [double](Get-Random -Minimum 0 -Maximum 1100))
                [System.Windows.Controls.Canvas]::SetTop($elipse, [double](Get-Random -Minimum 250 -Maximum 900))
                [void]$lienzo.Children.Add($elipse)
                $particulas += ,@{ Tr = $mueve; El = $elipse; Dur = (Get-Random -Minimum 6 -Maximum 13); Alt = (Get-Random -Minimum 160 -Maximum 380) }
            }
            [void]$aurora.Children.Add($lienzo)
        } catch { $particulas = @() }

        # Aurora: tres luces suaves que flotan lentamente (animaciones independientes del hilo de la interfaz)
        $estadoFx = @{ Activo = $true }
        $arrancarAurora = {
            param($mover, $dx, $dy, $segX, $segY)
            $suave = New-Object System.Windows.Media.Animation.SineEase
            $suave.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
            $ax = New-Object System.Windows.Media.Animation.DoubleAnimation
            $ax.From = -$dx; $ax.To = $dx
            $ax.Duration = [System.Windows.Duration]::new([TimeSpan]::FromSeconds($segX))
            $ax.AutoReverse = $true
            $ax.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
            $ax.EasingFunction = $suave
            $ay = New-Object System.Windows.Media.Animation.DoubleAnimation
            $ay.From = -$dy; $ay.To = $dy
            $ay.Duration = [System.Windows.Duration]::new([TimeSpan]::FromSeconds($segY))
            $ay.AutoReverse = $true
            $ay.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
            $ay.EasingFunction = $suave
            $mover.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $ax)
            $mover.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $ay)
        }.GetNewClosure()
        $iniciarFx = {
            & $arrancarAurora $mA 170 90 7 9
            & $arrancarAurora $mB -190 -110 9 6
            & $arrancarAurora $mC 140 120 11 8
            if ($punto) {
                $latido = New-Object System.Windows.Media.Animation.DoubleAnimation
                $latido.From = 0.35; $latido.To = 1
                $latido.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(800))
                $latido.AutoReverse = $true
                $latido.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
                $punto.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $latido)
            }
            # Brillo que recorre la barra de titulo
            if ($mBrillo) {
                $barrido = New-Object System.Windows.Media.Animation.DoubleAnimation
                $barrido.From = -240; $barrido.To = 1500
                $barrido.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(3400))
                $barrido.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
                $mBrillo.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $barrido)
            }
            # Particulas que suben y se desvanecen
            foreach ($pt in $particulas) {
                $sube = New-Object System.Windows.Media.Animation.DoubleAnimation
                $sube.From = 0; $sube.To = -$pt.Alt
                $sube.Duration = [System.Windows.Duration]::new([TimeSpan]::FromSeconds($pt.Dur))
                $sube.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
                $pt.Tr.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $sube)
                $brilla = New-Object System.Windows.Media.Animation.DoubleAnimation
                $brilla.From = 0; $brilla.To = 0.85
                $brilla.Duration = [System.Windows.Duration]::new([TimeSpan]::FromSeconds($pt.Dur / 2.0))
                $brilla.AutoReverse = $true
                $brilla.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
                $pt.El.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $brilla)
            }
            # Respiracion del halo exterior
            foreach ($h in @($halo1, $halo2, $halo3)) {
                if ($h) {
                    $resp = New-Object System.Windows.Media.Animation.DoubleAnimation
                    $resp.From = 0.45; $resp.To = 1
                    $resp.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(1600))
                    $resp.AutoReverse = $true
                    $resp.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
                    $h.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $resp)
                }
            }
        }.GetNewClosure()
        $detenerFx = {
            foreach ($m in @($mA, $mB, $mC)) {
                $m.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $null)
                $m.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $null)
            }
            if ($punto) { $punto.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $null) }
            if ($mBrillo) { $mBrillo.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $null) }
            foreach ($pt in $particulas) {
                $pt.Tr.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $null)
                $pt.El.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $null)
                $pt.El.Opacity = 0
            }
            foreach ($h in @($halo1, $halo2, $halo3)) { if ($h) { $h.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $null) } }
        }.GetNewClosure()
        $tierBajo = $false
        try { $tierBajo = ((([int][System.Windows.Media.RenderCapability]::Tier) -shr 16) -eq 0) } catch { }
        if ($tierBajo) {
            $estadoFx.Activo = $false
            $aurora.Visibility = 'Collapsed'
        } else {
            & $iniciarFx
        }

        # Mover el contenido original dentro del marco (los nombres siguen resolviendose con FindName)
        $Ventana.Content = $null
        $zona.Child = $contenidoOriginal
        $Ventana.Content = $marco

        # Ventana sin marco de Windows, translucida, con redimensionado conservado via WindowChrome
        $ventanaWpf = $Ventana
        $Ventana.WindowStyle = [System.Windows.WindowStyle]::None
        $Ventana.AllowsTransparency = $true
        $Ventana.Background = [System.Windows.Media.Brushes]::Transparent
        $cromo = New-Object System.Windows.Shell.WindowChrome
        $cromo.CaptionHeight = 50
        $cromo.GlassFrameThickness = [System.Windows.Thickness]::new(0)
        $cromo.CornerRadius = [System.Windows.CornerRadius]::new(0)
        $cromo.UseAeroCaptionButtons = $false
        $grosor = if ($permiteRedim) { 7 } else { 0 }
        $cromo.ResizeBorderThickness = [System.Windows.Thickness]::new($grosor)
        [System.Windows.Shell.WindowChrome]::SetWindowChrome($Ventana, $cromo)
        foreach ($b in @($btnCerrar, $btnMin, $btnMax, $btnEfectos)) {
            if ($b) { [System.Windows.Shell.WindowChrome]::SetIsHitTestVisibleInChrome($b, $true) }
        }

        # El marco ocupa espacio extra: se agranda el tamaño de las ventanas de tamaño fijo
        if ($Ventana.SizeToContent -eq [System.Windows.SizeToContent]::Manual) {
            if (-not [double]::IsNaN($Ventana.Height)) { $Ventana.Height = $Ventana.Height + 64 }
            if (-not [double]::IsNaN($Ventana.Width))  { $Ventana.Width  = $Ventana.Width + 24 }
        }
        # Ninguna ventana debe ser mas grande que el area de trabajo de la pantalla
        try {
            $aw = [System.Windows.SystemParameters]::WorkArea
            $Ventana.MaxHeight = $aw.Height
            $Ventana.MaxWidth = $aw.Width
        } catch { }
        if ($Ventana.MinHeight -gt 0) { $Ventana.MinHeight = $Ventana.MinHeight + 64 }
        if ($Ventana.MinWidth -gt 0)  { $Ventana.MinWidth  = $Ventana.MinWidth + 24 }

        # Entrada animada: la ventana aparece con un fundido y un pequeño "rebote" de escala
        try {
            $escalaEntrada = New-Object System.Windows.Media.ScaleTransform(0.94, 0.94)
            $borde.RenderTransformOrigin = [System.Windows.Point]::new(0.5, 0.5)
            $borde.RenderTransform = $escalaEntrada
            $marco.Opacity = 0
            $Ventana.Add_Loaded({
                try {
                    $rebote = New-Object System.Windows.Media.Animation.BackEase
                    $rebote.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
                    $rebote.Amplitude = 0.45
                    foreach ($eje in @([System.Windows.Media.ScaleTransform]::ScaleXProperty, [System.Windows.Media.ScaleTransform]::ScaleYProperty)) {
                        $crece = New-Object System.Windows.Media.Animation.DoubleAnimation
                        $crece.From = 0.94; $crece.To = 1
                        $crece.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(520))
                        $crece.EasingFunction = $rebote
                        $escalaEntrada.BeginAnimation($eje, $crece)
                    }
                    $aparece = New-Object System.Windows.Media.Animation.DoubleAnimation
                    $aparece.From = 0; $aparece.To = 1
                    $aparece.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(380))
                    $marco.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $aparece)
                } catch { $marco.Opacity = 1 }
            }.GetNewClosure())
        } catch { $marco.Opacity = 1 }

        $btnCerrar.Add_Click({ try { $ventanaWpf.Close() } catch { } }.GetNewClosure())
        if ($btnMin) { $btnMin.Add_Click({ try { $ventanaWpf.WindowState = [System.Windows.WindowState]::Minimized } catch { } }.GetNewClosure()) }
        if ($btnMax) {
            $btnMax.Add_Click({
                try {
                    if ($ventanaWpf.WindowState -eq [System.Windows.WindowState]::Maximized) { $ventanaWpf.WindowState = [System.Windows.WindowState]::Normal }
                    else { $ventanaWpf.WindowState = [System.Windows.WindowState]::Maximized }
                } catch { }
            }.GetNewClosure())
        }
        if ($btnEfectos) {
            $btnEfectos.Add_Click({
                try {
                    $pincelNeon = Obtener-PincelNeon -Elemento $ventanaWpf
                    if ($estadoFx.Activo) {
                        $estadoFx.Activo = $false
                        & $detenerFx
                        $aurora.Visibility = 'Collapsed'
                        [void](Animar-PincelNeon -Pincel $pincelNeon -Detener)
                    } else {
                        $estadoFx.Activo = $true
                        $aurora.Visibility = 'Visible'
                        & $iniciarFx
                        [void](Animar-PincelNeon -Pincel $pincelNeon)
                    }
                } catch { }
            }.GetNewClosure())
        }

        # Maximizado: sin esquinas redondeadas ni halo (y compensando el borde invisible de Windows)
        $Ventana.Add_StateChanged({
            try {
                if ($ventanaWpf.WindowState -eq [System.Windows.WindowState]::Maximized) {
                    $m = [System.Windows.SystemParameters]::WindowResizeBorderThickness
                    $borde.Margin = [System.Windows.Thickness]::new($m.Left + 2, $m.Top + 2, $m.Right + 2, $m.Bottom + 2)
                    $borde.CornerRadius = [System.Windows.CornerRadius]::new(0)
                    foreach ($h in @($halo1, $halo2, $halo3)) { $h.Visibility = 'Collapsed' }
                    if ($btnMax) { $btnMax.Content = [string][char]0x2750 }
                } else {
                    $borde.Margin = [System.Windows.Thickness]::new(10)
                    $borde.CornerRadius = [System.Windows.CornerRadius]::new(18)
                    foreach ($h in @($halo1, $halo2, $halo3)) { $h.Visibility = 'Visible' }
                    if ($btnMax) { $btnMax.Content = [string][char]0x25A1 }
                }
            } catch { }
        }.GetNewClosure())
    } catch {
        # Marcha atras: la ventana vuelve a su aspecto normal
        try {
            $Ventana.Content = $null
            if ($zona) { $zona.Child = $null }
            $Ventana.Content = $contenidoOriginal
            $Ventana.AllowsTransparency = $false
            $Ventana.WindowStyle = $estiloOriginal
        } catch { }
    }
}

# Pone en marcha los efectos animados de una ventana recien creada: el giro del borde
# neon (un solo pincel compartido mueve todos los bordes a la vez) y, en cada barra de
# progreso, el brillo que la recorre y el pulso de su aura. Son animaciones
# "independientes" de WPF: siguen moviendose aunque el hilo de la interfaz este ocupado.
function Global:Iniciar-EfectosNeon {
    param($Ventana)
    if (-not $Ventana) { return }
    # Marco neon translucido alrededor de la ventana (se omite si ya esta visible o no usa el pincel neon)
    if (-not $Ventana.Tag -or $Ventana.Tag -isnot [string] -or $Ventana.Tag -ne 'SinMarco') { Aplicar-MarcoNeon -Ventana $Ventana }
    # Boton "Volver" estandar de todas las ventanas: simplemente cierra la ventana que lo contiene
    # (en los dialogos modales equivale a cancelar).
    try {
        $botonVolver = $Ventana.FindName("BtnVolverVentana")
        if ($botonVolver) {
            $botonVolver.Add_Click({
                param($remitente, $evento)
                try { [System.Windows.Window]::GetWindow($remitente).Close() } catch { }
            })
        }
    } catch { }
    try {
        if ($Ventana.Resources.Contains("NeonBrush")) {
            $pincel = Obtener-PincelNeon -Elemento $Ventana
            [void](Animar-PincelNeon -Pincel $pincel)
        }
    } catch { }
    try {
        $pila = New-Object 'System.Collections.Generic.Stack[object]'
        $pila.Push($Ventana)
        while ($pila.Count -gt 0) {
            $nodo = $pila.Pop()
            if ($nodo -is [System.Windows.Controls.ProgressBar]) {
                [void]$nodo.ApplyTemplate()
                $brillo = $nodo.Template.FindName("Brillo", $nodo)
                $aura = $nodo.Template.FindName("Aura", $nodo)
                if ($brillo) {
                    $ancho = if ($nodo.ActualWidth -gt 40) { $nodo.ActualWidth } else { 480 }
                    $barrido = New-Object System.Windows.Media.Animation.DoubleAnimation
                    $barrido.From = -100
                    $barrido.To = $ancho + 100
                    $barrido.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(1700))
                    $barrido.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
                    $brillo.RenderTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $barrido)
                }
                if ($aura) {
                    $pulso = New-Object System.Windows.Media.Animation.DoubleAnimation
                    $pulso.From = 0.15
                    $pulso.To = 0.65
                    $pulso.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(900))
                    $pulso.AutoReverse = $true
                    $pulso.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
                    $aura.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $pulso)
                }
            }
            if ($nodo -is [System.Windows.DependencyObject]) {
                foreach ($hijo in [System.Windows.LogicalTreeHelper]::GetChildren($nodo)) {
                    if ($hijo -is [System.Windows.DependencyObject]) { $pila.Push($hijo) }
                }
            }
        }
    } catch { }
}

# Ventana emergente con barra de progreso en tiempo real, usada por los
# perfiles de optimizacion, acelerar CPU, liberar RAM, etc.
function Format-Duracion {
    param([double]$Segundos)
    if ($Segundos -lt 0 -or [double]::IsNaN($Segundos) -or [double]::IsInfinity($Segundos)) { return "calculando..." }
    if ($Segundos -lt 60) { return "$([math]::Round($Segundos)) segundo(s)" }
    $minutos = [math]::Floor($Segundos / 60)
    $segRestantes = [math]::Round($Segundos % 60)
    if ($minutos -lt 60) { return "$minutos min $segRestantes seg" }
    $horas = [math]::Floor($minutos / 60)
    $minRestantes = $minutos % 60
    return "$horas h $minRestantes min"
}

function New-VentanaProgreso {
    param([string]$Titulo, [switch]$PermitirDetener)
    $visibilidadDetener = if ($PermitirDetener) { "Visible" } else { "Collapsed" }
    [xml]$xamlProg = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="$Titulo" Height="490" Width="540" WindowStartupLocation="CenterScreen"
        Background="#10141D" ResizeMode="NoResize" Topmost="True">
  <Window.Resources>$($Global:RecursosNeonXaml)</Window.Resources>
  <StackPanel Margin="20">
    <Button x:Name="BtnVolverVentana" Content="⬅  Volver" Width="110" Height="34" HorizontalAlignment="Left" Margin="0,0,0,10"/>
    <TextBlock Text="$Titulo" Foreground="White" FontSize="16" FontWeight="Bold" Margin="0,0,0,14"/>
    <TextBlock x:Name="TxtEstadoProgreso" Text="Iniciando..." Foreground="#66AEFF" TextWrapping="Wrap" Margin="0,0,0,10"/>
    <ProgressBar x:Name="BarraProgreso" Minimum="0" Maximum="100" Height="26" Margin="0,4,0,10"/>
    <TextBlock x:Name="TxtTiempoRestante" Text="Calculando tiempo restante..." Foreground="#7C93BD" FontSize="12" Margin="0,0,0,14"/>
    <TextBox x:Name="TxtLogProgreso" IsReadOnly="True" Height="160" TextWrapping="Wrap" AcceptsReturn="True"
             Background="#070A10" Foreground="#66AEFF" FontFamily="Consolas" FontSize="11" VerticalScrollBarVisibility="Auto"/>
    <Button x:Name="BtnDetenerProgreso" Content="⏹️ Detener" Height="38" Margin="0,12,0,0" HorizontalAlignment="Right" Width="140"
            Foreground="White" Visibility="$visibilidadDetener"/>
  </StackPanel>
</Window>
"@
    $readerProg = New-Object System.Xml.XmlNodeReader $xamlProg
    $winProg = [Windows.Markup.XamlReader]::Load($readerProg)
    $winProg.Tag = $false
    $winProg.Resources.Add("HoraInicio", (Get-Date))
    if ($PermitirDetener) {
        $winProg.FindName("BtnDetenerProgreso").Add_Click({
            $winProg.Tag = $true
            $winProg.FindName("TxtEstadoProgreso").Text = "Deteniendo... (terminando el paso actual)"
        }.GetNewClosure())
    }
    Iniciar-EfectosNeon -Ventana $winProg
    $winProg.Show()
    Wait-UI -Milisegundos 1
    return $winProg
}

function Global:Update-VentanaProgreso {
    param($Ventana, [int]$Porcentaje, [string]$Estado, [string]$LogLinea = $null)
    if (-not $Ventana) { return }
    $barra = $Ventana.FindName("BarraProgreso")
    $txtEstado = $Ventana.FindName("TxtEstadoProgreso")
    $txtLog = $Ventana.FindName("TxtLogProgreso")
    $txtTiempo = $Ventana.FindName("TxtTiempoRestante")
    $pctSeguro = [math]::Min(100, [math]::Max(0, $Porcentaje))
    if ($barra) {
        # El relleno avanza con una transicion suave (en vez de dar saltos) hasta el nuevo valor.
        $desde = [double]$barra.Value
        $delta = $pctSeguro - $desde
        if ([math]::Abs($delta) -gt 1.5) {
            $pasos = [math]::Min(14, [int][math]::Ceiling([math]::Abs($delta) / 3))
            for ($paso = 1; $paso -le $pasos; $paso++) {
                $t = $paso / $pasos
                $barra.Value = $desde + ($delta * (1 - [math]::Pow(1 - $t, 2)))
                Wait-UI -Milisegundos 12
            }
        }
        $barra.Value = $pctSeguro
    }
    if ($txtEstado -and $Estado) { $txtEstado.Text = $Estado }
    if ($LogLinea -and $txtLog) { $txtLog.AppendText("$LogLinea`r`n"); $txtLog.ScrollToEnd() }
    if ($LogLinea -and $Script:PasosPerfil) { $Script:PasosPerfil.Add($LogLinea) }

    if ($txtTiempo -and $Ventana.Resources.Contains("HoraInicio")) {
        $transcurrido = (Get-Date) - $Ventana.Resources["HoraInicio"]
        if ($pctSeguro -ge 100) {
            $txtTiempo.Text = "Completado en $(Format-Duracion $transcurrido.TotalSeconds)."
        } elseif ($pctSeguro -gt 3) {
            $totalEstimado = $transcurrido.TotalSeconds * (100.0 / $pctSeguro)
            $restante = [math]::Max(0, $totalEstimado - $transcurrido.TotalSeconds)
            $txtTiempo.Text = "Tiempo restante estimado: $(Format-Duracion $restante) (transcurrido: $(Format-Duracion $transcurrido.TotalSeconds))"
        } else {
            $txtTiempo.Text = "Calculando tiempo restante... (transcurrido: $(Format-Duracion $transcurrido.TotalSeconds))"
        }
    }
    Wait-UI -Milisegundos 1
}

function Close-VentanaProgreso {
    param($Ventana, [string]$MensajeFinal = "Completado.")
    if (-not $Ventana) { return }
    Update-VentanaProgreso -Ventana $Ventana -Porcentaje 100 -Estado $MensajeFinal
    Start-Sleep -Milliseconds 600
    try { $Ventana.Close() } catch { }
}

$Script:RegistroErrores = New-Object System.Collections.Generic.List[object]

# Clasifica el origen de un error segun el prefijo de la funcion que lo genero,
# para poder distinguir si vino de una prueba de diagnostico, una descarga,
# instalacion/desinstalacion de programas, el registro de Windows, etc.
function Global:Get-CategoriaOrigenError {
    param([string]$Origen)
    if ($Origen -match '^(Iniciar-Escaneo|Revisar-Escaneo|Procesar-ResultadosHardware|Iniciar-Monitoreo)') { return 'Hardware' }
    if ($Origen -match 'Camara') { return 'Camara' }
    if ($Origen -match '^(Show-Prueba|Accion-Probar|Accion-DiagnosticoCompleto|Accion-VerDetallesPantalla)') { return 'Prueba de diagnostico' }
    if ($Origen -match '^(Accion-DescargarISO|Get-EnlaceDescarga|Descargar-ArchivoConProgreso|Accion-DescargarInstalarControladorFaltante|Accion-InstalarControladorDesdeArchivo)') { return 'Descarga de archivos' }
    if ($Origen -match '^(Accion-Instalar|Accion-Desinstalar|Show-VentanaProgramasInstalados|Limpiar-RastrosPrograma)') { return 'Instalar/Desinstalar programas' }
    if ($Origen -match 'Registro') { return 'Registro de Windows' }
    if ($Origen -match 'Driver|Controlador') { return 'Controladores' }
    if ($Origen -match '^Perfil-|^Accion-Acelerar|^Accion-LiberarRAM') { return 'Perfiles de optimizacion' }
    return 'Programa general'
}

# ---------------------------------------------------------------------------
#  MONITOREO DE ERRORES (programa + hardware)
# ---------------------------------------------------------------------------

function Global:Get-SolucionSugeridaError {
    param([string]$Categoria, [string]$Mensaje, [string]$Origen)
    switch -Regex ($Mensaje) {
        '(?i)acceso denegado|access.*denied|administrador|requiere.*admin' { return 'Cierra el programa y vuelvelo a abrir como administrador (clic derecho > Ejecutar como administrador).' }
        '(?i)descarg|webexception|remoto|internet|conexion|timed out|tiempo de espera|dns|proxy' { return 'Revisa tu conexion a internet, el firewall/antivirus o el proxy e intenta de nuevo.' }
        '(?i)camara' { return 'Revisa Configuracion > Privacidad y seguridad > Camara, cierra otras apps que usen la camara y prueba otra resolucion en la ventana de camara.' }
        '(?i)winget' { return 'Actualiza "Instalador de aplicaciones" desde Microsoft Store para tener winget funcionando.' }
        '(?i)registro de windows|regedit|clave del registro' { return 'Crea un punto de restauracion antes de tocar el Registro y ejecuta el programa como administrador.' }
        '(?i)controlador|driver' { return 'Actualiza o reinstala el controlador desde la pestaña Controladores o desde el sitio del fabricante.' }
        '(?i)espacio|disk full|disco lleno' { return 'Libera espacio en disco (Liberar espacio / Limpiar temporales) y vuelve a intentarlo.' }
        '(?i)portapapeles' { return 'Otro programa esta usando el portapapeles. Intenta de nuevo en unos segundos.' }
    }
    switch ($Categoria) {
        'Hardware' { return 'Revisa el componente indicado (cables, temperaturas, controladores) y vuelve a ejecutar el escaneo de hardware.' }
        'Prueba de diagnostico' { return 'Repite la prueba; si vuelve a fallar, el componente podria estar defectuoso o sin controlador.' }
        'Programa (excepcion)' { return 'Se evito el cierre del programa. Si se repite, copia este registro y reportalo para corregirlo.' }
        default { return 'Repite la accion como administrador. Si persiste, exporta este registro para analizarlo.' }
    }
}

# Agrega una entrada al registro de errores (con deduplicacion de repeticiones recientes).
function Global:Add-RegistroError {
    param(
        [string]$Tipo = 'ERROR', [string]$Categoria = 'Programa general', [string]$Origen = 'Desconocido',
        [string]$Mensaje, [string]$Solucion = '', [string]$Detalle = '', $Momento = $null
    )
    try {
        $ahora = if ($Momento) { [datetime]$Momento } else { Get-Date }
        $total = $Script:RegistroErrores.Count
        if (-not $Momento) {
            for ($i = $total - 1; $i -ge [math]::Max(0, $total - 40); $i--) {
                $e = $Script:RegistroErrores[$i]
                if ($e.Mensaje -eq $Mensaje -and $e.Origen -eq $Origen -and ($ahora - $e.Momento).TotalSeconds -lt 90) {
                    $e.Veces = [int]$e.Veces + 1; $e.Momento = $ahora
                    $e.Hora = $ahora.ToString('HH:mm:ss')
                    return
                }
            }
        }
        $hora = if ($ahora.Date -eq (Get-Date).Date) { $ahora.ToString('HH:mm:ss') } else { $ahora.ToString('dd/MM HH:mm') }
        $Script:RegistroErrores.Add([PSCustomObject]@{
            Hora = $hora; Fecha = $ahora.ToString('yyyy-MM-dd HH:mm:ss'); Momento = $ahora
            Tipo = $Tipo; Categoria = $Categoria; Origen = $Origen; Mensaje = $Mensaje
            Solucion = $(if ($Solucion) { $Solucion } else { Get-SolucionSugeridaError -Categoria $Categoria -Mensaje $Mensaje -Origen $Origen })
            Detalle = $Detalle; Veces = 1
        }) | Out-Null
    } catch {}
}

# Bloque autonomo (se ejecuta en un hilo aparte para no congelar la ventana).
# Busca en el visor de sucesos errores de hardware y revisa el estado de discos, memoria, temperatura, bateria y dispositivos.
$Script:ScanHardwareSB = {
    param([datetime]$Desde, [bool]$IncluirEstado)
    $res = New-Object System.Collections.Generic.List[object]
    function Nuevo($Momento, $Tipo, $Origen, $Mensaje, $Solucion, $Clave) {
        $res.Add([PSCustomObject]@{ Momento = $Momento; Tipo = $Tipo; Origen = $Origen; Mensaje = $Mensaje; Solucion = $Solucion; Clave = $Clave })
    }
    $def = @(
        @{ P='Microsoft-Windows-WHEA-Logger'; Id=$null; C='CPU / memoria / PCIe (WHEA)'; S='El procesador o la placa detectaron un error de hardware. Quita overclock/XMP, revisa temperaturas y fuente de poder, y prueba la RAM (Diagnostico de memoria).' },
        @{ P='disk'; Id=@(7,11,15,51,52,153); C='Disco duro/SSD'; S='El disco reporto errores de lectura/escritura. Haz copia de seguridad, revisa SMART (CrystalDiskInfo), cambia el cable SATA y ejecuta chkdsk /f /r.' },
        @{ P='Ntfs'; Id=@(55,98,137,140); C='Sistema de archivos NTFS'; S='Hay errores en el sistema de archivos. Ejecuta chkdsk /f /r en la unidad afectada y revisa el estado del disco.' },
        @{ P='stornvme'; Id=$null; C='SSD NVMe'; S='El SSD NVMe reporto problemas. Actualiza el firmware y el driver NVMe, y revisa la temperatura y el estado SMART.' },
        @{ P='storahci'; Id=$null; C='Controlador SATA (AHCI)'; S='El controlador SATA reporto problemas. Revisa cables/puertos del disco y actualiza el driver de chipset/almacenamiento.' },
        @{ P='volmgr'; Id=$null; C='Administrador de volumenes'; S='Windows tuvo problemas con un volumen (volcado o disco). Revisa el disco y la configuracion del archivo de paginacion.' },
        @{ P='Microsoft-Windows-Kernel-Power'; Id=@(41); C='Apagado inesperado'; S='El equipo se reinicio sin apagarse correctamente: corte de energia, fuente de poder fallando, sobrecalentamiento o pantalla azul. Revisa temperaturas, fuente y la pestaña BSOD.' },
        @{ P='Display'; Id=@(4101); C='Controlador de video'; S='El driver de video dejo de responder y se recupero. Reinstala el driver de video, quita overclock y revisa la temperatura de la GPU.' },
        @{ P='nvlddmkm'; Id=$null; C='GPU NVIDIA'; S='El driver de NVIDIA reporto errores. Reinstala el driver de forma limpia y revisa temperaturas/alimentacion.' },
        @{ P='Microsoft-Windows-Kernel-PnP'; Id=@(219); C='Dispositivo / controlador'; S='Windows no pudo cargar un controlador. Actualiza o reinstala el driver del dispositivo indicado.' },
        @{ P='BTHUSB'; Id=$null; C='Bluetooth'; S='El adaptador Bluetooth reporto problemas. Actualiza su driver o prueba otro puerto USB.' }
    )
    foreach ($d in $def) {
        try {
            $f = @{ LogName = 'System'; ProviderName = $d.P; StartTime = $Desde; Level = @(1,2,3) }
            if ($d.Id) { $f.Id = $d.Id }
            $ev = Get-WinEvent -FilterHashtable $f -MaxEvents 20 -ErrorAction Stop
            foreach ($e in $ev) {
                $msg = (("$($e.Message)" -split "`r?`n")[0]).Trim()
                if ($msg.Length -gt 230) { $msg = $msg.Substring(0, 230) + '...' }
                $tipo = if ($e.Level -le 2) { 'ERROR' } else { 'AVISO' }
                Nuevo $e.TimeCreated $tipo ("$($d.C) (Id $($e.Id))") $msg $d.S ("ev|$($e.ProviderName)|$($e.RecordId)")
            }
        } catch {}
    }
    if ($IncluirEstado) {
        $ahora = Get-Date
        try {
            foreach ($pd in @(Get-PhysicalDisk -ErrorAction Stop)) {
                $nom = "$($pd.FriendlyName)"
                if ("$($pd.HealthStatus)" -ne 'Healthy') {
                    Nuevo $ahora 'ERROR' "Disco: $nom" "Estado de salud del disco: $($pd.HealthStatus) ($($pd.OperationalStatus))." 'Haz copia de seguridad YA. El disco puede estar fallando: revisa SMART y planea reemplazarlo.' "disco|$nom|$($pd.HealthStatus)"
                }
                try {
                    $rc = $pd | Get-StorageReliabilityCounter -ErrorAction Stop
                    if ($rc.Temperature -gt 60) { Nuevo $ahora 'AVISO' "Disco: $nom" "Temperatura alta del disco: $($rc.Temperature) C." 'Mejora la ventilacion; temperaturas altas acortan la vida del disco.' "discotemp|$nom|$([int]($rc.Temperature/5))" }
                    if ($rc.Wear -gt 85) { Nuevo $ahora 'AVISO' "Disco: $nom" "Desgaste del SSD: $($rc.Wear)% usado." 'El SSD esta cerca del fin de su vida util: haz copias de seguridad y planea cambiarlo.' "discowear|$nom|$($rc.Wear)" }
                    $errs = [int]$rc.ReadErrorsUncorrected + [int]$rc.WriteErrorsUncorrected
                    if ($errs -gt 0) { Nuevo $ahora 'ERROR' "Disco: $nom" "El disco acumula $errs error(es) de lectura/escritura sin corregir." 'Haz copia de seguridad y reemplaza el disco si los errores aumentan.' "discoerr|$nom|$errs" }
                } catch {}
            }
        } catch {}
        try {
            foreach ($ld in @(Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3' -ErrorAction Stop)) {
                if ($ld.Size -gt 0) {
                    $pct = [math]::Round(($ld.FreeSpace / $ld.Size) * 100, 1)
                    if ($pct -lt 10) {
                        $t = if ($pct -lt 5) { 'ERROR' } else { 'AVISO' }
                        Nuevo $ahora $t "Almacenamiento $($ld.DeviceID)" "Poco espacio libre en $($ld.DeviceID): $pct% ($([math]::Round($ld.FreeSpace/1GB,1)) GB)." 'Libera espacio: Limpiar temporales, desinstalar programas, mover archivos grandes.' "espacio|$($ld.DeviceID)|$([int]($pct/2))"
                    }
                }
            }
        } catch {}
        try {
            $os = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop
            $uso = [math]::Round((1 - ($os.FreePhysicalMemory / $os.TotalVisibleMemorySize)) * 100, 0)
            if ($uso -gt 92) { Nuevo $ahora 'AVISO' 'Memoria RAM' "Uso de RAM muy alto: $uso%." 'Cierra programas, usa Liberar RAM o considera ampliar la memoria.' "ram|alta|$([int]($uso/3))" }
        } catch {}
        try {
            foreach ($z in @(Get-CimInstance -Namespace root/wmi -ClassName MSAcpi_ThermalZoneTemperature -ErrorAction Stop)) {
                $c = [math]::Round(($z.CurrentTemperature / 10) - 273.15, 0)
                if ($c -ge 80 -and $c -lt 150) {
                    $t = if ($c -ge 90) { 'ERROR' } else { 'AVISO' }
                    Nuevo $ahora $t 'Temperatura del sistema' "Temperatura elevada: $c C." 'Limpia el polvo, revisa ventiladores y pasta termica, y evita bloquear las rejillas del equipo.' "temp|$([int]($c/5))"
                }
            }
        } catch {}
        try {
            $full = Get-CimInstance -Namespace root/wmi -ClassName BatteryFullChargedCapacity -ErrorAction Stop | Select-Object -First 1
            $dis = Get-CimInstance -Namespace root/wmi -ClassName BatteryStaticData -ErrorAction Stop | Select-Object -First 1
            if ($full -and $dis -and $dis.DesignedCapacity -gt 0) {
                $des = [math]::Round(100 - ($full.FullChargedCapacity / $dis.DesignedCapacity) * 100, 0)
                if ($des -gt 40) { Nuevo $ahora 'AVISO' 'Bateria' "La bateria perdio $des% de su capacidad original." 'La bateria esta desgastada; considera reemplazarla.' "bateria|$([int]($des/10))" }
            }
        } catch {}
        try {
            $nombresCodigo = @{ 10='no puede iniciar'; 28='sin controlador instalado'; 31='no funciona correctamente'; 39='controlador danado o ausente'; 41='Windows detecto el hardware pero no pudo cargarlo'; 43='Windows detuvo el dispositivo (reporto problemas)'; 52='controlador sin firma digital' }
            foreach ($pn in @(Get-CimInstance Win32_PnPEntity -ErrorAction Stop | Where-Object { $_.ConfigManagerErrorCode -gt 0 -and $_.ConfigManagerErrorCode -ne 22 })) {
                $cod = [int]$pn.ConfigManagerErrorCode
                $txt = if ($nombresCodigo.ContainsKey($cod)) { $nombresCodigo[$cod] } else { 'con problema' }
                Nuevo $ahora 'AVISO' "Dispositivo: $($pn.Name)" "El dispositivo '$($pn.Name)' esta $txt (codigo $cod)." 'Actualiza o reinstala el controlador (pestaña Controladores) o revisa el dispositivo en el Administrador de dispositivos.' "pnp|$($pn.DeviceID)|$cod"
            }
        } catch {}
    }
    $res
}

$Script:HwVistos = @{}
$Script:HwScan = $null
$Script:HwUltimoEscaneo = $null
$Script:HwTimerPoll = $null
$Script:HwTimerVivo = $null

function Global:Procesar-ResultadosHardware {
    param($Lista)
    $nuevos = 0
    foreach ($r in @($Lista)) {
        if (-not $r -or -not $r.Clave) { continue }
        if ($Script:HwVistos.ContainsKey("$($r.Clave)")) { continue }
        $Script:HwVistos["$($r.Clave)"] = $true
        $mom = try { [datetime]$r.Momento } catch { Get-Date }
        Add-RegistroError -Tipo "$($r.Tipo)" -Categoria 'Hardware' -Origen "$($r.Origen)" -Mensaje "$($r.Mensaje)" -Solucion "$($r.Solucion)" -Momento $mom
        $nuevos++
    }
    $Script:HwUltimoEscaneo = Get-Date
    return $nuevos
}

function Global:Revisar-EscaneoHardware {
    $s = $Script:HwScan
    if (-not $s) { if ($Script:HwTimerPoll) { $Script:HwTimerPoll.Stop() }; return }
    if (-not $s.H.IsCompleted) {
        if (((Get-Date) - $s.Inicio).TotalSeconds -gt 120) {
            try { $s.PS.Stop(); $s.PS.Dispose() } catch {}
            $Script:HwScan = $null; $Script:HwTimerPoll.Stop()
            Write-Log "El escaneo de hardware tardo demasiado y se cancelo." -Tipo AVISO
            try { Cargar-RegistroErrores } catch {}
        }
        return
    }
    $res = $null
    try { $res = $s.PS.EndInvoke($s.H) } catch { Write-Log "El escaneo de hardware fallo: $($_.Exception.Message)" -Tipo AVISO }
    finally { try { $s.PS.Dispose() } catch {}; $Script:HwScan = $null; $Script:HwTimerPoll.Stop() }
    $n = Procesar-ResultadosHardware -Lista $res
    if ($s.Manual) { Write-Log "Escaneo de hardware completado: $n hallazgo(s) nuevo(s)." -Tipo $(if ($n -gt 0) { 'AVISO' } else { 'OK' }) }
    try { Cargar-RegistroErrores } catch {}
    if ($s.Manual) {
        if ($n -eq 0) { Show-Aviso "No se encontraron problemas de hardware nuevos.`n`nSe revisaron eventos de las ultimas horas, el estado de los discos (SMART), espacio libre, memoria, temperatura, bateria y dispositivos con errores." "Escaneo de hardware" }
        else { Show-Aviso "Se encontraron $n hallazgo(s) de hardware. Revisa la lista (categoria Hardware) y selecciona cada uno para ver que hacer." "Escaneo de hardware" }
    }
}

function Global:Iniciar-EscaneoHardware {
    param([int]$Horas = 72, [bool]$Manual = $false, [bool]$IncluirEstado = $true)
    if ($Script:HwScan) { if ($Manual) { Show-Aviso "Ya hay un escaneo de hardware en curso. Espera a que termine." "Escaneo en curso" }; return }
    try {
        $ps = [powershell]::Create()
        $null = $ps.AddScript($Script:ScanHardwareSB.ToString()).AddArgument((Get-Date).AddHours(-$Horas)).AddArgument($IncluirEstado)
        $Script:HwScan = @{ PS = $ps; H = $ps.BeginInvoke(); Manual = $Manual; Inicio = (Get-Date) }
        if ($Manual) { Write-Log "Escaneando hardware (eventos de las ultimas $Horas h y estado de discos, RAM, temperatura, bateria y dispositivos)..." }
        if (-not $Script:HwTimerPoll) {
            $Script:HwTimerPoll = New-Object System.Windows.Threading.DispatcherTimer
            $Script:HwTimerPoll.Interval = [TimeSpan]::FromMilliseconds(400)
            $Script:HwTimerPoll.Add_Tick({ Revisar-EscaneoHardware })
        }
        $Script:HwTimerPoll.Start()
    } catch {
        $Script:HwScan = $null
        Write-Log "No se pudo iniciar el escaneo de hardware: $($_.Exception.Message)" -Tipo ERROR
    }
}

function Global:Write-Log {
    param(
        [string]$Mensaje,
        [ValidateSet('INFO','OK','AVISO','ERROR')] [string]$Tipo = 'INFO',
        [switch]$SinRegistro
    )
    $hora = (Get-Date).ToString('HH:mm:ss')

    # Se recuerdan los dos ultimos mensajes: si la interfaz se bloquea entre ellos, el monitor de lentitud sabe que estaba pasando
    if (-not $SinRegistro) {
        $Global:ActividadPrev = $Global:Actividad
        $txtAct = if ($Mensaje.Length -gt 90) { $Mensaje.Substring(0, 90) + '...' } else { $Mensaje }
        $Global:Actividad = @{ Texto = $txtAct; Hora = Get-Date }
    }

    if (($Tipo -eq 'ERROR' -or $Tipo -eq 'AVISO') -and -not $SinRegistro) {
        try {
            $callStack = Get-PSCallStack
            $origen = if ($callStack.Count -gt 1 -and $callStack[1].FunctionName) { $callStack[1].FunctionName } else { "Desconocido" }
            if ($origen -eq '<ScriptBlock>') { $origen = "Interfaz (evento de la ventana)" }
            Add-RegistroError -Tipo $Tipo -Categoria (Get-CategoriaOrigenError -Origen $origen) -Origen $origen -Mensaje $Mensaje
        } catch {}
    }

    if (-not $Script:LogBox) { return }
    $prefijo = switch ($Tipo) {
        'OK'    { '[OK]   ' }
        'AVISO' { '[AVISO]' }
        'ERROR' { '[ERROR]' }
        default { '[INFO] ' }
    }
    $linea = "$hora  $prefijo  $Mensaje`r`n"
    $Script:LogBox.AppendText($linea)
    $Script:LogBox.ScrollToEnd()
    Wait-UI -Milisegundos 1
}

# ---------------------------------------------------------------------------
#  MONITOR DE LENTITUD (programa y pruebas)
#  Un hilo aparte mide cada pocos segundos CPU, RAM, disco y los procesos que mas
#  consumen. Si la interfaz se congela, el arranque tarda demasiado o una prueba se
#  alarga, se registra el aviso indicando la causa mas probable y que lo provoco.
# ---------------------------------------------------------------------------
$Global:Mon = [hashtable]::Synchronized(@{
    Parar = $false; Ultimo = $null; ForzarProcesos = $false
    Hist = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList))
})
$Global:MonActivo = $false
$Global:MonPS = $null
$Global:MonRS = $null
$Global:MonTimer = $null
$Global:MonUltTick = [DateTime]::UtcNow
$Global:MonUltReporte = [DateTime]::MinValue
$Global:MonLagTotalMs = 0.0
$Global:MonLagCuenta = 0
$Global:MonLagOmitidos = 0
$Global:EventosLentitud = New-Object System.Collections.ArrayList
$Global:HistPruebas = New-Object System.Collections.ArrayList
$Global:Actividad = $null
$Global:ActividadPrev = $null

# Bloque que corre en el hilo muestreador (no toca la interfaz)
$Global:MonSamplerSB = {
    param($Sync, [int]$MiPid, [int]$Nucleos)
    try { [System.Threading.Thread]::CurrentThread.Priority = [System.Threading.ThreadPriority]::BelowNormal } catch {}
    if ($Nucleos -lt 1) { $Nucleos = 1 }
    while (-not $Sync.Parar) {
        $t0 = Get-Date
        $m = @{ Hora = $t0; Cpu = $null; RamPct = $null; RamLibreMB = $null; DiscoPct = $null; Cola = $null; Top = @(); TopRam = @() }
        try { $c = Get-CimInstance Win32_PerfFormattedData_PerfOS_Processor -Filter "Name='_Total'" -ErrorAction Stop; $m.Cpu = [double]$c.PercentProcessorTime } catch {}
        try {
            $o = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop
            $m.RamPct = [math]::Round((($o.TotalVisibleMemorySize - $o.FreePhysicalMemory) / $o.TotalVisibleMemorySize) * 100, 0)
            $m.RamLibreMB = [math]::Round($o.FreePhysicalMemory / 1024, 0)
        } catch {}
        try {
            $d = Get-CimInstance Win32_PerfFormattedData_PerfDisk_PhysicalDisk -Filter "Name='_Total'" -ErrorAction Stop
            $m.DiscoPct = [double]$d.PercentDiskTime; $m.Cola = [double]$d.CurrentDiskQueueLength
        } catch {}
        $carga = (($m.Cpu -ge 60) -or ($m.RamPct -ge 85) -or ($m.DiscoPct -ge 80) -or $Sync.ForzarProcesos)
        if ($carga) {
            try {
                $pr = @(Get-CimInstance Win32_PerfFormattedData_PerfProc_Process -Filter "PercentProcessorTime > 0" -ErrorAction Stop |
                    Where-Object { $_.Name -ne '_Total' -and $_.Name -ne 'Idle' } |
                    Sort-Object PercentProcessorTime -Descending | Select-Object -First 5)
                $m.Top = @($pr | ForEach-Object { @{ Nombre = ($_.Name -replace '#\d+$', ''); Pid = [int]$_.IDProcess; Cpu = [math]::Round([double]$_.PercentProcessorTime / $Nucleos, 0) } })
            } catch {}
            try {
                $m.TopRam = @(Get-Process -ErrorAction Stop | Sort-Object WorkingSet64 -Descending | Select-Object -First 4 |
                    ForEach-Object { @{ Nombre = $_.ProcessName; Pid = [int]$_.Id; MB = [math]::Round($_.WorkingSet64 / 1MB, 0) } })
            } catch {}
            $Sync.ForzarProcesos = $false
        }
        [void]$Sync.Hist.Add($m)
        while ($Sync.Hist.Count -gt 60) { $Sync.Hist.RemoveAt(0) }
        $Sync.Ultimo = $m
        $dur = ((Get-Date) - $t0).TotalMilliseconds
        Start-Sleep -Milliseconds ([int][Math]::Max(500, 2500 - $dur))
    }
}

function Global:Iniciar-MonitorLentitud {
    if ($Global:MonPS) { return }
    try {
        $rs = [runspacefactory]::CreateRunspace()
        $rs.ApartmentState = 'MTA'
        $rs.Open()
        $ps = [powershell]::Create()
        $ps.Runspace = $rs
        [void]$ps.AddScript($Global:MonSamplerSB.ToString()).AddArgument($Global:Mon).AddArgument([int]$PID).AddArgument([int][Environment]::ProcessorCount)
        [void]$ps.BeginInvoke()
        $Global:MonPS = $ps; $Global:MonRS = $rs
    } catch {
        Write-Log "No se pudo iniciar el monitor de lentitud: $($_.Exception.Message)" -Tipo AVISO
    }
}

function Global:Detener-MonitorLentitud {
    try { $Global:Mon.Parar = $true } catch {}
    try { if ($Global:MonTimer) { $Global:MonTimer.Stop() } } catch {}
    try { if ($Global:MonPS) { $Global:MonPS.Stop() | Out-Null; $Global:MonPS.Dispose() } } catch {}
    try { if ($Global:MonRS) { $Global:MonRS.Close() } } catch {}
}

# Empieza a vigilar la interfaz: un temporizador de 0,5 s; si tarda mucho mas en ejecutarse, la interfaz estuvo bloqueada
function Global:Iniciar-VigilanciaInterfaz {
    $Global:MonUltTick = [DateTime]::UtcNow
    $Global:MonActivo = $true
    if (-not $Global:MonTimer) {
        $Global:MonTimer = New-Object System.Windows.Threading.DispatcherTimer
        $Global:MonTimer.Interval = [TimeSpan]::FromMilliseconds(500)
        $Global:MonTimer.Add_Tick({ Revisar-LagInterfaz })
    }
    $Global:MonTimer.Start()
}

function Global:Revisar-LagInterfaz {
    $ahora = [DateTime]::UtcNow
    $lag = ($ahora - $Global:MonUltTick).TotalMilliseconds - 500
    $Global:MonUltTick = $ahora
    if (-not $Global:MonActivo) { return }
    if ($lag -lt 900 -or $lag -gt 180000) { return }
    $Global:MonLagCuenta++
    $Global:MonLagTotalMs += $lag
    Registrar-Lentitud -Tipo 'Interfaz' -Milisegundos $lag
}

function Global:Nombre-ProcesoAmigable {
    param([string]$Nombre, [int]$Pid2 = 0)
    if ($Pid2 -eq $PID) { return @{ Texto = "The Dragon Tool (este programa)"; Propio = $true; Sol = '' } }
    switch -Regex ($Nombre) {
        '^(MsMpEng|MpDefenderCoreService|NisSrv)$' { return @{ Texto = "Windows Defender analizando archivos ($Nombre)"; Propio = $false; Sol = 'Espera a que termine el analisis del antivirus o excluye la carpeta del programa en Seguridad de Windows.' } }
        '^(TiWorker|TrustedInstaller|WaasMedicSvc|MoUsoCoreWorker|UsoClient|wuauclt)$' { return @{ Texto = "Windows Update instalando o buscando actualizaciones ($Nombre)"; Propio = $false; Sol = 'Deja que Windows Update termine y reinicia el equipo; luego repite la prueba.' } }
        '^(SearchIndexer|SearchProtocolHost|SearchFilterHost)$' { return @{ Texto = "Indexador de busqueda de Windows ($Nombre)"; Propio = $false; Sol = 'El indexador suele terminar solo; puedes pausarlo desde Opciones de indexacion.' } }
        '^OneDrive' { return @{ Texto = "OneDrive sincronizando archivos"; Propio = $false; Sol = 'Pausa la sincronizacion de OneDrive mientras haces las pruebas.' } }
        '^(chrome|msedge|firefox|opera|brave)$' { return @{ Texto = "navegador web ($Nombre) con muchas pestañas o descargas"; Propio = $false; Sol = 'Cierra pestañas o el navegador mientras haces las pruebas.' } }
        '^(powershell|pwsh)$' { return @{ Texto = "otra ventana de PowerShell ($Nombre)"; Propio = $false; Sol = 'Revisa si hay otro script de PowerShell ejecutandose.' } }
        '^System$' { return @{ Texto = "el Sistema de Windows (controladores / disco / red)"; Propio = $false; Sol = 'Actualiza los controladores de disco y red y revisa el estado del disco.' } }
        '^(svchost|dwm|csrss|explorer)$' { return @{ Texto = "servicio de Windows ($Nombre)"; Propio = $false; Sol = 'Reinicia el equipo para liberar servicios de Windows saturados.' } }
        default { return @{ Texto = "el proceso '$Nombre'"; Propio = $false; Sol = "Cierra o revisa el programa '$Nombre' si no lo necesitas." } }
    }
}

# Analiza las muestras del sistema desde una hora dada y devuelve causas probables
function Global:Analizar-CausaLentitud {
    param([datetime]$Desde, [string]$Contexto = '')
    $r = @{ Causas = @(); Soluciones = @(); Resumen = 'sin datos del sistema todavia'; Cpu = $null; Ram = $null; Disco = $null; Hay = $false; Propio = $false }
    $m = @()
    try { $m = @($Global:Mon.Hist.ToArray() | Where-Object { $_.Hora -ge $Desde }) } catch {}
    if ($m.Count -eq 0 -and $Global:Mon.Ultimo) { $m = @($Global:Mon.Ultimo) }
    if ($m.Count -eq 0) { return $r }
    $r.Hay = $true
    $cpus = @($m | Where-Object { $null -ne $_.Cpu } | ForEach-Object { [double]$_.Cpu })
    $rams = @($m | Where-Object { $null -ne $_.RamPct } | ForEach-Object { [double]$_.RamPct })
    $dis = @($m | Where-Object { $null -ne $_.DiscoPct } | ForEach-Object { [double]$_.DiscoPct })
    $colas = @($m | Where-Object { $null -ne $_.Cola } | ForEach-Object { [double]$_.Cola })
    $cpuP = if ($cpus.Count) { ($cpus | Measure-Object -Average).Average } else { $null }
    $cpuM = if ($cpus.Count) { ($cpus | Measure-Object -Maximum).Maximum } else { $null }
    $ramM = if ($rams.Count) { ($rams | Measure-Object -Maximum).Maximum } else { $null }
    $disP = if ($dis.Count) { ($dis | Measure-Object -Average).Average } else { $null }
    $disM = if ($dis.Count) { ($dis | Measure-Object -Maximum).Maximum } else { $null }
    $colaM = if ($colas.Count) { ($colas | Measure-Object -Maximum).Maximum } else { $null }
    $r.Cpu = $cpuP; $r.Ram = $ramM; $r.Disco = $disP
    $partes = @()
    if ($null -ne $cpuP) { $partes += ("CPU prom {0:N0}% (pico {1:N0}%)" -f $cpuP, $cpuM) }
    if ($null -ne $ramM) { $partes += ("RAM {0:N0}%" -f $ramM) }
    if ($null -ne $disP) { $partes += ("Disco prom {0:N0}% (pico {1:N0}%)" -f $disP, $disM) }
    # Procesos que mas consumieron (de la muestra con mas CPU)
    $conTop = @($m | Where-Object { $_.Top -and @($_.Top).Count -gt 0 } | Sort-Object { [double]$_.Cpu } -Descending)
    $top = @()
    if ($conTop.Count) { $top = @($conTop[0].Top) }
    if ($top.Count) { $partes += "Procesos: " + (($top | Select-Object -First 3 | ForEach-Object { "$($_.Nombre) $($_.Cpu)%" }) -join ', ') }
    $conRam = @($m | Where-Object { $_.TopRam -and @($_.TopRam).Count -gt 0 } | Select-Object -Last 1)
    $topRam = @(); if ($conRam.Count) { $topRam = @($conRam[0].TopRam) }
    $r.Resumen = ($partes -join ' | ')

    $propio = $false
    if ($null -ne $cpuP -and $cpuP -ge 80) {
        $quien = ''
        if ($top.Count) {
            $p = Nombre-ProcesoAmigable -Nombre $top[0].Nombre -Pid2 $top[0].Pid
            $quien = " Lo que mas consume: $($p.Texto) ($($top[0].Cpu)%)."
            if ($p.Propio) { $propio = $true } elseif ($p.Sol) { $r.Soluciones += $p.Sol }
        }
        $r.Causas += ("CPU saturada ({0:N0}% de promedio).{1}" -f $cpuP, $quien)
    }
    if ($null -ne $ramM -and $ramM -ge 90) {
        $quien = ''
        if ($topRam.Count) { $quien = " Mayor consumo de memoria: $($topRam[0].Nombre) ($($topRam[0].MB) MB)." }
        $r.Causas += ("Memoria casi llena ({0:N0}%): Windows usa el disco como memoria y todo se vuelve lento.{1}" -f $ramM, $quien)
        $r.Soluciones += 'Cierra programas que no uses o usa "Liberar RAM"; si ocurre siempre, conviene ampliar la memoria.'
    }
    if (($null -ne $disP -and $disP -ge 85) -or ($null -ne $colaM -and $colaM -ge 6)) {
        $r.Causas += ("Disco saturado (uso prom {0:N0}%): las lecturas/escrituras esperan en cola." -f $disP)
        $r.Soluciones += 'Revisa descargas, antivirus o actualizaciones en segundo plano; si el disco es mecanico (HDD), un SSD mejora mucho la fluidez.'
    }
    try {
        $t = Get-TemperaturaCPUC
        if ($null -ne $t -and $t -ge 85) {
            $r.Causas += "Temperatura alta ($t °C): el procesador reduce su velocidad para enfriarse."
            $r.Soluciones += 'Limpia el polvo, revisa ventiladores/pasta termica y evita superficies blandas.'
        }
    } catch {}
    if ($r.Causas.Count -eq 0) {
        $ctx = ''
        if ($Contexto) { $ctx = " ($Contexto)" }
        $nivelGrafico = 3
        try { $nivelGrafico = ([int][System.Windows.Media.RenderCapability]::Tier) -shr 16 } catch {}
        if ($nivelGrafico -le 1) {
            $r.Causas += "Aceleracion grafica limitada: los efectos animados (neon, aurora, particulas) cargan el procesador$ctx."
            $r.Soluciones += 'Desactiva los efectos con el boton ✨ de la barra de titulo.'
        } else {
            $r.Causas += "El retraso lo causo una operacion pesada del propio programa$ctx, sin carga alta del sistema en ese momento."
            $r.Soluciones += 'Es normal en pruebas largas (se ejecutan en el hilo principal). Espera a que termine; si ocurre en reposo, avisa con el registro exportado.'
        }
    } elseif ($propio) {
        $r.Soluciones += 'La carga la genera la propia prueba en curso: es esperable mientras dura.'
    }
    $r.Propio = $propio
    return $r
}

# Registra un aviso de lentitud (con causa probable) en el registro de actividad y en el registro de errores
function Global:Registrar-Lentitud {
    param(
        [string]$Tipo, [double]$Milisegundos = 0, [string]$Contexto = '', [string]$Nombre = '',
        [double]$Segundos = 0, [double]$Esperado = 0, [string]$FaseLenta = '', $Desde = $null, [switch]$ForzarAviso
    )
    try {
        $ahora = Get-Date
        if ($Tipo -eq 'Interfaz' -and ($ahora - $Global:MonUltReporte).TotalSeconds -lt 20) { $Global:MonLagOmitidos++; return }
        if ($Tipo -eq 'Interfaz') { $Global:MonUltReporte = $ahora }
        $seg = [math]::Round($Milisegundos / 1000, 1)
        if (-not $Desde) { $Desde = $ahora.AddSeconds(-([math]::Max(6, $seg + 4))) }
        # Que estaba pasando: la prueba en curso o los ultimos mensajes del registro de actividad
        $ctx = $Contexto
        if (-not $ctx -and $Tipo -eq 'Interfaz') {
            if ($Global:DiagEnCurso -and $Global:DiagNombreActual) { $ctx = "prueba en curso: $($Global:DiagNombreActual)" }
            elseif ($Global:Actividad) {
                $a = $Global:Actividad; $p = $Global:ActividadPrev
                if ($p -and (($a.Hora - $p.Hora).TotalMilliseconds -ge ($Milisegundos * 0.6))) { $ctx = "entre '$($p.Texto)' y '$($a.Texto)'" }
                else { $ctx = "ultima actividad: '$($a.Texto)'" }
            }
        }
        $an = Analizar-CausaLentitud -Desde $Desde -Contexto $ctx
        $causas = if ($an.Causas.Count) { $an.Causas -join ' ' } else { 'sin causa clara' }
        $extra = ''
        if ($Global:MonLagOmitidos -gt 0 -and $Tipo -eq 'Interfaz') { $extra = " (+$($Global:MonLagOmitidos) bloqueo(s) menores desde el aviso anterior)"; $Global:MonLagOmitidos = 0 }
        switch ($Tipo) {
            'Interfaz' { $msg = "Lentitud detectada: el programa dejo de responder $seg s. Causa probable: $causas Contexto: $ctx.$extra"; $icono = '🐢' }
            'Arranque' { $msg = "Arranque lento: el programa tardo $([math]::Round($Segundos,1)) s en abrirse (fase mas lenta: '$FaseLenta'). Causa probable: $causas"; $icono = '🚦' }
            default    { $msg = "Prueba lenta: '$Nombre' tardo $([math]::Round($Segundos,1)) s (lo normal es ~$([math]::Round($Esperado,0)) s). Causa probable: $causas"; $icono = '⏳' }
        }
        $sol = if ($an.Soluciones.Count) { ($an.Soluciones | Select-Object -Unique) -join ' ' } else { 'Repite la prueba con el equipo en reposo y exporta el registro si persiste.' }
        $detalle = "Sistema durante el evento: $($an.Resumen)"
        # Si el bloqueo fue breve y el sistema esta tranquilo solo se anota como informacion; si no, es un aviso del registro de errores
        $esAviso = $ForzarAviso -or ($Tipo -ne 'Interfaz') -or ($Milisegundos -ge 2500) -or ($an.Causas.Count -gt 0 -and $an.Causas[0] -notmatch '^El retraso lo causo|^Aceleracion')
        [void]$Global:EventosLentitud.Add(@{ Hora = $ahora; Tipo = $Tipo; Texto = $msg })
        if ($esAviso) {
            Write-Log "$icono $msg Sistema: $($an.Resumen)" -Tipo AVISO -SinRegistro
            Add-RegistroError -Tipo 'AVISO' -Categoria 'Rendimiento (lentitud)' -Origen 'Monitor de lentitud' -Mensaje $msg -Solucion $sol -Detalle $detalle
            try { if ($window.FindName("GridRegistroErrores")) { Cargar-RegistroErrores } } catch {}
        } else {
            Write-Log "$icono Bloqueo breve de la interfaz ($seg s). $ctx. Sistema: $($an.Resumen)" -Tipo INFO -SinRegistro
        }
        return $an
    } catch {}
}

# Mide el arranque del programa y avisa si fue lento
function Global:Reportar-Arranque {
    try {
        $Global:RelojArranque.Stop()
        $total = $Global:RelojArranque.Elapsed.TotalSeconds
        $fases = @($Global:FasesArranque.ToArray())
        $detalle = @(); $prev = 0.0; $peor = ''; $peorT = 0.0
        foreach ($f in $fases) {
            $d = $f.T - $prev
            $detalle += ("{0} {1:N1}s" -f $f.Fase, $d)
            if ($d -gt $peorT) { $peorT = $d; $peor = $f.Fase }
            $prev = $f.T
        }
        Write-Log ("Arranque del programa: {0:N1} s en total ({1})." -f $total, ($detalle -join ' | ')) -Tipo INFO -SinRegistro
        if ($total -ge 8) {
            [void](Registrar-Lentitud -Tipo 'Arranque' -Segundos $total -FaseLenta "$peor ($([math]::Round($peorT,1)) s)" -Desde (Get-Date).AddSeconds(-($total + 3)) -Contexto 'durante el arranque')
        }
    } catch {}
    Iniciar-VigilanciaInterfaz
}

# Informe manual de rendimiento (boton de la pestaña Registro de errores)
function Global:Informe-Lentitud {
    try {
        Write-Log "Analizando rendimiento del equipo (unos segundos)..." -Tipo INFO -SinRegistro
        $Global:Mon.ForzarProcesos = $true
        $t0 = Get-Date
        while (((Get-Date) - $t0).TotalSeconds -lt 3.5) { Wait-UI -Milisegundos 100 }
        $an = Analizar-CausaLentitud -Desde (Get-Date).AddSeconds(-30) -Contexto 'en reposo'
        $L = New-Object System.Collections.ArrayList
        [void]$L.Add("INFORME DE LENTITUD  ($((Get-Date).ToString('yyyy-MM-dd HH:mm:ss')))")
        [void]$L.Add("")
        [void]$L.Add("Sistema (ultimos 30 s): $($an.Resumen)")
        $u = $Global:Mon.Ultimo
        if ($u -and $u.Top -and @($u.Top).Count) {
            [void]$L.Add("Procesos que mas CPU usan ahora:")
            foreach ($p in @($u.Top)) { [void]$L.Add("   - $($p.Nombre) (PID $($p.Pid)): $($p.Cpu)%") }
        }
        if ($u -and $u.TopRam -and @($u.TopRam).Count) {
            [void]$L.Add("Procesos que mas memoria usan:")
            foreach ($p in @($u.TopRam)) { [void]$L.Add("   - $($p.Nombre) (PID $($p.Pid)): $($p.MB) MB") }
        }
        [void]$L.Add("")
        if ($an.Causas.Count) {
            [void]$L.Add("QUE LO ESTA RALENTIZANDO:")
            foreach ($c in $an.Causas) { [void]$L.Add("   * $c") }
            [void]$L.Add("QUE HACER:")
            foreach ($s in ($an.Soluciones | Select-Object -Unique)) { [void]$L.Add("   > $s") }
        } else {
            [void]$L.Add("No se detecta ahora una carga que ralentice el equipo (CPU, RAM y disco dentro de lo normal).")
        }
        [void]$L.Add("")
        [void]$L.Add("Eventos de lentitud en esta sesion: $($Global:EventosLentitud.Count) (la interfaz estuvo bloqueada $($Global:MonLagCuenta) vez/veces, $([math]::Round($Global:MonLagTotalMs/1000,1)) s en total).")
        foreach ($e in @($Global:EventosLentitud.ToArray() | Select-Object -Last 8)) { [void]$L.Add("   $($e.Hora.ToString('HH:mm:ss'))  $($e.Texto)") }
        if ($Global:HistPruebas.Count) {
            [void]$L.Add("")
            [void]$L.Add("Duracion de las ultimas pruebas de diagnostico:")
            foreach ($h in @($Global:HistPruebas.ToArray() | Select-Object -Last 10)) { [void]$L.Add("   $h") }
        }
        $fases = @($Global:FasesArranque.ToArray())
        if ($fases.Count) {
            $prev = 0.0; $tx = @()
            foreach ($f in $fases) { $tx += ("{0} {1:N1}s" -f $f.Fase, ($f.T - $prev)); $prev = $f.T }
            [void]$L.Add("")
            [void]$L.Add("Arranque del programa: $($tx -join ' | ')")
        }
        $texto = ($L -join "`r`n")
        $caja = $window.FindName("TxtDetalleError")
        if ($caja) { $caja.Text = $texto }
        foreach ($linea in @($L | Select-Object -First 4)) { if ($linea) { Write-Log $linea -Tipo INFO -SinRegistro } }
        if ($an.Causas.Count) { Write-Log "🐢 Lentitud actual: $($an.Causas -join ' ')" -Tipo AVISO -SinRegistro }
        else { Write-Log "Rendimiento actual normal. Detalle completo en la pestaña Registro de errores." -Tipo OK -SinRegistro }
    } catch { Write-Log "No se pudo generar el informe de lentitud: $($_.Exception.Message)" -Tipo AVISO }
}

# Duracion normal esperada (segundos) de cada prueba de diagnostico, para detectar pruebas lentas
$Global:DiagEsperadoSeg = @{
    'Rendimiento del procesador' = 20; 'Velocidad de disco' = 40; 'Velocidad de Internet' = 50; 'Latencia aleatoria 4K' = 45
    'Actividad del disco' = 15; 'Diagnostico completo del equipo' = 150; 'Diagnostico completo de disco' = 60
    'Verificacion CHKDSK' = 900; 'Fragmentacion y optimizacion' = 900
}

Iniciar-MonitorLentitud

function Global:Show-Confirm {
    param([string]$Mensaje, [string]$Titulo = "Confirmar")
    $resultado = [System.Windows.MessageBox]::Show($Mensaje, $Titulo, 'YesNo', 'Question')
    return ($resultado -eq 'Yes')
}

function Global:Show-Aviso {
    param([string]$Mensaje, [string]$Titulo = "Aviso")
    [System.Windows.MessageBox]::Show($Mensaje, $Titulo, 'OK', 'Information') | Out-Null
}

function Global:Requiere-Admin {
    if (-not (Test-Admin)) {
        Write-Log "Esta accion requiere permisos de administrador. Vuelve a abrir el programa como administrador." -Tipo AVISO
        return $false
    }
    return $true
}

# Pequeno dialogo generico con dos campos de texto (usado para memoria virtual)
function Show-DialogoMemoriaVirtual {
    param([string]$SugeridoInicial, [string]$SugeridoMaximo)

    [xml]$xamlDlg = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Configurar memoria virtual" Height="310" Width="420"
        WindowStartupLocation="CenterScreen" Background="#10141D">
  <Window.Resources>$($Global:RecursosNeonXaml)</Window.Resources>
  <StackPanel Margin="16">
    <Button x:Name="BtnVolverVentana" Content="⬅  Volver" Width="110" Height="34" HorizontalAlignment="Left" Margin="0,0,0,10"/>
    <TextBlock Text="Configurar memoria virtual (archivo de paginacion)" Foreground="White" FontWeight="Bold" FontSize="14" Margin="0,0,0,10" TextWrapping="Wrap"/>
    <RadioButton x:Name="RbAuto" Content="Administrar automaticamente (recomendado)" Foreground="White" GroupName="modo" IsChecked="True" Margin="0,2"/>
    <RadioButton x:Name="RbManual" Content="Tamaño personalizado en C:" Foreground="White" GroupName="modo" Margin="0,2,0,10"/>
    <TextBlock Text="Tamaño inicial (MB):" Foreground="White"/>
    <TextBox x:Name="TxtInicial" Margin="0,2,0,8"/>
    <TextBlock Text="Tamaño maximo (MB):" Foreground="White"/>
    <TextBox x:Name="TxtMaximo" Margin="0,2,0,12"/>
    <StackPanel Orientation="Horizontal" HorizontalAlignment="Right">
      <Button x:Name="BtnCancelar" Content="Cancelar" Width="90" Margin="0,0,8,0"/>
      <Button x:Name="BtnAceptar" Content="Aceptar" Width="90"/>
    </StackPanel>
  </StackPanel>
</Window>
"@
    $reader = New-Object System.Xml.XmlNodeReader $xamlDlg
    $dlg = [Windows.Markup.XamlReader]::Load($reader)
    Iniciar-EfectosNeon -Ventana $dlg
    $txtInicial = $dlg.FindName("TxtInicial")
    $txtMaximo  = $dlg.FindName("TxtMaximo")
    $rbAuto     = $dlg.FindName("RbAuto")
    $rbManual   = $dlg.FindName("RbManual")
    $txtInicial.Text = $SugeridoInicial
    $txtMaximo.Text  = $SugeridoMaximo

    $resultado = $null
    $dlg.FindName("BtnCancelar").Add_Click({ $dlg.DialogResult = $false })
    $dlg.FindName("BtnAceptar").Add_Click({
        $Script:_mv_modo    = if ($rbAuto.IsChecked) { 'auto' } else { 'manual' }
        $Script:_mv_inicial = $txtInicial.Text
        $Script:_mv_maximo  = $txtMaximo.Text
        $dlg.DialogResult = $true
    })
    $ok = $dlg.ShowDialog()
    if ($ok) {
        return @{ Modo = $Script:_mv_modo; Inicial = $Script:_mv_inicial; Maximo = $Script:_mv_maximo }
    }
    return $null
}

# Ventana con lista de procesos y opcion de cerrar el seleccionado
function Show-VentanaProcesos {
    [xml]$xamlProc = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Procesos que mas RAM consumen" Height="480" Width="520"
        WindowStartupLocation="CenterScreen" Background="#10141D">
  <Window.Resources>$($Global:RecursosNeonXaml)</Window.Resources>
  <DockPanel Margin="12">
    <Button x:Name="BtnVolverVentana" DockPanel.Dock="Top" Content="⬅  Volver" Width="110" Height="34" HorizontalAlignment="Left" Margin="0,0,0,10"/>
    <TextBlock DockPanel.Dock="Top" Text="Selecciona un proceso y pulsa 'Cerrar proceso' si deseas liberar RAM" Foreground="White" TextWrapping="Wrap" Margin="0,0,0,8"/>
    <StackPanel DockPanel.Dock="Bottom" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,8,0,0">
      <Button x:Name="BtnCerrarProceso" Content="Cerrar proceso" Width="140" Margin="0,0,8,0"/>
      <Button x:Name="BtnCerrarVentana" Content="Cerrar ventana" Width="120"/>
    </StackPanel>
    <DataGrid x:Name="GridProcesos" AutoGenerateColumns="False" IsReadOnly="True" SelectionMode="Single"
              Background="#151B27" RowBackground="#151B27" AlternatingRowBackground="#1C2635" Foreground="White"
              BorderBrush="#232B3D" HorizontalGridLinesBrush="#232B3D" VerticalGridLinesBrush="#232B3D" RowHeaderWidth="0">
      <DataGrid.Columns>
        <DataGridTextColumn Header="Nombre" Binding="{Binding Name}" Width="2*"/>
        <DataGridTextColumn Header="PID" Binding="{Binding Id}" Width="*"/>
        <DataGridTextColumn Header="RAM (MB)" Binding="{Binding RAM_MB}" Width="*"/>
      </DataGrid.Columns>
    </DataGrid>
  </DockPanel>
</Window>
"@
    $reader = New-Object System.Xml.XmlNodeReader $xamlProc
    $win = [Windows.Markup.XamlReader]::Load($reader)
    Iniciar-EfectosNeon -Ventana $win
    $grid = $win.FindName("GridProcesos")

    $datos = Get-Process | Sort-Object WS -Descending | Select-Object -First 25 Name, Id,
        @{N='RAM_MB';E={[math]::Round($_.WS/1MB,1)}}
    $grid.ItemsSource = $datos

    $win.FindName("BtnCerrarVentana").Add_Click({ $win.Close() })
    $win.FindName("BtnCerrarProceso").Add_Click({
        $sel = $grid.SelectedItem
        if (-not $sel) {
            Show-Aviso "Selecciona primero un proceso de la lista." "Sin seleccion"
            return
        }
        if (Show-Confirm "¿Cerrar el proceso '$($sel.Name)' (PID $($sel.Id))?" "Confirmar cierre") {
            try {
                Stop-Process -Id $sel.Id -Force -ErrorAction Stop
                Write-Log "Proceso '$($sel.Name)' (PID $($sel.Id)) cerrado." -Tipo OK
                $datos = Get-Process | Sort-Object WS -Descending | Select-Object -First 25 Name, Id,
                    @{N='RAM_MB';E={[math]::Round($_.WS/1MB,1)}}
                $grid.ItemsSource = $datos
            } catch {
                Write-Log "No se pudo cerrar '$($sel.Name)': $($_.Exception.Message)" -Tipo ERROR
            }
        }
    })
    $win.ShowDialog() | Out-Null
}

