function Global:Get-InfoBugCheck {
    param([string]$Codigo)
    if ($Codigo) {
        $clave = $Codigo.ToLower()
        if ($Script:TablaBugCheck.ContainsKey($clave)) { return $Script:TablaBugCheck[$clave] }
    }
    return @{
        Nombre = if ($Codigo) { "Codigo no catalogado ($Codigo)" } else { "Codigo no identificado" }
        Recomendacion = "No esta en nuestra tabla de codigos comunes. Busca el codigo en el sitio de soporte de Microsoft, ejecuta Verificar archivos de sistema (SFC), actualiza todos los controladores y revisa la memoria RAM."
    }
}

function Get-HistorialBSOD {
    try {
        $eventos = Get-WinEvent -FilterHashtable @{LogName='System'; Id=1001} -ErrorAction Stop |
            Where-Object { $_.ProviderName -match 'WER-SystemErrorReporting|Windows Error Reporting' -or $_.Message -match 'BugCheck' }
    } catch {
        return @()
    }
    $resultado = foreach ($e in $eventos) {
        $codigo = $null
        if ($e.Message -match '0x[0-9A-Fa-f]{8}') { $codigo = $Matches[0] }
        $info = Get-InfoBugCheck -Codigo $codigo
        [PSCustomObject]@{
            Fecha         = $e.TimeCreated.ToString('yyyy-MM-dd HH:mm')
            Codigo        = if ($codigo) { $codigo } else { "Desconocido" }
            Nombre        = $info.Nombre
            Recomendacion = $info.Recomendacion
        }
    }
    return $resultado
}

# Devuelve toda la informacion de un codigo (nombre, causa, pasos, gravedad) combinando las tablas.
function Global:Get-DetalleBugCheck {
    param([string]$Codigo)
    $info = Get-InfoBugCheck -Codigo $Codigo
    $clave = if ($Codigo) { $Codigo.ToLower() } else { '' }
    $det = if ($clave -and $Script:DetalleBugCheck.ContainsKey($clave)) { $Script:DetalleBugCheck[$clave] } else { $null }
    $causa = if ($det) { $det.Causa } else { 'Este codigo no esta en el catalogo del programa. Las pantallas azules suelen deberse a controladores defectuosos, memoria RAM o disco con errores, sobrecalentamiento, archivos de sistema danados o software de seguridad/terceros en conflicto.' }
    $pasos = if ($det) { $det.Pasos } else { @(
        'Busca el codigo en internet (boton Buscar en internet) para ver su significado exacto.',
        'Actualiza Windows y todos los controladores, empezando por video, red y almacenamiento.',
        'Ejecuta Verificar archivos de sistema (SFC) y reparacion DISM.',
        'Ejecuta el Diagnostico de memoria de Windows y comprueba el disco (chkdsk).',
        'Revisa que programa o driver instalaste justo antes de la primera pantalla azul y desinstalalo.') }
    $grav = if ($det) { $det.Gravedad } else { 'Media' }
    [PSCustomObject]@{
        Codigo = $Codigo; Nombre = $info.Nombre; Recomendacion = $info.Recomendacion
        Causa = $causa; Pasos = $pasos; Gravedad = $grav
    }
}

# Ventana que explica el motivo de la pantalla azul y como solucionarla paso a paso.
function Global:Show-VentanaExplicarBSOD {
    param([string]$Codigo, [string]$Fecha = '')
    $d = Get-DetalleBugCheck -Codigo $Codigo
    $colorGrav = if ($d.Gravedad -eq 'Alta') { '#FF6B6B' } else { '#FFC857' }
    $textoGrav = if ($d.Gravedad -eq 'Alta') { 'Gravedad ALTA: puede indicar hardware o disco fallando' } else { 'Gravedad MEDIA: normalmente software o controladores' }
    $codigoMostrar = if ($Codigo) { $Codigo } else { 'Desconocido' }
    $fechaTxt = if ($Fecha) { "Ocurrio: $Fecha" } else { 'Consulta del catalogo de errores' }

    [xml]$x = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Explicacion del error - The Dragon Tool" Height="700" Width="820" MinHeight="520" MinWidth="640"
        WindowStartupLocation="CenterScreen" Background="#10141D">
  <Window.Resources>$($Global:RecursosNeonXaml)</Window.Resources>
  <DockPanel Margin="16">
    <Button x:Name="BtnVolverVentana" DockPanel.Dock="Top" Content="⬅  Volver" Width="110" Height="34" HorizontalAlignment="Left" Margin="0,0,0,10"/>
    <WrapPanel DockPanel.Dock="Bottom" Margin="0,12,0,0">
      <Button x:Name="BtnExpSFC" Content="🔍 Verificar archivos (SFC)" Width="205" Height="40" FontSize="12"/>
      <Button x:Name="BtnExpMem" Content="🧠 Diagnostico de memoria" Width="205" Height="40" FontSize="12"/>
      <Button x:Name="BtnExpDisco" Content="💽 Comprobar disco (chkdsk)" Width="205" Height="40" FontSize="12"/>
      <Button x:Name="BtnExpDrivers" Content="🕒 Controladores recientes" Width="205" Height="40" FontSize="12"/>
      <Button x:Name="BtnExpWeb" Content="🌐 Buscar en internet" Width="205" Height="40" FontSize="12"/>
      <Button x:Name="BtnExpCopiar" Content="📋 Copiar explicacion" Width="205" Height="40" FontSize="12"/>
    </WrapPanel>
    <ScrollViewer VerticalScrollBarVisibility="Auto">
      <StackPanel>
        <Border Background="#0A0D14" BorderBrush="#232B3D" BorderThickness="1" CornerRadius="8" Padding="16" Margin="0,0,0,12">
          <StackPanel>
            <TextBlock x:Name="TxtExpNombre" FontSize="20" FontWeight="Bold" Foreground="White" TextWrapping="Wrap"/>
            <TextBlock x:Name="TxtExpCodigo" FontFamily="Consolas" FontSize="13" Foreground="#66AEFF" Margin="0,4,0,0"/>
            <TextBlock x:Name="TxtExpFecha" FontSize="12" Foreground="#7C93BD" Margin="0,2,0,8"/>
            <Border x:Name="BrdExpGravedad" CornerRadius="12" Padding="10,3" HorizontalAlignment="Left" Background="#1A1F2B">
              <TextBlock x:Name="TxtExpGravedad" FontSize="12" FontWeight="Bold"/>
            </Border>
          </StackPanel>
        </Border>
        <Border Background="#0A0D14" BorderBrush="#232B3D" BorderThickness="1" CornerRadius="8" Padding="16" Margin="0,0,0,12">
          <StackPanel>
            <TextBlock Text="❓ ¿Por que ocurre?" FontSize="15" FontWeight="Bold" Foreground="#66AEFF" Margin="0,0,0,6"/>
            <TextBlock x:Name="TxtExpCausa" Foreground="White" TextWrapping="Wrap" FontSize="13" LineHeight="21"/>
          </StackPanel>
        </Border>
        <Border Background="#0A0D14" BorderBrush="#232B3D" BorderThickness="1" CornerRadius="8" Padding="16" Margin="0,0,0,12">
          <StackPanel>
            <TextBlock Text="🛠️ ¿Como solucionarlo? (en este orden)" FontSize="15" FontWeight="Bold" Foreground="#66AEFF" Margin="0,0,0,6"/>
            <TextBlock x:Name="TxtExpPasos" Foreground="White" TextWrapping="Wrap" FontSize="13" LineHeight="23"/>
          </StackPanel>
        </Border>
        <Border Background="#0A0D14" BorderBrush="#232B3D" BorderThickness="1" CornerRadius="8" Padding="16">
          <StackPanel>
            <TextBlock Text="⚡ Resumen rapido" FontSize="15" FontWeight="Bold" Foreground="#66AEFF" Margin="0,0,0,6"/>
            <TextBlock x:Name="TxtExpResumen" Foreground="White" TextWrapping="Wrap" FontSize="13" LineHeight="21"/>
          </StackPanel>
        </Border>
      </StackPanel>
    </ScrollViewer>
  </DockPanel>
</Window>
"@
    $w = [Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader $x))
    try { if ($window -and $window.IsVisible) { $w.Owner = $window } } catch {}
    Iniciar-EfectosNeon -Ventana $w

    $w.FindName("TxtExpNombre").Text = $d.Nombre
    $w.FindName("TxtExpCodigo").Text = "Codigo STOP: $codigoMostrar"
    $w.FindName("TxtExpFecha").Text = $fechaTxt
    $g = $w.FindName("TxtExpGravedad")
    $g.Text = $textoGrav
    $g.Foreground = (New-Object System.Windows.Media.BrushConverter).ConvertFromString($colorGrav)
    $w.FindName("TxtExpCausa").Text = $d.Causa
    $n = 0
    $w.FindName("TxtExpPasos").Text = (($d.Pasos | ForEach-Object { $n++; "$n.  $_" }) -join "`r`n")
    $w.FindName("TxtExpResumen").Text = $d.Recomendacion

    $nombre = $d.Nombre
    $textoCopia = "$($d.Nombre) ($codigoMostrar)`r`n`r`nPor que ocurre:`r`n$($d.Causa)`r`n`r`nComo solucionarlo:`r`n" + (($d.Pasos | ForEach-Object -Begin { $k = 0 } -Process { $k++; "$k. $_" }) -join "`r`n")
    $w.FindName("BtnExpSFC").Add_Click({ Accion-VerificarArchivosSistema })
    $w.FindName("BtnExpMem").Add_Click({ Accion-DiagnosticoMemoriaWindows })
    $w.FindName("BtnExpDisco").Add_Click({
        try { Start-Process cmd.exe -ArgumentList '/k', 'chkdsk %SystemDrive% & echo. & echo Para reparar errores ejecuta: chkdsk %SystemDrive% /f /r (pedira reiniciar)' -Verb RunAs } catch { Write-Log "No se pudo abrir chkdsk: $($_.Exception.Message)" -Tipo AVISO }
    })
    $w.FindName("BtnExpDrivers").Add_Click({ Accion-VerControladoresRecientes })
    $w.FindName("BtnExpWeb").Add_Click({
        try { Start-Process ("https://www.bing.com/search?q=" + [uri]::EscapeDataString("pantalla azul $codigoMostrar $nombre solucion")) } catch {}
    }.GetNewClosure())
    $w.FindName("BtnExpCopiar").Add_Click({
        try { Set-Clipboard -Value $textoCopia; Write-Log "Explicacion del error copiada al portapapeles." -Tipo OK } catch { Write-Log "No se pudo copiar: $($_.Exception.Message)" -Tipo AVISO }
    }.GetNewClosure())
    $w.Show()
}

function Global:Accion-DiagnosticoMemoriaWindows {
    if (Show-Confirm "Se abrira el Diagnostico de memoria de Windows. El equipo se reiniciara para ejecutar la prueba. ¿Continuar?") {
        Write-Log "Iniciando Diagnostico de memoria de Windows (requiere reinicio)." -Tipo OK
        Start-Process "mdsched.exe"
    }
}

function Accion-AbrirCarpetaMinidump {
    $ruta = "$env:WINDIR\Minidump"
    if (Test-Path $ruta) {
        Start-Process explorer.exe -ArgumentList $ruta
        Write-Log "Carpeta de volcados de memoria abierta." -Tipo OK
    } else {
        Show-Aviso "No se encontro la carpeta de volcados de memoria ($ruta). Puede que Windows no este generando minidumps en este equipo." "Carpeta no encontrada"
    }
}

function Accion-ConfigVolcadoMemoria {
    Write-Log "Verificando configuracion de volcado de memoria..."
    try {
        $val = Get-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\CrashControl" -Name "CrashDumpEnabled" -ErrorAction Stop
        $desc = switch ($val.CrashDumpEnabled) {
            0 { "Desactivado (Windows NO esta guardando volcados de memoria cuando ocurre un BSOD)" }
            1 { "Volcado completo" }
            2 { "Volcado de kernel" }
            3 { "Volcado pequeño (minidump)" }
            7 { "Volcado automatico (recomendado)" }
            default { "Valor desconocido ($($val.CrashDumpEnabled))" }
        }
        Write-Log "Configuracion actual: $desc" -Tipo OK
        if ($val.CrashDumpEnabled -eq 0) {
            if (Show-Confirm "Los volcados de memoria estan desactivados: no se puede diagnosticar a fondo la proxima pantalla azul. ¿Activar volcados automaticos ahora?") {
                if (-not (Requiere-Admin)) { return }
                Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\CrashControl" -Name "CrashDumpEnabled" -Value 7 -Type DWord
                Write-Log "Volcados de memoria activados (modo automatico)." -Tipo OK
            }
        }
    } catch {
        Write-Log "No se pudo leer la configuracion de volcado de memoria." -Tipo AVISO
    }
}

function Accion-AbrirMonitorConfiabilidad {
    Start-Process "perfmon.exe" -ArgumentList "/rel"
    Write-Log "Monitor de confiabilidad de Windows abierto (linea de tiempo de errores y cambios recientes)." -Tipo OK
}

function Accion-ExportarHistorialBSOD {
    try {
        $datos = Get-HistorialBSOD
        if ($datos.Count -eq 0) { Write-Log "No hay historial de BSOD para exportar." -Tipo AVISO; return }
        $destino = Join-Path $Script:ScriptDir "Historial_BSOD_$(Get-Date -Format 'yyyyMMdd_HHmmss').txt"
        $lineas = foreach ($d in $datos) { "$($d.Fecha) | $($d.Codigo) | $($d.Nombre)`r`nRecomendacion: $($d.Recomendacion)`r`n" }
        ($lineas -join "`r`n") | Out-File -FilePath $destino -Encoding UTF8
        Write-Log "Historial exportado a: $destino" -Tipo OK
        if (Show-Confirm "¿Abrir el archivo exportado?") { Start-Process $destino }
    } catch {
        Write-Log "No se pudo exportar el historial: $($_.Exception.Message)" -Tipo ERROR
    }
}

function Global:Accion-VerControladoresRecientes {
    Write-Log "Buscando controladores instalados/actualizados recientemente (para correlacionar con las BSOD)..."
    $todos = Get-TodosLosControladores
    $recientes = $todos | Where-Object { $_.Fecha -ne "Desconocida" } | Sort-Object Fecha -Descending | Select-Object -First 10
    if ($recientes) {
        Write-Log "Los 10 controladores con fecha mas reciente:" -Tipo OK
        foreach ($r in $recientes) { Write-Log " - $($r.Fecha) | $($r.Nombre) [$($r.Fabricante)]" }
    } else {
        Write-Log "No se pudo determinar la fecha de los controladores instalados." -Tipo AVISO
    }
}

function Cargar-DatosBSODTab {
    Write-Log "Buscando historial de pantallas azules en el registro de sucesos..."
    $datos = Get-HistorialBSOD
    $gridB = $window.FindName("GridBSODTab")
    $txtB = $window.FindName("TxtResumenBSODTab")
    if ($gridB) { $gridB.ItemsSource = $datos }
    if ($txtB) {
        $txtB.Text = if ($datos.Count -eq 0) {
            "No se encontraron pantallas azules registradas (o no se pudo leer el registro de sucesos)."
        } else {
            "Se encontraron $($datos.Count) pantalla(s) azul(es) registrada(s)."
        }
    }
    Write-Log "Busqueda de BSOD completada: $($datos.Count) encontrada(s)." -Tipo OK
}

# ---------------------------------------------------------------------------
#  DIAGNOSTICAR EQUIPO (hardware) + analisis opcional con IA
# ---------------------------------------------------------------------------

$Script:DiagLogIniciado = $false
function Global:Write-DiagLog {
    param([string]$Mensaje)
    Write-Log $Mensaje -Tipo INFO
    $caja = $window.FindName("TxtDiagResultados")
    if ($caja) {
        if (-not $Script:DiagLogIniciado) {
            $caja.Clear()
            $Script:DiagLogIniciado = $true
            $Global:DiagInforme = $null
        }
        try { Registrar-LineaInforme $Mensaje } catch { }
        $caja.AppendText("$Mensaje`r`n")
        $caja.ScrollToEnd()
    }
    if ($Global:DiagStats) { $Global:DiagStats.Lineas++; if ($Global:DiagEnCurso) { Actualizar-DiagChips } }
    # Write-Log siempre recibe -Tipo INFO desde aqui (para no romper el formato
    # del registro de diagnostico), asi que los fallos de las pruebas se
    # detectan por patrones de texto y se registran aparte para la pestaña de
    # Registro de errores.
    if ($Mensaje -match '(?i)no se pudo|no se pud[oe]|error|ATENCION|no se detect[oó]|no se encontr[oó]|fall[oó]|sin conexion') {
        try {
            $callStack = Get-PSCallStack
            $origen = if ($callStack.Count -gt 1 -and $callStack[1].FunctionName) { $callStack[1].FunctionName } else { "Prueba de diagnostico" }
            Add-RegistroError -Tipo 'AVISO' -Categoria 'Prueba de diagnostico' -Origen $origen -Mensaje $Mensaje
        } catch {}
    }
}

# --- Gancho de teclado de bajo nivel (WH_KEYBOARD_LL) ---
# Se usa solo en la prueba de teclado, para poder detectar teclas especiales
# como Copilot (y, si el fabricante la reporta a Windows, Fn) que muchas
# veces no llegan como un Key normal de WPF. Captura el codigo de tecla
# virtual (vkCode) y el codigo de escaneo (scanCode) de cada tecla presionada
# en todo el sistema mientras la ventana de prueba esta abierta.
$Script:TipoTecladoHookListo = $false
function Ensure-TipoTecladoHook {
    if ($Script:TipoTecladoHookListo) { return }
    $codigo = @"
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Diagnostics;

public static class DragonToolTecladoHook {
    private const int WH_KEYBOARD_LL = 13;
    private const int WM_KEYDOWN = 0x0100;
    private const int WM_KEYUP = 0x0101;
    private const int WM_SYSKEYDOWN = 0x0104;
    private const int WM_SYSKEYUP = 0x0105;
    private static IntPtr hookId = IntPtr.Zero;
    private static LowLevelKeyboardProc proc = HookCallback;
    private static Queue<uint[]> eventos = new Queue<uint[]>();

    public delegate IntPtr LowLevelKeyboardProc(int nCode, IntPtr wParam, IntPtr lParam);

    [StructLayout(LayoutKind.Sequential)]
    private struct KBDLLHOOKSTRUCT {
        public uint vkCode;
        public uint scanCode;
        public uint flags;
        public uint time;
        public IntPtr dwExtraInfo;
    }

    public static void Instalar() {
        if (hookId != IntPtr.Zero) { return; }
        using (Process curProcess = Process.GetCurrentProcess())
        using (ProcessModule curModule = curProcess.MainModule) {
            hookId = SetWindowsHookEx(WH_KEYBOARD_LL, proc, GetModuleHandle(curModule.ModuleName), 0);
        }
    }

    public static void Desinstalar() {
        if (hookId == IntPtr.Zero) { return; }
        UnhookWindowsHookEx(hookId);
        hookId = IntPtr.Zero;
    }

    public static uint[] SacarSiguiente() {
        lock (eventos) {
            if (eventos.Count > 0) { return eventos.Dequeue(); }
        }
        return null;
    }

    public static void Limpiar() {
        lock (eventos) { eventos.Clear(); }
    }

    private static IntPtr HookCallback(int nCode, IntPtr wParam, IntPtr lParam) {
        if (nCode >= 0) {
            bool esBajada = (wParam == (IntPtr)WM_KEYDOWN || wParam == (IntPtr)WM_SYSKEYDOWN);
            bool esSubida = (wParam == (IntPtr)WM_KEYUP || wParam == (IntPtr)WM_SYSKEYUP);
            if (esBajada || esSubida) {
                KBDLLHOOKSTRUCT datos = (KBDLLHOOKSTRUCT)Marshal.PtrToStructure(lParam, typeof(KBDLLHOOKSTRUCT));
                // El cuarto valor indica si es una tecla que baja (1) o que sube (0),
                // para poder distinguir "recien pulsada" de "sigue sostenida". El
                // quinto valor es la marca de tiempo del propio hardware/driver del
                // teclado (milisegundos), no del momento en que PowerShell la lee de
                // la cola: se usa para medir con precision el intervalo real entre
                // pulsaciones de una misma tecla y asi detectar "rebote" (una sola
                // pulsada fisica que el interruptor manda como dos o mas).
                lock (eventos) { eventos.Enqueue(new uint[] { datos.vkCode, datos.scanCode, datos.flags, (uint)(esBajada ? 1 : 0), datos.time }); }
            }
        }
        return CallNextHookEx(hookId, nCode, wParam, lParam);
    }

    [DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
    private static extern IntPtr SetWindowsHookEx(int idHook, LowLevelKeyboardProc lpfn, IntPtr hMod, uint dwThreadId);

    [DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool UnhookWindowsHookEx(IntPtr hhk);

    [DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
    private static extern IntPtr CallNextHookEx(IntPtr hhk, int nCode, IntPtr wParam, IntPtr lParam);

    [DllImport("kernel32.dll", CharSet = CharSet.Auto, SetLastError = true)]
    private static extern IntPtr GetModuleHandle(string lpModuleName);
}
"@
    Add-Type -TypeDefinition $codigo -ErrorAction Stop
    $Script:TipoTecladoHookListo = $true
}

# Consulta en vivo a Windows (API nativa, no una tabla fija nuestra) de que
# caracter produce cada tecla fisica bajo la distribucion de teclado que el
# usuario tiene activa AHORA MISMO. Se identifica cada tecla fisica por su
# scanCode de hardware (el mismo valor "universal" que ya usa el gancho de
# bajo nivel para detectar pulsaciones, independiente del idioma), y se le
# pregunta a Windows que caracter le asigna la distribucion activa a esa
# posicion fisica. Asi el teclado en pantalla muestra el simbolo REAL de
# cada tecla sin importar si el usuario tiene Español Latinoamerica, España,
# Ingles EE.UU., u otra distribucion instalada: se detecta sola, no se
# adivina desde una lista fija de idiomas.
$Script:TipoTecladoLayoutListo = $false
function Ensure-TipoTecladoLayoutQuery {
    if ($Script:TipoTecladoLayoutListo) { return }
    $codigo = @"
using System;
using System.Runtime.InteropServices;
using System.Text;

public static class DragonToolTecladoLayout {
    private const uint MAPVK_VSC_TO_VK_EX = 3;

    [DllImport("user32.dll")]
    private static extern uint MapVirtualKeyEx(uint uCode, uint uMapType, IntPtr dwhkl);

    [DllImport("user32.dll")]
    private static extern int ToUnicodeEx(uint wVirtKey, uint wScanCode, byte[] lpKeyState, StringBuilder pwszBuff, int cchBuff, uint wFlags, IntPtr dwhkl);

    private static string Traducir(int scanCode, IntPtr hkl, bool conMayuscula) {
        uint vk = MapVirtualKeyEx((uint)scanCode, MAPVK_VSC_TO_VK_EX, hkl);
        if (vk == 0) { return ""; }
        byte[] estado = new byte[256];
        if (conMayuscula) { estado[0x10] = 0x80; } // VK_SHIFT sostenido
        StringBuilder buffer = new StringBuilder(8);
        int r = ToUnicodeEx(vk, (uint)scanCode, estado, buffer, buffer.Capacity, 0, hkl);
        if (r < 0) {
            // Tecla muerta (acento combinable, como el acento agudo suelto
            // de algunas distribuciones en español): se vuelve a llamar para
            // limpiar el estado interno del driver y no dejarlo "colgado"
            // para la proxima tecla real que el usuario escriba, pero no se
            // muestra ningun simbolo para esta.
            buffer.Clear();
            ToUnicodeEx(vk, (uint)scanCode, estado, buffer, buffer.Capacity, 0, hkl);
            return "";
        }
        if (r <= 0) { return ""; }
        string s = buffer.ToString();
        foreach (char c in s) { if (char.IsControl(c)) { return ""; } }
        return s;
    }

    // Caracter base (sin Shift) que produce la tecla fisica de ese scanCode
    // bajo la distribucion "hkl" indicada.
    public static string ObtenerBase(int scanCode, IntPtr hkl) { return Traducir(scanCode, hkl, false); }

    // Caracter con Shift sostenido (el simbolo de arriba, por ejemplo el "!"
    // sobre el "1") que produce esa misma tecla fisica.
    public static string ObtenerMayus(int scanCode, IntPtr hkl) { return Traducir(scanCode, hkl, true); }
}
"@
    Add-Type -TypeDefinition $codigo -ErrorAction Stop
    $Script:TipoTecladoLayoutListo = $true
}

function Show-PruebaTeclado {
    # El boton "Probar teclado" abre el teclado virtual directamente, sin
    # ningun paso ni ventana de seleccion previa: la distribucion de teclado
    # (que caracter tiene cada tecla) se detecta automaticamente de Windows.
    Iniciar-PruebaTecladoVisual
}

# Pinta una tecla segun su estado: sostenida (amarillo) > mapa de calor >
# probada (azul) > sin probar resaltada (rojo tenue) > color base. Global y
# con todo por parametro porque se llama desde .GetNewClosure().
function Global:Pintar-Tecla {
    param($Ctx, [string]$Nombre)
    if (-not $Ctx.Mapa.ContainsKey($Nombre)) { return }
    $c = $Ctx.Colores
    $pincel = $null
    if ($Ctx.Activas.Contains($Nombre)) {
        $pincel = $c.Mantenida
    } elseif ($Ctx.Modo.Calor -and $Ctx.Conteos.ContainsKey($Nombre)) {
        $maximo = [Math]::Max(1, [int]$Ctx.Est.MaxConteo)
        $t = [Math]::Min(1.0, [double]$Ctx.Conteos[$Nombre] / $maximo)
        # Azul (poco usada) -> rojo (la mas usada)
        $r = [byte][Math]::Round(47 + (255 - 47) * $t)
        $g = [byte][Math]::Round(124 + (70 - 124) * $t)
        $b = [byte][Math]::Round(246 + (60 - 246) * $t)
        $pincel = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromArgb(230, $r, $g, $b))
    } elseif ($Ctx.Probadas.Contains($Nombre)) {
        $pincel = $c.Presionado
    } elseif ($Ctx.Modo.Resaltar) {
        $pincel = $c.SinProbar
    } else {
        $pincel = $c.Base[$Nombre]
    }
    $fondo = Nuevo-FondoTecla -ColorBase $pincel
    foreach ($borde in $Ctx.Mapa[$Nombre]) { $borde.Background = $fondo }
}

function Global:Pintar-TodasTeclas {
    param($Ctx)
    foreach ($k in @($Ctx.Mapa.Keys)) { Pintar-Tecla -Ctx $Ctx -Nombre $k }
}

# Texto con las teclas que aun no se han probado, en el orden del teclado.
function Global:Texto-TeclasFaltantes {
    param($Orden, $Probadas, $Etiquetas, [int]$Maximo = 30)
    $faltan = @(foreach ($k in $Orden) { if (-not $Probadas.Contains($k)) { $Etiquetas[$k] } })
    if ($faltan.Count -eq 0) { return "✔ ¡Todas las teclas fueron probadas!" }
    $lista = @($faltan | Select-Object -First $Maximo) -join "  "
    $extra = if ($faltan.Count -gt $Maximo) { "  … (+$($faltan.Count - $Maximo))" } else { "" }
    return "Sin probar ($($faltan.Count)): $lista$extra"
}

function Global:Formato-DuracionTeclado {
    param([TimeSpan]$T)
    return ('{0:00}:{1:00}' -f [int][Math]::Floor($T.TotalMinutes), $T.Seconds)
}

function Iniciar-PruebaTecladoVisual {
    Write-DiagLog "=== TECLADO (prueba interactiva propia) ==="
    # Se pregunta ANTES de armar la ventana si el teclado tiene bloque
    # numerico: muchas laptops (sobre todo las de 13-14") no lo traen, y
    # mostrarlo igual dejaba un bloque de teclas que esa persona jamas iba a
    # poder probar (siempre se quedaba sin marcar, pareciendo una falla).
    $tieneNumerico = Show-Confirm -Mensaje "¿Tu teclado tiene bloque numerico (el grupo de teclas de numeros aparte, normalmente a la derecha del teclado)?" -Titulo "Prueba de teclado - The Dragon Tool"
    if ($tieneNumerico) {
        Write-DiagLog "Se abrira un teclado virtual completo (con numerico): pulsa teclas fisicas y observa si se iluminan en pantalla."
    } else {
        Write-DiagLog "Se abrira un teclado virtual completo (sin numerico): pulsa teclas fisicas y observa si se iluminan en pantalla."
    }
    try {
        # --- Distribucion, fila por fila ------------------------------------
        # Bloque principal, como el de una laptop real con teclado ISO en
        # español: incluye la tecla adicional "<>" junto al Shift izquierdo
        # (VK_OEM_102), presente en casi toda laptop en español y que antes
        # faltaba por completo en la distribucion de prueba.
        $filas = @(
            @(@{L='Esc';K='Escape'},@{L='F1';K='F1'},@{L='F2';K='F2'},@{L='F3';K='F3'},@{L='F4';K='F4'},@{L='F5';K='F5'},@{L='F6';K='F6'},@{L='F7';K='F7'},@{L='F8';K='F8'},@{L='F9';K='F9'},@{L='F10';K='F10'},@{L='F11';K='F11'},@{L='F12';K='F12'}),
            @(@{L='`';K='OemTilde'},@{L='1';K='D1'},@{L='2';K='D2'},@{L='3';K='D3'},@{L='4';K='D4'},@{L='5';K='D5'},@{L='6';K='D6'},@{L='7';K='D7'},@{L='8';K='D8'},@{L='9';K='D9'},@{L='0';K='D0'},@{L='-';K='OemMinus'},@{L='=';K='OemPlus'},@{L='Backspace';K='Back';W=2}),
            @(@{L='Tab';K='Tab';W=1.5},@{L='Q';K='Q'},@{L='W';K='W'},@{L='E';K='E'},@{L='R';K='R'},@{L='T';K='T'},@{L='Y';K='Y'},@{L='U';K='U'},@{L='I';K='I'},@{L='O';K='O'},@{L='P';K='P'},@{L='[';K='OemOpenBrackets'},@{L=']';K='OemCloseBrackets'},@{L='\';K='OemBackslash';W=1.5}),
            @(@{L='Caps';K='CapsLock';W=1.75},@{L='A';K='A'},@{L='S';K='S'},@{L='D';K='D'},@{L='F';K='F'},@{L='G';K='G'},@{L='H';K='H'},@{L='J';K='J'},@{L='K';K='K'},@{L='L';K='L'},@{L=';';K='OemSemicolon'},@{L="'";K='OemQuotes'},@{L='Enter';K='Return';W=2.25}),
            @(@{L='Shift';K='LeftShift';W=1.25},@{L='<>';K='OemAngleBracket102'},@{L='Z';K='Z'},@{L='X';K='X'},@{L='C';K='C'},@{L='V';K='V'},@{L='B';K='B'},@{L='N';K='N'},@{L='M';K='M'},@{L=',';K='OemComma'},@{L='.';K='OemPeriod'},@{L='/';K='OemQuestion'},@{L='Shift';K='RightShift';W=2.75}),
            @(@{L='Ctrl';K='LeftCtrl';W=1.4},@{L='Win';K='LWin';W=1.2},@{L='Alt';K='LeftAlt';W=1.2},@{L='Espacio';K='Space';W=6},@{L='Alt';K='RightAlt';W=1.2},@{L='Win';K='RWin';W=1.2},@{L='Menu';K='Apps';W=1.2},@{L='Ctrl';K='RightCtrl';W=1.4})
        )

        # Columna de navegacion + flechas, compacta y pegada al bloque
        # principal (como en una laptop de 15-16" con numerico integrado):
        # Ins/Supr, Inicio/Fin y RePag/AvPag en pares de 2 columnas; las
        # flechas en "T invertida" (arriba solo ↑, centrada sobre las otras
        # tres abajo), igual que en una laptop real.
        $filaSistema = @(@{L='PrtScn';K='PrintScreen';W=1.3},@{L='ScrLk';K='Scroll';W=1.3},@{L='Pausa';K='Pause';W=1.3})
        $filaNavGrid1 = @(@{L='Ins';K='Insert'},@{L='Supr';K='Delete'})
        $filaNavGrid2 = @(@{L='Inicio';K='Home'},@{L='Fin';K='End'})
        $filaNavGrid3 = @(@{L='RePag';K='Prior'},@{L='AvPag';K='Next'})
        $filaFlechasArriba = @(@{L='';K=$null},@{L='↑';K='Up'},@{L='';K=$null})
        $filaFlechasAbajo = @(@{L='←';K='Left'},@{L='↓';K='Down'},@{L='→';K='Right'})

        # Bloque numerico completo, pegado a la derecha de la columna de
        # navegacion. El Enter del numerico usa su PROPIO nombre interno
        # (NumPadEnter) en vez de compartir "Return" con el Enter principal:
        # son teclas fisicas distintas y el gancho las distingue por el bit
        # "extendida" (ver Resolver-NombreTeclaFisica), asi que antes de este
        # cambio pulsar solo una de las dos encendia las dos en pantalla.
        $filaNumpad1 = @(@{L='NumLk';K='NumLock'},@{L='Num/';K='Divide'},@{L='Num*';K='Multiply'},@{L='Num-';K='Subtract'})
        $filaNumpad2 = @(@{L='Num7';K='NumPad7'},@{L='Num8';K='NumPad8'},@{L='Num9';K='NumPad9'},@{L='Num+';K='Add'})
        $filaNumpad3 = @(@{L='Num4';K='NumPad4'},@{L='Num5';K='NumPad5'},@{L='Num6';K='NumPad6'})
        $filaNumpad4 = @(@{L='Num1';K='NumPad1'},@{L='Num2';K='NumPad2'},@{L='Num3';K='NumPad3'},@{L='NumEnter';K='NumPadEnter';W=1.4})
        $filaNumpad5 = @(@{L='Num0';K='NumPad0';W=2.1},@{L='Num.';K='Decimal'})

        # --- Deteccion automatica de la distribucion de teclado --------------
        # Se detecta la distribucion realmente activa en Windows (idioma +
        # variante de teclado que el usuario tiene puesta ahora mismo, la
        # misma que usa para escribir) y se le pregunta a Windows, tecla por
        # tecla fisica, que caracter le corresponde a cada una en esa
        # distribucion. Solo se consulta para las teclas que producen un
        # caracter (letras, numeros, simbolos): las de funcion, navegacion,
        # modificadores y numerico no cambian de un idioma a otro y se dejan
        # con su etiqueta fija.
        Ensure-TipoTecladoLayoutQuery
        $idiomaDetectado = [System.Windows.Forms.InputLanguage]::CurrentInputLanguage
        $hklActivo = $idiomaDetectado.Handle
        $nombreDistribucion = "$($idiomaDetectado.Culture.DisplayName) - $($idiomaDetectado.LayoutName)"

        # Mapa de tecla fisica -> scanCode de hardware "Set 1" estandar (el
        # mismo esquema universal que ya usa el gancho de bajo nivel), para
        # cada tecla del bloque principal que produce un caracter.
        $scMapaCaracteres = @{
            'OemTilde'=0x29; 'D1'=0x02; 'D2'=0x03; 'D3'=0x04; 'D4'=0x05; 'D5'=0x06; 'D6'=0x07; 'D7'=0x08; 'D8'=0x09; 'D9'=0x0A; 'D0'=0x0B; 'OemMinus'=0x0C; 'OemPlus'=0x0D
            'Q'=0x10; 'W'=0x11; 'E'=0x12; 'R'=0x13; 'T'=0x14; 'Y'=0x15; 'U'=0x16; 'I'=0x17; 'O'=0x18; 'P'=0x19; 'OemOpenBrackets'=0x1A; 'OemCloseBrackets'=0x1B; 'OemBackslash'=0x2B
            'A'=0x1E; 'S'=0x1F; 'D'=0x20; 'F'=0x21; 'G'=0x22; 'H'=0x23; 'J'=0x24; 'K'=0x25; 'L'=0x26; 'OemSemicolon'=0x27; 'OemQuotes'=0x28
            'OemAngleBracket102'=0x56; 'Z'=0x2C; 'X'=0x2D; 'C'=0x2E; 'V'=0x2F; 'B'=0x30; 'N'=0x31; 'M'=0x32; 'OemComma'=0x33; 'OemPeriod'=0x34; 'OemQuestion'=0x35
        }
        $teclasSoloLetra = @('Q','W','E','R','T','Y','U','I','O','P','A','S','D','F','G','H','J','K','L','Z','X','C','V','B','N','M')
        foreach ($fila in $filas) {
            foreach ($tecla in $fila) {
                if (-not $scMapaCaracteres.ContainsKey($tecla.K)) { continue }
                $sc = $scMapaCaracteres[$tecla.K]
                $base = [DragonToolTecladoLayout]::ObtenerBase($sc, $hklActivo)
                if (-not $base) { continue }   # Sin caracter en esta distribucion: se deja la etiqueta original.
                if ($teclasSoloLetra -contains $tecla.K) {
                    # Las letras solo muestran su caracter en mayuscula, como
                    # en un teclado real (no hace falta mostrar tambien el
                    # shift, que es la misma letra en mayuscula).
                    $tecla.L = $base.ToUpperInvariant()
                } else {
                    $mayus = [DragonToolTecladoLayout]::ObtenerMayus($sc, $hklActivo)
                    if ($mayus -and $mayus -ne $base) {
                        # Simbolo de Shift arriba, caracter base abajo, igual
                        # que se ve impreso en una tecla fisica real.
                        $tecla.L = "$mayus`n$base"
                    } else {
                        $tecla.L = $base
                    }
                }
            }
        }

        Ensure-TipoTecladoHook

        # --- Ventana ---------------------------------------------------------
        [xml]$xamlTec = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Prueba de teclado - The Dragon Tool" SizeToContent="WidthAndHeight" MinWidth="900" MinHeight="440" WindowStartupLocation="CenterScreen" Background="#10141D">
  <Window.Resources>$($Global:RecursosNeonXaml)</Window.Resources>
  <DockPanel Margin="16">
    <Button x:Name="BtnVolverVentana" DockPanel.Dock="Top" Content="⬅  Volver" Width="110" Height="34" HorizontalAlignment="Left" Margin="0,0,0,10"/>
    <TextBlock DockPanel.Dock="Top" Text="Pulsa las teclas de tu teclado fisico; se iluminaran aqui en tiempo real. Azul = tecla ya probada. Amarillo = la tecla sigue sostenida ahora mismo." Foreground="White" Margin="0,0,0,6" TextWrapping="Wrap"/>
    <TextBlock x:Name="TxtDistribucion" DockPanel.Dock="Top" Text="Distribucion detectada: (detectando...)" Foreground="#C9A6FF" FontSize="11" Margin="0,0,0,8" TextWrapping="Wrap"/>
    <TextBlock x:Name="TxtUltimaTecla" DockPanel.Dock="Top" Text="Ultima tecla: (ninguna)" Foreground="#66AEFF" FontWeight="Bold" Margin="0,0,0,4"/>
    <TextBlock x:Name="TxtProbadas" DockPanel.Dock="Top" Text="Teclas probadas: 0 / 0" Foreground="#8FE38F" FontWeight="Bold" Margin="0,0,0,4"/>
    <TextBlock x:Name="TxtCodigoEspecial" DockPanel.Dock="Top" Text="Ultimo codigo detectado: (ninguno)" Foreground="#7C93BD" FontSize="11" Margin="0,0,0,6"/>
    <TextBlock x:Name="TxtRebotes" DockPanel.Dock="Top" Text="" Foreground="#FF6B6B" FontWeight="Bold" Margin="0,0,0,6" TextWrapping="Wrap"/>
    <Border DockPanel.Dock="Top" Background="#33000000" BorderBrush="#30FFFFFF" BorderThickness="1" CornerRadius="10" Padding="12,8" Margin="0,0,0,8">
      <WrapPanel>
        <StackPanel Margin="0,0,26,4"><TextBlock Text="PULSACIONES" FontSize="10" Foreground="#7C93BD"/><TextBlock x:Name="StatTotal" Text="0" Foreground="White" FontWeight="Bold" FontSize="17"/></StackPanel>
        <StackPanel Margin="0,0,26,4"><TextBlock Text="SIMULTANEAS (AHORA / MAX)" FontSize="10" Foreground="#7C93BD"/><TextBlock x:Name="StatSimult" Text="0 / 0" Foreground="White" FontWeight="Bold" FontSize="17"/></StackPanel>
        <StackPanel Margin="0,0,26,4"><TextBlock Text="PICO (PULSACIONES/SEG)" FontSize="10" Foreground="#7C93BD"/><TextBlock x:Name="StatPps" Text="0" Foreground="White" FontWeight="Bold" FontSize="17"/></StackPanel>
        <StackPanel Margin="0,0,26,4"><TextBlock Text="PULSACION MEDIA" FontSize="10" Foreground="#7C93BD"/><TextBlock x:Name="StatHold" Text="-" Foreground="White" FontWeight="Bold" FontSize="17"/></StackPanel>
        <StackPanel Margin="0,0,26,4"><TextBlock Text="TECLA MAS USADA" FontSize="10" Foreground="#7C93BD"/><TextBlock x:Name="StatTop" Text="-" Foreground="White" FontWeight="Bold" FontSize="17"/></StackPanel>
        <StackPanel Margin="0,0,26,4"><TextBlock Text="TIEMPO DE PRUEBA" FontSize="10" Foreground="#7C93BD"/><TextBlock x:Name="StatTiempo" Text="00:00" Foreground="White" FontWeight="Bold" FontSize="17"/></StackPanel>
        <StackPanel Margin="0,0,0,4"><TextBlock Text="INDICADORES" FontSize="10" Foreground="#7C93BD"/>
          <StackPanel Orientation="Horizontal">
            <TextBlock x:Name="LedCaps" Text="● Mayus  " Foreground="#556070" FontWeight="Bold" FontSize="13"/>
            <TextBlock x:Name="LedNum" Text="● Num  " Foreground="#556070" FontWeight="Bold" FontSize="13"/>
            <TextBlock x:Name="LedScroll" Text="● Despl" Foreground="#556070" FontWeight="Bold" FontSize="13"/>
          </StackPanel></StackPanel>
      </WrapPanel>
    </Border>
    <TextBlock x:Name="TxtMantenidas" DockPanel.Dock="Top" Text="Sostenidas ahora: (ninguna)  |  Mayor combinacion simultanea: (ninguna)" Foreground="#F5C518" FontSize="12" Margin="0,0,0,4" TextWrapping="Wrap"/>
    <TextBlock x:Name="TxtFaltan" DockPanel.Dock="Top" Text="" Foreground="#FFB86B" FontSize="12" Margin="0,0,0,6" TextWrapping="Wrap"/>
    <WrapPanel DockPanel.Dock="Top" Margin="0,0,0,8">
      <CheckBox x:Name="ChkCalor" Content="🔥 Mapa de calor (teclas mas usadas)" Foreground="White" Margin="0,0,22,0" VerticalContentAlignment="Center"/>
      <CheckBox x:Name="ChkSinProbar" Content="🎯 Resaltar teclas sin probar" Foreground="White" VerticalContentAlignment="Center"/>
    </WrapPanel>
    <StackPanel DockPanel.Dock="Bottom" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,14,0,0">
      <Button x:Name="BtnReporteRebotes" Content="Reporte completo" Width="150" Margin="0,0,8,0"/>
      <Button x:Name="BtnReiniciarTeclado" Content="Reiniciar prueba" Width="130" Margin="0,0,8,0"/>
      <Button x:Name="BtnCerrarTeclado" Content="Cerrar" Width="100"/>
    </StackPanel>
    <StackPanel x:Name="PanelTeclado" Orientation="Horizontal" HorizontalAlignment="Center" VerticalAlignment="Center"/>
  </DockPanel>
</Window>
"@
        $readerTec = New-Object System.Xml.XmlNodeReader $xamlTec
        $winTec = [Windows.Markup.XamlReader]::Load($readerTec)
        Iniciar-EfectosNeon -Ventana $winTec
        $panelTeclado = $winTec.FindName("PanelTeclado")
        $txtDistribucion = $winTec.FindName("TxtDistribucion")
        $txtUltimaTecla = $winTec.FindName("TxtUltimaTecla")
        $txtProbadas = $winTec.FindName("TxtProbadas")
        $txtCodigoEspecial = $winTec.FindName("TxtCodigoEspecial")
        $txtRebotes = $winTec.FindName("TxtRebotes")
        $statTotal = $winTec.FindName("StatTotal")
        $statSimult = $winTec.FindName("StatSimult")
        $statPps = $winTec.FindName("StatPps")
        $statHold = $winTec.FindName("StatHold")
        $statTop = $winTec.FindName("StatTop")
        $statTiempo = $winTec.FindName("StatTiempo")
        $ledCaps = $winTec.FindName("LedCaps")
        $ledNum = $winTec.FindName("LedNum")
        $ledScroll = $winTec.FindName("LedScroll")
        $txtMantenidas = $winTec.FindName("TxtMantenidas")
        $txtFaltan = $winTec.FindName("TxtFaltan")
        $chkCalor = $winTec.FindName("ChkCalor")
        $chkSinProbar = $winTec.FindName("ChkSinProbar")
        $txtDistribucion.Text = "Distribucion de teclado detectada: $nombreDistribucion"

        $mapaTeclas = @{}
        $mapaColorBase = @{}
        $etiquetasTecla = @{}
        $ordenTeclas = New-Object 'System.Collections.Generic.List[string]'
        # Colores con canal alfa (2 primeros digitos del hex) para el efecto
        # de "vidrio esmerilado": se deja ver un poco el fondo de la tarjeta
        # detras de cada tecla en vez de un color solido plano.
        $colorNormal = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#CC181F2E")
        $colorAcento = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#CC212B45")
        $colorPresionado = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#E62F7CF6")
        $colorMantenida = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#E6F5C518")
        $bordeNormal = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#40FFFFFF")

        # --- Funciones auxiliares --------------------------------------------
        # Nuevo-FondoTecla e Iluminar-Tecla se declaran Global: y reciben TODO
        # por parametro (nada de closures sobre variables externas) porque se
        # llaman tanto desde codigo normal como desde dentro de scriptblocks
        # .GetNewClosure() (el timer del gancho de teclado, el boton de
        # reinicio). .GetNewClosure() desconecta el scriptblock de la funcion
        # que lo creo: solo arrastra el VALOR de las variables locales
        # capturadas, nunca las funciones normales del scope padre. Llamar a
        # una funcion normal (no Global) desde dentro de un .GetNewClosure()
        # falla en silencio ("no se reconoce como nombre de cmdlet"): asi fue
        # como en una version anterior de esta prueba ninguna tecla se
        # iluminaba pese a que el gancho si detectaba cada pulsacion.
        function Global:Nuevo-FondoTecla {
            param($ColorBase)
            $degradado = New-Object System.Windows.Media.LinearGradientBrush
            $degradado.StartPoint = [System.Windows.Point]::new(0, 0)
            $degradado.EndPoint = [System.Windows.Point]::new(0, 1)
            $paradaClara = New-Object System.Windows.Media.GradientStop
            # Usa el mismo canal alfa del color base (no 255 fijo) para que el
            # degradado mantenga el efecto de vidrio en toda la tecla.
            $paradaClara.Color = [System.Windows.Media.Color]::FromArgb($ColorBase.Color.A, [Math]::Min(255, $ColorBase.Color.R + 18), [Math]::Min(255, $ColorBase.Color.G + 18), [Math]::Min(255, $ColorBase.Color.B + 20))
            $paradaClara.Offset = 0
            $paradaOscura = New-Object System.Windows.Media.GradientStop
            $paradaOscura.Color = $ColorBase.Color
            $paradaOscura.Offset = 1
            $degradado.GradientStops.Add($paradaClara) | Out-Null
            $degradado.GradientStops.Add($paradaOscura) | Out-Null
            return $degradado
        }

        function Global:Iluminar-Tecla {
            # Azul (colorPresionado) = tecla ya probada (se pulso al menos una vez).
            # Amarillo (colorMantenida) = la tecla sigue sostenida en este momento.
            param($MapaTeclas, [string]$NombreTecla, $Color)
            if ($MapaTeclas.ContainsKey($NombreTecla)) {
                foreach ($b in $MapaTeclas[$NombreTecla]) { $b.Background = $Color }
            }
        }

        # Traduce un codigo VK (+ scanCode + bit "extendida") del gancho de
        # bajo nivel al nombre interno de tecla que usamos como clave en
        # $mapaTeclas. Global: y sin depender de nada del scope externo
        # (mismo motivo que las funciones de arriba: se llama desde dentro de
        # .GetNewClosure()). KeyInterop.KeyFromVirtualKey() por si solo NO
        # basta para identificar todas las teclas fisicas, por 4 motivos
        # reales de Windows:
        #  - Shift: el gancho de bajo nivel reporta SIEMPRE el VK generico
        #    (0x10) tanto para el Shift izquierdo como el derecho; solo el
        #    scanCode los diferencia (0x2A=izquierdo, 0x36=derecho).
        #  - Numerico: las teclas 7,8,9,4,5,6,1,2,3,0,. cambian de VK segun
        #    el estado de Bloq Num (con Bloq Num apagado mandan el mismo VK
        #    que Inicio/Fin/RePag/AvPag/flechas/Supr). El scanCode de esas
        #    teclas fisicas nunca cambia, y el bit "extendida" (presente
        #    siempre en las teclas de navegacion reales y nunca en las del
        #    numerico) permite distinguirlas sin importar Bloq Num.
        #  - Enter: el Enter principal y el del numerico comparten el mismo
        #    VK (0x0D); el del numerico siempre llega marcado como
        #    "extendida" y el principal nunca, asi que el bit "extendida" los
        #    separa en dos teclas fisicas distintas (Return / NumPadEnter).
        #  - Tecla "<>" adicional (VK_OEM_102, 0xE2): presente en casi toda
        #    laptop en español junto al Shift izquierdo; se resuelve aparte
        #    porque KeyInterop no siempre la reconoce.
        function Global:Resolver-NombreTeclaFisica {
            # Traduce un scanCode de hardware (+ el bit "extendida") del
            # gancho de bajo nivel al nombre interno de tecla fisica que
            # usamos como clave en $mapaTeclas. USA EL SCANCODE COMO FUENTE
            # PRINCIPAL DE VERDAD, NO el VK. Motivo real (el motivo por el
            # que "algunas teclas" seguian sin marcar en algunas maquinas):
            # el VK de las letras y numeros SI es fijo por posicion sin
            # importar la distribucion de teclado activa, pero el VK de las
            # teclas OEM/simbolos (guion, igual, corchetes, punto y coma,
            # comillas, acento, coma, punto, barra, barra invertida, etc.)
            # LO ASIGNA CADA DISTRIBUCION DE TECLADO A SU MANERA: Español
            # (Latinoamerica), Español (España) e Ingles (EE.UU.) pueden
            # asignarle un VK distinto a la MISMA posicion fisica. Antes
            # esta funcion resolvia esas teclas con
            # KeyInterop.KeyFromVirtualKey(vk), que en una distribucion
            # distinta a la que se probo podia devolver un nombre que no
            # coincidia con ninguna tecla del layout, y esa tecla fisica
            # nunca se iluminaba aunque el gancho si la detectara. El
            # scanCode identifica la posicion fisica de la tecla sin
            # importar que caracter o VK le asigne la distribucion activa,
            # asi que es la unica forma fiable de que CADA tecla marque sin
            # importar el idioma/distribucion de teclado que tenga el
            # usuario. De paso, esto resuelve de forma mas directa (con dos
            # tablas separadas por el bit "extendida") los mismos casos que
            # antes se manejaban con reglas sueltas: Shift/Ctrl/Alt
            # izquierdo-derecho, Enter principal vs Enter del numerico, y el
            # numerico sin importar el estado de Bloq Num.
            param([int]$Vk, [int]$Sc, [bool]$EsExtendida)

            # Caso especial: la tecla Pausa manda una secuencia de scanCode
            # muy irregular en el hardware real (distinta a todas las demas
            # teclas) que en algunos equipos puede llegar a coincidir con el
            # scanCode de Bloq Num; su VK (0x13) en cambio es fijo y no
            # depende de la distribucion, asi que se resuelve aparte antes
            # de consultar la tabla de scanCodes.
            if ($Vk -eq 0x13) { return 'Pause' }

            $scNormal = @{
                0x01='Escape'
                0x02='D1'; 0x03='D2'; 0x04='D3'; 0x05='D4'; 0x06='D5'; 0x07='D6'; 0x08='D7'; 0x09='D8'; 0x0A='D9'; 0x0B='D0'
                0x0C='OemMinus'; 0x0D='OemPlus'; 0x0E='Back'
                0x0F='Tab'; 0x10='Q'; 0x11='W'; 0x12='E'; 0x13='R'; 0x14='T'; 0x15='Y'; 0x16='U'; 0x17='I'; 0x18='O'; 0x19='P'
                0x1A='OemOpenBrackets'; 0x1B='OemCloseBrackets'; 0x1C='Return'
                0x1D='LeftCtrl'
                0x1E='A'; 0x1F='S'; 0x20='D'; 0x21='F'; 0x22='G'; 0x23='H'; 0x24='J'; 0x25='K'; 0x26='L'
                0x27='OemSemicolon'; 0x28='OemQuotes'; 0x29='OemTilde'
                0x2A='LeftShift'
                0x2B='OemBackslash'
                0x2C='Z'; 0x2D='X'; 0x2E='C'; 0x2F='V'; 0x30='B'; 0x31='N'; 0x32='M'
                0x33='OemComma'; 0x34='OemPeriod'; 0x35='OemQuestion'
                0x36='RightShift'
                0x37='Multiply'
                0x38='LeftAlt'
                0x39='Space'
                0x3A='CapsLock'
                0x3B='F1'; 0x3C='F2'; 0x3D='F3'; 0x3E='F4'; 0x3F='F5'; 0x40='F6'; 0x41='F7'; 0x42='F8'; 0x43='F9'; 0x44='F10'
                0x45='NumLock'
                0x46='Scroll'
                0x47='NumPad7'; 0x48='NumPad8'; 0x49='NumPad9'; 0x4A='Subtract'
                0x4B='NumPad4'; 0x4C='NumPad5'; 0x4D='NumPad6'; 0x4E='Add'
                0x4F='NumPad1'; 0x50='NumPad2'; 0x51='NumPad3'; 0x52='NumPad0'; 0x53='Decimal'
                0x56='OemAngleBracket102'
                0x57='F11'; 0x58='F12'
            }
            $scExtendida = @{
                0x1C='NumPadEnter'; 0x1D='RightCtrl'; 0x35='Divide'; 0x37='PrintScreen'; 0x38='RightAlt'
                0x47='Home'; 0x48='Up'; 0x49='Prior'; 0x4B='Left'; 0x4D='Right'; 0x4F='End'; 0x50='Down'; 0x51='Next'
                0x52='Insert'; 0x53='Delete'; 0x5B='LWin'; 0x5C='RWin'; 0x5D='Apps'
            }

            $tabla = if ($EsExtendida) { $scExtendida } else { $scNormal }
            if ($tabla.ContainsKey($Sc)) { return $tabla[$Sc] }

            # Red de seguridad por si llega una tecla fuera de la tabla de
            # arriba (por ejemplo una tecla multimedia de algun fabricante):
            # se intenta resolver por VK como ultimo recurso.
            try {
                $claveEnum = [System.Windows.Input.KeyInterop]::KeyFromVirtualKey($Vk)
                if ($claveEnum -ne [System.Windows.Input.Key]::None) { return $claveEnum.ToString() }
            } catch {}
            return $null
        }

        function Agregar-FilaTeclado {
            # No es Global: solo se llama de forma sincrona mientras se arma
            # el teclado (nunca desde dentro de un .GetNewClosure()), asi que
            # puede quedarse como funcion normal.
            # $Estilo 'acento' tine las teclas que no son letras/numeros
            # (funcion, modificadores, flechas, navegacion, operadores del
            # numerico) para que la distribucion se lea mejor de un vistazo.
            param($Fila, $Panel, $Estilo = 'normal')
            $filaPanel = New-Object System.Windows.Controls.StackPanel
            $filaPanel.Orientation = "Horizontal"
            $filaPanel.HorizontalAlignment = "Center"
            $filaPanel.Margin = "0,3,0,3"
            $colorBase = if ($Estilo -eq 'acento') { $colorAcento } else { $colorNormal }
            foreach ($tecla in $Fila) {
                $ancho = 46
                if ($tecla.W) { $ancho = 46 * [double]$tecla.W }
                $border = New-Object System.Windows.Controls.Border
                $border.Width = $ancho
                $border.Height = 40
                $border.Margin = "2.5"
                if ($null -eq $tecla.K) {
                    # Celda vacia (espaciador invisible): solo se usa para armar
                    # la forma de "T invertida" de las flechas, como en una
                    # laptop real (la flecha arriba queda centrada sobre "abajo").
                    $border.Background = [System.Windows.Media.Brushes]::Transparent
                    $filaPanel.Children.Add($border) | Out-Null
                    continue
                }
                $border.CornerRadius = 14
                $border.Background = Nuevo-FondoTecla -ColorBase $colorBase
                $border.BorderBrush = $bordeNormal
                $border.BorderThickness = 1.2
                $sombra = New-Object System.Windows.Media.Effects.DropShadowEffect
                $sombra.Color = [System.Windows.Media.Colors]::Black
                $sombra.Direction = 270
                $sombra.ShadowDepth = 1.5
                $sombra.BlurRadius = 5
                $sombra.Opacity = 0.4
                $border.Effect = $sombra
                $txt = New-Object System.Windows.Controls.TextBlock
                $txt.Text = $tecla.L
                $txt.Foreground = [System.Windows.Media.Brushes]::White
                $txt.FontSize = 11
                $txt.FontWeight = "SemiBold"
                $txt.HorizontalAlignment = "Center"
                $txt.VerticalAlignment = "Center"
                $txt.TextAlignment = "Center"
                $border.Child = $txt
                $filaPanel.Children.Add($border) | Out-Null
                # Se guarda una LISTA de bordes por cada tecla (no un solo
                # borde): es una red de seguridad por si en el futuro dos
                # teclas fisicas distintas volvieran a compartir el mismo
                # nombre resuelto (como pasaba antes con Enter/NumEnter); con
                # una lista se iluminan todos los bordes que correspondan.
                if (-not $mapaTeclas.ContainsKey($tecla.K)) {
                    $mapaTeclas[$tecla.K] = New-Object System.Collections.Generic.List[object]
                    $ordenTeclas.Add($tecla.K)
                    $etiquetasTecla[$tecla.K] = (("$($tecla.L)" -split "`n")[-1])
                }
                $mapaTeclas[$tecla.K].Add($border) | Out-Null
                $mapaColorBase[$tecla.K] = $colorBase
            }
            $Panel.Children.Add($filaPanel) | Out-Null
        }

        function Nueva-Tarjeta {
            # No es Global: se llama de forma sincrona mientras se arma el
            # teclado, nunca desde dentro de un .GetNewClosure().
            param($Contenido)
            $tarjeta = New-Object System.Windows.Controls.Border
            $tarjeta.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#D9141A28")
            $tarjeta.BorderBrush = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#40FFFFFF")
            $tarjeta.BorderThickness = 1
            $tarjeta.CornerRadius = 20
            $tarjeta.Padding = 18
            $sombraTarjeta = New-Object System.Windows.Media.Effects.DropShadowEffect
            $sombraTarjeta.Color = [System.Windows.Media.Colors]::Black
            $sombraTarjeta.Direction = 270
            $sombraTarjeta.ShadowDepth = 2
            $sombraTarjeta.BlurRadius = 10
            $sombraTarjeta.Opacity = 0.35
            $tarjeta.Effect = $sombraTarjeta
            $tarjeta.Child = $Contenido
            return $tarjeta
        }

        # --- Construccion del teclado -----------------------------------------
        # Todo el teclado (bloque principal + navegacion/flechas + numerico)
        # se arma dentro de UNA sola tarjeta, pegado entre si, para que se
        # vea como el cuerpo compacto de una laptop real con numerico
        # integrado. La fila de funcion y la de modificadores/espacio llevan
        # el color de acento para resaltar, como en un teclado real.
        $panelPrincipal = New-Object System.Windows.Controls.StackPanel
        for ($i = 0; $i -lt $filas.Count; $i++) {
            $estiloFila = if ($i -eq 0 -or $i -eq ($filas.Count - 1)) { 'acento' } else { 'normal' }
            Agregar-FilaTeclado -Fila $filas[$i] -Panel $panelPrincipal -Estilo $estiloFila
        }

        $panelNavFlechas = New-Object System.Windows.Controls.StackPanel
        $panelNavFlechas.Margin = "14,0,0,0"
        $panelNavFlechas.VerticalAlignment = "Top"
        Agregar-FilaTeclado -Fila $filaSistema -Panel $panelNavFlechas -Estilo 'acento'
        Agregar-FilaTeclado -Fila $filaNavGrid1 -Panel $panelNavFlechas -Estilo 'acento'
        Agregar-FilaTeclado -Fila $filaNavGrid2 -Panel $panelNavFlechas -Estilo 'acento'
        Agregar-FilaTeclado -Fila $filaNavGrid3 -Panel $panelNavFlechas -Estilo 'acento'
        $espaciadorFlechas = New-Object System.Windows.Controls.Border
        $espaciadorFlechas.Height = 14
        $panelNavFlechas.Children.Add($espaciadorFlechas) | Out-Null
        Agregar-FilaTeclado -Fila $filaFlechasArriba -Panel $panelNavFlechas -Estilo 'acento'
        Agregar-FilaTeclado -Fila $filaFlechasAbajo -Panel $panelNavFlechas -Estilo 'acento'

        # El bloque numerico solo se arma y se agrega si el usuario confirmo
        # que su teclado lo trae: si no, ni se dibuja ni sus teclas se
        # registran en $mapaTeclas, para que no quede un bloque muerto que
        # nunca se puede marcar ni cuente en el contador de "teclas probadas".
        if ($tieneNumerico) {
            $panelNumerico = New-Object System.Windows.Controls.StackPanel
            $panelNumerico.Margin = "14,0,0,0"
            $panelNumerico.VerticalAlignment = "Top"
            Agregar-FilaTeclado -Fila $filaNumpad1 -Panel $panelNumerico -Estilo 'acento'
            foreach ($fila in @($filaNumpad2, $filaNumpad3, $filaNumpad4, $filaNumpad5)) {
                Agregar-FilaTeclado -Fila $fila -Panel $panelNumerico -Estilo 'normal'
            }
        }

        $panelConjunto = New-Object System.Windows.Controls.StackPanel
        $panelConjunto.Orientation = "Horizontal"
        $panelConjunto.Children.Add($panelPrincipal) | Out-Null
        $panelConjunto.Children.Add($panelNavFlechas) | Out-Null
        if ($tieneNumerico) { $panelConjunto.Children.Add($panelNumerico) | Out-Null }
        $panelTeclado.Children.Add((Nueva-Tarjeta -Contenido $panelConjunto)) | Out-Null

        $totalTeclas = $mapaTeclas.Keys.Count
        $txtProbadas.Text = "Teclas probadas: 0 / $totalTeclas"

        # --- Deteccion ----------------------------------------------------
        [DragonToolTecladoHook]::Limpiar()
        [DragonToolTecladoHook]::Instalar()
        # $teclasActivas guarda el NOMBRE resuelto (no el VK crudo) de las
        # teclas sostenidas ahora mismo. Usar el nombre resuelto evita que
        # dos teclas fisicas distintas que comparten VK (por ejemplo Shift
        # izquierdo/derecho, ambas VK 0x10) se confundan entre si al sostener
        # una y pulsar la otra: con el VK crudo, sostener la izquierda y
        # tocar la derecha marcaba la derecha como "ya sostenida" sin nunca
        # mostrarla en azul ni contarla como probada.
        $teclasActivas = New-Object 'System.Collections.Generic.HashSet[string]'
        $teclasProbadas = New-Object 'System.Collections.Generic.HashSet[string]'

        # --- Deteccion de "rebote" (fallo de hardware) ------------------
        # Un interruptor de tecla desgastado o con suciedad puede mandar la
        # señal de pulsacion DOS (o mas) veces por cada pulsada fisica real.
        # Se detecta comparando, para cada tecla, cuanto tiempo real de
        # hardware paso entre que se SOLTO y que se volvio a PULSAR: nadie
        # suelta y vuelve a presionar la misma tecla a proposito en unos
        # pocos milisegundos, asi que un intervalo menor a $umbralReboteMs
        # casi siempre significa que fue el mismo contacto fisico "rebotando"
        # electricamente, no dos pulsaciones reales de la persona. Se usa la
        # marca de tiempo que manda el propio driver del teclado (no el
        # momento en que PowerShell procesa la cola), para que sea precisa
        # de verdad sin importar cada cuanto corre este timer.
        $umbralReboteMs = 80
        $ultimoLevantadaMs = @{}
        $registroRebotes = @{}

        # --- Estadisticas en vivo (todo en objetos por referencia: dentro de
        # los closures no se pueden reasignar variables simples) --------------
        $est = @{ Total = 0; MaxSimult = 0; MaxSimultNombres = ''; PicoPps = 0; MaxConteo = 0; TopTecla = ''; SumaHold = [int64]0; NHold = 0; Inicio = [DateTime]::Now }
        $conteos = @{}
        $bajadaMs = @{}
        $colaPps = New-Object 'System.Collections.Generic.Queue[int64]'
        $modo = @{ Calor = $false; Resaltar = $false }
        $pincelSinProbar = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#CC6B2430")
        $colores = @{ Mantenida = $colorMantenida; Presionado = $colorPresionado; SinProbar = $pincelSinProbar; Base = $mapaColorBase }
        $ctx = @{ Mapa = $mapaTeclas; Conteos = $conteos; Probadas = $teclasProbadas; Activas = $teclasActivas; Modo = $modo; Colores = $colores; Est = $est }
        $pincelLedOn = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#4CE08A")
        $pincelLedOff = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#556070")
        $txtFaltan.Text = "Sin probar: $totalTeclas teclas (pulsa cada tecla de tu teclado)"

        $timerEspecial = New-Object System.Windows.Threading.DispatcherTimer
        $timerEspecial.Interval = [TimeSpan]::FromMilliseconds(50)
        $timerEspecial.Add_Tick({
            $datos = $null
            $huboEventos = $false
            $nuevaProbada = $false
            $maxCambio = $false
            while ($null -ne ($datos = [DragonToolTecladoHook]::SacarSiguiente())) {
                $vk = [int]$datos[0]
                $sc = [int]$datos[1]
                $flags = [int]$datos[2]
                $esExtendida = (($flags -band 0x01) -eq 0x01)
                $esBajada = ([int]$datos[3] -eq 1)
                $tiempo = [uint32]$datos[4]
                # Se iluminan las teclas usando el gancho global de bajo
                # nivel, nunca los eventos KeyDown/KeyUp propios de WPF: la
                # ventana de la prueba no siempre queda como ventana activa
                # de Windows (grabacion de pantalla, otra ventana encima, el
                # foco quedandose en la consola de PowerShell, etc), y en
                # esos casos WPF nunca recibe el evento de teclado aunque el
                # gancho global si detecta cada pulsacion. El gancho no
                # depende del foco, asi que es la unica fuente de verdad.
                $nombreTecla = Resolver-NombreTeclaFisica -Vk $vk -Sc $sc -EsExtendida $esExtendida
                if ($nombreTecla -and $mapaTeclas.ContainsKey($nombreTecla)) {
                    $huboEventos = $true
                    if ($esBajada) {
                        if ($teclasActivas.Contains($nombreTecla)) {
                            Pintar-Tecla -Ctx $ctx -Nombre $nombreTecla
                        } else {
                            # Rebote: esta misma tecla ya estaba SUELTA (no
                            # sostenida) y se acaba de soltar hace muy poco.
                            if ($ultimoLevantadaMs.ContainsKey($nombreTecla)) {
                                $intervalo = $tiempo - $ultimoLevantadaMs[$nombreTecla]
                                if ($intervalo -lt $umbralReboteMs) {
                                    if (-not $registroRebotes.ContainsKey($nombreTecla)) {
                                        $registroRebotes[$nombreTecla] = [PSCustomObject]@{ Conteo = 0; MenorIntervalo = $umbralReboteMs }
                                    }
                                    $registroRebotes[$nombreTecla].Conteo++
                                    if ($intervalo -lt $registroRebotes[$nombreTecla].MenorIntervalo) {
                                        $registroRebotes[$nombreTecla].MenorIntervalo = $intervalo
                                    }
                                    $nombresConRebote = ($registroRebotes.Keys | Sort-Object) -join ", "
                                    $txtRebotes.Text = "Posible falla de hardware (rebote) detectada en: $nombresConRebote -- usa 'Reporte de errores' para ver el detalle."
                                }
                            }
                            $teclasActivas.Add($nombreTecla) | Out-Null
                            if ($teclasProbadas.Add($nombreTecla)) {
                                $txtProbadas.Text = "Teclas probadas: $($teclasProbadas.Count) / $totalTeclas"
                                $nuevaProbada = $true
                            }
                            # Estadisticas: total, conteo por tecla, tecla mas usada,
                            # pulsaciones por segundo (ventana de 1 s con la hora del
                            # hardware), teclas simultaneas (rollover).
                            $est.Total = $est.Total + 1
                            $conteos[$nombreTecla] = 1 + [int]$conteos[$nombreTecla]
                            if ($conteos[$nombreTecla] -gt $est.MaxConteo) {
                                $est.MaxConteo = $conteos[$nombreTecla]
                                $est.TopTecla = $nombreTecla
                                $maxCambio = $true
                            }
                            $bajadaMs[$nombreTecla] = [int64]$tiempo
                            $colaPps.Enqueue([int64]$tiempo)
                            while ($colaPps.Count -gt 0 -and (([int64]$tiempo - $colaPps.Peek()) -gt 1000)) { [void]$colaPps.Dequeue() }
                            if ($colaPps.Count -gt $est.PicoPps) { $est.PicoPps = $colaPps.Count }
                            if ($teclasActivas.Count -gt $est.MaxSimult) {
                                $est.MaxSimult = $teclasActivas.Count
                                $est.MaxSimultNombres = (@($teclasActivas | ForEach-Object { $etiquetasTecla[$_] }) -join ' + ')
                            }
                            $textoTip = "$($etiquetasTecla[$nombreTecla]): $($conteos[$nombreTecla]) pulsaciones"
                            foreach ($bordeTip in $mapaTeclas[$nombreTecla]) { $bordeTip.ToolTip = $textoTip }
                            if ($modo.Calor -and $maxCambio) { Pintar-TodasTeclas -Ctx $ctx } else { Pintar-Tecla -Ctx $ctx -Nombre $nombreTecla }
                        }
                        $txtUltimaTecla.Text = "Ultima tecla detectada: $nombreTecla"
                    } else {
                        $teclasActivas.Remove($nombreTecla) | Out-Null
                        $ultimoLevantadaMs[$nombreTecla] = $tiempo
                        if ($bajadaMs.ContainsKey($nombreTecla)) {
                            $durHold = [int64]$tiempo - [int64]$bajadaMs[$nombreTecla]
                            if ($durHold -ge 0 -and $durHold -lt 2000) {
                                $est.SumaHold = $est.SumaHold + $durHold
                                $est.NHold = $est.NHold + 1
                            }
                            $bajadaMs.Remove($nombreTecla)
                        }
                        Pintar-Tecla -Ctx $ctx -Nombre $nombreTecla
                    }
                }
                if ($txtCodigoEspecial) {
                    $estadoTxt = if ($esBajada) { "pulsada" } else { "liberada" }
                    $txtCodigoEspecial.Text = "Ultimo codigo detectado: VK=0x$('{0:X2}' -f $vk) ($vk)  ScanCode=0x$('{0:X2}' -f $sc) ($sc)  [$estadoTxt]"
                }
            }
            if ($huboEventos) {
                $statTotal.Text = "$($est.Total)"
                $statSimult.Text = "$($teclasActivas.Count) / $($est.MaxSimult)"
                $statPps.Text = "$($est.PicoPps)"
                if ($est.NHold -gt 0) { $statHold.Text = "$([int]($est.SumaHold / $est.NHold)) ms" }
                if ($est.TopTecla) { $statTop.Text = "$($etiquetasTecla[$est.TopTecla]) ($($est.MaxConteo))" }
                $sostenidas = @($teclasActivas | ForEach-Object { $etiquetasTecla[$_] }) -join ' + '
                if (-not $sostenidas) { $sostenidas = '(ninguna)' }
                $mayor = if ($est.MaxSimultNombres) { "$($est.MaxSimult) teclas: $($est.MaxSimultNombres)" } else { '(ninguna)' }
                $txtMantenidas.Text = "Sostenidas ahora: $sostenidas  |  Mayor combinacion simultanea: $mayor"
            }
            if ($nuevaProbada) {
                $txtFaltan.Text = Texto-TeclasFaltantes -Orden $ordenTeclas -Probadas $teclasProbadas -Etiquetas $etiquetasTecla
                if ($modo.Resaltar) { Pintar-TodasTeclas -Ctx $ctx }
            }
            $statTiempo.Text = Formato-DuracionTeclado -T ([DateTime]::Now - $est.Inicio)
            # Indicadores de Bloq Mayus / Bloq Num / Bloq Despl
            try {
                $ledCaps.Foreground = if ([System.Windows.Input.Keyboard]::IsKeyToggled([System.Windows.Input.Key]::CapsLock)) { $pincelLedOn } else { $pincelLedOff }
                $ledNum.Foreground = if ([System.Windows.Input.Keyboard]::IsKeyToggled([System.Windows.Input.Key]::NumLock)) { $pincelLedOn } else { $pincelLedOff }
                $ledScroll.Foreground = if ([System.Windows.Input.Keyboard]::IsKeyToggled([System.Windows.Input.Key]::Scroll)) { $pincelLedOn } else { $pincelLedOff }
            } catch {}
        }.GetNewClosure())
        $timerEspecial.Start()

        # PreviewKeyDown/PreviewKeyUp quedan como respaldo (por si la ventana
        # si llega a tener el foco de Windows): si llegan a disparar, solo
        # refuerzan la misma iluminacion que ya hace el gancho global, que es
        # la fuente principal y fiable.
        $winTec.Focusable = $true
        $winTec.Add_Loaded({
            $winTec.Activate() | Out-Null
            [System.Windows.Input.Keyboard]::Focus($winTec) | Out-Null
        }.GetNewClosure())
        $winTec.Add_PreviewKeyDown({
            param($s, $e)
            # El gancho global es la unica fuente de iluminacion; aqui solo se
            # evita que la ventana reaccione a las teclas (atajos, sonidos).
            $e.Handled = $true
        }.GetNewClosure())
        $winTec.Add_PreviewKeyUp({
            param($s, $e)
            $e.Handled = $true
        }.GetNewClosure())

        $chkCalor.Add_Click({
            $modo.Calor = [bool]$chkCalor.IsChecked
            Pintar-TodasTeclas -Ctx $ctx
        }.GetNewClosure())
        $chkSinProbar.Add_Click({
            $modo.Resaltar = [bool]$chkSinProbar.IsChecked
            Pintar-TodasTeclas -Ctx $ctx
        }.GetNewClosure())

        $winTec.FindName("BtnReporteRebotes").Add_Click({
            # Los botones tambien corren dentro de un .GetNewClosure(), asi
            # que solo pueden llamar funciones Global: -- Show-Aviso ya lo es.
            $dur = Formato-DuracionTeclado -T ([DateTime]::Now - $est.Inicio)
            $media = if ($est.NHold -gt 0) { "$([int]($est.SumaHold / $est.NHold)) ms" } else { "-" }
            $mayor = if ($est.MaxSimultNombres) { "$($est.MaxSimult) ($($est.MaxSimultNombres))" } else { "0" }
            $top = if ($est.TopTecla) { "$($etiquetasTecla[$est.TopTecla]) ($($est.MaxConteo) veces)" } else { "-" }
            $faltantes = Texto-TeclasFaltantes -Orden $ordenTeclas -Probadas $teclasProbadas -Etiquetas $etiquetasTecla -Maximo 200
            $texto = "RESUMEN DE LA PRUEBA DE TECLADO`n`n" +
                "Duracion: $dur`n" +
                "Pulsaciones totales: $($est.Total)`n" +
                "Teclas probadas: $($teclasProbadas.Count) / $totalTeclas`n" +
                "Mayor cantidad de teclas simultaneas: $mayor`n" +
                "Pico de velocidad: $($est.PicoPps) pulsaciones por segundo`n" +
                "Tiempo medio de pulsacion: $media`n" +
                "Tecla mas usada: $top`n`n" +
                "$faltantes`n`n"
            if ($registroRebotes.Count -eq 0) {
                $texto += "Rebote de hardware: no se detecto ninguno en esta sesion."
            } else {
                $lineas = foreach ($nombre in ($registroRebotes.Keys | Sort-Object)) {
                    $info = $registroRebotes[$nombre]
                    "- $nombre : $($info.Conteo) veces (menor intervalo detectado: $($info.MenorIntervalo) ms)"
                }
                $texto += "POSIBLES FALLAS DE HARDWARE (rebote):`n" + ($lineas -join "`n") + "`n`nUn 'rebote' significa que, al presionar la tecla UNA sola vez, el interruptor mando la señal de pulsacion mas de una vez en menos de $umbralReboteMs ms -- algo que una persona no puede hacer fisicamente a proposito. Normalmente indica un interruptor desgastado o con suciedad debajo, y suele empeorar con el tiempo."
            }
            $texto += "`n`nConsejo: mantén pulsadas varias teclas a la vez; si una nueva deja de responder, ese es el limite de rollover de tu teclado."
            Show-Aviso -Mensaje $texto -Titulo "Reporte de teclado - The Dragon Tool"
        }.GetNewClosure())
        $winTec.FindName("BtnReiniciarTeclado").Add_Click({
            $teclasActivas.Clear()
            $teclasProbadas.Clear()
            $ultimoLevantadaMs.Clear()
            $registroRebotes.Clear()
            $conteos.Clear()
            $bajadaMs.Clear()
            $colaPps.Clear()
            $est.Total = 0; $est.MaxSimult = 0; $est.MaxSimultNombres = ''; $est.PicoPps = 0
            $est.MaxConteo = 0; $est.TopTecla = ''; $est.SumaHold = [int64]0; $est.NHold = 0; $est.Inicio = [DateTime]::Now
            foreach ($k in $mapaTeclas.Keys) { foreach ($b in $mapaTeclas[$k]) { $b.ToolTip = $null } }
            Pintar-TodasTeclas -Ctx $ctx
            $txtProbadas.Text = "Teclas probadas: 0 / $totalTeclas"
            $txtUltimaTecla.Text = "Ultima tecla: (ninguna)"
            $txtRebotes.Text = ""
            $statTotal.Text = "0"; $statSimult.Text = "0 / 0"; $statPps.Text = "0"; $statHold.Text = "-"; $statTop.Text = "-"
            $txtMantenidas.Text = "Sostenidas ahora: (ninguna)  |  Mayor combinacion simultanea: (ninguna)"
            $txtFaltan.Text = "Sin probar: $totalTeclas teclas (pulsa cada tecla de tu teclado)"
        }.GetNewClosure())
        $winTec.FindName("BtnCerrarTeclado").Add_Click({ $winTec.Close() })
        $winTec.Add_Closed({
            $timerEspecial.Stop()
            [DragonToolTecladoHook]::Desinstalar()
        }.GetNewClosure())

        $winTec.ShowDialog() | Out-Null
        Write-DiagLog "Prueba de teclado finalizada ($(Formato-DuracionTeclado -T ([DateTime]::Now - $est.Inicio)))."
        if ($est.Total -eq 0) {
            Write-DiagLog "   • No se pulso ninguna tecla: la prueba no es concluyente."
        } else {
            if ($teclasProbadas.Count -ge $totalTeclas) {
                Diag-Ok "Teclado: las $totalTeclas teclas respondieron correctamente."
            } else {
                Write-DiagLog "   • Teclas probadas: $($teclasProbadas.Count) / $totalTeclas. $(Texto-TeclasFaltantes -Orden $ordenTeclas -Probadas $teclasProbadas -Etiquetas $etiquetasTecla -Maximo 200)"
            }
            $mediaLog = if ($est.NHold -gt 0) { "$([int]($est.SumaHold / $est.NHold)) ms" } else { "-" }
            Write-DiagLog "   • Teclas simultaneas maximas: $($est.MaxSimult) | Pico: $($est.PicoPps) pulsaciones/s | Pulsacion media: $mediaLog | Pulsaciones totales: $($est.Total)"
            if ($registroRebotes.Count -gt 0) {
                $resumen = ($registroRebotes.Keys | Sort-Object | ForEach-Object { "$_ (x$($registroRebotes[$_].Conteo))" }) -join ", "
                Diag-Aviso "Teclado: posible falla de hardware (rebote) en: $resumen"
            } else {
                Diag-Ok "Teclado: sin rebote de hardware en las teclas pulsadas."
            }
        }
    } catch {
        try { [DragonToolTecladoHook]::Desinstalar() } catch {}
        Write-DiagLog "No se pudo abrir la prueba de teclado: $($_.Exception.Message)"
    }
}

# --- Microfono: medidor de nivel en tiempo real (captura directa, sin abrir Windows) ---

$Script:TipoMicTestListo = $false
function Ensure-TipoMicTest {
    if ($Script:TipoMicTestListo) { return }
    $codigo = @"
using System;
using System.Runtime.InteropServices;

public class DragonToolMicTest {
    [DllImport("winmm.dll")] static extern int waveInOpen(out IntPtr hWaveIn, int uDeviceID, ref WAVEFORMATEX lpFormat, IntPtr dwCallback, IntPtr dwInstance, int dwFlags);
    [DllImport("winmm.dll")] static extern int waveInPrepareHeader(IntPtr hWaveIn, ref WAVEHDR lpWaveInHdr, int uSize);
    [DllImport("winmm.dll")] static extern int waveInAddBuffer(IntPtr hWaveIn, ref WAVEHDR lpWaveInHdr, int uSize);
    [DllImport("winmm.dll")] static extern int waveInStart(IntPtr hWaveIn);
    [DllImport("winmm.dll")] static extern int waveInStop(IntPtr hWaveIn);
    [DllImport("winmm.dll")] static extern int waveInClose(IntPtr hWaveIn);
    [DllImport("winmm.dll")] static extern int waveInUnprepareHeader(IntPtr hWaveIn, ref WAVEHDR lpWaveInHdr, int uSize);

    [StructLayout(LayoutKind.Sequential)]
    public struct WAVEFORMATEX {
        public ushort wFormatTag; public ushort nChannels; public uint nSamplesPerSec;
        public uint nAvgBytesPerSec; public ushort nBlockAlign; public ushort wBitsPerSample; public ushort cbSize;
    }
    [StructLayout(LayoutKind.Sequential)]
    public struct WAVEHDR {
        public IntPtr lpData; public uint dwBufferLength; public uint dwBytesRecorded;
        public IntPtr dwUser; public uint dwFlags; public uint dwLoops; public IntPtr lpNext; public IntPtr reserved;
    }

    IntPtr hWaveIn = IntPtr.Zero;
    WAVEHDR hdr;
    IntPtr bufferPtr = IntPtr.Zero;
    int bufferSize = 8192;
    bool activo = false;

    public bool Iniciar() {
        WAVEFORMATEX fmt = new WAVEFORMATEX();
        fmt.wFormatTag = 1; fmt.nChannels = 1; fmt.nSamplesPerSec = 11025; fmt.wBitsPerSample = 16;
        fmt.nBlockAlign = (ushort)(fmt.nChannels * fmt.wBitsPerSample / 8);
        fmt.nAvgBytesPerSec = fmt.nSamplesPerSec * fmt.nBlockAlign;
        fmt.cbSize = 0;

        int result = waveInOpen(out hWaveIn, -1, ref fmt, IntPtr.Zero, IntPtr.Zero, 0);
        if (result != 0) return false;

        bufferPtr = Marshal.AllocHGlobal(bufferSize);
        hdr = new WAVEHDR();
        hdr.lpData = bufferPtr;
        hdr.dwBufferLength = (uint)bufferSize;
        waveInPrepareHeader(hWaveIn, ref hdr, Marshal.SizeOf(hdr));
        waveInAddBuffer(hWaveIn, ref hdr, Marshal.SizeOf(hdr));
        waveInStart(hWaveIn);
        activo = true;
        return true;
    }

    public int LeerNivelPico() {
        if (!activo) return 0;
        int peak = 0;
        if ((hdr.dwFlags & 1) != 0) {
            int muestras = (int)hdr.dwBytesRecorded / 2;
            for (int i = 0; i < muestras; i++) {
                short muestra = Marshal.ReadInt16(bufferPtr, i * 2);
                int abs = Math.Abs((int)muestra);
                if (abs > peak) peak = abs;
            }
            waveInUnprepareHeader(hWaveIn, ref hdr, Marshal.SizeOf(hdr));
            hdr.dwBufferLength = (uint)bufferSize; hdr.dwBytesRecorded = 0; hdr.dwFlags = 0;
            waveInPrepareHeader(hWaveIn, ref hdr, Marshal.SizeOf(hdr));
            waveInAddBuffer(hWaveIn, ref hdr, Marshal.SizeOf(hdr));
        }
        return peak;
    }

    public void Detener() {
        if (!activo) return;
        activo = false;
        try {
            waveInStop(hWaveIn);
            waveInUnprepareHeader(hWaveIn, ref hdr, Marshal.SizeOf(hdr));
            waveInClose(hWaveIn);
        } catch {}
        if (bufferPtr != IntPtr.Zero) { Marshal.FreeHGlobal(bufferPtr); bufferPtr = IntPtr.Zero; }
    }
}
"@
    Add-Type -TypeDefinition $codigo -ErrorAction Stop
    $Script:TipoMicTestListo = $true
}

function Show-PruebaMicrofono {
    Write-DiagLog "=== MICROFONO (medidor de nivel en vivo, captura directa) ==="
    try {
        Ensure-TipoMicTest
    } catch {
        Write-DiagLog "No se pudo preparar la prueba de microfono: $($_.Exception.Message)"
        return
    }
    try {
        [xml]$xamlMic = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Prueba de microfono - The Dragon Tool" Height="310" Width="480" WindowStartupLocation="CenterScreen" Background="#10141D">
  <Window.Resources>$($Global:RecursosNeonXaml)</Window.Resources>
  <StackPanel Margin="20">
    <Button x:Name="BtnVolverVentana" Content="⬅  Volver" Width="110" Height="34" HorizontalAlignment="Left" Margin="0,0,0,10"/>
    <TextBlock Text="Habla cerca del microfono: la barra debe moverse en tiempo real si funciona." Foreground="White" TextWrapping="Wrap" Margin="0,0,0,14"/>
    <ProgressBar x:Name="BarraNivelMic" Minimum="0" Maximum="100" Height="30" Margin="0,0,0,10"/>
    <TextBlock x:Name="TxtNivelMic" Text="Nivel: 0%" Foreground="#66AEFF" FontWeight="Bold"/>
    <Button x:Name="BtnCerrarMic" Content="Cerrar" Height="38" Margin="0,20,0,0"/>
  </StackPanel>
</Window>
"@
        $readerMic = New-Object System.Xml.XmlNodeReader $xamlMic
        $winMic = [Windows.Markup.XamlReader]::Load($readerMic)
        Iniciar-EfectosNeon -Ventana $winMic
        $barra = $winMic.FindName("BarraNivelMic")
        $txtNivel = $winMic.FindName("TxtNivelMic")

        $mic = New-Object DragonToolMicTest
        if (-not $mic.Iniciar()) {
            Write-DiagLog "No se pudo iniciar la captura de microfono (puede estar en uso por otra app o no haber ninguno conectado)."
            return
        }

        $timerMic = New-Object System.Windows.Threading.DispatcherTimer
        $timerMic.Interval = [TimeSpan]::FromMilliseconds(120)
        $timerMic.Add_Tick({
            $nivel = $mic.LeerNivelPico()
            $pct = [math]::Min(100, [math]::Round(($nivel / 32767) * 300))
            $barra.Value = $pct
            $txtNivel.Text = "Nivel: $pct%"
        }.GetNewClosure())
        $timerMic.Start()

        $winMic.Add_Closed({ $timerMic.Stop(); $mic.Detener() }.GetNewClosure())
        $winMic.FindName("BtnCerrarMic").Add_Click({ $winMic.Close() })

        $winMic.ShowDialog() | Out-Null
        Write-DiagLog "Prueba de microfono finalizada."
    } catch {
        Write-DiagLog "No se pudo completar la prueba de microfono: $($_.Exception.Message)"
    }
}

# --- Audio: generador de tonos propio (sin abrir el panel de sonido de Windows) ---

function New-TonoWav {
    param([double]$Frecuencia = 440, [double]$DuracionSegundos = 1.5, [string]$Canal = "Ambos")
    $sampleRate = 44100
    $numSamples = [int]($sampleRate * $DuracionSegundos)
    $dataSize = $numSamples * 2 * 2

    $ms = New-Object System.IO.MemoryStream
    $bw = New-Object System.IO.BinaryWriter($ms)
    $bw.Write([char[]]"RIFF"); $bw.Write([int32](36 + $dataSize)); $bw.Write([char[]]"WAVE")
    $bw.Write([char[]]"fmt "); $bw.Write([int32]16); $bw.Write([int16]1); $bw.Write([int16]2)
    $bw.Write([int32]$sampleRate); $bw.Write([int32]($sampleRate * 4)); $bw.Write([int16]4); $bw.Write([int16]16)
    $bw.Write([char[]]"data"); $bw.Write([int32]$dataSize)

    for ($i = 0; $i -lt $numSamples; $i++) {
        $t = $i / $sampleRate
        $valor = [math]::Sin(2 * [math]::PI * $Frecuencia * $t) * 0.5
        $muestra = [int16]($valor * [int16]::MaxValue)
        $izq = [int16]0; $der = [int16]0
        switch ($Canal) {
            'Izquierdo' { $izq = $muestra }
            'Derecho'   { $der = $muestra }
            default     { $izq = $muestra; $der = $muestra }
        }
        $bw.Write($izq); $bw.Write($der)
    }
    $bw.Flush()
    $ms.Position = 0
    return $ms
}

function Accion-ProbarAudioCanal {
    param([string]$Canal)
    Write-DiagLog "=== AUDIO / ALTAVOCES ($Canal) ==="
    try {
        $ms = New-TonoWav -Frecuencia 440 -DuracionSegundos 1.5 -Canal $Canal
        $player = New-Object System.Media.SoundPlayer
        $player.Stream = $ms
        $player.PlaySync()
        $ms.Dispose()
        Write-DiagLog "Tono de prueba reproducido en: $Canal. ¿Se escucho correctamente de ese lado?"
    } catch {
        Write-DiagLog "No se pudo reproducir el tono de prueba: $($_.Exception.Message)"
    }
}

function Show-PruebaPantalla {
    Write-DiagLog "=== PANTALLA ==="
    Write-DiagLog "Se abrira una ventana a pantalla completa con colores solidos. Revisa manchas o pixeles muertos. Clic para cambiar de color, Esc para salir."
    try {
        [xml]$xamlPant = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        WindowStyle="None" WindowState="Maximized" Background="White" Topmost="True" ShowInTaskbar="False">
  <TextBlock Text="Clic = cambiar de color      Esc = salir" Foreground="Gray" FontSize="16"
             HorizontalAlignment="Center" VerticalAlignment="Bottom" Margin="0,0,0,30"/>
</Window>
"@
        $readerP = New-Object System.Xml.XmlNodeReader $xamlPant
        $winP = [Windows.Markup.XamlReader]::Load($readerP)
        $colores = @('White', 'Red', 'Lime', 'Blue', 'Black', 'Gray')
        $Script:_idxColorPantalla = 0
        $winP.Add_MouseLeftButtonDown({
            $Script:_idxColorPantalla = ($Script:_idxColorPantalla + 1) % $colores.Count
            $winP.Background = [System.Windows.Media.Brushes]::($colores[$Script:_idxColorPantalla])
        }.GetNewClosure())
        $winP.Add_KeyDown({
            param($s, $e)
            if ($e.Key -eq 'Escape') { $winP.Close() }
        })
        $winP.ShowDialog() | Out-Null
        Write-DiagLog "Prueba de pantalla finalizada."
    } catch {
        Write-DiagLog "No se pudo abrir la prueba de pantalla: $($_.Exception.Message)"
    }
}

function Accion-VerDetallesPantalla {
    Write-DiagLog "=== PANTALLA: DETALLES ==="
    try {
        $monitores = Get-CimInstance -Namespace root\wmi -ClassName WmiMonitorID -ErrorAction SilentlyContinue
        foreach ($m in $monitores) {
            $nombre = -join ($m.UserFriendlyName | Where-Object { $_ -ne 0 } | ForEach-Object { [char]$_ })
            if ($nombre) { Write-DiagLog " - Monitor: $nombre" }
        }
        $videoCtrl = Get-CimInstance Win32_VideoController -ErrorAction SilentlyContinue
        foreach ($v in $videoCtrl) {
            if ($v.CurrentHorizontalResolution) {
                Write-DiagLog " - Resolucion actual: $($v.CurrentHorizontalResolution) x $($v.CurrentVerticalResolution) @ $($v.CurrentRefreshRate) Hz"
            }
        }
        if (-not $monitores -and -not $videoCtrl) { Write-DiagLog "No se pudo obtener el detalle de pantalla." }
    } catch {
        Write-DiagLog "No se pudo obtener el detalle de pantalla."
    }
}

# --- RAM: prueba propia de patrones (sin reiniciar, sin abrir Windows) ---

$Script:TipoMemTestListo = $false
function Ensure-TipoMemTest {
    if ($Script:TipoMemTestListo) { return }
    $codigo = @"
using System;

public static class DragonToolMemTest {
    public static void Fill(byte[] buffer, byte pattern) {
        for (int i = 0; i < buffer.Length; i++) buffer[i] = pattern;
    }
    public static long CountMismatches(byte[] buffer, byte pattern) {
        long count = 0;
        for (int i = 0; i < buffer.Length; i++) {
            if (buffer[i] != pattern) count++;
        }
        return count;
    }
}
"@
    Add-Type -TypeDefinition $codigo -ErrorAction Stop
    $Script:TipoMemTestListo = $true
}

function Show-PruebaRAM {
    param(
        [int]$TamanoMB = 512,
        [array]$Patrones = @(0xFF, 0x00, 0xAA, 0x55, 0x01, 0xFE),
        [string]$ModoEjecucion = 'Pasadas',   # 'Pasadas' | 'Tiempo' | 'Bucle'
        [int]$Pasadas = 1,
        [int]$DuracionMinutos = 5
    )
    Write-DiagLog "=== MEMORIA RAM (prueba propia, sin reiniciar) ==="

    # Un array de bytes en .NET no puede superar Int32.MaxValue elementos
    # (2147483647). 2048 MB exactos ya superan ese limite por 1 byte, asi que
    # se limita el tamaño maximo permitido a un valor seguro.
    $maxSeguroMB = [math]::Floor([int32]::MaxValue / 1MB)
    if ($TamanoMB -gt $maxSeguroMB) {
        Write-DiagLog "El tamaño solicitado ($TamanoMB MB) supera el maximo posible para esta prueba. Se ajusta a $maxSeguroMB MB."
        $TamanoMB = $maxSeguroMB
    }

    try {
        Ensure-TipoMemTest
    } catch {
        Write-DiagLog "No se pudo preparar la prueba de RAM: $($_.Exception.Message)"
        return
    }

    try {
        $os = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop
        $ramLibreMB = [math]::Round($os.FreePhysicalMemory / 1KB)
        if ($TamanoMB -gt ($ramLibreMB * 0.6)) {
            if (-not (Show-Confirm "Pediste probar $TamanoMB MB, pero solo hay $ramLibreMB MB de RAM libre. Esto puede ralentizar mucho el equipo o fallar. ¿Continuar de todas formas?")) {
                Write-DiagLog "Prueba de RAM cancelada (memoria libre insuficiente para el tamaño solicitado)."
                return
            }
        }
    } catch {}

    $descripcionModo = switch ($ModoEjecucion) {
        'Tiempo' { "durante $DuracionMinutos minuto(s)" }
        'Bucle'  { "en bucle continuo hasta que la detengas manualmente" }
        default  { "con $Pasadas pasada(s)" }
    }
    if (-not (Show-Confirm "Se probaran $TamanoMB MB con $($Patrones.Count) patron(es) $descripcionModo, dentro de Windows (no requiere reiniciar). ¿Continuar?")) {
        Write-DiagLog "Prueba de RAM cancelada por el usuario."
        return
    }

    $permitirDetener = ($ModoEjecucion -ne 'Pasadas') -or ($Pasadas -gt 1)
    $prog = New-VentanaProgreso -Titulo "Probando memoria RAM" -PermitirDetener:$permitirDetener
    try {
        Update-VentanaProgreso -Ventana $prog -Porcentaje 2 -Estado "Reservando $TamanoMB MB de memoria para la prueba..." -LogLinea "Reservando bloque de prueba de $TamanoMB MB."
        $buffer = New-Object byte[] ($TamanoMB * 1MB)

        $erroresTotal = 0
        $pasadasCompletadas = 0
        $cronometro = [System.Diagnostics.Stopwatch]::StartNew()
        $detenido = $false

        while (-not $detenido) {
            $pasadasCompletadas++
            foreach ($patron in $Patrones) {
                if ($prog.Tag -eq $true) { $detenido = $true; break }

                $patronTexto = "0x{0:X2}" -f $patron
                $idxPatron = [Array]::IndexOf($Patrones, $patron) + 1

                switch ($ModoEjecucion) {
                    'Tiempo' {
                        $pct = [math]::Min(98, [math]::Round(($cronometro.Elapsed.TotalMinutes / [math]::Max($DuracionMinutos,0.01)) * 100))
                        $tiempoTexto = "{0:N1}" -f $cronometro.Elapsed.TotalMinutes
                        $etiqueta = "Pasada $pasadasCompletadas, patron $patronTexto ($tiempoTexto / $DuracionMinutos min)"
                    }
                    'Bucle' {
                        $pct = [math]::Round(($idxPatron / $Patrones.Count) * 100)
                        $etiqueta = "Pasada $pasadasCompletadas (bucle continuo), patron $patronTexto"
                    }
                    default {
                        $totalPasos = $Patrones.Count * $Pasadas
                        $pasoActual = (($pasadasCompletadas - 1) * $Patrones.Count) + $idxPatron
                        $pct = [math]::Round(($pasoActual / $totalPasos) * 100)
                        $etiqueta = "Pasada $pasadasCompletadas de $Pasadas, patron $patronTexto"
                    }
                }
                Update-VentanaProgreso -Ventana $prog -Porcentaje $pct -Estado "$etiqueta..." -LogLinea "$etiqueta."

                [DragonToolMemTest]::Fill($buffer, [byte]$patron)
                $errores = [DragonToolMemTest]::CountMismatches($buffer, [byte]$patron)
                $erroresTotal += $errores
                if ($errores -gt 0) {
                    Update-VentanaProgreso -Ventana $prog -Porcentaje $pct -LogLinea "¡$errores error(es) detectados con el patron $patronTexto!"
                }
            }

            if ($detenido) { break }
            switch ($ModoEjecucion) {
                'Tiempo' { if ($cronometro.Elapsed.TotalMinutes -ge $DuracionMinutos) { $detenido = $true } }
                'Bucle'  { }
                default  { if ($pasadasCompletadas -ge $Pasadas) { $detenido = $true } }
            }
        }
        $cronometro.Stop()

        Update-VentanaProgreso -Ventana $prog -Porcentaje 100 -Estado "Finalizando..."
        $buffer = $null
        [System.GC]::Collect()

        $resumen = "$TamanoMB MB, $pasadasCompletadas pasada(s), $("{0:N1}" -f $cronometro.Elapsed.TotalMinutes) minuto(s)"
        if ($erroresTotal -eq 0) {
            Close-VentanaProgreso -Ventana $prog -MensajeFinal "Sin errores detectados."
            Write-DiagLog "Prueba de RAM completada sin errores: $resumen."
        } else {
            Close-VentanaProgreso -Ventana $prog -MensajeFinal "$erroresTotal error(es) detectados."
            Write-DiagLog "ATENCION: se detectaron $erroresTotal error(es) de memoria tras $resumen. Se recomienda una prueba mas exhaustiva (con reinicio) para confirmar, por ejemplo desde Windows."
        }
    } catch {
        Close-VentanaProgreso -Ventana $prog -MensajeFinal "Error durante la prueba."
        Write-DiagLog "No se pudo completar la prueba de RAM: $($_.Exception.Message)"
    }
}

function Show-SeleccionPruebaRAM {
    [xml]$xamlSelRam = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Elegir tipo de prueba de RAM - The Dragon Tool" Height="640" Width="500"
        WindowStartupLocation="CenterScreen" Background="#10141D">
  <Window.Resources>$($Global:RecursosNeonXaml)</Window.Resources>
  <ScrollViewer VerticalScrollBarVisibility="Auto">
  <StackPanel Margin="24">
    <Button x:Name="BtnVolverVentana" Content="⬅  Volver" Width="110" Height="34" HorizontalAlignment="Left" Margin="0,0,0,10"/>
    <TextBlock Text="Tamaño de la prueba:" Foreground="#66AEFF" FontWeight="Bold" FontSize="14" Margin="0,0,0,10"/>

    <RadioButton x:Name="RbRamRapida" GroupName="TipoRAM" Foreground="White" IsChecked="True" Margin="0,0,0,10">
      <StackPanel>
        <TextBlock Text="🟢 Rapida" FontWeight="Bold"/>
        <TextBlock Text="128 MB, 2 patrones. Lista en segundos, buena para un vistazo rapido." FontSize="11" Opacity="0.85" TextWrapping="Wrap"/>
      </StackPanel>
    </RadioButton>

    <RadioButton x:Name="RbRamEstandar" GroupName="TipoRAM" Foreground="White" Margin="0,0,0,10">
      <StackPanel>
        <TextBlock Text="🟡 Estandar (recomendada)" FontWeight="Bold"/>
        <TextBlock Text="512 MB, 6 patrones. Buen equilibrio entre rapidez y cobertura." FontSize="11" Opacity="0.85" TextWrapping="Wrap"/>
      </StackPanel>
    </RadioButton>

    <RadioButton x:Name="RbRamExhaustiva" GroupName="TipoRAM" Foreground="White" Margin="0,0,0,10">
      <StackPanel>
        <TextBlock Text="🔴 Exhaustiva" FontWeight="Bold"/>
        <TextBlock Text="1900 MB, 10 patrones. Mas lenta y usa mas RAM libre." FontSize="11" Opacity="0.85" TextWrapping="Wrap"/>
      </StackPanel>
    </RadioButton>

    <RadioButton x:Name="RbRamPersonalizada" GroupName="TipoRAM" Foreground="White" Margin="0,0,0,6">
      <TextBlock Text="⚙️ Personalizada" FontWeight="Bold"/>
    </RadioButton>
    <StackPanel x:Name="PanelRamPersonalizada" Visibility="Collapsed" Margin="24,4,0,10">
      <DockPanel Margin="0,4,0,4">
        <TextBlock Text="Tamaño (MB):" Foreground="White" Width="100" VerticalAlignment="Center"/>
        <TextBox x:Name="TxtRamTamano" Text="1024"/>
      </DockPanel>
    </StackPanel>

    <Separator Margin="0,6,0,14" Opacity="0.2"/>

    <TextBlock Text="Modo de ejecucion:" Foreground="#66AEFF" FontWeight="Bold" FontSize="14" Margin="0,0,0,10"/>

    <RadioButton x:Name="RbModoPasadas" GroupName="ModoRAM" Foreground="White" IsChecked="True" Margin="0,0,0,6">
      <TextBlock Text="Numero de pasadas" FontWeight="Bold"/>
    </RadioButton>
    <StackPanel x:Name="PanelModoPasadas" Margin="24,0,0,10">
      <DockPanel Margin="0,4,0,4">
        <TextBlock Text="Pasadas:" Foreground="White" Width="100" VerticalAlignment="Center"/>
        <TextBox x:Name="TxtRamPasadas" Text="1"/>
      </DockPanel>
    </StackPanel>

    <RadioButton x:Name="RbModoTiempo" GroupName="ModoRAM" Foreground="White" Margin="0,0,0,6">
      <TextBlock Text="Por tiempo de duracion" FontWeight="Bold"/>
    </RadioButton>
    <StackPanel x:Name="PanelModoTiempo" Visibility="Collapsed" Margin="24,0,0,10">
      <DockPanel Margin="0,4,0,4">
        <TextBlock Text="Minutos:" Foreground="White" Width="100" VerticalAlignment="Center"/>
        <TextBox x:Name="TxtRamMinutos" Text="5"/>
      </DockPanel>
    </StackPanel>

    <RadioButton x:Name="RbModoBucle" GroupName="ModoRAM" Foreground="White" Margin="0,0,0,6">
      <StackPanel>
        <TextBlock Text="En bucle continuo" FontWeight="Bold"/>
        <TextBlock Text="Se repite sin parar hasta que pulses 'Detener' en la ventana de progreso." FontSize="11" Opacity="0.85" TextWrapping="Wrap"/>
      </StackPanel>
    </RadioButton>

    <Button x:Name="BtnIniciarPruebaRAM" Content="▶️ Iniciar prueba" Height="42" Margin="0,16,0,0" BorderBrush="#2F7CF6"/>
  </StackPanel>
  </ScrollViewer>
</Window>
"@
    $readerSelRam = New-Object System.Xml.XmlNodeReader $xamlSelRam
    $winSelRam = [Windows.Markup.XamlReader]::Load($readerSelRam)
    Iniciar-EfectosNeon -Ventana $winSelRam

    $winSelRam.FindName("RbRamPersonalizada").Add_Checked({
        $winSelRam.FindName("PanelRamPersonalizada").Visibility = 'Visible'
    })
    foreach ($otro in @("RbRamRapida", "RbRamEstandar", "RbRamExhaustiva")) {
        $winSelRam.FindName($otro).Add_Checked({
            $winSelRam.FindName("PanelRamPersonalizada").Visibility = 'Collapsed'
        }.GetNewClosure())
    }

    $winSelRam.FindName("RbModoPasadas").Add_Checked({
        $winSelRam.FindName("PanelModoPasadas").Visibility = 'Visible'
        $winSelRam.FindName("PanelModoTiempo").Visibility = 'Collapsed'
    })
    $winSelRam.FindName("RbModoTiempo").Add_Checked({
        $winSelRam.FindName("PanelModoPasadas").Visibility = 'Collapsed'
        $winSelRam.FindName("PanelModoTiempo").Visibility = 'Visible'
    })
    $winSelRam.FindName("RbModoBucle").Add_Checked({
        $winSelRam.FindName("PanelModoPasadas").Visibility = 'Collapsed'
        $winSelRam.FindName("PanelModoTiempo").Visibility = 'Collapsed'
    })

    $winSelRam.FindName("BtnIniciarPruebaRAM").Add_Click({
        if ($winSelRam.FindName("RbRamRapida").IsChecked) {
            $tamanoSel = 128; $patronesSel = @(0xFF, 0x00)
        } elseif ($winSelRam.FindName("RbRamEstandar").IsChecked) {
            $tamanoSel = 512; $patronesSel = @(0xFF, 0x00, 0xAA, 0x55, 0x01, 0xFE)
        } elseif ($winSelRam.FindName("RbRamExhaustiva").IsChecked) {
            $tamanoSel = 1900; $patronesSel = @(0xFF, 0x00, 0xAA, 0x55, 0x01, 0xFE, 0x33, 0xCC, 0x0F, 0xF0)
        } else {
            $tamanoSel = 1024
            [int]::TryParse($winSelRam.FindName("TxtRamTamano").Text, [ref]$tamanoSel) | Out-Null
            if ($tamanoSel -lt 16) { $tamanoSel = 16 }
            $patronesSel = @(0xFF, 0x00, 0xAA, 0x55, 0x01, 0xFE)
        }

        if ($winSelRam.FindName("RbModoTiempo").IsChecked) {
            $minutosSel = 5
            [int]::TryParse($winSelRam.FindName("TxtRamMinutos").Text, [ref]$minutosSel) | Out-Null
            if ($minutosSel -lt 1) { $minutosSel = 1 }
            $winSelRam.Close()
            Show-PruebaRAM -TamanoMB $tamanoSel -Patrones $patronesSel -ModoEjecucion 'Tiempo' -DuracionMinutos $minutosSel
        } elseif ($winSelRam.FindName("RbModoBucle").IsChecked) {
            $winSelRam.Close()
            Show-PruebaRAM -TamanoMB $tamanoSel -Patrones $patronesSel -ModoEjecucion 'Bucle'
        } else {
            $pasadasSel = 1
            [int]::TryParse($winSelRam.FindName("TxtRamPasadas").Text, [ref]$pasadasSel) | Out-Null
            if ($pasadasSel -lt 1) { $pasadasSel = 1 }
            $winSelRam.Close()
            Show-PruebaRAM -TamanoMB $tamanoSel -Patrones $patronesSel -ModoEjecucion 'Pasadas' -Pasadas $pasadasSel
        }
    })

    $winSelRam.ShowDialog() | Out-Null
}

# ---------------------------------------------------------------------------
#  PRUEBAS DE DIAGNOSTICO (hardware / sistema) - versiones reforzadas
# ---------------------------------------------------------------------------

# ---------------------------------------------------------------------------
#  TARJETA ANIMADA DE PROGRESO DE LAS PRUEBAS DE DIAGNOSTICO
#  Anillo giratorio, icono que pulsa, barra de progreso con brillo, cronometro,
#  contadores en vivo y efectos finales (confeti si todo esta bien, sacudida si hay avisos).
#  Las animaciones son "independientes" de WPF: siguen fluidas aunque la prueba ocupe el hilo.
# ---------------------------------------------------------------------------
$Global:DiagUi = $null
$Global:DiagEnCurso = $false
$Global:DiagCancelada = $false
$Global:DiagStats = @{ Ok = 0; Aviso = 0; Lineas = 0 }
$Global:DiagReloj = New-Object System.Diagnostics.Stopwatch
$Global:DiagTimer = $null
$Global:DiagShimmerListo = $false

function Global:Obtener-DiagUi {
    if ($Global:DiagUi) { return $Global:DiagUi }
    $nombres = @('PanelDiagProgreso', 'GlowDiag', 'AroDiag', 'GiroDiag', 'IcoDiag', 'EscIcoDiag', 'TxtDiagTitulo', 'TxtDiagSub', 'TxtDiagTiempo',
                 'PbDiag', 'MarqueeDiag', 'SegDiag', 'MovSegDiag', 'ChipOkDiag', 'ChipAvDiag', 'ChipLinDiag', 'CanvasConfetiDiag',
                 'EscDiagCard', 'MovDiagCard', 'ScrollDiagIzq')
    $u = @{}
    foreach ($n in $nombres) { $u[$n] = $window.FindName($n) }
    if (-not $u.PanelDiagProgreso) { return $null }
    $Global:DiagUi = $u
    return $u
}

function Global:Nuevo-PincelDiag {
    param([string]$Hex)
    $c = New-Object System.Windows.Media.BrushConverter
    return $c.ConvertFromString($Hex)
}

function Global:Actualizar-DiagChips {
    try {
        $u = Obtener-DiagUi; if (-not $u) { return }
        $u.ChipOkDiag.Text = "✔ $($Global:DiagStats.Ok)"
        $u.ChipAvDiag.Text = "⚠ $($Global:DiagStats.Aviso)"
        $u.ChipLinDiag.Text = "📝 $($Global:DiagStats.Lineas)"
    } catch {}
}

function Global:Actualizar-DiagTiempo {
    try {
        $u = Obtener-DiagUi; if (-not $u) { return }
        $u.TxtDiagTiempo.Text = "⏱ " + $Global:DiagReloj.Elapsed.ToString('mm\:ss')
    } catch {}
}

# Pone en marcha las animaciones continuas de la tarjeta
function Global:Diag-Animar {
    $u = Obtener-DiagUi; if (-not $u) { return }
    $suave = New-Object System.Windows.Media.Animation.SineEase
    $suave.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
    # Anillo giratorio
    $giro = New-Object System.Windows.Media.Animation.DoubleAnimation
    $giro.From = 0; $giro.To = 360
    $giro.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(1800))
    $giro.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
    $u.GiroDiag.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty, $giro)
    # Icono que late
    $pulso = New-Object System.Windows.Media.Animation.DoubleAnimation
    $pulso.From = 0.85; $pulso.To = 1.2
    $pulso.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(650))
    $pulso.AutoReverse = $true
    $pulso.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
    $pulso.EasingFunction = $suave
    $u.EscIcoDiag.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $pulso)
    $u.EscIcoDiag.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $pulso)
    # Segmento que recorre la barra cuando no se conoce el porcentaje
    $ancho = 380
    try { if ($u.MarqueeDiag.ActualWidth -gt 60) { $ancho = $u.MarqueeDiag.ActualWidth } } catch {}
    $barrido = New-Object System.Windows.Media.Animation.DoubleAnimation
    $barrido.From = -130; $barrido.To = $ancho + 20
    $barrido.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(1400))
    $barrido.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
    $u.MovSegDiag.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $barrido)
    # Halo que respira
    $halo = New-Object System.Windows.Media.Animation.DoubleAnimation
    $halo.From = 0.25; $halo.To = 0.75
    $halo.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(900))
    $halo.AutoReverse = $true
    $halo.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
    $u.GlowDiag.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $halo)
    # Brillo y aura de la barra de progreso (partes de su plantilla)
    if (-not $Global:DiagShimmerListo) {
        try {
            [void]$u.PbDiag.ApplyTemplate()
            $brillo = $u.PbDiag.Template.FindName("Brillo", $u.PbDiag)
            $aura = $u.PbDiag.Template.FindName("Aura", $u.PbDiag)
            if ($brillo) {
                $b = New-Object System.Windows.Media.Animation.DoubleAnimation
                $b.From = -100; $b.To = $ancho + 100
                $b.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(1500))
                $b.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
                $brillo.RenderTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $b)
            }
            if ($aura) {
                $a = New-Object System.Windows.Media.Animation.DoubleAnimation
                $a.From = 0.15; $a.To = 0.65
                $a.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(900))
                $a.AutoReverse = $true
                $a.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
                $aura.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $a)
            }
            $Global:DiagShimmerListo = $true
        } catch {}
    }
}

function Global:Diag-DetenerAnimaciones {
    $u = Obtener-DiagUi; if (-not $u) { return }
    try {
        $u.GiroDiag.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty, $null)
        $u.EscIcoDiag.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $null)
        $u.EscIcoDiag.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $null)
        $u.MovSegDiag.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $null)
        $u.GlowDiag.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $null)
        $u.GiroDiag.Angle = 0
        $u.EscIcoDiag.ScaleX = 1; $u.EscIcoDiag.ScaleY = 1
    } catch {}
}

function Global:Diag-Inicio {
    param([string]$Nombre, [string]$Icono = '🔎')
    $u = Obtener-DiagUi; if (-not $u) { return }
    try {
        $Global:DiagStats.Ok = 0; $Global:DiagStats.Aviso = 0; $Global:DiagStats.Lineas = 0
        foreach ($p in @([System.Windows.Media.ScaleTransform]::ScaleXProperty, [System.Windows.Media.ScaleTransform]::ScaleYProperty)) { $u.EscDiagCard.BeginAnimation($p, $null) }
        $u.MovDiagCard.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $null)
        $u.PanelDiagProgreso.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $null)
        $u.PbDiag.BeginAnimation([System.Windows.Controls.Primitives.RangeBase]::ValueProperty, $null)
        $u.EscDiagCard.ScaleX = 1; $u.EscDiagCard.ScaleY = 1; $u.MovDiagCard.X = 0
        $u.CanvasConfetiDiag.Children.Clear()
        $u.PbDiag.Value = 0
        $u.PbDiag.Visibility = 'Collapsed'
        $u.MarqueeDiag.Visibility = 'Visible'
        $u.IcoDiag.Text = $Icono
        $u.TxtDiagTitulo.Text = "Analizando: $Nombre"
        $u.TxtDiagSub.Text = "Preparando la prueba..."
        $u.GlowDiag.Background = (Nuevo-PincelDiag '#00B7FF')
        $u.TxtDiagTiempo.Text = "⏱ 00:00"
        Actualizar-DiagChips
        $u.PanelDiagProgreso.Visibility = 'Visible'
        Diag-Animar
        # Entrada: aparece con un pequeno rebote
        $rebote = New-Object System.Windows.Media.Animation.BackEase
        $rebote.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
        $rebote.Amplitude = 0.5
        foreach ($p in @([System.Windows.Media.ScaleTransform]::ScaleXProperty, [System.Windows.Media.ScaleTransform]::ScaleYProperty)) {
            $e = New-Object System.Windows.Media.Animation.DoubleAnimation
            $e.From = 0.8; $e.To = 1
            $e.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(450))
            $e.EasingFunction = $rebote
            $u.EscDiagCard.BeginAnimation($p, $e)
        }
        $f = New-Object System.Windows.Media.Animation.DoubleAnimation
        $f.From = 0; $f.To = 1
        $f.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(300))
        $u.PanelDiagProgreso.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $f)
        # Cronometro
        $Global:DiagReloj.Restart()
        if (-not $Global:DiagTimer) {
            $Global:DiagTimer = New-Object System.Windows.Threading.DispatcherTimer
            $Global:DiagTimer.Interval = [TimeSpan]::FromMilliseconds(250)
            $Global:DiagTimer.Add_Tick({ Actualizar-DiagTiempo })
        }
        $Global:DiagTimer.Start()
    } catch {}
}

# Cambia a barra con porcentaje real (suave) y actualiza el texto de estado
function Global:Diag-Progreso {
    param([double]$Pct, [string]$Texto = '')
    if (-not $Global:DiagEnCurso) { return }
    $u = Obtener-DiagUi; if (-not $u) { return }
    try {
        if ($u.PbDiag.Visibility -ne 'Visible') {
            $u.MarqueeDiag.Visibility = 'Collapsed'
            $u.PbDiag.Visibility = 'Visible'
        }
        $v = [Math]::Max(0, [Math]::Min(100, $Pct))
        $an = New-Object System.Windows.Media.Animation.DoubleAnimation
        $an.To = $v
        $an.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(350))
        $ease = New-Object System.Windows.Media.Animation.CubicEase
        $ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
        $an.EasingFunction = $ease
        $u.PbDiag.BeginAnimation([System.Windows.Controls.Primitives.RangeBase]::ValueProperty, $an)
        if ($Texto) { $u.TxtDiagSub.Text = $Texto }
        Wait-UI -Milisegundos 1
    } catch {}
}

# Solo cambia el texto de estado (para pruebas sin porcentaje conocido)
function Global:Diag-Texto {
    param([string]$Texto)
    if (-not $Global:DiagEnCurso) { return }
    try { $u = Obtener-DiagUi; if ($u) { $u.TxtDiagSub.Text = $Texto } } catch {}
}

function Global:Diag-Confeti {
    $u = Obtener-DiagUi; if (-not $u) { return }
    try {
        $cv = $u.CanvasConfetiDiag
        $cv.Children.Clear()
        $colores = @('#29D398', '#00B7FF', '#FFFFFF', '#FFC857', '#5B9CFF', '#FF7AC6')
        $cx = 34.0; $cy = 36.0
        for ($i = 0; $i -lt 26; $i++) {
            $tam = Get-Random -Minimum 5 -Maximum 10
            $r = New-Object System.Windows.Shapes.Rectangle
            $r.Width = $tam; $r.Height = $tam
            $r.RadiusX = 2; $r.RadiusY = 2
            $r.Fill = (Nuevo-PincelDiag $colores[$i % $colores.Count])
            $r.IsHitTestVisible = $false
            $grupo = New-Object System.Windows.Media.TransformGroup
            $mov = New-Object System.Windows.Media.TranslateTransform
            $rot = New-Object System.Windows.Media.RotateTransform
            [void]$grupo.Children.Add($rot); [void]$grupo.Children.Add($mov)
            $r.RenderTransform = $grupo
            $r.RenderTransformOrigin = [System.Windows.Point]::new(0.5, 0.5)
            [System.Windows.Controls.Canvas]::SetLeft($r, $cx)
            [System.Windows.Controls.Canvas]::SetTop($r, $cy)
            [void]$cv.Children.Add($r)
            $ang = (Get-Random -Minimum 0 -Maximum 360) * [Math]::PI / 180.0
            $dist = Get-Random -Minimum 60 -Maximum 190
            $seg = (Get-Random -Minimum 800 -Maximum 1500)
            $dur = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds($seg))
            $suave = New-Object System.Windows.Media.Animation.CubicEase
            $suave.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
            $ax = New-Object System.Windows.Media.Animation.DoubleAnimation
            $ax.From = 0; $ax.To = [Math]::Cos($ang) * $dist; $ax.Duration = $dur; $ax.EasingFunction = $suave
            $ay = New-Object System.Windows.Media.Animation.DoubleAnimation
            $ay.From = 0; $ay.To = [Math]::Sin($ang) * $dist + 45; $ay.Duration = $dur; $ay.EasingFunction = $suave
            $ar = New-Object System.Windows.Media.Animation.DoubleAnimation
            $ar.From = 0; $ar.To = (Get-Random -Minimum -540 -Maximum 540); $ar.Duration = $dur
            $ao = New-Object System.Windows.Media.Animation.DoubleAnimation
            $ao.From = 1; $ao.To = 0; $ao.BeginTime = [TimeSpan]::FromMilliseconds($seg * 0.45)
            $ao.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds($seg * 0.55))
            $mov.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $ax)
            $mov.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $ay)
            $rot.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty, $ar)
            $r.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $ao)
        }
    } catch {}
}

function Global:Diag-Ocultar {
    $u = Obtener-DiagUi; if (-not $u) { return }
    try {
        if ($Global:DiagTimer) { $Global:DiagTimer.Stop() }
        $Global:DiagReloj.Stop()
        Diag-DetenerAnimaciones
        $u.CanvasConfetiDiag.Children.Clear()
        $u.PanelDiagProgreso.Visibility = 'Collapsed'
    } catch {}
}

function Global:Diag-Fin {
    param([string]$Nombre)
    $u = Obtener-DiagUi; if (-not $u) { return }
    try {
        if ($Global:DiagTimer) { $Global:DiagTimer.Stop() }
        $Global:DiagReloj.Stop()
        Actualizar-DiagTiempo
        Diag-DetenerAnimaciones
        Actualizar-DiagChips
        # La barra se llena hasta el 100%
        $u.MarqueeDiag.Visibility = 'Collapsed'
        $u.PbDiag.Visibility = 'Visible'
        $an = New-Object System.Windows.Media.Animation.DoubleAnimation
        $an.To = 100
        $an.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(450))
        $u.PbDiag.BeginAnimation([System.Windows.Controls.Primitives.RangeBase]::ValueProperty, $an)
        $av = [int]$Global:DiagStats.Aviso
        $u.GlowDiag.Opacity = 0.8
        if ($av -eq 0) {
            $u.IcoDiag.Text = '✅'
            $u.TxtDiagTitulo.Text = "Completado: $Nombre"
            $u.TxtDiagSub.Text = "Sin advertencias: todo en orden."
            $u.GlowDiag.Background = (Nuevo-PincelDiag '#29D398')
            # Pequeno "pop" de celebracion y confeti
            $pop = New-Object System.Windows.Media.Animation.DoubleAnimation
            $pop.From = 1; $pop.To = 1.07
            $pop.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(170))
            $pop.AutoReverse = $true
            foreach ($p in @([System.Windows.Media.ScaleTransform]::ScaleXProperty, [System.Windows.Media.ScaleTransform]::ScaleYProperty)) { $u.EscDiagCard.BeginAnimation($p, $pop) }
            Diag-Confeti
        } else {
            $u.IcoDiag.Text = '⚠️'
            $u.TxtDiagTitulo.Text = "Completado con avisos: $Nombre"
            $u.TxtDiagSub.Text = "$av advertencia(s). Revisa las lineas con ⚠ en los resultados."
            $u.GlowDiag.Background = (Nuevo-PincelDiag '#FFC857')
            # Sacudida para llamar la atencion
            $sacude = New-Object System.Windows.Media.Animation.DoubleAnimationUsingKeyFrames
            $valores = @(@(0, 0), @(-9, 60), @(9, 120), @(-7, 180), @(7, 240), @(-3, 290), @(0, 340))
            foreach ($kv in $valores) {
                $kt = [System.Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds($kv[1]))
                [void]$sacude.KeyFrames.Add((New-Object System.Windows.Media.Animation.LinearDoubleKeyFrame -ArgumentList @([double]$kv[0], $kt)))
            }
            $u.MovDiagCard.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $sacude)
        }
        # El icono hace un pequeno rebote al cambiar
        $ico = New-Object System.Windows.Media.Animation.DoubleAnimation
        $ico.From = 0.3; $ico.To = 1
        $ico.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(420))
        $bk = New-Object System.Windows.Media.Animation.BackEase
        $bk.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
        $bk.Amplitude = 0.8
        $ico.EasingFunction = $bk
        $u.EscIcoDiag.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $ico)
        $u.EscIcoDiag.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $ico)
    } catch {}
}

# Resume la duracion de la prueba y su impacto en el sistema; avisa si fue lenta y por que
function Global:Diag-AnalisisRendimiento {
    param([string]$Nombre, $Inicio, [int]$Lag0 = 0, [double]$LagMs0 = 0)
    try {
        $seg = ((Get-Date) - $Inicio).TotalSeconds
        $esp = 40
        if ($Global:DiagEsperadoSeg.ContainsKey($Nombre)) { $esp = $Global:DiagEsperadoSeg[$Nombre] }
        $an = Analizar-CausaLentitud -Desde $Inicio -Contexto "prueba '$Nombre'"
        $lagN = $Global:MonLagCuenta - $Lag0
        $lagS = ($Global:MonLagTotalMs - $LagMs0) / 1000
        $linea = ("   ⏱ Duracion: {0:N1} s" -f $seg)
        if ($an.Hay) { $linea += " | Sistema durante la prueba: $($an.Resumen)" }
        if ($lagN -gt 0) { $linea += (" | La ventana se congelo {0} vez/veces ({1:N1} s en total)" -f $lagN, $lagS) }
        Write-DiagLog $linea
        [void]$Global:HistPruebas.Add(("{0}  {1}: {2:N1} s" -f (Get-Date).ToString('HH:mm:ss'), $Nombre, $seg))
        $cargaAlta = ($an.Hay -and -not $an.Propio -and (($an.Cpu -ge 80) -or ($an.Ram -ge 90) -or ($an.Disco -ge 85)))
        if ($seg -gt $esp -or $cargaAlta) {
            $r = Registrar-Lentitud -Tipo 'Prueba' -Nombre $Nombre -Segundos $seg -Esperado $esp -Desde $Inicio
            $causas = if ($r -and $r.Causas.Count) { $r.Causas -join ' ' } else { 'revisa el informe de lentitud en la pestaña Registro de errores' }
            Diag-Aviso "Lentitud detectada en '$Nombre': $causas"
        }
    } catch {}
}

# Envoltorio: muestra la tarjeta animada mientras corre una prueba automatica
function Global:Ejecutar-PruebaDiag {
    param([string]$Nombre, [string]$Icono = '🔎', [scriptblock]$Accion)
    if ($Global:DiagEnCurso) { return }
    $Global:DiagEnCurso = $true
    $Global:DiagCancelada = $false
    $Global:DiagNombreActual = $Nombre
    $Global:VidaSsdImpresa = @{}
    $inicioPrueba = Get-Date
    $u = Obtener-DiagUi
    try {
        if ($u) { $u.ScrollDiagIzq.IsEnabled = $false }
        Diag-Inicio -Nombre $Nombre -Icono $Icono
        Wait-UI -Milisegundos 30
        $lagCuenta0 = $Global:MonLagCuenta; $lagMs0 = $Global:MonLagTotalMs
        & $Accion
        if (-not $Global:DiagCancelada) { Diag-AnalisisRendimiento -Nombre $Nombre -Inicio $inicioPrueba -Lag0 $lagCuenta0 -LagMs0 $lagMs0 }
    } catch {
        Write-DiagLog "No se pudo completar '$Nombre': $($_.Exception.Message)"
    } finally {
        $Global:DiagEnCurso = $false
        $Global:DiagNombreActual = ''
        try {
            if (-not $Global:DiagCancelada) {
                if (-not $Global:DiagInforme) { Registrar-LineaInforme '' }
                $Global:DiagInforme.Pruebas.Add([PSCustomObject]@{ Nombre = $Nombre; Inicio = $inicioPrueba; Seg = ((Get-Date) - $inicioPrueba).TotalSeconds; Ok = [int]$Global:DiagStats.Ok; Aviso = [int]$Global:DiagStats.Aviso })
            }
        } catch { }
        try { if ($u) { $u.ScrollDiagIzq.IsEnabled = $true } } catch {}
        if ($Global:DiagCancelada) { Diag-Ocultar } else { Diag-Fin -Nombre $Nombre }
    }
}

$Script:DiagAdvertencias = 0
function Global:Diag-Ok { param([string]$m) $Global:DiagStats.Ok++; Write-DiagLog "   ✔ $m" }
function Global:Diag-Aviso {
    param([string]$m)
    $Script:DiagAdvertencias++
    $Global:DiagStats.Aviso++
    Write-DiagLog "   ⚠ ATENCION: $m"
}

function Accion-ProbarAlmacenamiento {
    Write-DiagLog "=== ALMACENAMIENTO (salud, S.M.A.R.T. y espacio) ==="
    $hallado = $false
    try {
        foreach ($d in @(Get-PhysicalDisk -ErrorAction Stop)) {
            $hallado = $true
            $tam = [math]::Round($d.Size / 1GB, 0)
            Write-DiagLog " - $($d.FriendlyName) | $($d.MediaType) | $($d.BusType) | $tam GB"
            if ("$($d.HealthStatus)" -eq 'Healthy') { Diag-Ok "Salud del disco: Healthy (OK)" }
            else { Diag-Aviso "Salud del disco: $($d.HealthStatus) ($($d.OperationalStatus)). Haz copia de seguridad y revisa el disco." }
            try { Escribir-VidaSSD -Disco $d } catch { }
            try {
                $rc = $d | Get-StorageReliabilityCounter -ErrorAction Stop
                $partes = @()
                if ($null -ne $rc.Temperature) { $partes += "Temperatura: $($rc.Temperature) °C" }
                if ($null -ne $rc.Wear) { $partes += "Desgaste: $($rc.Wear)%" }
                if ($null -ne $rc.PowerOnHours) { $partes += "Horas encendido: $($rc.PowerOnHours) h" }
                if ($partes.Count) { Write-DiagLog "     $($partes -join ' | ')" }
                if ($rc.Temperature -gt 60) { Diag-Aviso "Temperatura alta del disco ($($rc.Temperature) °C). Mejora la ventilacion." }
                if ($rc.Wear -gt 85) { Diag-Aviso "El SSD tiene mas del 85% de desgaste. Planea reemplazarlo." }
                $sinCorregir = [int]$rc.ReadErrorsUncorrected + [int]$rc.WriteErrorsUncorrected
                if ($sinCorregir -gt 0) { Diag-Aviso "El disco acumula $sinCorregir operacion(es) de lectura/escritura sin corregir." }
            } catch {}
        }
    } catch { Write-DiagLog "Get-PhysicalDisk no esta disponible en este equipo." }
    try {
        foreach ($s in @(Get-CimInstance -Namespace root\wmi -ClassName MSStorageDriver_FailurePredictStatus -ErrorAction Stop)) {
            $hallado = $true
            if ($s.PredictFailure) { Diag-Aviso "S.M.A.R.T. predice un fallo inminente en: $($s.InstanceName). Haz copia de seguridad YA." }
            else { Diag-Ok "S.M.A.R.T.: sin fallos predichos ($($s.InstanceName))" }
        }
    } catch { Write-DiagLog "   (El estado S.M.A.R.T. detallado no esta disponible en este equipo/controlador.)" }
    try {
        foreach ($v in @(Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3' -ErrorAction Stop)) {
            if ($v.Size -le 0) { continue }
            $libre = [math]::Round($v.FreeSpace / 1GB, 1); $total = [math]::Round($v.Size / 1GB, 0)
            $pct = [math]::Round(($v.FreeSpace / $v.Size) * 100, 0)
            Write-DiagLog " - Unidad $($v.DeviceID) ($($v.VolumeName)) | $libre GB libres de $total GB ($pct% libre)"
            if ($pct -lt 10) { Diag-Aviso "Poco espacio libre en $($v.DeviceID). Libera espacio para evitar lentitud." }
        }
    } catch {}
    if (-not $hallado) { Write-DiagLog "No se pudo obtener informacion de los discos." }
}

function Accion-ProbarVelocidadDisco {
    $uDisco = Unidad-Diag
    Write-DiagLog "=== VELOCIDAD DE DISCO (lectura/escritura secuencial en $uDisco) ==="
    $archivoPrueba = $null
    try {
        $ld = Get-CimInstance Win32_LogicalDisk -Filter "DeviceID='$uDisco'" -ErrorAction SilentlyContinue
        $tamanoMB = 256
        if ($ld -and ($ld.FreeSpace / 1MB) -lt ($tamanoMB * 3)) { $tamanoMB = 64 }
        $carpetaPrueba = Carpeta-PruebaDisco $uDisco
        if (-not (Test-Path $carpetaPrueba)) { New-Item -Path $carpetaPrueba -ItemType Directory -Force | Out-Null }
        $archivoPrueba = Join-Path $carpetaPrueba "prueba.tmp"
        $bloque = New-Object byte[] (4MB)
        (New-Object Random).NextBytes($bloque)
        $bloques = [int]($tamanoMB / 4)

        Write-DiagLog "Escribiendo $tamanoMB MB (con escritura directa a disco)..."
        $fs = New-Object System.IO.FileStream($archivoPrueba, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None, 4MB, [System.IO.FileOptions]::WriteThrough)
        $cron = [System.Diagnostics.Stopwatch]::StartNew()
        for ($i = 0; $i -lt $bloques; $i++) { $fs.Write($bloque, 0, $bloque.Length); if ($i % 4 -eq 0) { Diag-Progreso -Pct (($i / [Math]::Max(1,$bloques)) * 50) -Texto "Escribiendo $tamanoMB MB en el disco..." } }
        $fs.Flush($true); $cron.Stop(); $fs.Close()
        $vEsc = [math]::Round($tamanoMB / [math]::Max(0.001, $cron.Elapsed.TotalSeconds), 1)

        Write-DiagLog "Leyendo $tamanoMB MB..."
        $fs = New-Object System.IO.FileStream($archivoPrueba, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read, 4MB, [System.IO.FileOptions]::SequentialScan)
        $buf = New-Object byte[] (4MB)
        $cron = [System.Diagnostics.Stopwatch]::StartNew()
        $i = 0
        while ($fs.Read($buf, 0, $buf.Length) -gt 0) { $i++; if ($i % 4 -eq 0) { Diag-Progreso -Pct (50 + ($i / [Math]::Max(1,$bloques)) * 50) -Texto "Leyendo $tamanoMB MB del disco..." } }
        $cron.Stop(); $fs.Close()
        $vLec = [math]::Round($tamanoMB / [math]::Max(0.001, $cron.Elapsed.TotalSeconds), 1)

        Write-DiagLog " - Escritura: $vEsc MB/s | Lectura: $vLec MB/s (la lectura puede verse inflada por la cache de Windows)"
        $clase = if ($vEsc -lt 60) { "muy lento (tipico de disco mecanico viejo o USB 2.0)" } elseif ($vEsc -lt 150) { "disco mecanico (HDD) o unidad externa" } elseif ($vEsc -lt 400) { "SSD SATA" } else { "SSD rapido (NVMe)" }
        Write-DiagLog " - Clasificacion por velocidad de escritura: $clase"
        if ($vEsc -lt 60) { Diag-Aviso "Velocidad de escritura muy baja. Un SSD mejoraria enormemente la fluidez del equipo." } else { Diag-Ok "Velocidad de disco aceptable." }
    } catch {
        Write-DiagLog "No se pudo medir la velocidad de disco: $($_.Exception.Message)"
    } finally {
        if ($archivoPrueba) { Remove-Item $archivoPrueba -Force -ErrorAction SilentlyContinue }
    }
}

function Accion-ProbarVentiladores {
    Write-DiagLog "=== VENTILADORES Y ESTADO TERMICO ==="
    $fans = @()
    try { $fans = @(Get-CimInstance Win32_Fan -ErrorAction Stop) } catch {}
    if ($fans.Count -gt 0) {
        foreach ($f in $fans) { Write-DiagLog " - $($f.Name) | Estado: $($f.Status)" }
    } else {
        Write-DiagLog "Windows no expone la velocidad de los ventiladores en este equipo (limitacion comun: solo la muestran las apps del fabricante o HWiNFO)."
    }
    # Pista indirecta: si la CPU esta lenta frente a su maximo y hay calor, los ventiladores/disipador pueden no estar cumpliendo.
    try {
        $cpu = Get-CimInstance Win32_Processor -ErrorAction Stop | Select-Object -First 1
        Write-DiagLog " - CPU: $($cpu.CurrentClockSpeed) MHz actuales (maximo $($cpu.MaxClockSpeed) MHz) | Carga: $($cpu.LoadPercentage)%"
    } catch {}
    $temp = Get-TemperaturaCPUC
    if ($null -ne $temp) {
        Write-DiagLog " - Temperatura del sistema: $temp °C"
        if ($temp -ge 90) { Diag-Aviso "Temperatura critica. Apaga el equipo, limpia el polvo y revisa ventiladores y pasta termica." }
        elseif ($temp -ge 80) { Diag-Aviso "Temperatura alta. Revisa la ventilacion y limpia el equipo." }
        else { Diag-Ok "Temperatura normal; la refrigeracion parece funcionar." }
    } else {
        Write-DiagLog "   (No hay sensor de temperatura accesible; escucha si los ventiladores giran al encender y al exigir al equipo.)"
    }
}

# Devuelve la temperatura (C) del sistema usando varias fuentes de Windows, o $null si no hay ninguna.
function Global:Get-TemperaturaCPUC {
    try {
        $z = @(Get-CimInstance -ClassName Win32_PerfFormattedData_Counters_ThermalZoneInformation -ErrorAction Stop)
        $vals = @($z | ForEach-Object { [double]$_.Temperature - 273.15 } | Where-Object { $_ -gt 0 -and $_ -lt 150 })
        if ($vals.Count) { return [math]::Round(($vals | Measure-Object -Maximum).Maximum, 1) }
    } catch {}
    try {
        $z = @(Get-CimInstance -Namespace root/wmi -ClassName MSAcpi_ThermalZoneTemperature -ErrorAction Stop)
        $vals = @($z | ForEach-Object { ($_.CurrentTemperature / 10) - 273.15 } | Where-Object { $_ -gt 0 -and $_ -lt 150 })
        if ($vals.Count) { return [math]::Round(($vals | Measure-Object -Maximum).Maximum, 1) }
    } catch {}
    return $null
}

function Accion-ProbarTemperaturaCPU {
    Write-DiagLog "=== TEMPERATURA DEL PROCESADOR ==="
    $t = Get-TemperaturaCPUC
    if ($null -ne $t) {
        Write-DiagLog " - Zona termica mas caliente: $t °C"
        if ($t -ge 90) { Diag-Aviso "Temperatura critica ($t °C). Riesgo de apagados y desgaste. Limpia el equipo y cambia la pasta termica." }
        elseif ($t -ge 80) { Diag-Aviso "Temperatura alta ($t °C). Revisa la ventilacion." }
        elseif ($t -ge 70) { Write-DiagLog "   Temperatura elevada pero aceptable bajo carga." }
        else { Diag-Ok "Temperatura normal." }
    } else {
        Write-DiagLog "Windows no expone la temperatura en este equipo (limitacion comun de hardware/BIOS: usa HWiNFO o la app del fabricante)."
    }
    try {
        $cpu = Get-CimInstance Win32_Processor -ErrorAction Stop | Select-Object -First 1
        Write-DiagLog " - $($cpu.Name.Trim()) | $($cpu.NumberOfCores) nucleos / $($cpu.NumberOfLogicalProcessors) hilos | $($cpu.CurrentClockSpeed) de $($cpu.MaxClockSpeed) MHz"
    } catch {}
}

function Accion-ProbarGraficaDiag {
    Write-DiagLog "=== TARJETA GRAFICA ==="
    try {
        $vcs = @(Get-CimInstance Win32_VideoController -ErrorAction Stop)
        if ($vcs.Count -eq 0) { Write-DiagLog "No se detecto ninguna tarjeta de video."; return }
        foreach ($g in $vcs) {
            Write-DiagLog " - $($g.Name) | Driver: $($g.DriverVersion) | Fecha del driver: $(try { $g.DriverDate.ToString('yyyy-MM-dd') } catch { 'desconocida' })"
            $vram = $null
            try {
                $claves = Get-ChildItem 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}' -ErrorAction SilentlyContinue
                foreach ($k in $claves) {
                    $p = Get-ItemProperty $k.PSPath -ErrorAction SilentlyContinue
                    if ($p.DriverDesc -eq $g.Name -and $p.'HardwareInformation.qwMemorySize') { $vram = [math]::Round([double]$p.'HardwareInformation.qwMemorySize' / 1GB, 1); break }
                }
            } catch {}
            if (-not $vram -and $g.AdapterRAM) { $vram = [math]::Round($g.AdapterRAM / 1GB, 1) }
            if ($vram) { Write-DiagLog "     Memoria de video: $vram GB" }
            if ($g.CurrentHorizontalResolution) { Write-DiagLog "     Salida: $($g.CurrentHorizontalResolution) x $($g.CurrentVerticalResolution) @ $($g.CurrentRefreshRate) Hz" }
            if ("$($g.Status)" -eq 'OK' -and [int]$g.ConfigManagerErrorCode -eq 0) { Diag-Ok "La tarjeta funciona correctamente segun Windows." }
            else { Diag-Aviso "Windows reporta problemas con esta tarjeta (estado: $($g.Status), codigo $($g.ConfigManagerErrorCode)). Reinstala el controlador de video." }
            if ($g.Name -match 'Microsoft Basic Display') { Diag-Aviso "Se esta usando el controlador basico de Microsoft: instala el driver real de la tarjeta." }
            try {
                if ($g.DriverDate -and ((Get-Date) - $g.DriverDate).TotalDays -gt 730) { Write-DiagLog "     Driver con mas de 2 años: conviene actualizarlo." }
            } catch {}
        }
    } catch { Write-DiagLog "No se pudo consultar la tarjeta grafica." }
}

function Accion-ProbarBateria {
    Write-DiagLog "=== BATERIA ==="
    try {
        $bateria = @(Get-CimInstance Win32_Battery -ErrorAction Stop)
        if ($bateria.Count -eq 0) { Write-DiagLog "No se detecto ninguna bateria (equipo de escritorio, o bateria no reconocida)."; return }
        $estados = @{ 1 = 'Descargando'; 2 = 'Conectada a la corriente'; 3 = 'Carga completa'; 4 = 'Baja'; 5 = 'Critica'; 6 = 'Cargando'; 7 = 'Cargando (alta)'; 8 = 'Cargando (baja)'; 9 = 'Cargando (critica)'; 11 = 'Parcialmente cargada' }
        foreach ($b in $bateria) {
            $est = if ($estados.ContainsKey([int]$b.BatteryStatus)) { $estados[[int]$b.BatteryStatus] } else { "$($b.BatteryStatus)" }
            Write-DiagLog " - $($b.Name) | $est | Carga: $($b.EstimatedChargeRemaining)%"
            if ($b.EstimatedRunTime -and $b.EstimatedRunTime -lt 71582788) { Write-DiagLog "     Autonomia estimada: $($b.EstimatedRunTime) min" }
        }
        try {
            $carpetaTemp = Join-Path $env:TEMP "DragonToolBattery"
            if (-not (Test-Path $carpetaTemp)) { New-Item -Path $carpetaTemp -ItemType Directory -Force | Out-Null }
            $archivoXml = Join-Path $carpetaTemp "battery-report.xml"
            powercfg /batteryreport /xml /output $archivoXml *> $null
            if (Test-Path $archivoXml) {
                $contenido = Get-Content $archivoXml -Raw
                $dis = [regex]::Match($contenido, '<DesignCapacity>(\d+)</DesignCapacity>')
                $act = [regex]::Match($contenido, '<FullChargeCapacity>(\d+)</FullChargeCapacity>')
                if (-not $dis.Success) { $dis = [regex]::Match($contenido, 'DesignCapacity="(\d+)"'); $act = [regex]::Match($contenido, 'FullChargeCapacity="(\d+)"') }
                $cic = [regex]::Match($contenido, '<CycleCount>(\d+)</CycleCount>')
                if ($dis.Success -and $act.Success) {
                    $diseno = [double]$dis.Groups[1].Value; $actual = [double]$act.Groups[1].Value
                    if ($diseno -gt 0) {
                        $desgaste = [math]::Round((1 - ($actual / $diseno)) * 100, 1)
                        Write-DiagLog "     Capacidad de diseño: $diseno mWh | Capacidad maxima actual: $actual mWh | Desgaste: $desgaste%"
                        if ($cic.Success -and [int]$cic.Groups[1].Value -gt 0) { Write-DiagLog "     Ciclos de carga: $($cic.Groups[1].Value)" }
                        if ($desgaste -gt 50) { Diag-Aviso "La bateria perdio mas del 50% de su capacidad. Conviene reemplazarla." }
                        elseif ($desgaste -gt 30) { Diag-Aviso "La bateria esta bastante desgastada ($desgaste%)." }
                        else { Diag-Ok "Salud de la bateria buena (desgaste $desgaste%)." }
                    }
                }
                Remove-Item $archivoXml -Force -ErrorAction SilentlyContinue
            }
        } catch { Write-DiagLog "   (No se pudo generar el reporte detallado de desgaste; no es critico.)" }
    } catch { Write-DiagLog "No se detecto ninguna bateria (equipo de escritorio, o bateria no reconocida)." }
}

function Accion-ProbarRed {
    Write-DiagLog "=== RED / CONECTIVIDAD ==="
    try {
        foreach ($a in @(Get-NetAdapter -Physical -ErrorAction Stop | Where-Object { $_.Status -eq 'Up' })) {
            Write-DiagLog " - Adaptador activo: $($a.Name) ($($a.InterfaceDescription)) | $($a.LinkSpeed)"
        }
    } catch {}
    try {
        $cfg = Get-NetIPConfiguration -ErrorAction Stop | Where-Object { $_.IPv4DefaultGateway } | Select-Object -First 1
        if ($cfg) {
            Write-DiagLog " - IP: $($cfg.IPv4Address.IPAddress) | Puerta de enlace: $($cfg.IPv4DefaultGateway.NextHop) | DNS: $(($cfg.DNSServer.ServerAddresses | Select-Object -First 2) -join ', ')"
            try {
                $gw = Test-Connection -ComputerName $cfg.IPv4DefaultGateway.NextHop -Count 3 -ErrorAction Stop
                $ms = [math]::Round(($gw | Measure-Object ResponseTime -Average).Average, 0)
                Write-DiagLog " - Router: responde en $ms ms"
                if ($ms -gt 30) { Diag-Aviso "El router responde lento ($ms ms): mala senal WiFi o red local congestionada." } else { Diag-Ok "Red local (router) en buen estado." }
            } catch { Diag-Aviso "El router no responde a ping (puede estar bloqueado o haber un problema de red local)." }
        } else { Diag-Aviso "No hay puerta de enlace configurada: el equipo no esta conectado a una red." }
    } catch {}
    try {
        $resultado = Test-Connection -ComputerName "8.8.8.8" -Count 4 -ErrorAction Stop
        $latencias = $resultado | ForEach-Object { $_.ResponseTime }
        $promedio = [math]::Round(($latencias | Measure-Object -Average).Average, 0)
        $minimo = ($latencias | Measure-Object -Minimum).Minimum
        $maximo = ($latencias | Measure-Object -Maximum).Maximum
        Write-DiagLog " - Internet: OK | Latencia promedio: $promedio ms (min $minimo ms, max $maximo ms)"
        if ($promedio -gt 100) { Diag-Aviso "Latencia alta hacia Internet ($promedio ms)." }
        $perdidos = 4 - @($resultado).Count
        if ($perdidos -gt 0) { Diag-Aviso "Se perdieron $perdidos de 4 paquetes: conexion inestable." }
    } catch {
        Diag-Aviso "Sin conexion a Internet detectada (no respondio 8.8.8.8)."
        return
    }
    try {
        $cron = [System.Diagnostics.Stopwatch]::StartNew()
        Resolve-DnsName -Name "www.google.com" -ErrorAction Stop | Out-Null
        $cron.Stop()
        Write-DiagLog " - Resolucion DNS: OK ($($cron.ElapsedMilliseconds) ms)"
    } catch { Diag-Aviso "No se pudo resolver DNS (posible problema con el servidor DNS configurado)." }
    try {
        $https = Test-NetConnection -ComputerName "www.google.com" -Port 443 -WarningAction SilentlyContinue -ErrorAction Stop
        if ($https.TcpTestSucceeded) { Write-DiagLog " - Conexion HTTPS (puerto 443): OK" }
        else { Diag-Aviso "No se pudo establecer conexion HTTPS de salida (revisa el firewall)." }
    } catch { Write-DiagLog "   (No se pudo probar la conexion HTTPS.)" }
}

function Accion-ProbarWifi {
    Write-DiagLog "=== WI-FI (senal y velocidad) ==="
    try {
        $salida = @(netsh wlan show interfaces 2>$null)
        if ($salida.Count -eq 0 -or ($salida -join ' ') -match 'no hay ninguna interfaz|There is no wireless interface|not running') {
            Write-DiagLog "No se detecto ninguna interfaz Wi-Fi activa (equipo de escritorio con cable o adaptador apagado)."
            return
        }
        $lineas = $salida | Where-Object { $_ -match '^\s*(Nombre|Name|SSID|BSSID|Estado|State|Tipo de radio|Radio type|Banda|Band|Canal|Channel|Velocidad|Receive rate|Transmit rate|Se.al|Signal)' }
        foreach ($l in $lineas) { Write-DiagLog "   $($l.Trim())" }
        $sen = $salida | Where-Object { $_ -match '^\s*(Se.al|Signal)\s*:\s*(\d+)\s*%' } | Select-Object -First 1
        if ($sen -match '(\d+)\s*%') {
            $pct = [int]$Matches[1]
            if ($pct -ge 70) { Diag-Ok "Senal Wi-Fi buena ($pct%)." }
            elseif ($pct -ge 40) { Write-DiagLog "   Senal Wi-Fi regular ($pct%): acercate al router para mejor velocidad." }
            else { Diag-Aviso "Senal Wi-Fi debil ($pct%). Acercate al router o usa un repetidor/cable." }
        }
    } catch { Write-DiagLog "No se pudo consultar el Wi-Fi." }
}

function Accion-ProbarVelocidadInternet {
    Write-DiagLog "=== VELOCIDAD DE INTERNET (descarga) ==="
    $wc = $null
    try {
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        $wc = New-Object System.Net.WebClient
        $tam = 25000000
        Write-DiagLog "Descargando 25 MB de prueba (puede tardar unos segundos)..."
        $cron = [System.Diagnostics.Stopwatch]::StartNew()
        $tarea = $wc.DownloadDataTaskAsync("https://speed.cloudflare.com/__down?bytes=$tam")
        while (-not $tarea.IsCompleted -and $cron.Elapsed.TotalSeconds -lt 40) { Diag-Texto "Descargando archivo de prueba... $([int]$cron.Elapsed.TotalSeconds) s"; Wait-UI -Milisegundos 100 }
        $cron.Stop()
        if (-not $tarea.IsCompleted) { $wc.CancelAsync(); Diag-Aviso "La descarga de prueba tardo mas de 40 s: conexion muy lenta o inestable."; return }
        if ($tarea.IsFaulted) { throw $tarea.Exception.GetBaseException() }
        $bytes = $tarea.Result.Length
        $mbps = [math]::Round(($bytes * 8 / 1MB) / [math]::Max(0.001, $cron.Elapsed.TotalSeconds), 1)
        Write-DiagLog " - Velocidad de descarga: $mbps Mbps ($([math]::Round($bytes/1MB,1)) MB en $([math]::Round($cron.Elapsed.TotalSeconds,1)) s)"
        if ($mbps -lt 10) { Diag-Aviso "Velocidad baja ($mbps Mbps). Revisa el Wi-Fi o contacta a tu proveedor." }
        elseif ($mbps -lt 50) { Write-DiagLog "   Velocidad suficiente para uso general y video HD." }
        else { Diag-Ok "Buena velocidad de descarga." }
    } catch {
        Write-DiagLog "No se pudo medir la velocidad de Internet (¿sin conexion o bloqueada?): $($_.Exception.Message)"
    } finally { if ($wc) { $wc.Dispose() } }
}

function Accion-ProbarTiempoArranque {
    Write-DiagLog "=== TIEMPO DE ARRANQUE ==="
    try {
        $os = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop
        $up = (Get-Date) - $os.LastBootUpTime
        Write-DiagLog " - Encendido desde: $($os.LastBootUpTime.ToString('yyyy-MM-dd HH:mm')) (hace $([int]$up.TotalHours) h $($up.Minutes) min)"
        if ($up.TotalDays -gt 14) { Diag-Aviso "El equipo lleva mas de 14 dias sin reiniciarse. Reiniciar aplica actualizaciones y libera memoria." }
    } catch {}
    try {
        $eventos = @(Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-Diagnostics-Performance/Operational'; Id = 100 } -MaxEvents 5 -ErrorAction Stop)
        $tiempos = @()
        foreach ($ev in $eventos) {
            $xmlEvento = [xml]$ev.ToXml()
            $ms = ($xmlEvento.Event.EventData.Data | Where-Object { $_.Name -eq 'BootTime' }).'#text'
            if ($ms) { $tiempos += [math]::Round([double]$ms / 1000, 1); Write-DiagLog " - Arranque del $($ev.TimeCreated.ToString('yyyy-MM-dd HH:mm')): $([math]::Round([double]$ms/1000,1)) s" }
        }
        if ($tiempos.Count) {
            $prom = [math]::Round(($tiempos | Measure-Object -Average).Average, 1)
            if ($prom -gt 90) { Diag-Aviso "Arranque lento (promedio $prom s). Desactiva programas de inicio y considera un SSD." }
            elseif ($prom -gt 45) { Write-DiagLog "   Promedio $prom s: aceptable, se puede mejorar quitando programas de inicio." }
            else { Diag-Ok "Arranque rapido (promedio $prom s)." }
        } else { Write-DiagLog "No se pudo leer la duracion de los arranques." }
    } catch { Write-DiagLog "El registro de eventos no tiene datos de arranque en este equipo." }
}

function Accion-ProbarBluetooth {
    Write-DiagLog "=== BLUETOOTH ==="
    try {
        $bt = @(Get-PnpDevice -Class Bluetooth -PresentOnly -ErrorAction Stop)
        if ($bt.Count -eq 0) { Write-DiagLog "No se detecto ningun adaptador Bluetooth en este equipo."; return }
        foreach ($b in $bt) { Write-DiagLog " - $($b.FriendlyName) | Estado: $($b.Status)" }
        $malos = @($bt | Where-Object { "$($_.Status)" -ne 'OK' -and $_.FriendlyName -notmatch 'Enumerator|Enumerador' })
        if ($malos.Count) { Diag-Aviso "Hay $($malos.Count) dispositivo(s) Bluetooth con problemas. Actualiza el driver del adaptador." } else { Diag-Ok "El adaptador Bluetooth funciona correctamente." }
        $svc = Get-Service bthserv -ErrorAction SilentlyContinue
        if ($svc) { Write-DiagLog " - Servicio Bluetooth: $($svc.Status) ($($svc.StartType))" }
    } catch { Write-DiagLog "No se detecto ningun adaptador Bluetooth en este equipo." }
}

function Accion-ProbarPuertosUSB {
    Write-DiagLog "=== DISPOSITIVOS USB CONECTADOS ==="
    try {
        $usb = @(Get-PnpDevice -PresentOnly -ErrorAction Stop | Where-Object { $_.InstanceId -like 'USB\*' })
        if ($usb.Count -eq 0) { Write-DiagLog "No se detectaron dispositivos USB conectados actualmente."; return }
        foreach ($d in $usb) { Write-DiagLog " - $($d.FriendlyName) | Estado: $($d.Status)" }
        $malos = @($usb | Where-Object { "$($_.Status)" -ne 'OK' })
        if ($malos.Count) { Diag-Aviso "$($malos.Count) dispositivo(s) USB con problemas (desconocidos o sin driver): $(($malos | ForEach-Object { $_.FriendlyName }) -join ', ')" }
        else { Diag-Ok "Todos los dispositivos USB funcionan correctamente ($($usb.Count))." }
        try {
            $hub = @(Get-CimInstance Win32_USBHub -ErrorAction Stop)
            Write-DiagLog " - Concentradores/controladores USB detectados: $($hub.Count)"
        } catch {}
    } catch { Write-DiagLog "No se pudo obtener la lista de dispositivos USB." }
}

# --- Pruebas nuevas ---

$Script:TipoCpuBenchListo = $false
function Ensure-TipoCpuBench {
    if ($Script:TipoCpuBenchListo) { return }
    $codigo = @"
using System;
using System.Threading;
public static class DragonCpuBench {
    static volatile bool detener;
    static long total;
    static Thread[] hilos;
    static void Trabajo() {
        long n = 0; double x = 1.0001;
        while (!detener) {
            for (int i = 1; i < 20000; i++) { x = x * 1.0000001 + Math.Sqrt(i); if (x > 1e9) x = 1.0; }
            n += 20000;
        }
        Interlocked.Add(ref total, n);
    }
    public static void Iniciar(int cantidad) {
        detener = false; total = 0; hilos = new Thread[cantidad];
        for (int i = 0; i < cantidad; i++) { hilos[i] = new Thread(Trabajo); hilos[i].IsBackground = true; hilos[i].Start(); }
    }
    public static long Detener() { detener = true; foreach (Thread t in hilos) t.Join(); return total; }
}
"@
    Add-Type -TypeDefinition $codigo -ErrorAction Stop
    $Script:TipoCpuBenchListo = $true
}

function Accion-ProbarCPUBenchmark {
    Write-DiagLog "=== RENDIMIENTO DEL PROCESADOR (prueba de 10 segundos) ==="
    try {
        Ensure-TipoCpuBench
        $hilos = [Environment]::ProcessorCount
        $t0 = Get-TemperaturaCPUC
        Write-DiagLog "Prueba con 1 hilo (4 s)..."
        [DragonCpuBench]::Iniciar(1)
        $cron = [System.Diagnostics.Stopwatch]::StartNew()
        while ($cron.Elapsed.TotalSeconds -lt 4) { Diag-Progreso -Pct (($cron.Elapsed.TotalSeconds / 4) * 45) -Texto "Midiendo 1 hilo..."; Wait-UI -Milisegundos 100 }
        $n1 = [DragonCpuBench]::Detener(); $s1 = $cron.Elapsed.TotalSeconds
        $v1 = [math]::Round($n1 / $s1 / 1e6, 1)

        Write-DiagLog "Prueba con los $hilos hilos del procesador (5 s)..."
        [DragonCpuBench]::Iniciar($hilos)
        $cron = [System.Diagnostics.Stopwatch]::StartNew()
        $tMax = $t0
        while ($cron.Elapsed.TotalSeconds -lt 5) { Diag-Progreso -Pct (45 + ($cron.Elapsed.TotalSeconds / 5) * 55) -Texto "Midiendo con todos los hilos ($hilos)..." ; Wait-UI -Milisegundos 100 }
        $tFin = Get-TemperaturaCPUC
        $nN = [DragonCpuBench]::Detener(); $sN = $cron.Elapsed.TotalSeconds
        $vN = [math]::Round($nN / $sN / 1e6, 1)
        $escala = [math]::Round($vN / [math]::Max(0.001, $v1), 1)

        Write-DiagLog " - 1 hilo: $v1 millones de operaciones/s"
        Write-DiagLog " - $hilos hilos: $vN millones de operaciones/s (escala x$escala sobre 1 hilo)"
        $cpu = Get-CimInstance Win32_Processor -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($cpu) { Write-DiagLog " - CPU: $($cpu.Name.Trim()) | $($cpu.NumberOfCores) nucleos / $($cpu.NumberOfLogicalProcessors) hilos" }
        if ($null -ne $tFin) {
            Write-DiagLog " - Temperatura: $t0 °C antes -> $tFin °C tras la prueba"
            if ($tFin -ge 90) { Diag-Aviso "La CPU llego a $tFin °C bajo carga: refrigeracion insuficiente." }
            elseif ($tFin -ge 80) { Diag-Aviso "La CPU llego a $tFin °C bajo carga: conviene revisar disipador y pasta termica." }
            else { Diag-Ok "Temperatura bajo carga correcta." }
        }
        if ($escala -lt ($hilos * 0.35)) { Diag-Aviso "La CPU escalo poco con todos los hilos (x$escala de $hilos): puede haber limitacion por temperatura/energia o procesos pesados en segundo plano." }
        else { Diag-Ok "El procesador escala bien con todos sus hilos." }
        $ref = if ($v1 -lt 40) { "bajo (equipo antiguo o de gama baja)" } elseif ($v1 -lt 90) { "medio" } else { "alto" }
        Write-DiagLog " - Rendimiento por hilo: $ref (referencia relativa; compara con otros equipos usando esta misma prueba)"
    } catch {
        try { [DragonCpuBench]::Detener() | Out-Null } catch {}
        Write-DiagLog "No se pudo ejecutar la prueba de rendimiento: $($_.Exception.Message)"
    }
}

function Accion-InfoHardwareCompleta {
    Write-DiagLog "=== INFORMACION DEL HARDWARE ==="
    try {
        $cs = Get-CimInstance Win32_ComputerSystem -ErrorAction Stop
        Write-DiagLog " - Equipo: $($cs.Manufacturer) $($cs.Model)"
    } catch {}
    try {
        $bb = Get-CimInstance Win32_BaseBoard -ErrorAction Stop; $bios = Get-CimInstance Win32_BIOS -ErrorAction Stop
        Write-DiagLog " - Placa base: $($bb.Manufacturer) $($bb.Product)"
        Write-DiagLog " - BIOS: $($bios.SMBIOSBIOSVersion) ($(try { $bios.ReleaseDate.ToString('yyyy-MM-dd') } catch { 'sin fecha' }))"
        try { if ($bios.ReleaseDate -and ((Get-Date) - $bios.ReleaseDate).TotalDays -gt 1460) { Write-DiagLog "   La BIOS tiene mas de 4 años: revisa si el fabricante publico una actualizacion." } } catch {}
    } catch {}
    try {
        $cpu = Get-CimInstance Win32_Processor -ErrorAction Stop | Select-Object -First 1
        Write-DiagLog " - Procesador: $($cpu.Name.Trim()) | $($cpu.NumberOfCores) nucleos / $($cpu.NumberOfLogicalProcessors) hilos | hasta $($cpu.MaxClockSpeed) MHz | Cache L3: $([math]::Round($cpu.L3CacheSize/1024,0)) MB"
    } catch {}
    try {
        $tipos = @{ 20 = 'DDR'; 21 = 'DDR2'; 24 = 'DDR3'; 26 = 'DDR4'; 34 = 'DDR5'; 35 = 'LPDDR5' }
        $mods = @(Get-CimInstance Win32_PhysicalMemory -ErrorAction Stop)
        $arr = Get-CimInstance Win32_PhysicalMemoryArray -ErrorAction SilentlyContinue | Select-Object -First 1
        $totalGB = [math]::Round(($mods | Measure-Object Capacity -Sum).Sum / 1GB, 0)
        Write-DiagLog " - Memoria RAM: $totalGB GB en $($mods.Count) modulo(s)$(if ($arr) { " de $($arr.MemoryDevices) ranuras" })"
        foreach ($m in $mods) {
            $tp = if ($tipos.ContainsKey([int]$m.SMBIOSMemoryType)) { $tipos[[int]$m.SMBIOSMemoryType] } else { 'RAM' }
            Write-DiagLog "     · $($m.BankLabel) $($m.DeviceLocator): $([math]::Round($m.Capacity/1GB,0)) GB $tp $($m.Speed) MHz | $("$($m.Manufacturer)".Trim()) $("$($m.PartNumber)".Trim())"
        }
        if ($mods.Count -eq 1 -and $arr -and $arr.MemoryDevices -gt 1) { Write-DiagLog "   Solo hay 1 modulo: con 2 modulos iguales trabajaria en doble canal (mas rendimiento)." }
    } catch {}
    try {
        foreach ($g in @(Get-CimInstance Win32_VideoController -ErrorAction Stop)) { Write-DiagLog " - Video: $($g.Name) | Driver $($g.DriverVersion)" }
    } catch {}
    try {
        foreach ($d in @(Get-PhysicalDisk -ErrorAction Stop)) { Write-DiagLog " - Disco: $($d.FriendlyName) | $($d.MediaType) $($d.BusType) | $([math]::Round($d.Size/1GB,0)) GB | $($d.HealthStatus)" }
    } catch {}
    try {
        $os = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop
        Write-DiagLog " - Sistema: $($os.Caption) $($os.OSArchitecture) | Version $($os.Version) | Instalado el $($os.InstallDate.ToString('yyyy-MM-dd'))"
    } catch {}
    try { Write-DiagLog " - Arranque seguro (Secure Boot): $(if (Confirm-SecureBootUEFI -ErrorAction Stop) { 'Activado' } else { 'Desactivado' })" } catch { Write-DiagLog " - Arranque seguro: no disponible (BIOS clasica o sin permisos)" }
    try { $tpm = Get-Tpm -ErrorAction Stop; Write-DiagLog " - TPM: $(if ($tpm.TpmPresent) { if ($tpm.TpmReady) { 'Presente y listo' } else { 'Presente' } } else { 'No presente' })" } catch {}
}

function Accion-ProbarDispositivosAudio {
    Write-DiagLog "=== DISPOSITIVOS DE AUDIO ==="
    try {
        $snd = @(Get-CimInstance Win32_SoundDevice -ErrorAction Stop)
        if ($snd.Count -eq 0) { Diag-Aviso "No se detecto ninguna tarjeta de sonido."; return }
        foreach ($s in $snd) {
            Write-DiagLog " - $($s.Name) | Estado: $($s.Status) | Fabricante: $($s.Manufacturer)"
            if ("$($s.Status)" -ne 'OK') { Diag-Aviso "El dispositivo de audio '$($s.Name)' reporta estado $($s.Status). Reinstala su controlador." }
        }
        $svc = Get-Service Audiosrv -ErrorAction SilentlyContinue
        if ($svc) {
            Write-DiagLog " - Servicio de audio de Windows: $($svc.Status)"
            if ("$($svc.Status)" -ne 'Running') { Diag-Aviso "El servicio de audio de Windows (Audiosrv) esta detenido; sin el no habra sonido." } else { Diag-Ok "Audio de Windows en ejecucion." }
        }
        try {
            $ep = @(Get-PnpDevice -Class AudioEndpoint -PresentOnly -ErrorAction Stop)
            foreach ($e in $ep) { Write-DiagLog "     · $($e.FriendlyName) ($($e.Status))" }
        } catch {}
        Write-DiagLog "Usa los botones de altavoz izquierdo/derecho y microfono para probar el sonido real."
    } catch { Write-DiagLog "No se pudo consultar los dispositivos de audio." }
}

function Accion-ProbarDispositivosProblemas {
    Write-DiagLog "=== DISPOSITIVOS CON PROBLEMAS (Administrador de dispositivos) ==="
    try {
        $codigos = @{ 1 = 'mal configurado'; 3 = 'driver danado o poca memoria'; 10 = 'no puede iniciar'; 12 = 'recursos en conflicto'; 18 = 'reinstalar driver'; 19 = 'registro danado'; 22 = 'deshabilitado'; 24 = 'no presente o con fallos'; 28 = 'sin driver instalado'; 31 = 'no funciona correctamente'; 33 = 'recurso no determinado'; 39 = 'driver danado o ausente'; 40 = 'registro invalido'; 41 = 'Windows lo detecto pero no puede cargarlo'; 43 = 'Windows lo detuvo (reporto problemas)'; 45 = 'dispositivo no conectado'; 52 = 'driver sin firma digital' }
        $malos = @(Get-CimInstance Win32_PnPEntity -ErrorAction Stop | Where-Object { $_.ConfigManagerErrorCode -gt 0 })
        if ($malos.Count -eq 0) { Diag-Ok "Ningun dispositivo reporta problemas."; return }
        foreach ($m in $malos) {
            $c = [int]$m.ConfigManagerErrorCode
            $txt = if ($codigos.ContainsKey($c)) { $codigos[$c] } else { 'con problema' }
            if ($c -eq 22) { Write-DiagLog " - $($m.Name): deshabilitado manualmente (codigo 22)" }
            else { Diag-Aviso "$($m.Name): $txt (codigo $c). Actualiza o reinstala el controlador en la pestaña Controladores." }
        }
    } catch { Write-DiagLog "No se pudo consultar el Administrador de dispositivos." }
}

function Accion-ProbarEventosCriticos {
    Write-DiagLog "=== EVENTOS CRITICOS DEL SISTEMA (ultimos 7 dias) ==="
    try {
        $desde = (Get-Date).AddDays(-7)
        $ev = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; Level = @(1, 2); StartTime = $desde } -MaxEvents 400 -ErrorAction Stop)
        if ($ev.Count -eq 0) { Diag-Ok "Sin incidencias graves en el registro del sistema durante la ultima semana."; return }
        Write-DiagLog "Se registraron $($ev.Count) evento(s) graves. Los mas frecuentes:"
        $grupos = $ev | Group-Object ProviderName | Sort-Object Count -Descending | Select-Object -First 8
        foreach ($g in $grupos) {
            $ult = ($g.Group | Sort-Object TimeCreated -Descending | Select-Object -First 1)
            $msg = (("$($ult.Message)" -split "`r?`n")[0]).Trim(); if ($msg.Length -gt 110) { $msg = $msg.Substring(0, 110) + '...' }
            Write-DiagLog " - $($g.Name): $($g.Count) vez/veces | ultimo $($ult.TimeCreated.ToString('dd/MM HH:mm')) | $msg"
        }
        $graves = @($ev | Where-Object { $_.ProviderName -match 'WHEA|Kernel-Power|disk|Ntfs|nvlddmkm|stornvme|volmgr|BugCheck' })
        if ($graves.Count) { Diag-Aviso "Hay $($graves.Count) evento(s) relacionados con hardware/apagados inesperados. Usa 'Escanear hardware' en la pestaña Registro de errores para el detalle." }
    } catch { Write-DiagLog "No se pudo leer el registro de eventos del sistema (¿sin permisos?)." }
}

function Accion-ProbarEstadoWindows {
    Write-DiagLog "=== ESTADO GENERAL DE WINDOWS ==="
    try {
        $pendiente = (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired') -or (Test-Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\PendingFileRenameOperations')
        if ($pendiente) { Diag-Aviso "Hay un reinicio pendiente (actualizaciones o instalaciones). Reinicia el equipo." } else { Diag-Ok "No hay reinicios pendientes." }
    } catch {}
    try {
        $mp = Get-MpComputerStatus -ErrorAction Stop
        if ($mp.RealTimeProtectionEnabled) { Diag-Ok "Proteccion en tiempo real de Windows Defender: activa." } else { Diag-Aviso "La proteccion en tiempo real esta desactivada (puede haber otro antivirus instalado)." }
        $edad = ((Get-Date) - $mp.AntivirusSignatureLastUpdated).TotalDays
        if ($edad -gt 7) { Diag-Aviso "Las firmas del antivirus tienen $([int]$edad) dias. Actualizalas." } else { Write-DiagLog " - Firmas del antivirus al dia ($([int]$edad) dia(s))." }
    } catch { Write-DiagLog " - Windows Defender no disponible (puede haber otro antivirus)." }
    try {
        $fw = @(Get-NetFirewallProfile -ErrorAction Stop | Where-Object { -not $_.Enabled })
        if ($fw.Count) { Diag-Aviso "El firewall esta desactivado en: $(($fw | ForEach-Object { $_.Name }) -join ', ')." } else { Diag-Ok "Firewall de Windows activo en todos los perfiles." }
    } catch {}
    try {
        $uac = (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' -ErrorAction Stop).EnableLUA
        if ($uac -eq 1) { Diag-Ok "Control de cuentas de usuario (UAC) activo." } else { Diag-Aviso "UAC esta desactivado: menos proteccion ante programas maliciosos." }
    } catch {}
    try {
        $svc = Get-Service wuauserv -ErrorAction Stop
        Write-DiagLog " - Windows Update: servicio $($svc.Status) ($($svc.StartType))"
        if ("$($svc.StartType)" -eq 'Disabled') { Write-DiagLog "   Windows Update esta deshabilitado: no recibira parches de seguridad." }
    } catch {}
    try {
        $ld = Get-CimInstance Win32_LogicalDisk -Filter "DeviceID='$($env:SystemDrive)'" -ErrorAction Stop
        $pct = [math]::Round(($ld.FreeSpace / $ld.Size) * 100, 0)
        if ($pct -lt 10) { Diag-Aviso "La unidad del sistema tiene solo $pct% libre." } else { Diag-Ok "Espacio en la unidad del sistema correcto ($pct% libre)." }
    } catch {}
}

# ---------------------------------------------------------------------------
#  ALMACENAMIENTO AVANZADO (disco duro / SSD): detalle fisico, particiones,
#  atributos S.M.A.R.T., sectores danados, latencia, actividad y eventos
# ---------------------------------------------------------------------------
# Convierte a numero entero sin fallar con valores como "Unknown" o vacios (devuelve 0)
function Global:Numero-Seguro {
    param($Valor)
    try { if ($null -eq $Valor) { return [int64]0 }; $r = [int64]0; if ([int64]::TryParse("$Valor", [ref]$r)) { return $r } } catch { }
    return [int64]0
}

function Global:Format-TamanoDisco {
    param([double]$Bytes)
    if ($Bytes -ge 1TB) { return ("{0:N2} TB" -f ($Bytes / 1TB)) }
    if ($Bytes -ge 1GB) { return ("{0:N1} GB" -f ($Bytes / 1GB)) }
    return ("{0:N0} MB" -f ($Bytes / 1MB))
}

# Nombres legibles de los atributos S.M.A.R.T. mas comunes
$Global:SmartNombres = @{
    1 = 'Tasa de errores de lectura'; 3 = 'Tiempo de arranque del motor'; 4 = 'Ciclos de arranque/parada'
    5 = 'Sectores reasignados'; 7 = 'Errores de posicionamiento'; 9 = 'Horas de uso'
    10 = 'Reintentos de arranque del motor'; 12 = 'Ciclos de encendido'; 177 = 'Desgaste (nivelado de celdas)'
    179 = 'Bloques de reserva usados'; 181 = 'Fallos de programacion'; 182 = 'Fallos de borrado'
    183 = 'Errores de enlace SATA'; 184 = 'Errores de datos extremo a extremo'; 187 = 'Errores incorregibles reportados'
    188 = 'Tiempos de espera de comandos'; 190 = 'Temperatura (flujo de aire)'; 191 = 'Golpes / impactos'
    192 = 'Apagados inseguros'; 193 = 'Ciclos de estacionamiento de cabezales'; 194 = 'Temperatura'
    195 = 'Errores corregidos por ECC'; 196 = 'Eventos de reasignacion'; 197 = 'Sectores pendientes de reasignar'
    198 = 'Sectores incorregibles (offline)'; 199 = 'Errores CRC (cable/conexion)'; 200 = 'Errores de escritura multizona'
    231 = 'Vida restante del SSD'; 232 = 'Reserva disponible'; 233 = 'Desgaste de la memoria flash'
    241 = 'Total escrito (LBAs)'; 242 = 'Total leido (LBAs)'
}

# Decodifica el bloque binario S.M.A.R.T. (512 bytes) de Windows en una lista de atributos
function Global:Convertir-AtributosSmart {
    param([byte[]]$Datos, [byte[]]$Umbrales)
    $res = @()
    if (-not $Datos -or $Datos.Length -lt 362) { return $res }
    $umb = @{}
    if ($Umbrales -and $Umbrales.Length -ge 362) {
        for ($i = 2; $i -le 350; $i += 12) {
            $id = [int]$Umbrales[$i]
            if ($id -ne 0) { $umb[$id] = [int]$Umbrales[$i + 1] }
        }
    }
    for ($i = 2; $i -le 350; $i += 12) {
        $id = [int]$Datos[$i]
        if ($id -eq 0) { continue }
        $raw = [int64]0
        for ($k = 5; $k -ge 0; $k--) { $raw = ($raw -shl 8) -bor [int64]$Datos[$i + 5 + $k] }
        $u = 0
        if ($umb.ContainsKey($id)) { $u = $umb[$id] }
        $res += [pscustomobject]@{ Id = $id; Valor = [int]$Datos[$i + 3]; Peor = [int]$Datos[$i + 4]; Umbral = $u; Raw = $raw; RawBajo = [int]$Datos[$i + 5] }
    }
    return $res
}

# Estadisticas de una lista de latencias (ms)
function Global:Estadistica-Latencias {
    param($Lista)
    $arr = [double[]]$Lista.ToArray()
    if ($arr.Length -eq 0) { return @{ Prom = 0; P95 = 0; P99 = 0; Max = 0 } }
    [Array]::Sort($arr)
    $suma = 0.0; foreach ($v in $arr) { $suma += $v }
    $i95 = [Math]::Min($arr.Length - 1, [int][Math]::Floor($arr.Length * 0.95))
    $i99 = [Math]::Min($arr.Length - 1, [int][Math]::Floor($arr.Length * 0.99))
    return @{ Prom = ($suma / $arr.Length); P95 = $arr[$i95]; P99 = $arr[$i99]; Max = $arr[$arr.Length - 1] }
}

# Escribe los contadores de confiabilidad (salud, desgaste, errores) de un disco fisico; devuelve $true si habia datos
function Global:Escribir-ContadoresDisco {
    param($Disco)
    try { $rc = $Disco | Get-StorageReliabilityCounter -ErrorAction Stop } catch { return $false }
    if (-not $rc) { return $false }
    $p1 = @()
    if ($null -ne $rc.Temperature) { $p1 += "Temperatura: $($rc.Temperature) °C" }
    if ($null -ne $rc.TemperatureMax -and [int]$rc.TemperatureMax -gt 0) { $p1 += "Maxima registrada: $($rc.TemperatureMax) °C" }
    if ($null -ne $rc.Wear) { $p1 += "Desgaste: $($rc.Wear)%" }
    if ($null -ne $rc.PowerOnHours) { $p1 += "Horas encendido: $($rc.PowerOnHours) h" }
    if ($p1.Count) { Write-DiagLog "     $($p1 -join ' | ')" }
    $p2 = @()
    if ($null -ne $rc.ReadErrorsTotal) { $p2 += "Errores de lectura: $($rc.ReadErrorsTotal) (corregidos $($rc.ReadErrorsCorrected), sin corregir $($rc.ReadErrorsUncorrected))" }
    if ($null -ne $rc.WriteErrorsTotal) { $p2 += "Errores de escritura: $($rc.WriteErrorsTotal) (sin corregir $($rc.WriteErrorsUncorrected))" }
    if ($p2.Count) { Write-DiagLog "     $($p2 -join ' | ')" }
    $p3 = @()
    if ($null -ne $rc.StartStopCycleCount) { $p3 += "Ciclos de arranque/parada: $($rc.StartStopCycleCount)" }
    if ($null -ne $rc.LoadUnloadCycleCount) { $p3 += "Ciclos de carga de cabezales: $($rc.LoadUnloadCycleCount)" }
    if ($null -ne $rc.ReadLatencyMax -and (Numero-Seguro $rc.ReadLatencyMax) -gt 0) { $p3 += "Latencia max. lectura: $($rc.ReadLatencyMax) ms" }
    if ($null -ne $rc.WriteLatencyMax -and (Numero-Seguro $rc.WriteLatencyMax) -gt 0) { $p3 += "Latencia max. escritura: $($rc.WriteLatencyMax) ms" }
    if ($p3.Count) { Write-DiagLog "     $($p3 -join ' | ')" }
    if ($null -ne $rc.Temperature -and [int]$rc.Temperature -gt 60) { Diag-Aviso "Temperatura alta del disco ($($rc.Temperature) °C). Mejora la ventilacion." }
    if ($null -ne $rc.Wear -and [int]$rc.Wear -gt 85) { Diag-Aviso "El SSD tiene mas del 85% de desgaste. Planea reemplazarlo." }
    $sinCorregir = 0
    if ($null -ne $rc.ReadErrorsUncorrected) { $sinCorregir += (Numero-Seguro $rc.ReadErrorsUncorrected) }
    if ($null -ne $rc.WriteErrorsUncorrected) { $sinCorregir += (Numero-Seguro $rc.WriteErrorsUncorrected) }
    if ($sinCorregir -gt 0) { Diag-Aviso "El disco acumula $sinCorregir error(es) de lectura/escritura sin corregir (posibles sectores danados)." }
    return $true
}

function Accion-DiscoDetalleFisico {
    Write-DiagLog "=== DISCO: DETALLE FISICO Y SECTORES ==="
    $pd = @(); $dk = @(); $wd = @()
    try { $pd = @(Get-PhysicalDisk -ErrorAction Stop) } catch {}
    try { $dk = @(Get-Disk -ErrorAction Stop) } catch {}
    try { $wd = @(Get-CimInstance Win32_DiskDrive -ErrorAction Stop) } catch {}
    if ($wd.Count -eq 0) { Write-DiagLog "No se pudo obtener la lista de discos de este equipo."; return }
    foreach ($w in $wd) {
        $num = "$($w.Index)"
        $p = $pd | Where-Object { "$($_.DeviceId)" -eq $num } | Select-Object -First 1
        $d = $dk | Where-Object { "$($_.Number)" -eq $num } | Select-Object -First 1
        $tipo = ''; $bus = "$($w.InterfaceType)"
        if ($p) { $tipo = "$($p.MediaType)"; $bus = "$($p.BusType)" }
        Write-DiagLog " - Disco ${num}: $($w.Model) | $tipo | $bus | $(Format-TamanoDisco $w.Size)"
        $serie = "$($w.SerialNumber)".Trim()
        $linea = @()
        if ($serie) { $linea += "Serie: $serie" }
        if ($w.FirmwareRevision) { $linea += "Firmware: $($w.FirmwareRevision)" }
        if ($d) { $linea += "Estilo de particion: $($d.PartitionStyle)"; $linea += "Particiones: $($d.NumberOfPartitions)" }
        if ($linea.Count) { Write-DiagLog "     $($linea -join ' | ')" }
        $ls = [int](Numero-Seguro $w.BytesPerSector)
        $ps = 0
        if ($p) {
            if ((Numero-Seguro $p.LogicalSectorSize) -gt 0) { $ls = [int](Numero-Seguro $p.LogicalSectorSize) }
            if ((Numero-Seguro $p.PhysicalSectorSize) -gt 0) { $ps = [int](Numero-Seguro $p.PhysicalSectorSize) }
        }
        $fmt = ''
        if ($ls -eq 512 -and $ps -eq 4096) { $fmt = ' (formato 512e / Advanced Format)' }
        elseif ($ls -eq 4096) { $fmt = ' (formato 4Kn nativo)' }
        $sec = "Sector logico: $ls bytes"
        if ($ps -gt 0) { $sec += " | Sector fisico: $ps bytes" }
        Write-DiagLog "     $sec$fmt"
        if ((Numero-Seguro $w.TotalSectors) -gt 0) {
            $g = ''
            if ($w.TotalCylinders) { $g = " | Geometria: $($w.TotalCylinders) cilindros x $($w.TotalHeads) cabezas x $($w.SectorsPerTrack) sectores/pista" }
            Write-DiagLog "     Sectores totales: $('{0:N0}' -f (Numero-Seguro $w.TotalSectors))$g"
        }
        if ($p -and (Numero-Seguro $p.SpindleSpeed) -gt 0 -and (Numero-Seguro $p.SpindleSpeed) -lt 100000) { Write-DiagLog "     Velocidad de giro: $($p.SpindleSpeed) RPM (disco mecanico)" }
        if ($d) {
            if ($d.IsOffline) { Diag-Aviso "El disco $num esta sin conexion (offline) en Administracion de discos." }
            if ($d.IsReadOnly) { Diag-Aviso "El disco $num esta en modo solo lectura." }
        }
        if ($p) {
            if ("$($p.HealthStatus)" -eq 'Healthy') { Diag-Ok "Salud del disco ${num}: Healthy (OK)" }
            else { Diag-Aviso "Salud del disco ${num}: $($p.HealthStatus) ($($p.OperationalStatus)). Haz copia de seguridad y revisa el disco." }
            if (-not (Escribir-ContadoresDisco -Disco $p)) { Write-DiagLog "     (Este disco/controlador no entrega contadores de confiabilidad.)" }
            try { Escribir-VidaSSD -Disco $p } catch { }
        }
    }
    # TRIM (importante para el rendimiento y vida util de los SSD)
    try {
        $t = (& fsutil.exe behavior query DisableDeleteNotify 2>&1) -join ' '
        if ($t -match '=\s*0') { Diag-Ok "TRIM activado (los SSD liberan bloques correctamente)." }
        elseif ($t -match '=\s*1') { Diag-Aviso "TRIM desactivado. En un SSD baja el rendimiento con el tiempo (activalo con: fsutil behavior set DisableDeleteNotify 0)." }
    } catch {}
}

function Accion-DiscoParticiones {
    Write-DiagLog "=== DISCO: PARTICIONES, VOLUMENES Y ALINEACION ==="
    $parts = @(); $vols = @(); $wv = @()
    try { $parts = @(Get-Partition -ErrorAction Stop | Sort-Object DiskNumber, PartitionNumber) } catch { Write-DiagLog "No se pudo leer la tabla de particiones (Get-Partition no disponible)."; return }
    try { $vols = @(Get-Volume -ErrorAction Stop) } catch {}
    try { $wv = @(Get-CimInstance Win32_Volume -Filter 'DriveType=3' -ErrorAction Stop) } catch {}
    foreach ($pt in $parts) {
        $letra = ''
        if ($pt.DriveLetter) { $letra = "$($pt.DriveLetter):" }
        $tipo = "$($pt.Type)"
        Write-DiagLog " - Disco $($pt.DiskNumber) / Particion $($pt.PartitionNumber) $letra | $tipo | $(Format-TamanoDisco $pt.Size)"
        $off = Numero-Seguro $pt.Offset
        $alin = 'sin alinear a 4 KB'
        if (($off % 1048576) -eq 0) { $alin = 'alineada a 1 MB (optima)' }
        elseif (($off % 4096) -eq 0) { $alin = 'alineada a 4 KB (correcta)' }
        Write-DiagLog "     Inicio: sector $('{0:N0}' -f ($off / 512)) | Alineacion: $alin"
        if (($off % 4096) -ne 0) { Diag-Aviso "La particion no esta alineada a 4 KB: puede reducir el rendimiento en SSD y discos 4K." }
        if ($pt.IsBoot) { Write-DiagLog "     Contiene el arranque (Boot)" }
        if ($pt.IsSystem) { Write-DiagLog "     Particion del sistema (EFI/System)" }
        if ($pt.DriveLetter) {
            $v = $vols | Where-Object { "$($_.DriveLetter)" -eq "$($pt.DriveLetter)" } | Select-Object -First 1
            $x = $wv | Where-Object { $_.DriveLetter -eq $letra } | Select-Object -First 1
            if ($v) {
                $libre = $v.SizeRemaining; $total = $v.Size
                $pct = 0; if ($total -gt 0) { $pct = [math]::Round(($libre / $total) * 100, 0) }
                Write-DiagLog "     Sistema de archivos: $($v.FileSystem) | Etiqueta: $($v.FileSystemLabel) | Libre: $(Format-TamanoDisco $libre) ($pct%)"
                if ("$($v.HealthStatus)" -ne 'Healthy' -and "$($v.HealthStatus)") { Diag-Aviso "El volumen $letra reporta estado '$($v.HealthStatus)'. Ejecuta la verificacion CHKDSK." }
                if ($total -gt 0 -and $pct -lt 10) { Diag-Aviso "Poco espacio libre en $letra ($pct%). Libera espacio para evitar lentitud." }
            }
            if ($x) {
                $extra = @()
                if ($x.BlockSize) { $extra += "Cluster: $($x.BlockSize) bytes" }
                if ($x.Compressed) { $extra += "comprimido" }
                if ($extra.Count) { Write-DiagLog "     $($extra -join ' | ')" }
                if ($x.DirtyBitSet) { Diag-Aviso "El volumen $letra tiene el indicador de 'sucio' (apagado incorrecto o errores). Ejecuta CHKDSK." }
                else { Diag-Ok "Volumen $letra sin indicador de error pendiente (dirty bit limpio)." }
            }
        }
    }
}

function Accion-DiscoSmartAtributos {
    Write-DiagLog "=== DISCO: ATRIBUTOS S.M.A.R.T. (sectores danados, desgaste, errores) ==="
    $datos = @(); $umbr = @()
    try { $datos = @(Get-CimInstance -Namespace root\wmi -ClassName MSStorageDriver_ATAPISmartData -ErrorAction Stop) } catch {}
    try { $umbr = @(Get-CimInstance -Namespace root\wmi -ClassName MSStorageDriver_FailurePredictThresholds -ErrorAction Stop) } catch {}
    if ($datos.Count -eq 0) {
        Write-DiagLog "   Este equipo no expone la tabla S.M.A.R.T. clasica (discos NVMe, USB o controlador RAID). Se muestran los contadores de confiabilidad de Windows:"
        $hubo = $false
        try {
            foreach ($p in @(Get-PhysicalDisk -ErrorAction Stop)) {
                Write-DiagLog " - $($p.FriendlyName) | $($p.MediaType) | $($p.BusType)"
                if (Escribir-ContadoresDisco -Disco $p) { $hubo = $true }
            }
        } catch {}
        if (-not $hubo) { Write-DiagLog "   No hay contadores de confiabilidad disponibles. Prueba con la herramienta del fabricante del disco (CrystalDiskInfo, Samsung Magician, etc.)." }
        return
    }
    foreach ($d in $datos) {
        $u = $umbr | Where-Object { $_.InstanceName -eq $d.InstanceName } | Select-Object -First 1
        $ub = $null; if ($u) { $ub = $u.VendorSpecific }
        $attrs = @(Convertir-AtributosSmart -Datos $d.VendorSpecific -Umbrales $ub)
        Write-DiagLog " - Unidad: $($d.InstanceName)"
        if ($attrs.Count -eq 0) { Write-DiagLog "     (No se pudieron leer atributos de esta unidad.)"; continue }
        Write-DiagLog ("     {0,-4} {1,-36} {2,5} {3,5} {4,6}  {5}" -f 'ID', 'Atributo', 'Valor', 'Peor', 'Umbral', 'Dato / estado')
        foreach ($a in $attrs) {
            $nombre = $Global:SmartNombres[[int]$a.Id]
            $conocido = [bool]$nombre
            if (-not $conocido) { $nombre = "Atributo $($a.Id)" }
            $dato = "$($a.Raw)"
            switch ($a.Id) {
                9   { $dato = "$($a.Raw) h (~$([math]::Round($a.Raw / 24, 0)) dias)" }
                190 { $dato = "$($a.RawBajo) °C" }
                194 { $dato = "$($a.RawBajo) °C" }
                241 { $dato = "$($a.Raw) (~$([math]::Round(($a.Raw * 512) / 1GB, 0)) GB)" }
                242 { $dato = "$($a.Raw) (~$([math]::Round(($a.Raw * 512) / 1GB, 0)) GB)" }
            }
            $estado = ''
            if ($a.Umbral -gt 0 -and $a.Valor -le $a.Umbral) { $estado = ' ⚠ POR DEBAJO DEL UMBRAL'; Diag-Aviso "S.M.A.R.T.: '$nombre' esta por debajo del umbral del fabricante. El disco esta fallando." }
            elseif (@(5, 196, 197, 198) -contains $a.Id -and $a.Raw -gt 0) {
                $estado = ' ⚠ SECTORES DANADOS'
                Diag-Aviso "S.M.A.R.T.: '$nombre' = $($a.Raw). El disco tiene sectores defectuosos; haz copia de seguridad y planea reemplazarlo."
            }
            elseif (@(184, 187, 10) -contains $a.Id -and $a.Raw -gt 0) {
                $estado = ' ⚠ ERRORES'
                Diag-Aviso "S.M.A.R.T.: '$nombre' = $($a.Raw). Vigila el disco y haz copia de seguridad."
            }
            elseif ($a.Id -eq 199 -and $a.Raw -gt 0) {
                $estado = ' ⚠ revisar cable'
                Write-DiagLog "     (Errores CRC: suelen deberse al cable SATA o a la conexion; cambia el cable si aumentan.)"
            }
            elseif (@(194, 190) -contains $a.Id -and $a.RawBajo -ge 60) {
                $estado = ' ⚠ CALIENTE'; Diag-Aviso "Temperatura del disco alta ($($a.RawBajo) °C)."
            }
            elseif (@(177, 231, 233) -contains $a.Id -and $a.Valor -le 20) {
                $estado = ' ⚠ VIDA BAJA'; Diag-Aviso "'$nombre' indica poca vida util restante ($($a.Valor)%)."
            }
            elseif ($conocido) { $estado = ' OK' }
            if ($conocido -or $estado) {
                Write-DiagLog ("     {0,-4} {1,-36} {2,5} {3,5} {4,6}  {5}{6}" -f $a.Id, $nombre, $a.Valor, $a.Peor, $a.Umbral, $dato, $estado)
            }
        }
        $pend = $attrs | Where-Object { $_.Id -eq 197 } | Select-Object -First 1
        $real = $attrs | Where-Object { $_.Id -eq 5 } | Select-Object -First 1
        if (($pend -and $pend.Raw -eq 0) -and ($real -and $real.Raw -eq 0)) { Diag-Ok "Sin sectores reasignados ni pendientes: la superficie del disco esta sana segun S.M.A.R.T." }
    }
}

function Accion-DiscoEventos {
    Write-DiagLog "=== DISCO: EVENTOS DE ERROR DEL SISTEMA (ultimos 30 dias) ==="
    $desc = @{
        'disk|7'  = 'Bloque defectuoso (bad block) detectado'
        'disk|11' = 'Error del controlador de disco'
        'disk|15' = 'Dispositivo de disco no listo'
        'disk|51' = 'Error de paginacion en el disco'
        'disk|52' = 'El disco predice un fallo (S.M.A.R.T.)'
        'disk|153' = 'Reintento de E/S (el disco tarda o falla)'
        'disk|154' = 'Error de hardware irrecuperable en el disco'
        'Ntfs|55'  = 'Estructura del sistema de archivos danada'
        'Ntfs|137' = 'NTFS no pudo escribir datos de la unidad'
        'Ntfs|140' = 'NTFS no pudo vaciar datos al disco'
        'stornvme|129' = 'Restablecimiento del dispositivo NVMe'
        'storahci|129' = 'Restablecimiento del controlador SATA'
        'stornvme|153' = 'Reintento de E/S en NVMe'
    }
    $ids = @(7, 11, 15, 51, 52, 129, 137, 140, 153, 154, 55)
    $proveedores = @('disk', 'Ntfs', 'stornvme', 'storahci')
    $evs = @()
    try {
        $evs = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = $proveedores; Id = $ids; StartTime = (Get-Date).AddDays(-30) } -ErrorAction Stop)
    } catch {
        if ("$($_.Exception.Message)" -match '(?i)no events|no se encontr') { $evs = @() }
        else { Write-DiagLog "   No se pudo leer el visor de sucesos: $($_.Exception.Message)"; return }
    }
    $conocidos = @($evs | Where-Object { $desc.ContainsKey("$($_.ProviderName)|$($_.Id)") })
    if ($conocidos.Count -eq 0) { Diag-Ok "No hay eventos de error de disco ni de sistema de archivos en los ultimos 30 dias."; return }
    $grupos = $conocidos | Group-Object { "$($_.ProviderName)|$($_.Id)" } | Sort-Object Count -Descending
    foreach ($g in $grupos) {
        $ult = ($g.Group | Sort-Object TimeCreated -Descending | Select-Object -First 1).TimeCreated
        $txt = $desc[$g.Name]
        $linea = "$($g.Count) vez/veces - $txt (ultimo: $($ult.ToString('yyyy-MM-dd HH:mm')))"
        if (@('disk|7', 'disk|11', 'disk|51', 'disk|52', 'disk|154', 'Ntfs|55') -contains $g.Name) { Diag-Aviso $linea }
        else { Write-DiagLog "   - $linea" }
    }
    Write-DiagLog "   Si ves 'Bloque defectuoso' o 'Error del controlador' repetidos, el disco o su cable pueden estar fallando."
}

function Accion-DiscoActividad {
    Write-DiagLog "=== DISCO: ACTIVIDAD EN VIVO (6 segundos) ==="
    Write-DiagLog "Midiendo uso, cola y transferencia de cada disco..."
    $muestras = @{}
    for ($i = 0; $i -lt 6; $i++) {
        $d = @()
        try { $d = @(Get-CimInstance Win32_PerfFormattedData_PerfDisk_PhysicalDisk -Filter "Name<>'_Total'" -ErrorAction Stop) }
        catch { Write-DiagLog "   Los contadores de rendimiento de disco no estan disponibles: $($_.Exception.Message)"; return }
        foreach ($x in $d) {
            if (-not $muestras.ContainsKey($x.Name)) { $muestras[$x.Name] = @() }
            $muestras[$x.Name] += ,@([double]$x.PercentDiskTime, [double]$x.DiskReadBytesPerSec, [double]$x.DiskWriteBytesPerSec, [double]$x.CurrentDiskQueueLength)
        }
        Diag-Progreso -Pct ((($i + 1) / 6) * 100) -Texto "Muestra $($i + 1) de 6..."
        Wait-UI -Milisegundos 1000
    }
    foreach ($k in $muestras.Keys) {
        $m = $muestras[$k]
        $uso = 0.0; $usoMax = 0.0; $lec = 0.0; $esc = 0.0; $colaMax = 0.0
        foreach ($s in $m) {
            $uso += $s[0]; if ($s[0] -gt $usoMax) { $usoMax = $s[0] }
            $lec += $s[1]; $esc += $s[2]
            if ($s[3] -gt $colaMax) { $colaMax = $s[3] }
        }
        $n = [Math]::Max(1, $m.Count)
        Write-DiagLog (" - Disco {0}: uso medio {1:N0}% (pico {2:N0}%) | lectura {3:N1} MB/s | escritura {4:N1} MB/s | cola maxima {5:N0}" -f $k, ($uso / $n), $usoMax, (($lec / $n) / 1MB), (($esc / $n) / 1MB), $colaMax)
        if (($uso / $n) -ge 90) { Diag-Aviso "El disco $k esta al 90% o mas de uso de forma sostenida: causa lentitud. Revisa que proceso lo esta usando (Administrador de tareas)." }
        elseif ($colaMax -ge 8) { Diag-Aviso "El disco $k tiene cola de operaciones alta; puede estar saturado o con problemas." }
        else { Diag-Ok "Actividad del disco $k normal." }
    }
}

function Accion-DiscoLatencia4K {
    $uDisco = Unidad-Diag
    Write-DiagLog "=== DISCO: LATENCIA ALEATORIA 4K (en $uDisco) ==="
    $arch = $null
    try {
        $ld = Get-CimInstance Win32_LogicalDisk -Filter "DeviceID='$uDisco'" -ErrorAction SilentlyContinue
        $tamMB = 128
        if ($ld -and ($ld.FreeSpace / 1MB) -lt ($tamMB * 4)) { Write-DiagLog "Hay muy poco espacio libre para esta prueba."; return }
        $carp = Carpeta-PruebaDisco $uDisco
        if (-not (Test-Path $carp)) { New-Item -Path $carp -ItemType Directory -Force | Out-Null }
        $arch = Join-Path $carp "lat4k.tmp"
        $tam = [int64]$tamMB * 1MB
        $bloques = [int]($tam / 4096)
        $buf = New-Object byte[] 4096
        (New-Object Random).NextBytes($buf)
        $rnd = New-Object Random
        $ops = 1000
        $sw = New-Object System.Diagnostics.Stopwatch

        Write-DiagLog "Escritura aleatoria de $ops bloques de 4 KB (escritura directa a disco)..."
        $fs = New-Object System.IO.FileStream($arch, [System.IO.FileMode]::Create, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None, 4096, [System.IO.FileOptions]::WriteThrough)
        $fs.SetLength($tam)
        $latE = New-Object 'System.Collections.Generic.List[double]'
        for ($i = 0; $i -lt $ops; $i++) {
            $pos = [int64]$rnd.Next(0, $bloques) * 4096
            $sw.Restart()
            [void]$fs.Seek($pos, [System.IO.SeekOrigin]::Begin)
            $fs.Write($buf, 0, 4096)
            $sw.Stop()
            $latE.Add($sw.Elapsed.TotalMilliseconds)
            if ($i % 25 -eq 0) { Diag-Progreso -Pct (($i / $ops) * 50) -Texto "Escritura aleatoria 4K ($i de $ops)..." }
        }
        $fs.Flush($true); $fs.Close()

        Write-DiagLog "Lectura aleatoria de $ops bloques de 4 KB..."
        $fs = New-Object System.IO.FileStream($arch, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read, 4096, [System.IO.FileOptions]::RandomAccess)
        $latL = New-Object 'System.Collections.Generic.List[double]'
        for ($i = 0; $i -lt $ops; $i++) {
            $pos = [int64]$rnd.Next(0, $bloques) * 4096
            $sw.Restart()
            [void]$fs.Seek($pos, [System.IO.SeekOrigin]::Begin)
            [void]$fs.Read($buf, 0, 4096)
            $sw.Stop()
            $latL.Add($sw.Elapsed.TotalMilliseconds)
            if ($i % 25 -eq 0) { Diag-Progreso -Pct (50 + ($i / $ops) * 50) -Texto "Lectura aleatoria 4K ($i de $ops)..." }
        }
        $fs.Close()

        $e = Estadistica-Latencias -Lista $latE
        $l = Estadistica-Latencias -Lista $latL
        Write-DiagLog (" - Escritura 4K: promedio {0:N2} ms | p95 {1:N2} ms | p99 {2:N2} ms | maximo {3:N1} ms | ~{4:N0} IOPS" -f $e.Prom, $e.P95, $e.P99, $e.Max, (1000 / [Math]::Max(0.001, $e.Prom)))
        Write-DiagLog (" - Lectura 4K:   promedio {0:N3} ms | p95 {1:N3} ms | p99 {2:N3} ms | maximo {3:N1} ms (puede venir de la cache de Windows)" -f $l.Prom, $l.P95, $l.P99, $l.Max)
        if ($e.Prom -lt 1) { Write-DiagLog " - Clasificacion: SSD rapido (NVMe o SATA moderno)" }
        elseif ($e.Prom -lt 5) { Write-DiagLog " - Clasificacion: SSD SATA / unidad con cache" }
        elseif ($e.Prom -lt 25) { Write-DiagLog " - Clasificacion: disco mecanico (HDD) normal" }
        else { Write-DiagLog " - Clasificacion: latencia muy alta" }
        if ($e.Prom -ge 25) { Diag-Aviso "Latencia de escritura muy alta ($([math]::Round($e.Prom,1)) ms). El disco esta lento o con problemas: revisa S.M.A.R.T. y cables." }
        elseif ($e.Max -ge 500) { Diag-Aviso "Hubo un pico de latencia de $([math]::Round($e.Max,0)) ms. Pueden ser reintentos por sectores debiles." }
        else { Diag-Ok "Latencia del disco dentro de lo esperado." }
    } catch {
        Write-DiagLog "No se pudo medir la latencia del disco: $($_.Exception.Message)"
    } finally {
        if ($arch) { Remove-Item $arch -Force -ErrorAction SilentlyContinue }
    }
}

# ---------------------------------------------------------------------------
#  UNIDAD ELEGIDA PARA LAS PRUEBAS DE DISCO Y PRUEBA DE ESTRES CON DURACION
# ---------------------------------------------------------------------------
$Global:CmbDiagUnidad = $null

# Rellena la lista de unidades (fijas y extraibles) del panel de disco
function Global:Cargar-UnidadesDiag {
    $cmb = $Global:CmbDiagUnidad
    if (-not $cmb) { return }
    $Global:CargandoUnidades = $true
    $previa = ''
    try { if ($cmb.SelectedItem) { $previa = "$($cmb.SelectedItem.Tag)" } } catch { }
    $cmb.Items.Clear()
    $unidades = @()
    try { $unidades = @(Get-CimInstance Win32_LogicalDisk -ErrorAction Stop | Where-Object { $_.DriveType -in 2, 3 -and $_.Size } | Sort-Object DeviceID) } catch { }
    $sys = "$env:SystemDrive"
    $idx = 0; $i = 0
    foreach ($u in $unidades) {
        $it = New-Object System.Windows.Controls.ComboBoxItem
        $tipo = if ($u.DriveType -eq 2) { 'extraible' } else { 'fija' }
        $it.Content = "$($u.DeviceID)  $($u.VolumeName)  ($(Format-TamanoDisco $u.Size), $(Format-TamanoDisco $u.FreeSpace) libres, $tipo)"
        $it.Tag = "$($u.DeviceID)"
        [void]$cmb.Items.Add($it)
        if ($previa -and "$($u.DeviceID)" -eq $previa) { $idx = $i } elseif (-not $previa -and "$($u.DeviceID)" -eq $sys) { $idx = $i }
        $i++
    }
    if ($cmb.Items.Count -gt 0) { $cmb.SelectedIndex = $idx }
    $Global:CargandoUnidades = $false
}

# Unidad elegida en el panel (por defecto, la del sistema)
function Global:Unidad-Diag {
    try { if ($Global:CmbDiagUnidad -and $Global:CmbDiagUnidad.SelectedItem) { return "$($Global:CmbDiagUnidad.SelectedItem.Tag)" } } catch { }
    return "$env:SystemDrive"
}

# Carpeta temporal de pruebas dentro de la unidad elegida (en la del sistema, la carpeta TEMP)
function Global:Carpeta-PruebaDisco {
    param([string]$Unidad)
    if (-not $Unidad -or $Unidad -eq "$env:SystemDrive") { return (Join-Path $env:TEMP "DragonToolDiskTest") }
    return (Join-Path "$Unidad\" "DragonToolDiskTest")
}

# Numero de disco fisico que contiene una unidad (C: -> 0, etc.). $null si no se puede saber.
function Global:Disco-DeUnidad {
    param([string]$Unidad)
    try {
        $letra = "$Unidad".Substring(0, 1)
        $p = Get-Partition -DriveLetter $letra -ErrorAction Stop | Select-Object -First 1
        if ($p) { return [int]$p.DiskNumber }
    } catch { }
    return $null
}

function Global:Temperatura-DiscoUnidad {
    param([string]$Unidad)
    try {
        $n = Disco-DeUnidad $Unidad
        if ($null -eq $n) { return $null }
        $pd = Get-PhysicalDisk -ErrorAction Stop | Where-Object { "$($_.DeviceId)" -eq "$n" } | Select-Object -First 1
        if (-not $pd) { return $null }
        $rc = $pd | Get-StorageReliabilityCounter -ErrorAction Stop
        if ($rc -and $null -ne $rc.Temperature -and [int]$rc.Temperature -gt 0) { return [int]$rc.Temperature }
    } catch { }
    return $null
}

function Global:Ensure-TipoDiskVerif {
    if ('DragonDiskVerif' -as [type]) { return }
    Add-Type -TypeDefinition @"
using System;
public static class DragonDiskVerif {
    public static bool Igual(byte[] a, byte[] b, int n) {
        for (int i = 0; i < n; i++) { if (a[i] != b[i]) return false; }
        return true;
    }
    public static void Marca(byte[] a, long idx) {
        byte[] x = BitConverter.GetBytes(idx);
        Array.Copy(x, 0, a, 0, 8);
    }
}
"@
}

$Global:EstState = @{ Corriendo = $false; Detener = $false; Limite = 0; Reloj = $null; CerrarAlTerminar = $false }
$Global:EstUi = $null

function Global:Estres-Parar {
    $st = $Global:EstState
    if ($st.Detener) { return $true }
    if ($st.Limite -gt 0 -and $st.Reloj -and $st.Reloj.Elapsed.TotalSeconds -ge $st.Limite) { return $true }
    return $false
}

function Global:Estres-Formato {
    param([double]$Seg)
    $t = [TimeSpan]::FromSeconds([math]::Max(0, $Seg))
    return ("{0:00}:{1:00}:{2:00}" -f [int][math]::Floor($t.TotalHours), $t.Minutes, $t.Seconds)
}

# Prueba de estres: escribe, lee y VERIFICA datos en la unidad elegida durante el tiempo indicado (o sin limite)
function Global:Ejecutar-EstresDisco {
    $ui = $Global:EstUi; $st = $Global:EstState
    if ($st.Corriendo) { return }
    $sel = $ui.CmbUnidad.SelectedItem
    if (-not $sel) { $ui.Estado.Text = "Elige una unidad."; return }
    $u = "$($sel.Tag)"
    $secuencial = [bool]$ui.ChkSec.IsChecked
    $aleatorio = [bool]$ui.ChkAle.IsChecked
    if (-not ($secuencial -or $aleatorio)) { $ui.Estado.Text = "Marca al menos una prueba (secuencial o aleatoria 4K)."; return }
    # duracion
    $minutos = 0.0
    switch ($ui.CmbDur.SelectedIndex) {
        0 { $minutos = 1 } 1 { $minutos = 5 } 2 { $minutos = 10 } 3 { $minutos = 30 } 4 { $minutos = 60 }
        5 {
            $txt = "$($ui.TxtMin.Text)".Trim().Replace(',', '.')
            $val = 0.0
            if (-not [double]::TryParse($txt, [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$val) -or $val -le 0) {
                $ui.Estado.Text = "Escribe los minutos como numero mayor que 0 (por ejemplo 15)."; return
            }
            $minutos = $val
        }
        default { $minutos = 0 }
    }
    try { Ensure-TipoDiskVerif } catch { $ui.Estado.Text = "No se pudo preparar la prueba: $($_.Exception.Message)"; return }
    $tamMB = 512
    try { $tamMB = [int]$ui.CmbTam.SelectedItem.Tag } catch { }
    try {
        $ld = Get-CimInstance Win32_LogicalDisk -Filter "DeviceID='$u'" -ErrorAction Stop
        if ($ld) {
            $libreMB = $ld.FreeSpace / 1MB
            if ($libreMB -lt 300) { $ui.Estado.Text = "La unidad $u tiene muy poco espacio libre (menos de 300 MB)."; return }
            while ($tamMB -gt 64 -and ($tamMB * 3) -gt $libreMB) { $tamMB = [int]($tamMB / 2) }
        }
    } catch { }
    $tamMB = [int]([math]::Floor($tamMB / 4) * 4)
    $carp = Carpeta-PruebaDisco $u
    $arch = $null
    $errores = 0; $msgErr = New-Object System.Collections.Generic.List[string]
    $ciclo = 0; $totEscMB = 0.0; $totLecMB = 0.0
    $esc = New-Object 'System.Collections.Generic.List[double]'
    $lec = New-Object 'System.Collections.Generic.List[double]'
    $escCiclo = New-Object 'System.Collections.Generic.List[double]'
    $sumLatE = 0.0; $nLatE = 0; $maxLatE = 0.0; $sumLatL = 0.0; $nLatL = 0; $maxLatL = 0.0
    $tempIni = Temperatura-DiscoUnidad $u; $tempMax = $tempIni; $tempAct = $tempIni; $ultTemp = [DateTime]::UtcNow
    $velAct = @{ E = 0.0; L = 0.0 }
    $st.Corriendo = $true; $st.Detener = $false; $st.CerrarAlTerminar = $false
    $st.Limite = [double]($minutos * 60)
    $st.Reloj = [System.Diagnostics.Stopwatch]::StartNew()
    $ui.Iniciar.IsEnabled = $false; $ui.Detener.IsEnabled = $true
    foreach ($c in @($ui.CmbUnidad, $ui.CmbDur, $ui.CmbTam, $ui.ChkSec, $ui.ChkAle, $ui.TxtMin)) { $c.IsEnabled = $false }
    $ui.Barra.IsIndeterminate = ($minutos -le 0)
    $ui.Barra.Value = 0
    $infinito = ($minutos -le 0)
    $durTxt = if ($infinito) { 'sin limite (hasta detener)' } else { (Estres-Formato $st.Limite) }
    $ui.Estado.Text = "Probando la unidad $u ($tamMB MB por ciclo)... pulsa Detener para terminar cuando quieras."
    $actualizar = {
        $seg = $st.Reloj.Elapsed.TotalSeconds
        if (-not $infinito -and $st.Limite -gt 0) { $ui.Barra.Value = [math]::Min(100, 100 * $seg / $st.Limite) }
        $avg = { param($l) if ($l.Count -gt 0) { ($l | Measure-Object -Average).Average } else { 0 } }
        $mn = { param($l) if ($l.Count -gt 0) { ($l | Measure-Object -Minimum).Minimum } else { 0 } }
        $mx = { param($l) if ($l.Count -gt 0) { ($l | Measure-Object -Maximum).Maximum } else { 0 } }
        $t = New-Object System.Text.StringBuilder
        [void]$t.AppendLine(("Tiempo: {0} / {1}      Ciclos: {2}" -f (Estres-Formato $seg), $durTxt, $ciclo))
        [void]$t.AppendLine(("Escrito: {0:N2} GB      Leido: {1:N2} GB" -f ($totEscMB / 1024), ($totLecMB / 1024)))
        if ($secuencial) {
            [void]$t.AppendLine(("Escritura secuencial: actual {0:N0} | prom {1:N0} | min {2:N0} | max {3:N0} MB/s" -f $velAct.E, (& $avg $esc), (& $mn $esc), (& $mx $esc)))
            [void]$t.AppendLine(("Lectura secuencial:   actual {0:N0} | prom {1:N0} | min {2:N0} | max {3:N0} MB/s" -f $velAct.L, (& $avg $lec), (& $mn $lec), (& $mx $lec)))
        }
        if ($aleatorio -and $nLatE -gt 0) {
            [void]$t.AppendLine(("4K aleatorio: escritura prom {0:N2} ms (max {1:N1}) | lectura prom {2:N3} ms (max {3:N1})" -f ($sumLatE / $nLatE), $maxLatE, ($sumLatL / [math]::Max(1, $nLatL)), $maxLatL))
        }
        if ($null -ne $tempAct) { [void]$t.AppendLine(("Temperatura del disco: {0} °C (maxima {1} °C)" -f $tempAct, $tempMax)) }
        [void]$t.AppendLine(("Errores de verificacion de datos: {0}" -f $errores))
        $ui.Stats.Text = $t.ToString()
    }
    try {
        if (-not (Test-Path $carp)) { New-Item -Path $carp -ItemType Directory -Force | Out-Null }
        $arch = Join-Path $carp "estres.tmp"
        $bytes4m = 4MB
        $base = New-Object byte[] $bytes4m
        (New-Object Random).NextBytes($base)
        $bloque = $base.Clone(); $ref = $base.Clone(); $buf = New-Object byte[] $bytes4m
        $p4 = New-Object byte[] 4096; (New-Object Random).NextBytes($p4)
        $b4 = New-Object byte[] 4096
        $nB = [int]($tamMB / 4)
        $rnd = New-Object Random
        $sw = New-Object System.Diagnostics.Stopwatch
        while (-not (Estres-Parar)) {
            $ciclo++
            $escritos = 0
            if ($secuencial) {
                # --- escritura ---
                $fs = New-Object System.IO.FileStream($arch, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None, 4MB, [System.IO.FileOptions]::WriteThrough)
                $acum = 0.0
                try {
                    for ($i = 0; $i -lt $nB; $i++) {
                        if (Estres-Parar) { break }
                        [DragonDiskVerif]::Marca($bloque, [int64]$i)
                        $sw.Restart(); $fs.Write($bloque, 0, $bytes4m); $sw.Stop()
                        $acum += $sw.Elapsed.TotalSeconds; $escritos++; $totEscMB += 4
                        if ($sw.Elapsed.TotalSeconds -gt 0) { $velAct.E = 4 / $sw.Elapsed.TotalSeconds }
                        if (($i % 2) -eq 0) { & $actualizar; Wait-UI -Milisegundos 1 }
                    }
                    $fs.Flush($true)
                } finally { $fs.Close() }
                if ($escritos -gt 0 -and $acum -gt 0) { $ve = ($escritos * 4) / $acum; $esc.Add($ve); $escCiclo.Add($ve); $velAct.E = $ve }
                # --- lectura y verificacion ---
                if ($escritos -gt 0) {
                    $fs = New-Object System.IO.FileStream($arch, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read, 4MB, [System.IO.FileOptions]::SequentialScan)
                    $acumL = 0.0; $leidos = 0
                    try {
                        for ($i = 0; $i -lt $escritos; $i++) {
                            if ($st.Detener) { break }
                            $sw.Restart()
                            $n = 0
                            while ($n -lt $bytes4m) { $r = $fs.Read($buf, $n, $bytes4m - $n); if ($r -le 0) { break }; $n += $r }
                            $sw.Stop()
                            $acumL += $sw.Elapsed.TotalSeconds; $leidos++; $totLecMB += 4
                            if ($sw.Elapsed.TotalSeconds -gt 0) { $velAct.L = 4 / $sw.Elapsed.TotalSeconds }
                            [DragonDiskVerif]::Marca($ref, [int64]$i)
                            if ($n -lt $bytes4m -or -not [DragonDiskVerif]::Igual($buf, $ref, $bytes4m)) {
                                $errores++
                                if ($msgErr.Count -lt 15) { $msgErr.Add("Ciclo $ciclo, bloque $i : los datos leidos NO coinciden con los escritos.") }
                                $ui.Estado.Text = "ERROR de verificacion en el ciclo $ciclo (bloque $i)."
                            }
                            if (($i % 2) -eq 0) { & $actualizar; Wait-UI -Milisegundos 1 }
                        }
                    } finally { $fs.Close() }
                    if ($leidos -gt 0 -and $acumL -gt 0) { $lec.Add(($leidos * 4) / $acumL) }
                }
            }
            # --- aleatorio 4K con verificacion ---
            if ($aleatorio -and -not (Estres-Parar)) {
                $fa = New-Object System.IO.FileStream($arch, [System.IO.FileMode]::OpenOrCreate, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None, 4096, [System.IO.FileOptions]::WriteThrough)
                try {
                    $largo = [int64]$tamMB * 1MB
                    if ($fa.Length -lt $largo) { $fa.SetLength($largo) }
                    $bl4 = [int]($largo / 4096)
                    for ($k = 0; $k -lt 400; $k++) {
                        if (Estres-Parar) { break }
                        $pos = [int64]$rnd.Next(0, $bl4) * 4096
                        [DragonDiskVerif]::Marca($p4, $pos)
                        $sw.Restart(); [void]$fa.Seek($pos, [System.IO.SeekOrigin]::Begin); $fa.Write($p4, 0, 4096); $sw.Stop()
                        $le = $sw.Elapsed.TotalMilliseconds; $sumLatE += $le; $nLatE++; if ($le -gt $maxLatE) { $maxLatE = $le }
                        $sw.Restart(); [void]$fa.Seek($pos, [System.IO.SeekOrigin]::Begin); [void]$fa.Read($b4, 0, 4096); $sw.Stop()
                        $ll = $sw.Elapsed.TotalMilliseconds; $sumLatL += $ll; $nLatL++; if ($ll -gt $maxLatL) { $maxLatL = $ll }
                        $totEscMB += 4 / 1024; $totLecMB += 4 / 1024
                        if (-not [DragonDiskVerif]::Igual($b4, $p4, 4096)) {
                            $errores++
                            if ($msgErr.Count -lt 15) { $msgErr.Add("Ciclo $ciclo, posicion $pos : lectura aleatoria 4K distinta de lo escrito.") }
                        }
                        if (($k % 20) -eq 0) { & $actualizar; Wait-UI -Milisegundos 1 }
                    }
                    $fa.Flush($true)
                } finally { $fa.Close() }
            }
            # temperatura cada ~15 s
            if (([DateTime]::UtcNow - $ultTemp).TotalSeconds -ge 15) {
                $ultTemp = [DateTime]::UtcNow
                $tt = Temperatura-DiscoUnidad $u
                if ($null -ne $tt) { $tempAct = $tt; if ($null -eq $tempMax -or $tt -gt $tempMax) { $tempMax = $tt } }
            }
            & $actualizar
            Wait-UI -Milisegundos 1
        }
    } catch {
        $ui.Estado.Text = "La prueba se interrumpio: $($_.Exception.Message)"
        $msgErr.Add("Interrupcion: $($_.Exception.Message)")
    } finally {
        $st.Reloj.Stop()
        if ($arch) { Remove-Item $arch -Force -ErrorAction SilentlyContinue }
        try { if ((Test-Path $carp) -and -not (Get-ChildItem $carp -Force -ErrorAction SilentlyContinue)) { Remove-Item $carp -Force -ErrorAction SilentlyContinue } } catch { }
        $st.Corriendo = $false
        $ui.Barra.IsIndeterminate = $false
        $ui.Iniciar.IsEnabled = $true; $ui.Detener.IsEnabled = $false
        foreach ($c in @($ui.CmbUnidad, $ui.CmbDur, $ui.CmbTam, $ui.ChkSec, $ui.ChkAle)) { $c.IsEnabled = $true }
        $ui.TxtMin.IsEnabled = ($ui.CmbDur.SelectedIndex -eq 5)
    }
    & $actualizar
    $seg = $st.Reloj.Elapsed.TotalSeconds
    $ui.Barra.Value = if ($infinito) { 0 } else { [math]::Min(100, 100 * $seg / [math]::Max(1, $st.Limite)) }
    $ui.Estado.Text = if ($errores -gt 0) { "Terminada con $errores error(es) de verificacion. Revisa el informe del diagnostico." } else { "Terminada sin errores (duracion real $(Estres-Formato $seg))." }
    # ---- resultado hacia el registro/informe del diagnostico ----
    try {
        $okN = 0; $avN = 0
        Write-DiagLog "=== DISCO: PRUEBA DE ESTRES en $u (duracion $(Estres-Formato $seg), $ciclo ciclo(s), archivo de $tamMB MB) ==="
        Write-DiagLog (" - Datos escritos: {0:N2} GB | leidos: {1:N2} GB" -f ($totEscMB / 1024), ($totLecMB / 1024))
        if ($esc.Count -gt 0) {
            Write-DiagLog (" - Escritura secuencial: prom {0:N0} MB/s (min {1:N0}, max {2:N0})" -f ($esc | Measure-Object -Average).Average, ($esc | Measure-Object -Minimum).Minimum, ($esc | Measure-Object -Maximum).Maximum)
        }
        if ($lec.Count -gt 0) {
            Write-DiagLog (" - Lectura secuencial: prom {0:N0} MB/s (min {1:N0}, max {2:N0}) - puede verse inflada por la cache de Windows" -f ($lec | Measure-Object -Average).Average, ($lec | Measure-Object -Minimum).Minimum, ($lec | Measure-Object -Maximum).Maximum)
        }
        if ($nLatE -gt 0) { Write-DiagLog (" - 4K aleatorio: escritura prom {0:N2} ms (max {1:N1} ms) | lectura prom {2:N3} ms (max {3:N1} ms)" -f ($sumLatE / $nLatE), $maxLatE, ($sumLatL / [math]::Max(1, $nLatL)), $maxLatL) }
        if ($null -ne $tempMax) { Write-DiagLog " - Temperatura del disco: inicio $tempIni °C, maxima $tempMax °C" }
        if ($errores -gt 0) {
            Diag-Aviso "Se detectaron $errores error(es) de verificacion: los datos leidos no coinciden con los escritos. Posible disco, cable, controlador o memoria RAM defectuosos. Haz copia de seguridad."
            $avN++
            foreach ($m in $msgErr) { Write-DiagLog "     $m" }
        } elseif ($ciclo -gt 0 -and ($totEscMB + $totLecMB) -gt 0) {
            Diag-Ok "Sin errores de verificacion tras $([math]::Round($totEscMB / 1024, 2)) GB escritos y leidos en $u."
            $okN++
        }
        if ($escCiclo.Count -ge 3) {
            $n3 = [math]::Max(1, [int]([math]::Floor($escCiclo.Count / 3)))
            $primeros = ($escCiclo | Select-Object -First $n3 | Measure-Object -Average).Average
            $ultimos = ($escCiclo | Select-Object -Last $n3 | Measure-Object -Average).Average
            if ($primeros -gt 0 -and $ultimos -lt ($primeros * 0.6)) {
                Diag-Aviso ("La velocidad de escritura cayo de {0:N0} a {1:N0} MB/s durante la prueba (agotamiento de la cache SLC, sobrecalentamiento o disco con problemas)." -f $primeros, $ultimos)
                $avN++
            }
        }
        if ($null -ne $tempMax -and $tempMax -ge 70) { Diag-Aviso "El disco llego a $tempMax °C durante la prueba. Mejora la ventilacion."; $avN++ }
        if ($errores -eq 0 -and $msgErr.Count -gt 0) { foreach ($m in $msgErr) { Write-DiagLog "     $m" } }
        if ($Global:DiagInforme) {
            $Global:DiagInforme.Pruebas.Add([PSCustomObject]@{ Nombre = "Prueba de estres de disco ($u)"; Inicio = (Get-Date).AddSeconds(-$seg); Seg = $seg; Ok = $okN; Aviso = $avN })
        }
    } catch { }
    if ($st.CerrarAlTerminar) { try { $ui.Win.Close() } catch { } }
}

function Global:Show-PruebaEstresDisco {
    try {
        [xml]$xamlEst = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Prueba de estres de disco - The Dragon Tool" Height="640" Width="720" MinHeight="560" MinWidth="620" WindowStartupLocation="CenterScreen" Background="#10141D">
  <Window.Resources>$($Global:RecursosNeonXaml)</Window.Resources>
  <DockPanel Margin="14">
    <Button x:Name="BtnVolverVentana" DockPanel.Dock="Top" Content="⬅  Volver" Width="110" Height="34" HorizontalAlignment="Left" Margin="0,0,0,8"/>
    <TextBlock DockPanel.Dock="Top" Foreground="White" TextWrapping="Wrap" Margin="0,0,0,10" FontSize="12"
               Text="Escribe, lee y VERIFICA datos en un archivo temporal de la unidad elegida durante el tiempo indicado (o sin limite hasta pulsar Detener). Detecta errores de datos, caidas de velocidad y calentamiento. El archivo se borra al terminar. En un SSD cada ciclo consume algo de vida util: usa duraciones razonables."/>
    <Grid DockPanel.Dock="Top" Margin="0,0,0,8">
      <Grid.ColumnDefinitions><ColumnDefinition Width="150"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
      <Grid.RowDefinitions><RowDefinition Height="42"/><RowDefinition Height="42"/><RowDefinition Height="42"/><RowDefinition Height="36"/></Grid.RowDefinitions>
      <TextBlock Grid.Row="0" Text="Unidad:" Foreground="White" VerticalAlignment="Center"/>
      <ComboBox x:Name="CmbUnidadEst" Grid.Row="0" Grid.Column="1" Height="34"/>
      <TextBlock Grid.Row="1" Text="Duracion:" Foreground="White" VerticalAlignment="Center"/>
      <StackPanel Grid.Row="1" Grid.Column="1" Orientation="Horizontal">
        <ComboBox x:Name="CmbDurEst" Width="290" Height="34">
          <ComboBoxItem Content="1 minuto"/>
          <ComboBoxItem Content="5 minutos" IsSelected="True"/>
          <ComboBoxItem Content="10 minutos"/>
          <ComboBoxItem Content="30 minutos"/>
          <ComboBoxItem Content="60 minutos"/>
          <ComboBoxItem Content="Personalizado (minutos)..."/>
          <ComboBoxItem Content="Infinito (hasta pulsar Detener)"/>
        </ComboBox>
        <TextBlock Text="Minutos:" Foreground="White" VerticalAlignment="Center" Margin="14,0,6,0"/>
        <TextBox x:Name="TxtMinEst" Width="80" Height="34" Text="15" IsEnabled="False" FontSize="14"/>
      </StackPanel>
      <TextBlock Grid.Row="2" Text="Archivo de prueba:" Foreground="White" VerticalAlignment="Center"/>
      <ComboBox x:Name="CmbTamEst" Grid.Row="2" Grid.Column="1" Width="290" Height="34" HorizontalAlignment="Left">
        <ComboBoxItem Content="256 MB" Tag="256"/>
        <ComboBoxItem Content="512 MB" Tag="512" IsSelected="True"/>
        <ComboBoxItem Content="1 GB" Tag="1024"/>
        <ComboBoxItem Content="2 GB" Tag="2048"/>
      </ComboBox>
      <StackPanel Grid.Row="3" Grid.Column="1" Orientation="Horizontal">
        <CheckBox x:Name="ChkSecEst" Content="Secuencial (escritura + lectura + verificacion)" Foreground="White" IsChecked="True" Margin="0,0,18,0" VerticalAlignment="Center"/>
        <CheckBox x:Name="ChkAleEst" Content="Aleatorio 4K" Foreground="White" IsChecked="True" VerticalAlignment="Center"/>
      </StackPanel>
    </Grid>
    <WrapPanel DockPanel.Dock="Top" Margin="0,0,0,8">
      <Button x:Name="BtnIniciarEst" Content="▶ Iniciar prueba" Width="170" Height="38"/>
      <Button x:Name="BtnDetenerEst" Content="⏹ Detener" Width="130" Height="38" IsEnabled="False"/>
    </WrapPanel>
    <ProgressBar x:Name="PbEst" DockPanel.Dock="Top" Height="14" Minimum="0" Maximum="100" Margin="0,0,0,6"/>
    <TextBlock x:Name="TxtEstadoEst" DockPanel.Dock="Top" Foreground="#66AEFF" TextWrapping="Wrap" Margin="0,0,0,6" FontSize="12" Text="Elige la unidad y la duracion, y pulsa Iniciar."/>
    <Border BorderBrush="#232B3D" BorderThickness="1" Background="#151B27" Padding="12">
      <TextBlock x:Name="TxtStatsEst" Foreground="#EAF0FA" FontFamily="Consolas" FontSize="13" TextWrapping="Wrap" Text="Los datos en vivo apareceran aqui."/>
    </Border>
  </DockPanel>
</Window>
"@
        $winEst = [Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader $xamlEst))
        Iniciar-EfectosNeon -Ventana $winEst
        $cmbU = $winEst.FindName("CmbUnidadEst")
        $unidades = @()
        try { $unidades = @(Get-CimInstance Win32_LogicalDisk -ErrorAction Stop | Where-Object { $_.DriveType -in 2, 3 -and $_.Size } | Sort-Object DeviceID) } catch { }
        if ($unidades.Count -eq 0) { Write-DiagLog "No se encontraron unidades para probar."; return }
        $actual = Unidad-Diag; $idx = 0; $i = 0
        foreach ($u in $unidades) {
            $it = New-Object System.Windows.Controls.ComboBoxItem
            $it.Content = "$($u.DeviceID)  $($u.VolumeName)  ($(Format-TamanoDisco $u.Size), $(Format-TamanoDisco $u.FreeSpace) libres)"
            $it.Tag = "$($u.DeviceID)"
            [void]$cmbU.Items.Add($it)
            if ("$($u.DeviceID)" -eq $actual) { $idx = $i }
            $i++
        }
        $cmbU.SelectedIndex = $idx
        $Global:EstState.Corriendo = $false; $Global:EstState.Detener = $false; $Global:EstState.CerrarAlTerminar = $false
        $Global:EstUi = @{
            Win = $winEst; CmbUnidad = $cmbU; CmbDur = $winEst.FindName("CmbDurEst"); TxtMin = $winEst.FindName("TxtMinEst"); CmbTam = $winEst.FindName("CmbTamEst")
            ChkSec = $winEst.FindName("ChkSecEst"); ChkAle = $winEst.FindName("ChkAleEst")
            Iniciar = $winEst.FindName("BtnIniciarEst"); Detener = $winEst.FindName("BtnDetenerEst")
            Barra = $winEst.FindName("PbEst"); Estado = $winEst.FindName("TxtEstadoEst"); Stats = $winEst.FindName("TxtStatsEst")
        }
        $Global:EstUi.CmbDur.Add_SelectionChanged({ try { $Global:EstUi.TxtMin.IsEnabled = ($Global:EstUi.CmbDur.SelectedIndex -eq 5) -and (-not $Global:EstState.Corriendo) } catch { } })
        $Global:EstUi.Iniciar.Add_Click({ Ejecutar-EstresDisco })
        $Global:EstUi.Detener.Add_Click({ $Global:EstState.Detener = $true; $Global:EstUi.Estado.Text = "Deteniendo y limpiando el archivo de prueba..." })
        $winEst.Add_Closing({
            param($s, $e)
            if ($Global:EstState.Corriendo) { $e.Cancel = $true; $Global:EstState.Detener = $true; $Global:EstState.CerrarAlTerminar = $true; $Global:EstUi.Estado.Text = "Deteniendo y limpiando el archivo de prueba..." }
        })
        $winEst.ShowDialog() | Out-Null
    } catch {
        Write-DiagLog "No se pudo abrir la ventana de la prueba de estres: $($_.Exception.Message)"
    }
}

# Ventanita para elegir una unidad (C:, D:, ...). Devuelve la letra con dos puntos o $null.
function Global:Pedir-UnidadDiag {
    param([string]$Titulo = "Elegir unidad", [string]$Texto = "Elige la unidad:")
    # si ya hay una unidad elegida en el panel de disco, se usa sin preguntar de nuevo
    try { if ($Global:CmbDiagUnidad -and $Global:CmbDiagUnidad.SelectedItem) { return "$($Global:CmbDiagUnidad.SelectedItem.Tag)" } } catch { }
    $unidades = @()
    try { $unidades = @(Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3' -ErrorAction Stop | Sort-Object DeviceID) } catch {}
    if ($unidades.Count -eq 0) { Show-Aviso "No se encontraron unidades de disco." "Sin unidades"; return $null }
    $Global:UnidadElegida = $null
    [xml]$x = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="$Titulo" Height="230" Width="440" WindowStartupLocation="CenterScreen" Background="#10141D" ResizeMode="NoResize">
  <Window.Resources>$($Global:RecursosNeonXaml)</Window.Resources>
  <StackPanel Margin="18">
    <TextBlock x:Name="TxtPedirUnidad" Foreground="White" TextWrapping="Wrap" Margin="0,0,0,10"/>
    <ComboBox x:Name="CmbPedirUnidad" Height="34" Margin="0,0,0,16"/>
    <StackPanel Orientation="Horizontal" HorizontalAlignment="Right">
      <Button x:Name="BtnOkUnidad" Content="Aceptar" Width="110" Height="36" Margin="0,0,8,0"/>
      <Button x:Name="BtnNoUnidad" Content="Cancelar" Width="110" Height="36"/>
    </StackPanel>
  </StackPanel>
</Window>
"@
    $w = [Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader $x))
    Iniciar-EfectosNeon -Ventana $w
    $w.FindName("TxtPedirUnidad").Text = $Texto
    $cmb = $w.FindName("CmbPedirUnidad")
    foreach ($u in $unidades) {
        $it = New-Object System.Windows.Controls.ComboBoxItem
        $it.Content = "$($u.DeviceID)  $($u.VolumeName)  ($(Format-TamanoDisco $u.Size))"
        $it.Tag = "$($u.DeviceID)"
        [void]$cmb.Items.Add($it)
    }
    $cmb.SelectedIndex = 0
    $Global:UiPedirUnidad = @{ Win = $w; Cmb = $cmb }
    $w.FindName("BtnOkUnidad").Add_Click({
        $sel = $Global:UiPedirUnidad.Cmb.SelectedItem
        if ($sel) { $Global:UnidadElegida = "$($sel.Tag)" }
        $Global:UiPedirUnidad.Win.Close()
    })
    $w.FindName("BtnNoUnidad").Add_Click({ $Global:UiPedirUnidad.Win.Close() })
    $w.ShowDialog() | Out-Null
    return $Global:UnidadElegida
}

# Ejecuta un programa de consola en segundo plano (sin congelar la ventana) y devuelve sus lineas de salida
function Global:Invoke-ConsolaDiag {
    param([string]$Exe, [string]$Argumentos, [string]$Etiqueta)
    $tmp = Join-Path $env:TEMP ("dragon_" + [guid]::NewGuid().ToString('N') + ".txt")
    $res = @{ Codigo = -1; Lineas = @() }
    try {
        $p = Start-Process -FilePath $Exe -ArgumentList $Argumentos -NoNewWindow -RedirectStandardOutput $tmp -PassThru -ErrorAction Stop
        $t0 = Get-Date; $ultimo = 0
        while (-not $p.HasExited) {
            Wait-UI -Milisegundos 250
            $seg = [int]((Get-Date) - $t0).TotalSeconds
            Diag-Texto "$Etiqueta en curso: $seg s transcurridos (no cierres el programa)..."
            if ($seg -ge $ultimo + 20) { $ultimo = $seg; Write-DiagLog "   ... $Etiqueta sigue en curso ($seg s)" }
        }
        $p.WaitForExit()
        $res.Codigo = $p.ExitCode
        if (Test-Path $tmp) { $res.Lineas = @(Get-Content -Path $tmp -Encoding OEM -ErrorAction SilentlyContinue | Where-Object { "$_".Trim() }) }
    } catch {
        Write-DiagLog "No se pudo ejecutar ${Etiqueta}: $($_.Exception.Message)"
    } finally {
        Remove-Item $tmp -Force -ErrorAction SilentlyContinue
    }
    return $res
}

function Accion-DiscoChkdsk {
    $u = Pedir-UnidadDiag -Titulo "Verificar sectores (CHKDSK)" -Texto "Unidad a verificar. Es una revision de SOLO LECTURA: no repara ni modifica nada."
    if (-not $u) { $Global:DiagCancelada = $true; return }
    Write-DiagLog "=== DISCO: VERIFICACION DE ERRORES Y SECTORES (CHKDSK solo lectura) en ${u} ==="
    if (-not (Test-Admin)) { Diag-Aviso "CHKDSK necesita permisos de administrador. Abre The Dragon Tool como administrador."; return }
    Write-DiagLog "Verificando la unidad ${u}... puede tardar varios minutos segun su tamano."
    $r = Invoke-ConsolaDiag -Exe "$env:SystemRoot\System32\chkdsk.exe" -Argumentos $u -Etiqueta "CHKDSK"
    if ($r.Lineas.Count -gt 0) {
        $mostrar = @($r.Lineas | Select-Object -Last 16)
        foreach ($l in $mostrar) { Write-DiagLog "   $("$l".Trim())" }
    }
    switch ([int]$r.Codigo) {
        0 { Diag-Ok "CHKDSK no encontro errores en ${u}." }
        1 { Diag-Aviso "CHKDSK corrigio errores en ${u}." }
        2 { Diag-Aviso "CHKDSK encontro problemas en ${u} que requieren reparacion (ejecuta 'chkdsk ${u} /f' o programa la revision al reiniciar)." }
        3 { Diag-Aviso "CHKDSK no pudo completar la verificacion de ${u} (unidad en uso, bloqueada o con errores graves)." }
        default { Write-DiagLog "   (Codigo de salida de CHKDSK: $($r.Codigo))" }
    }
    Write-DiagLog "   Para buscar sectores danados en la superficie fisica usa 'Escanear superficie (mapa)'."
}

function Accion-DiscoOptimizacion {
    $u = Pedir-UnidadDiag -Titulo "Fragmentacion y optimizacion" -Texto "Unidad a analizar (solo analisis, no modifica nada):"
    if (-not $u) { $Global:DiagCancelada = $true; return }
    Write-DiagLog "=== DISCO: ANALISIS DE FRAGMENTACION / OPTIMIZACION en ${u} ==="
    if (-not (Test-Admin)) { Diag-Aviso "El analisis necesita permisos de administrador. Abre The Dragon Tool como administrador."; return }
    Write-DiagLog "Analizando ${u}..."
    $r = Invoke-ConsolaDiag -Exe "$env:SystemRoot\System32\defrag.exe" -Argumentos "$u /A /V" -Etiqueta "el analisis"
    $txt = ($r.Lineas -join ' ')
    foreach ($l in @($r.Lineas | Select-Object -First 30)) { Write-DiagLog "   $("$l".Trim())" }
    if ($txt -match '(\d{1,3})\s*%') {
        $frag = [int]$Matches[1]
        if ($frag -ge 15) { Diag-Aviso "Fragmentacion elevada (~$frag%). En un disco mecanico conviene desfragmentar; en un SSD usa solo 'Optimizar' (TRIM)." }
    }
    if ($r.Lineas.Count -eq 0) { Write-DiagLog "   (La herramienta no devolvio resultados para esta unidad.)" }
}

function Accion-DiscoCompleto {
    Write-DiagLog "========================================"
    Write-DiagLog "   DIAGNOSTICO COMPLETO DE ALMACENAMIENTO"
    Write-DiagLog "========================================"
    Diag-Progreso -Pct 0 -Texto 'Paso 1 de 5: Detalle fisico del disco'
    Accion-DiscoDetalleFisico
    Diag-Progreso -Pct 20 -Texto 'Paso 2 de 5: Particiones'
    Accion-DiscoParticiones
    Diag-Progreso -Pct 40 -Texto 'Paso 3 de 5: Atributos S.M.A.R.T.'
    Accion-DiscoSmartAtributos
    Diag-Progreso -Pct 60 -Texto 'Paso 4 de 5: Eventos de disco'
    Accion-DiscoEventos
    Diag-Progreso -Pct 80 -Texto 'Paso 5 de 5: Actividad del disco'
    Accion-DiscoActividad
    Write-DiagLog "========================================"
    Write-DiagLog "   Para mas detalle usa: Escanear superficie (mapa), Verificar CHKDSK, Latencia 4K y Velocidad de disco."
    Write-DiagLog "========================================"
}

# --- Escaneo de superficie con mapa de sectores -------------------------------
# Lee el disco fisico (solo lectura) por segmentos y colorea un mapa: verde = bien,
# amarillo = lento (reintentos), rojo = sector ilegible. No escribe ni modifica nada.
$Global:EscEstado = @{ Corriendo = $false; Cancelar = $false }
$Global:EscUi = @{}

# Localiza los sectores ilegibles dentro de una zona que fallo al leerse
function Global:Localizar-SectoresMalos {
    param([string]$Ruta, [int64]$Pos, [int]$Len, [int]$Sec, $Malos)
    $cnt = 0
    $f = $null
    try {
        $f = New-Object System.IO.FileStream($Ruta, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite, 1)
        $b = New-Object byte[] 65536
        for ($o = 0; $o -lt $Len; $o += 65536) {
            if ($Global:EscEstado.Cancelar) { break }
            $l = [Math]::Min(65536, $Len - $o)
            $l = $l - ($l % $Sec)
            if ($l -le 0) { break }
            $ok = $true
            try { [void]$f.Seek($Pos + $o, [System.IO.SeekOrigin]::Begin); [void]$f.Read($b, 0, $l) } catch { $ok = $false }
            if (-not $ok) {
                for ($so = 0; $so -lt $l; $so += $Sec) {
                    if ($Global:EscEstado.Cancelar) { break }
                    try {
                        if (-not $f) { $f = New-Object System.IO.FileStream($Ruta, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite, 1) }
                        [void]$f.Seek($Pos + $o + $so, [System.IO.SeekOrigin]::Begin)
                        [void]$f.Read($b, 0, $Sec)
                    } catch {
                        $cnt++
                        if ($Malos.Count -lt 200) { $Malos.Add([int64](($Pos + $o + $so) / $Sec)) }
                        try { $f.Dispose() } catch {}
                        $f = $null
                    }
                }
            }
            Wait-UI -Milisegundos 1
        }
    } finally { if ($f) { try { $f.Dispose() } catch {} } }
    return $cnt
}

function Global:Iniciar-EscaneoSuperficie {
    $ui = $Global:EscUi; $st = $Global:EscEstado
    if ($st.Corriendo) { return }
    if (-not (Test-Admin)) { $ui.Estado.Text = "Se necesitan permisos de administrador para leer el disco directamente. Cierra el programa y abrelo como administrador."; return }
    $sel = $ui.CmbDisco.SelectedItem
    if (-not $sel) { $ui.Estado.Text = "No hay discos para analizar."; return }
    $partes = "$($sel.Tag)".Split('|')
    $num = [int]$partes[0]; $tam = [int64]$partes[1]; $sec = [int]$partes[2]
    if ($sec -lt 512) { $sec = 512 }
    if ($tam -lt 4MB) { $ui.Estado.Text = "El disco seleccionado es demasiado pequeno o no informa su tamano."; return }
    $modo = $ui.CmbModo.SelectedIndex
    $ruta = "\\.\PhysicalDrive$num"
    if ($ui.RutaPrueba) { $ruta = $ui.RutaPrueba }
    $totalCeldas = $ui.Celdas.Count
    $seg = [int64][Math]::Ceiling($tam / [double]$totalCeldas)
    $seg = [int64]([Math]::Ceiling($seg / 1048576.0) * 1048576)
    $nSeg = [int][Math]::Ceiling($tam / [double]$seg)
    $bytesSeg = $seg
    if ($modo -eq 0) { $bytesSeg = 1048576 } elseif ($modo -eq 1) { $bytesSeg = 16777216 }
    if ($bytesSeg -gt $seg) { $bytesSeg = $seg }

    foreach ($c in $ui.Celdas) { $c.Fill = $ui.Pincel.Sin; $c.ToolTip = $null }
    $st.Corriendo = $true; $st.Cancelar = $false
    $ui.Iniciar.IsEnabled = $false; $ui.CmbDisco.IsEnabled = $false; $ui.CmbModo.IsEnabled = $false
    $ui.Detener.IsEnabled = $true
    $ui.Resumen.Text = ""
    $ui.Barra.Value = 0
    $malos = New-Object 'System.Collections.Generic.List[int64]'
    $vels = New-Object 'System.Collections.Generic.List[double]'
    $buf = New-Object byte[] 1048576
    $total = [int64]0; $segLentos = 0; $segErr = 0; $chunksLentos = 0; $malosTotal = 0; $leidos = 0
    $velMin = [double]::MaxValue; $velMax = 0.0
    $relojTotal = [System.Diagnostics.Stopwatch]::StartNew()
    $relojPump = [System.Diagnostics.Stopwatch]::StartNew()
    $sw = New-Object System.Diagnostics.Stopwatch
    $fs = $null
    $abortado = ''
    try {
        $fs = New-Object System.IO.FileStream($ruta, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite, 1)
        for ($s = 0; $s -lt $nSeg; $s++) {
            if ($st.Cancelar) { break }
            $ini = [int64]$s * $seg
            $fin = [Math]::Min($ini + $seg, $tam)
            $lim = [Math]::Min($ini + $bytesSeg, $fin)
            $pos = $ini
            $segBytes = [int64]0; $segMs = 0.0; $huboErr = $false; $huboLento = $false
            while ($pos -lt $lim) {
                if ($st.Cancelar) { break }
                $len = [int][Math]::Min(1048576, $lim - $pos)
                $len = $len - ($len % $sec)
                if ($len -le 0) { break }
                $ok = $true
                $sw.Restart()
                try {
                    [void]$fs.Seek($pos, [System.IO.SeekOrigin]::Begin)
                    $n = $fs.Read($buf, 0, $len)
                    if ($n -le 0) { $sw.Stop(); break }
                } catch { $ok = $false }
                $sw.Stop()
                $ms = $sw.Elapsed.TotalMilliseconds
                if ($ok) {
                    $segBytes += $len; $segMs += $ms
                    if ($ms -gt 700) { $huboLento = $true; $chunksLentos++ }
                } else {
                    $huboErr = $true
                    try { $fs.Dispose() } catch {}
                    $fs = $null
                    $ui.Estado.Text = "Error de lectura cerca del sector $([int64]($pos / $sec)). Localizando sectores danados..."
                    $malosTotal += (Localizar-SectoresMalos -Ruta $ruta -Pos $pos -Len $len -Sec $sec -Malos $malos)
                    $fs = New-Object System.IO.FileStream($ruta, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite, 1)
                    if ($malosTotal -gt 400) { $abortado = 'Se detuvo el analisis: demasiados sectores ilegibles. Copia tus datos importantes cuanto antes.'; $st.Cancelar = $true }
                }
                $pos += $len
                if ($relojPump.ElapsedMilliseconds -gt 100) { Wait-UI -Milisegundos 1; $relojPump.Restart() }
            }
            if ($segBytes -gt 0) {
                $total += $segBytes; $leidos++
                $v = ($segBytes / 1MB) / [Math]::Max(0.001, ($segMs / 1000.0))
                $base = 0.0
                if ($vels.Count -ge 10) {
                    $ini2 = [Math]::Max(0, $vels.Count - 40)
                    $ult = [double[]]$vels.GetRange($ini2, $vels.Count - $ini2).ToArray()
                    [Array]::Sort($ult)
                    $base = $ult[[int][Math]::Floor($ult.Length / 2)]
                }
                if ($base -gt 0 -and $v -lt ($base * 0.2)) { $huboLento = $true }
                $vels.Add($v)
                if ($v -lt $velMin) { $velMin = $v }
                if ($v -gt $velMax) { $velMax = $v }
            } else { $v = 0.0 }
            $celda = $ui.Celdas[$s]
            if ($huboErr) { $celda.Fill = $ui.Pincel.Error; $segErr++ }
            elseif ($huboLento) { $celda.Fill = $ui.Pincel.Lento; $segLentos++ }
            else { $celda.Fill = $ui.Pincel.Ok }
            $celda.ToolTip = "Segmento $($s + 1) | Desde $(Format-TamanoDisco $ini) | Velocidad: $([math]::Round($v,1)) MB/s"
            $pct = (($s + 1) / [double]$nSeg) * 100
            $ui.Barra.Value = $pct
            $trans = $relojTotal.Elapsed
            $resta = ''
            if ($s -gt 2) { $falta = [TimeSpan]::FromSeconds(($trans.TotalSeconds / ($s + 1)) * ($nSeg - $s - 1)); $resta = " | Restante ~ " + $falta.ToString('hh\:mm\:ss') }
            $ui.Estado.Text = ("Leyendo... {0:N0}%  |  {1} de {2} segmentos  |  {3:N0} MB/s  |  Sectores danados: {4}  |  Transcurrido {5}{6}" -f $pct, ($s + 1), $nSeg, $v, $malosTotal, $trans.ToString('hh\:mm\:ss'), $resta)
            if ($relojPump.ElapsedMilliseconds -gt 60) { Wait-UI -Milisegundos 1; $relojPump.Restart() }
        }
    } catch {
        $abortado = "No se pudo leer el disco: $($_.Exception.Message)"
    } finally {
        if ($fs) { try { $fs.Dispose() } catch {} }
        $relojTotal.Stop()
        $st.Corriendo = $false
        try { $ui.Iniciar.IsEnabled = $true; $ui.CmbDisco.IsEnabled = $true; $ui.CmbModo.IsEnabled = $true; $ui.Detener.IsEnabled = $false } catch {}
    }

    $cancelado = ($st.Cancelar -and -not $abortado)
    $vmed = 0.0; if ($vels.Count) { $s2 = 0.0; foreach ($q in $vels) { $s2 += $q }; $vmed = $s2 / $vels.Count }
    if ($velMin -eq [double]::MaxValue) { $velMin = 0.0 }
    $lineas = @()
    $lineas += "RESULTADO DEL ESCANEO DE SUPERFICIE - Disco $num ($($sel.Content))"
    $lineas += ("Leido: {0} en {1} ({2} segmentos de {3})" -f (Format-TamanoDisco $total), $relojTotal.Elapsed.ToString('hh\:mm\:ss'), $leidos, $nSeg)
    $lineas += ("Velocidad: media {0:N0} MB/s | minima {1:N0} MB/s | maxima {2:N0} MB/s" -f $vmed, $velMin, $velMax)
    $lineas += "Segmentos lentos (reintentos): $segLentos | Segmentos con error de lectura: $segErr | Sectores ilegibles: $malosTotal"
    if ($malos.Count -gt 0) {
        $primeros = @($malos | Select-Object -First 20)
        $lineas += "Primeros sectores danados (LBA): $($primeros -join ', ')"
    }
    if ($abortado) { $lineas += $abortado }
    if ($cancelado) { $lineas += "Analisis detenido por el usuario: resultado PARCIAL." }
    if ($malosTotal -gt 0) { $lineas += "CONCLUSION: el disco tiene sectores que no se pueden leer. Haz copia de seguridad ahora y considera reemplazarlo." }
    elseif ($segLentos -gt 0) { $lineas += "CONCLUSION: no hay sectores ilegibles, pero hay zonas lentas. Revisa S.M.A.R.T. y repite la prueba; si aumentan, el disco se esta degradando." }
    elseif (-not $abortado) { $lineas += "CONCLUSION: no se detectaron sectores danados en la zona analizada." }
    if ($modo -ne 2 -and -not $abortado) { $lineas += "Nota: el modo elegido analiza una muestra; para revisar el 100% de los sectores usa 'Completo'." }
    $ui.Resumen.Text = ($lineas -join "`r`n")
    $ui.Estado.Text = if ($cancelado) { "Detenido." } elseif ($abortado) { "Finalizado con avisos." } else { "Escaneo terminado." }
    foreach ($l in $lineas) { Write-DiagLog $l }
    if ($malosTotal -gt 0) { Diag-Aviso "El escaneo de superficie encontro $malosTotal sector(es) ilegible(s) en el disco $num." }
}

function Show-EscaneoSuperficieDisco {
    Write-DiagLog "=== DISCO: ESCANEO DE SUPERFICIE (mapa de sectores) ==="
    $discos = @()
    try { $discos = @(Get-CimInstance Win32_DiskDrive -ErrorAction Stop | Sort-Object Index) } catch {}
    if ($discos.Count -eq 0) { Write-DiagLog "No se pudo obtener la lista de discos."; return }
    try {
        [xml]$xamlEsc = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Escaneo de superficie - The Dragon Tool" Height="660" Width="860" MinHeight="520" MinWidth="640" WindowStartupLocation="CenterScreen" Background="#10141D">
  <Window.Resources>$($Global:RecursosNeonXaml)</Window.Resources>
  <DockPanel Margin="14">
    <Button x:Name="BtnVolverVentana" DockPanel.Dock="Top" Content="⬅  Volver" Width="110" Height="34" HorizontalAlignment="Left" Margin="0,0,0,8"/>
    <TextBlock DockPanel.Dock="Top" Foreground="White" TextWrapping="Wrap" Margin="0,0,0,8" FontSize="12"
               Text="Lee el disco fisico por zonas (SOLO LECTURA, no modifica nada) y pinta un mapa: verde = sano, amarillo = lento (reintentos), rojo = sector ilegible. Requiere ejecutar el programa como administrador."/>
    <WrapPanel DockPanel.Dock="Top" Margin="0,0,0,8">
      <TextBlock Text="Disco:" Foreground="White" VerticalAlignment="Center" Margin="0,0,6,0"/>
      <ComboBox x:Name="CmbDiscoEsc" Width="330" Margin="0,0,14,0"/>
      <TextBlock Text="Modo:" Foreground="White" VerticalAlignment="Center" Margin="0,0,6,0"/>
      <ComboBox x:Name="CmbModoEsc" Width="300">
        <ComboBoxItem Content="Rapido: muestreo de todo el disco (minutos)" IsSelected="True"/>
        <ComboBoxItem Content="Medio: 16 MB por zona (decenas de minutos)"/>
        <ComboBoxItem Content="Completo: todos los sectores (puede tardar horas)"/>
      </ComboBox>
    </WrapPanel>
    <WrapPanel DockPanel.Dock="Top" Margin="0,0,0,8">
      <Button x:Name="BtnIniciarEsc" Content="▶ Iniciar escaneo" Width="170" Height="38"/>
      <Button x:Name="BtnDetenerEsc" Content="⏹ Detener" Width="130" Height="38" IsEnabled="False"/>
    </WrapPanel>
    <ProgressBar x:Name="PbEsc" DockPanel.Dock="Top" Height="14" Minimum="0" Maximum="100" Margin="0,0,0,6"/>
    <TextBlock x:Name="TxtEstadoEsc" DockPanel.Dock="Top" Foreground="#66AEFF" TextWrapping="Wrap" Margin="0,0,0,6" FontSize="12" Text="Elige un disco y pulsa Iniciar."/>
    <WrapPanel DockPanel.Dock="Top" Margin="0,0,0,6">
      <Border Width="14" Height="14" Background="#29D398" Margin="0,0,5,0"/><TextBlock Text="Sano" Foreground="White" Margin="0,0,14,0" FontSize="12"/>
      <Border Width="14" Height="14" Background="#FFC857" Margin="0,0,5,0"/><TextBlock Text="Lento" Foreground="White" Margin="0,0,14,0" FontSize="12"/>
      <Border Width="14" Height="14" Background="#FF4D4D" Margin="0,0,5,0"/><TextBlock Text="Error de lectura" Foreground="White" Margin="0,0,14,0" FontSize="12"/>
      <Border Width="14" Height="14" Background="#232B3D" Margin="0,0,5,0"/><TextBlock Text="Sin leer" Foreground="White" FontSize="12"/>
    </WrapPanel>
    <TextBox x:Name="TxtResumenEsc" DockPanel.Dock="Bottom" Height="140" Margin="0,8,0,0" IsReadOnly="True" TextWrapping="Wrap" AcceptsReturn="True"
             Background="#070A10" Foreground="#66AEFF" FontFamily="Consolas" FontSize="12" VerticalScrollBarVisibility="Auto"/>
    <Border BorderBrush="#232B3D" BorderThickness="1" Background="#0A0E14" Padding="4">
      <UniformGrid x:Name="MapaEsc" Rows="20" Columns="40"/>
    </Border>
  </DockPanel>
</Window>
"@
        $winEsc = [Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader $xamlEsc))
        Iniciar-EfectosNeon -Ventana $winEsc
        $conv = New-Object System.Windows.Media.BrushConverter
        $mk = {
            param($hex)
            $b = $conv.ConvertFromString($hex); $b.Freeze(); return $b
        }
        $pincel = @{
            Sin = (& $mk '#232B3D'); Ok = (& $mk '#29D398'); Lento = (& $mk '#FFC857'); Error = (& $mk '#FF4D4D')
        }
        $mapa = $winEsc.FindName("MapaEsc")
        $celdas = New-Object System.Collections.ArrayList
        for ($i = 0; $i -lt 800; $i++) {
            $r = New-Object System.Windows.Shapes.Rectangle
            $r.Fill = $pincel.Sin
            $r.Margin = [System.Windows.Thickness]::new(1)
            [void]$mapa.Children.Add($r)
            [void]$celdas.Add($r)
        }
        $cmbD = $winEsc.FindName("CmbDiscoEsc")
        foreach ($d in $discos) {
            $it = New-Object System.Windows.Controls.ComboBoxItem
            $bs = [int]$d.BytesPerSector; if ($bs -lt 512) { $bs = 512 }
            $it.Content = "Disco $($d.Index): $($d.Model) ($(Format-TamanoDisco $d.Size))"
            $it.Tag = "$($d.Index)|$([int64]$d.Size)|$bs"
            [void]$cmbD.Items.Add($it)
        }
        $cmbD.SelectedIndex = 0
        $Global:EscEstado.Corriendo = $false; $Global:EscEstado.Cancelar = $false
        $Global:EscUi = @{
            Win = $winEsc; CmbDisco = $cmbD; CmbModo = $winEsc.FindName("CmbModoEsc")
            Iniciar = $winEsc.FindName("BtnIniciarEsc"); Detener = $winEsc.FindName("BtnDetenerEsc")
            Barra = $winEsc.FindName("PbEsc"); Estado = $winEsc.FindName("TxtEstadoEsc"); Resumen = $winEsc.FindName("TxtResumenEsc")
            Celdas = $celdas; Pincel = $pincel
        }
        $winEsc.FindName("BtnIniciarEsc").Add_Click({ Iniciar-EscaneoSuperficie })
        $winEsc.FindName("BtnDetenerEsc").Add_Click({ $Global:EscEstado.Cancelar = $true; $Global:EscUi.Estado.Text = "Deteniendo..." })
        $winEsc.Add_Closing({ $Global:EscEstado.Cancelar = $true })
        $winEsc.ShowDialog() | Out-Null
    } catch {
        Write-DiagLog "No se pudo abrir la ventana de escaneo de superficie: $($_.Exception.Message)"
    }
}

# ---------------------------------------------------------------------------
#  VIDA UTIL DEL SSD, IDENTIDAD DEL EQUIPO Y NUEVAS PRUEBAS (CPU / Wi-Fi / mouse)
# ---------------------------------------------------------------------------

# Marca, modelo y numero de serie del equipo (descarta los valores de relleno que dejan algunos fabricantes)
function Global:Obtener-IdentidadEquipo {
    $r = @{ Marca = ''; Modelo = ''; Serie = '' }
    $util = {
        param($v)
        $t = "$v".Trim()
        if (-not $t) { return $false }
        if ($t -match '(?i)to be filled|default string|system (serial|manufacturer|product|version)|o\.e\.m|^none$|not specified|not applicable|^n/?a$|^0+$|^x+$|0123456789|^unknown$|serial ?number|chassis') { return $false }
        return $true
    }
    $cs = $null; $csp = $null; $bios = $null; $bb = $null; $enc = $null
    try { $cs = Get-CimInstance Win32_ComputerSystem -ErrorAction Stop | Select-Object -First 1 } catch { }
    try { $csp = Get-CimInstance Win32_ComputerSystemProduct -ErrorAction Stop | Select-Object -First 1 } catch { }
    try { $bios = Get-CimInstance Win32_BIOS -ErrorAction Stop | Select-Object -First 1 } catch { }
    try { $bb = Get-CimInstance Win32_BaseBoard -ErrorAction Stop | Select-Object -First 1 } catch { }
    try { $enc = Get-CimInstance Win32_SystemEnclosure -ErrorAction Stop | Select-Object -First 1 } catch { }
    foreach ($m in @($(if ($cs) { $cs.Manufacturer }), $(if ($csp) { $csp.Vendor }), $(if ($bb) { $bb.Manufacturer }), $(if ($bios) { $bios.Manufacturer }))) {
        if (& $util $m) { $r.Marca = "$m".Trim(); break }
    }
    $modelo = ''
    if ($cs -and (& $util $cs.Model)) { $modelo = "$($cs.Model)".Trim() }
    # Lenovo guarda el nombre comercial (ThinkPad T480, IdeaPad...) en "Version"
    if ($r.Marca -match '(?i)lenovo' -and $csp -and (& $util $csp.Version)) {
        $v = "$($csp.Version)".Trim()
        $modelo = if ($modelo -and $modelo -ne $v) { "$v ($modelo)" } else { $v }
    }
    if (-not $modelo -and $csp -and (& $util $csp.Name)) { $modelo = "$($csp.Name)".Trim() }
    if (-not $modelo -and $bb -and (& $util $bb.Product)) { $modelo = "$($bb.Product)".Trim() }
    $r.Modelo = $modelo
    foreach ($s in @($(if ($bios) { $bios.SerialNumber }), $(if ($csp) { $csp.IdentifyingNumber }), $(if ($enc) { $enc.SerialNumber }), $(if ($bb) { $bb.SerialNumber }))) {
        if (& $util $s) { $r.Serie = "$s".Trim(); break }
    }
    if (-not $r.Marca) { $r.Marca = 'No disponible' }
    if (-not $r.Modelo) { $r.Modelo = 'No disponible' }
    if (-not $r.Serie) { $r.Serie = 'No registrado en la BIOS' }
    return $r
}

# Porcentaje de vida util restante de un SSD. Prioridad: atributos S.M.A.R.T. de vida (como CrystalDiskInfo);
# el contador "Wear" de Windows solo se usa si es mayor que 0 o si no hay otra fuente (muchos SSD SATA devuelven 0 aunque no sea cierto).
function Global:Obtener-VidaSSD {
    param($Disco)
    $nombreDisco = "$($Disco.FriendlyName)".Trim()
    $esWdSandisk = $nombreDisco -match '(?i)\bWDC?\b|WD |SanDisk|WDS\d'
    $orden = if ($esWdSandisk) { @(230, 231, 233, 177, 202) } else { @(231, 233, 177, 202, 169, 230) }
    $leidos = New-Object System.Collections.Generic.List[string]
    $porSmart = $null
    try {
        $partes = @($nombreDisco -split '\s+')
        $token = ($partes | Select-Object -Last 1) -replace '[^A-Za-z0-9]', ''
        $token = $token.ToUpper()
        if ($token.Length -gt 12) { $token = $token.Substring(0, 12) }
        $datos = @(Get-CimInstance -Namespace root\wmi -ClassName MSStorageDriver_ATAPISmartData -ErrorAction Stop)
        $umbr = @()
        try { $umbr = @(Get-CimInstance -Namespace root\wmi -ClassName MSStorageDriver_FailurePredictThresholds -ErrorAction Stop) } catch { }
        foreach ($d in $datos) {
            $inst = ("$($d.InstanceName)" -replace '[^A-Za-z0-9]', '').ToUpper()
            if ($datos.Count -gt 1 -and $token.Length -ge 4 -and -not $inst.Contains($token)) { continue }
            $u = $umbr | Where-Object { $_.InstanceName -eq $d.InstanceName } | Select-Object -First 1
            $ub = $null; if ($u) { $ub = $u.VendorSpecific }
            $attrs = @(Convertir-AtributosSmart -Datos $d.VendorSpecific -Umbrales $ub)
            if ($esWdSandisk) {
                # WD/SanDisk: el atributo E6 (indicador de desgaste del soporte) guarda el % de desgaste en el 2.o byte del dato crudo (asi lo calcula CrystalDiskInfo)
                $e6 = $attrs | Where-Object { $_.Id -eq 230 } | Select-Object -First 1
                if ($e6 -and $e6.Raw -gt 0) {
                    $des = [int](([int64]$e6.Raw -shr 8) -band 0xFF)
                    [void]$leidos.Add(("E6 crudo=0x{0:X12} -> desgaste {1} %" -f [int64]$e6.Raw, $des))
                    if ($des -ge 0 -and $des -le 100) {
                        $porSmart = [PSCustomObject]@{ Pct = (100 - $des); Fuente = 'atributo S.M.A.R.T. E6h (indicador de desgaste del soporte, dato crudo; mismo calculo que CrystalDiskInfo)'; Leidos = '' }
                    }
                }
            }
            if (-not $porSmart) {
            foreach ($id in $orden) {
                $at = $attrs | Where-Object { $_.Id -eq $id } | Select-Object -First 1
                if ($at) { [void]$leidos.Add(("{0:X2}={1}" -f $id, $at.Valor)) }
                if (-not $porSmart -and $at -and $at.Valor -gt 0 -and $at.Valor -le 100) {
                    $porSmart = [PSCustomObject]@{ Pct = [int]$at.Valor; Fuente = ("atributo S.M.A.R.T. {0:X2}h ({1})" -f $id, $Global:SmartNombres[$id]); Leidos = '' }
                }
            }
            }
            if ($porSmart) { break }
        }
    } catch { }
    if ($porSmart) { $porSmart.Leidos = ($leidos -join ', '); return $porSmart }
    try {
        $rc = $Disco | Get-StorageReliabilityCounter -ErrorAction Stop
        if ($rc -and $null -ne $rc.Wear -and "$($rc.Wear)" -match '^\d+$') {
            $w = [int]$rc.Wear
            if ($w -gt 0 -and $w -le 100) { return [PSCustomObject]@{ Pct = (100 - $w); Fuente = 'contadores de confiabilidad de Windows'; Leidos = '' } }
            if ($w -eq 0) { return [PSCustomObject]@{ Pct = 100; Fuente = 'contador de Windows = 0 % de desgaste (NO CONFIRMADO: este SSD no entrega un indicador de vida por S.M.A.R.T.; contrastalo con CrystalDiskInfo o la herramienta del fabricante)'; Leidos = ($leidos -join ', '); Dudoso = $true } }
        }
    } catch { }
    return $null
}

# Muestra la vida util del SSD (una vez por prueba) y la guarda para el informe PDF
function Global:Escribir-VidaSSD {
    param($Disco)
    $nombre = "$($Disco.FriendlyName)".Trim()
    $esSsd = ("$($Disco.MediaType)" -eq 'SSD') -or ("$($Disco.BusType)" -eq 'NVMe') -or ($nombre -match '(?i)\bSSD\b|NVMe|M\.2')
    if (-not $esSsd) { Escribir-EstadoHDD -Disco $Disco; return }
    if (-not $Global:VidaSsdImpresa) { $Global:VidaSsdImpresa = @{} }
    if ($Global:VidaSsdImpresa.ContainsKey($nombre)) { return }
    $Global:VidaSsdImpresa[$nombre] = $true
    $v = Obtener-VidaSSD -Disco $Disco
    if (-not $v) {
        Write-DiagLog "     💽 Vida util del SSD: no disponible (el SSD o su controlador no entrega el dato; usa la herramienta del fabricante)."
        return
    }
    $pct = [int]$v.Pct; $uso = 100 - $pct; $dudoso = $false
    $llenos = [int][math]::Round($pct / 10)
    $barra = ('█' * $llenos) + ('░' * (10 - $llenos))
    if ($v.Dudoso) { Write-DiagLog "     💽 VIDA UTIL DEL SSD: NO CONFIRMADA - $($v.Fuente)" }
    else { Write-DiagLog "     💽 VIDA UTIL DEL SSD: $pct % restante  [$barra]  (desgaste $uso %) - fuente: $($v.Fuente)" }
    if ($v.Leidos) { Write-DiagLog "     Indicadores S.M.A.R.T. de vida leidos (valor normalizado): $($v.Leidos)" }
    if ($v.Dudoso) { Diag-Aviso "No se pudo confirmar la vida util real del SSD (Windows informa 0 % de desgaste, pero este modelo suele reportarlo mal). Compara con CrystalDiskInfo."; $dudoso = $true }
    elseif ($pct -lt 10) { Diag-Aviso "Vida util del SSD critica ($pct %). Haz copia de seguridad y reemplazalo cuanto antes." }
    elseif ($pct -lt 30) { Diag-Aviso "Vida util del SSD baja ($pct %). Planea reemplazarlo pronto y mantén copias de seguridad." }
    elseif ($pct -ge 70) { Diag-Ok "Vida util del SSD en buen estado ($pct % restante)." }
    else { Write-DiagLog "     Desgaste moderado ($uso %): el SSD aun tiene vida util, pero conviene vigilarlo." }
    try { if ($Global:DiagInforme -and $Global:DiagInforme.Ssd) { $Global:DiagInforme.Ssd[$nombre] = @{ Pct = $pct; Fuente = $v.Fuente; Dudoso = $dudoso; Tam = [math]::Round($Disco.Size / 1GB, 0) } } } catch { }
}

# ---------------------------------------------------------------------------
#  INFORMACION DEL DISCO ELEGIDO Y ESTADO DE SALUD DE LOS DISCOS DUROS (HDD)
# ---------------------------------------------------------------------------

# ---------------------------------------------------------------------------
#  IDENTIFY DEVICE (ATA): rpm real, modo de transferencia SATA y estandar, igual que CrystalDiskInfo
# ---------------------------------------------------------------------------
function Global:Ensure-TipoAta {
    if ('DragonAta' -as [type]) { return }
    Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public static class DragonAta {
    [StructLayout(LayoutKind.Sequential)]
    struct ATA_PASS_THROUGH_EX {
        public ushort Length; public ushort AtaFlags; public byte PathId; public byte TargetId; public byte Lun; public byte ReservedAsUchar;
        public uint DataTransferLength; public uint TimeOutValue; public uint ReservedAsUlong; public IntPtr DataBufferOffset;
        [MarshalAs(UnmanagedType.ByValArray, SizeConst = 8)] public byte[] PreviousTaskFile;
        [MarshalAs(UnmanagedType.ByValArray, SizeConst = 8)] public byte[] CurrentTaskFile;
    }
    [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
    static extern IntPtr CreateFile(string name, uint access, uint share, IntPtr sec, uint disp, uint flags, IntPtr tmpl);
    [DllImport("kernel32.dll", SetLastError = true)]
    static extern bool DeviceIoControl(IntPtr h, uint code, IntPtr inBuf, uint inSize, IntPtr outBuf, uint outSize, out uint ret, IntPtr ov);
    [DllImport("kernel32.dll")]
    static extern bool CloseHandle(IntPtr h);
    public static ushort[] Identify(int disk) {
        IntPtr h = CreateFile("\\\\.\\PhysicalDrive" + disk, 0xC0000000, 3, IntPtr.Zero, 3, 0, IntPtr.Zero);
        if (h == new IntPtr(-1)) return null;
        try {
            int hdr = Marshal.SizeOf(typeof(ATA_PASS_THROUGH_EX));
            int total = hdr + 512;
            IntPtr buf = Marshal.AllocHGlobal(total);
            try {
                for (int i = 0; i < total; i++) Marshal.WriteByte(buf, i, 0);
                ATA_PASS_THROUGH_EX p = new ATA_PASS_THROUGH_EX();
                p.Length = (ushort)hdr; p.AtaFlags = 0x02; p.DataTransferLength = 512; p.TimeOutValue = 5;
                p.DataBufferOffset = new IntPtr(hdr);
                p.PreviousTaskFile = new byte[8]; p.CurrentTaskFile = new byte[8];
                p.CurrentTaskFile[6] = 0xEC;
                Marshal.StructureToPtr(p, buf, false);
                uint ret;
                if (!DeviceIoControl(h, 0x4D02C, buf, (uint)total, buf, (uint)total, out ret, IntPtr.Zero)) return null;
                ushort[] w = new ushort[256];
                bool alguno = false;
                for (int i = 0; i < 256; i++) {
                    w[i] = (ushort)(Marshal.ReadByte(buf, hdr + 2 * i) | (Marshal.ReadByte(buf, hdr + 2 * i + 1) << 8));
                    if (w[i] != 0) alguno = true;
                }
                return alguno ? w : null;
            } finally { Marshal.FreeHGlobal(buf); }
        } finally { CloseHandle(h); }
    }
}
"@
}

# Interpreta las 256 palabras del comando IDENTIFY DEVICE
function Global:Analizar-IdentifyAta {
    param([uint16[]]$W)
    $txt = {
        param($ini, $fin)
        $sb = New-Object System.Text.StringBuilder
        for ($i = $ini; $i -le $fin; $i++) { [void]$sb.Append([char](([int]$W[$i]) -shr 8)); [void]$sb.Append([char](([int]$W[$i]) -band 0xFF)) }
        return ($sb.ToString() -replace '[^\x20-\x7E]', '').Trim()
    }
    $r = [PSCustomObject]@{ Modelo = (& $txt 27 46); Serie = (& $txt 10 19); Firmware = (& $txt 23 26); Rpm = 0; Rotativo = $null; Actual = ''; Maximo = ''; Modo = ''; Estandar = ''; Serial = $false }
    $rot = [int]$W[217]
    if ($rot -eq 1) { $r.Rotativo = $false }
    elseif ($rot -ge 1025 -and $rot -le 65534) { $r.Rotativo = $true; $r.Rpm = $rot }
    $nombres = @{ 1 = 'SATA/150'; 2 = 'SATA/300'; 3 = 'SATA/600' }
    $w76 = [int]$W[76]; $w77 = [int]$W[77]
    if ($w76 -ne 0 -and $w76 -ne 65535) {
        $max = 0
        foreach ($g in 3, 2, 1) { if (($w76 -band (1 -shl $g)) -ne 0) { $max = $g; break } }
        $cur = ($w77 -shr 1) -band 7
        if ($max -gt 0) { $r.Maximo = $nombres[$max] }
        if ($cur -gt 0 -and $nombres.ContainsKey($cur)) { $r.Actual = $nombres[$cur] } elseif ($max -gt 0) { $r.Actual = $nombres[$max] }
        if ($r.Actual -or $r.Maximo) { $r.Modo = ("{0} | {1}" -f $(if ($r.Actual) { $r.Actual } else { '-' }), $(if ($r.Maximo) { $r.Maximo } else { '-' })); $r.Serial = $true }
    }
    $std = @{ 4 = 'ATA/ATAPI-4'; 5 = 'ATA/ATAPI-5'; 6 = 'ATA/ATAPI-6'; 7 = 'ATA/ATAPI-7'; 8 = 'ATA8-ACS'; 9 = 'ACS-2'; 10 = 'ACS-3'; 11 = 'ACS-4' }
    $w80 = [int]$W[80]
    if ($w80 -ne 0 -and $w80 -ne 65535) {
        foreach ($b in 11..4) { if (($w80 -band (1 -shl $b)) -ne 0) { $r.Estandar = $std[$b]; break } }
    }
    return $r
}

$Global:IdentCache = @{}
function Global:Obtener-IdentifyAta {
    param([int]$Numero)
    if ($Global:IdentCache.ContainsKey($Numero)) { return $Global:IdentCache[$Numero] }
    $res = $null
    try {
        Ensure-TipoAta
        $w = [DragonAta]::Identify($Numero)
        if ($w) { $res = Analizar-IdentifyAta -W $w }
    } catch { }
    $Global:IdentCache[$Numero] = $res
    return $res
}

# Atributos S.M.A.R.T. del disco indicado (objeto de Get-PhysicalDisk) y bandera de "fallo previsto"
function Global:Obtener-SmartDeDisco {
    param($Disco)
    $res = [PSCustomObject]@{ Attrs = @(); Prediccion = $null }
    try {
        $nombre = "$($Disco.FriendlyName)".Trim()
        $token = (@($nombre -split '\s+') | Select-Object -Last 1) -replace '[^A-Za-z0-9]', ''
        $token = $token.ToUpper()
        if ($token.Length -gt 12) { $token = $token.Substring(0, 12) }
        $datos = @(Get-CimInstance -Namespace root\wmi -ClassName MSStorageDriver_ATAPISmartData -ErrorAction Stop)
        $umbr = @(); $pred = @()
        try { $umbr = @(Get-CimInstance -Namespace root\wmi -ClassName MSStorageDriver_FailurePredictThresholds -ErrorAction Stop) } catch { }
        try { $pred = @(Get-CimInstance -Namespace root\wmi -ClassName MSStorageDriver_FailurePredictStatus -ErrorAction Stop) } catch { }
        foreach ($d in $datos) {
            $inst = ("$($d.InstanceName)" -replace '[^A-Za-z0-9]', '').ToUpper()
            if ($datos.Count -gt 1 -and $token.Length -ge 4 -and -not $inst.Contains($token)) { continue }
            $u = $umbr | Where-Object { $_.InstanceName -eq $d.InstanceName } | Select-Object -First 1
            $ub = $null; if ($u) { $ub = $u.VendorSpecific }
            $res.Attrs = @(Convertir-AtributosSmart -Datos $d.VendorSpecific -Umbrales $ub)
            $p = $pred | Where-Object { $_.InstanceName -eq $d.InstanceName } | Select-Object -First 1
            if ($p) { $res.Prediccion = [bool]$p.PredictFailure }
            break
        }
    } catch { }
    return $res
}

# Datos de la unidad: serie, horas de uso, velocidad y (en SSD) lecturas/escrituras
function Global:Obtener-InfoDisco {
    param([string]$Unidad)
    $num = Disco-DeUnidad $Unidad
    if ($null -eq $num) { return $null }
    $pd = $null; $wd = $null
    try { $pd = Get-PhysicalDisk -ErrorAction Stop | Where-Object { "$($_.DeviceId)" -eq "$num" } | Select-Object -First 1 } catch { }
    try { $wd = Get-CimInstance Win32_DiskDrive -ErrorAction Stop | Where-Object { "$($_.Index)" -eq "$num" } | Select-Object -First 1 } catch { }
    if (-not $pd -and -not $wd) { return $null }
    $o = [ordered]@{ Numero = $num; Modelo = ''; Serie = ''; Firmware = ''; Tipo = 'Desconocido'; Interfaz = ''; Rpm = 0; Horas = $null; Encendidos = $null; Modo = ''; Estandar = ''; Temp = $null; Capacidad = 0; LecHostGB = $null; EscHostGB = $null; EscNandGB = $null; Smart = $null; Disco = $pd }
    $o.Modelo = if ($pd -and $pd.FriendlyName) { "$($pd.FriendlyName)".Trim() } elseif ($wd) { "$($wd.Model)".Trim() } else { '' }
    $serie = ''
    if ($pd -and $pd.SerialNumber) { $serie = "$($pd.SerialNumber)".Trim(" ", "_", ".") }
    if (-not $serie -and $wd -and $wd.SerialNumber) { $serie = "$($wd.SerialNumber)".Trim(" ", "_", ".") }
    $o.Serie = if ($serie) { $serie } else { 'No informado' }
    if ($wd -and $wd.FirmwareRevision) { $o.Firmware = "$($wd.FirmwareRevision)".Trim() }
    $o.Capacidad = if ($pd -and $pd.Size) { [double]$pd.Size } elseif ($wd) { [double]$wd.Size } else { 0 }
    $bus = if ($pd) { "$($pd.BusType)" } elseif ($wd) { "$($wd.InterfaceType)" } else { '' }
    $o.Interfaz = switch -Regex ($bus) { '^SATA$' { 'Serial ATA' } '^NVMe$' { 'NVM Express (PCIe)' } '^USB$' { 'USB' } '^SAS$' { 'SAS' } '^ATA$' { 'ATA (IDE)' } '^SCSI$' { 'SCSI' } default { $bus } }
    $media = if ($pd) { "$($pd.MediaType)" } else { '' }
    $rpm = 0; if ($pd) { $rpm = [int](Numero-Seguro $pd.SpindleSpeed); if ($rpm -le 0 -or $rpm -ge 100000) { $rpm = 0 } }
    $o.Rpm = $rpm
    if ($bus -eq 'NVMe') { $o.Tipo = 'SSD NVMe' }
    elseif ($media -eq 'SSD') { $o.Tipo = 'SSD' }
    elseif ($media -eq 'HDD' -or $rpm -gt 0) { $o.Tipo = 'HDD' }
    elseif ($o.Modelo -match '(?i)\bSSD\b|NVMe|M\.2') { $o.Tipo = 'SSD' }
    # IDENTIFY DEVICE del propio disco: rpm real, modo de transferencia y estandar ATA (necesita administrador)
    if ($bus -ne 'NVMe') {
        $idt = Obtener-IdentifyAta -Numero $num
        if ($idt) {
            if ($idt.Rotativo -eq $true) { $o.Tipo = 'HDD'; if ($idt.Rpm -gt 0) { $o.Rpm = [int]$idt.Rpm } }
            elseif ($idt.Rotativo -eq $false -and $o.Tipo -eq 'Desconocido') { $o.Tipo = 'SSD' }
            if ($idt.Modo) { $o.Modo = $idt.Modo }
            if ($idt.Estandar) { $o.Estandar = $idt.Estandar }
            if ($o.Serie -eq 'No informado' -and $idt.Serie) { $o.Serie = $idt.Serie }
            if (-not $o.Firmware -and $idt.Firmware) { $o.Firmware = $idt.Firmware }
        }
    }
    # contadores de Windows
    if ($pd) {
        try {
            $rc = $pd | Get-StorageReliabilityCounter -ErrorAction Stop
            if ($rc) {
                if ($null -ne $rc.PowerOnHours -and (Numero-Seguro $rc.PowerOnHours) -gt 0) { $o.Horas = [int64](Numero-Seguro $rc.PowerOnHours) }
                if ($null -ne $rc.Temperature -and (Numero-Seguro $rc.Temperature) -gt 0) { $o.Temp = [int](Numero-Seguro $rc.Temperature) }
            }
        } catch { }
    }
    # S.M.A.R.T. (horas, GB leidos/escritos)
    if ($pd -and $bus -ne 'NVMe') {
        $sm = Obtener-SmartDeDisco -Disco $pd
        $o.Smart = $sm
        $at = @($sm.Attrs)
        $g = { param($id) $at | Where-Object { $_.Id -eq $id } | Select-Object -First 1 }
        $a12 = & $g 12; if ($a12 -and $a12.Raw -gt 0) { $o.Encendidos = [int64]([int64]$a12.Raw -band [int64]4294967295) }
        if ($null -eq $o.Horas) { $a9 = & $g 9; if ($a9 -and $a9.Raw -gt 0) { $o.Horas = [int64]($a9.Raw -band 0xFFFFFF) } }
        if ($null -eq $o.Temp) { $c2 = & $g 194; if ($c2) { $t = [int]($c2.Raw -band 0xFF); if ($t -gt 0 -and $t -lt 120) { $o.Temp = $t } } }
        if ($o.Tipo -like 'SSD*') {
            $wdFam = $o.Modelo -match '(?i)^WDC|^WD |SanDisk|WDS\d'
            $sam = $o.Modelo -match '(?i)samsung'
            $f1 = & $g 241; $f2 = & $g 242; $e9 = & $g 233
            if ($wdFam) {
                if ($f1 -and $f1.Raw -gt 0) { $o.EscHostGB = [double]$f1.Raw }
                if ($f2 -and $f2.Raw -gt 0) { $o.LecHostGB = [double]$f2.Raw }
                if ($e9 -and $e9.Raw -gt 0) { $o.EscNandGB = [double]$e9.Raw }
            } elseif ($sam) {
                if ($f1 -and $f1.Raw -gt 0) { $o.EscHostGB = [math]::Round([double]$f1.Raw * 512 / 1GB, 0) }
                if ($f2 -and $f2.Raw -gt 0) { $o.LecHostGB = [math]::Round([double]$f2.Raw * 512 / 1GB, 0) }
            }
        }
    }
    return [PSCustomObject]$o
}

# Texto de la tarjeta "Datos de la unidad" que se ve al elegir la unidad
function Global:Texto-InfoDisco {
    param($i)
    if (-not $i) { return "No se pudo identificar el disco fisico de esta unidad (puede ser una unidad virtual o de red)." }
    $l = New-Object System.Collections.Generic.List[string]
    $l.Add("$($i.Modelo)  |  $($i.Tipo)  |  $(Format-TamanoDisco $i.Capacidad)")
    $fw = if ($i.Firmware) { "  |  Firmware: $($i.Firmware)" } else { '' }
    $l.Add("N° de serie: $($i.Serie)$fw")
    $modo = if ($i.Modo) { $i.Modo } elseif ($i.Interfaz -eq 'NVM Express (PCIe)') { 'enlace PCIe (no informado por Windows)' } else { 'no informado' }
    $std = if ($i.Estandar) { "  |  Estandar: $($i.Estandar)" } else { '' }
    $l.Add("Interfaz: $($i.Interfaz)  |  Modo de transferencia: $modo$std")
    $h = if ($null -ne $i.Horas) { "{0:N0} h (~{1:N0} dias)" -f $i.Horas, ($i.Horas / 24) } else { 'no informado' }
    $enc = if ($null -ne $i.Encendidos) { "{0:N0} veces" -f $i.Encendidos } else { 'no informado' }
    $l.Add("Horas de uso: $h  |  Veces encendido: $enc")
    $t = if ($null -ne $i.Temp) { "Temperatura: $($i.Temp) °C" } else { '' }
    if ($i.Tipo -eq 'HDD') {
        $v = if ($i.Rpm -gt 0) { "$($i.Rpm) RPM" } else { 'no informada por el disco' }
        $l.Add("Velocidad de rotacion: $v" + $(if ($t) { "  |  $t" } else { '' }))
    } elseif ($t) {
        $l.Add($t)
    }
    if ($i.Tipo -like 'SSD*') {
        $f = { param($x) if ($null -ne $x) { "{0:N0} GB" -f $x } else { 'no disponible' } }
        $l.Add("Lecturas del host: $(& $f $i.LecHostGB)  |  Escrituras del host: $(& $f $i.EscHostGB)  |  Escrituras a NAND: $(& $f $i.EscNandGB)")
    }
    return ($l -join "`r`n")
}

# Refresca la tarjeta de informacion segun la unidad elegida en el panel
function Global:Mostrar-InfoUnidad {
    $caja = $Global:TxtInfoUnidad
    if (-not $caja) { return }
    $u = Unidad-Diag
    $caja.Text = "Leyendo datos de la unidad $u..."
    try { Wait-UI -Milisegundos 1 } catch { }
    try { $caja.Text = Texto-InfoDisco (Obtener-InfoDisco -Unidad $u) } catch { $caja.Text = "No se pudieron leer los datos de la unidad $u : $($_.Exception.Message)" }
}

# Escribe en el diagnostico la identificacion del disco (serie, horas, velocidad, NAND)
function Global:Escribir-InfoDisco {
    param($Info)
    if (-not $Info) { return }
    foreach ($ln in @((Texto-InfoDisco $Info) -split "`r?`n")) { Write-DiagLog "     $ln" }
}

# Evalua el estado de un disco duro: Bueno / En riesgo / Malo
function Global:Evaluar-SaludHDD {
    param($Smart, $Horas, $Temp)
    $at = @($Smart.Attrs)
    $raw = { param($id) $a = $at | Where-Object { $_.Id -eq $id } | Select-Object -First 1; if ($a) { [int64]([int64]$a.Raw -band [int64]4294967295) } else { $null } }
    $malo = New-Object System.Collections.Generic.List[string]
    $riesgo = New-Object System.Collections.Generic.List[string]
    $datos = New-Object System.Collections.Generic.List[string]
    if ($Smart.Prediccion -eq $true) { $malo.Add("Windows/S.M.A.R.T. predice un fallo inminente del disco") }
    $realoc = & $raw 5; $pend = & $raw 197; $incorr = & $raw 198; $off = & $raw 187; $giro = & $raw 10; $crc = & $raw 199; $reev = & $raw 196
    if ($null -ne $realoc) { $datos.Add("Sectores reasignados: $realoc") }
    if ($null -ne $pend) { $datos.Add("Sectores pendientes: $pend") }
    if ($null -ne $incorr) { $datos.Add("Sectores no corregibles: $incorr") }
    if ($null -ne $giro) { $datos.Add("Reintentos de giro: $giro") }
    if ($null -ne $crc) { $datos.Add("Errores CRC: $crc") }
    if ($null -ne $realoc) { if ($realoc -ge 100) { $malo.Add("$realoc sectores reasignados (muchos)") } elseif ($realoc -gt 0) { $riesgo.Add("$realoc sector(es) reasignado(s): la superficie ya esta fallando") } }
    if ($null -ne $pend) { if ($pend -ge 50) { $malo.Add("$pend sectores pendientes de reasignar") } elseif ($pend -gt 0) { $riesgo.Add("$pend sector(es) pendiente(s) de reasignar") } }
    if ($null -ne $incorr) { if ($incorr -ge 50) { $malo.Add("$incorr sectores no corregibles") } elseif ($incorr -gt 0) { $riesgo.Add("$incorr sector(es) no corregible(s)") } }
    if ($null -ne $off -and $off -gt 0) { $riesgo.Add("$off error(es) no corregibles notificados") }
    if ($null -ne $giro -and $giro -gt 0) { $riesgo.Add("$giro reintento(s) de giro del motor") }
    if ($null -ne $crc -and $crc -gt 0) { $riesgo.Add("$crc error(es) de comunicacion CRC (revisa cable/puerto SATA)") }
    if ($null -ne $reev -and $reev -gt 0) { $riesgo.Add("$reev evento(s) de reasignacion") }
    # valores normalizados cerca o por debajo del umbral del fabricante
    foreach ($a in $at) {
        if ($a.Umbral -gt 0 -and $a.Id -in 1, 2, 3, 4, 5, 7, 8, 10, 196, 197, 198, 199, 200) {
            if ($a.Valor -le $a.Umbral) { $malo.Add(("Atributo {0:X2}h por debajo del umbral del fabricante ({1} <= {2})" -f $a.Id, $a.Valor, $a.Umbral)) }
            elseif ($a.Valor -le ($a.Umbral + 10)) { $riesgo.Add(("Atributo {0:X2}h cerca del umbral del fabricante ({1} / umbral {2})" -f $a.Id, $a.Valor, $a.Umbral)) }
        }
    }
    if ($null -ne $Horas) {
        if ($Horas -ge 50000) { $riesgo.Add(("{0:N0} horas de uso: disco muy veterano" -f $Horas)) }
        elseif ($Horas -ge 35000) { $riesgo.Add(("{0:N0} horas de uso: disco con mucho uso" -f $Horas)) }
    }
    if ($null -ne $Temp) {
        if ($Temp -ge 60) { $malo.Add("Temperatura muy alta ($Temp °C)") }
        elseif ($Temp -ge 50) { $riesgo.Add("Temperatura alta ($Temp °C)") }
    }
    $estado = 'Bueno'
    if ($malo.Count -gt 0) { $estado = 'Malo' } elseif ($riesgo.Count -gt 0) { $estado = 'En riesgo' }
    $motivos = @($malo) + @($riesgo)
    return [PSCustomObject]@{ Estado = $estado; Motivos = $motivos; Datos = @($datos) }
}

# Muestra el estado del disco duro (una vez por prueba) y lo guarda para el informe PDF
function Global:Escribir-EstadoHDD {
    param($Disco)
    $nombre = "$($Disco.FriendlyName)".Trim()
    $rpm = [int](Numero-Seguro $Disco.SpindleSpeed)
    $esHdd = ("$($Disco.MediaType)" -eq 'HDD') -or ($rpm -gt 0 -and $rpm -lt 100000)
    if (-not $esHdd -and "$($Disco.MediaType)" -ne 'SSD' -and "$($Disco.BusType)" -ne 'NVMe') {
        try { $idt = Obtener-IdentifyAta -Numero ([int]$Disco.DeviceId); if ($idt -and $idt.Rotativo -eq $true) { $esHdd = $true } } catch { }
    }
    if (-not $esHdd) { return }
    if (-not $Global:VidaSsdImpresa) { $Global:VidaSsdImpresa = @{} }
    $clave = "HDD:$nombre"
    if ($Global:VidaSsdImpresa.ContainsKey($clave)) { return }
    $Global:VidaSsdImpresa[$clave] = $true
    $sm = Obtener-SmartDeDisco -Disco $Disco
    if (@($sm.Attrs).Count -eq 0 -and $null -eq $sm.Prediccion) {
        Write-DiagLog "     🩺 ESTADO DEL DISCO DURO: no determinado (este disco o su controlador no entrega datos S.M.A.R.T.; prueba con CrystalDiskInfo)."
        return
    }
    $horas = $null; $temp = $null
    try {
        $rc = $Disco | Get-StorageReliabilityCounter -ErrorAction Stop
        if ($rc -and (Numero-Seguro $rc.PowerOnHours) -gt 0) { $horas = [int64](Numero-Seguro $rc.PowerOnHours) }
        if ($rc -and (Numero-Seguro $rc.Temperature) -gt 0) { $temp = [int](Numero-Seguro $rc.Temperature) }
    } catch { }
    $a9 = @($sm.Attrs) | Where-Object { $_.Id -eq 9 } | Select-Object -First 1
    if ($null -eq $horas -and $a9 -and $a9.Raw -gt 0) { $horas = [int64]($a9.Raw -band 0xFFFFFF) }
    if ($null -eq $temp) { $c2 = @($sm.Attrs) | Where-Object { $_.Id -eq 194 } | Select-Object -First 1; if ($c2) { $tt = [int]($c2.Raw -band 0xFF); if ($tt -gt 0 -and $tt -lt 120) { $temp = $tt } } }
    $ev = Evaluar-SaludHDD -Smart $sm -Horas $horas -Temp $temp
    $icono = switch ($ev.Estado) { 'Bueno' { '🟢' } 'En riesgo' { '🟠' } default { '🔴' } }
    Write-DiagLog "     $icono ESTADO DEL DISCO DURO: $($ev.Estado.ToUpper())"
    if ($ev.Datos.Count) { Write-DiagLog "     $($ev.Datos -join ' | ')" }
    foreach ($m in $ev.Motivos) { Write-DiagLog "       - $m" }
    switch ($ev.Estado) {
        'Bueno' { Diag-Ok "El disco duro esta en buen estado (sin sectores danados ni alertas S.M.A.R.T.)." }
        'En riesgo' { Diag-Aviso "Disco duro EN RIESGO: hay senales de desgaste o errores. Haz copia de seguridad de tus datos y vigilalo." }
        default { Diag-Aviso "Disco duro en MAL ESTADO: copia de seguridad inmediata y reemplazo urgente." }
    }
    try { if ($Global:DiagInforme -and $Global:DiagInforme.Ssd) { $Global:DiagInforme.Ssd[$nombre] = @{ Tipo = 'HDD'; Estado = $ev.Estado; Motivos = @($ev.Motivos); Pct = -1; Fuente = 'S.M.A.R.T.'; Dudoso = $false; Tam = [math]::Round($Disco.Size / 1GB, 0); Horas = $horas } } } catch { }
}

function Accion-DiscoVidaSSD {
    $uSel = Unidad-Diag
    $numSel = Disco-DeUnidad $uSel
    Write-DiagLog "=== VIDA UTIL / ESTADO DEL DISCO - unidad $uSel ==="
    $info = $null
    try { $info = Obtener-InfoDisco -Unidad $uSel } catch { }
    $hay = $false
    try {
        foreach ($d in @(Get-PhysicalDisk -ErrorAction Stop)) {
            if ($null -ne $numSel -and "$($d.DeviceId)" -ne "$numSel") { continue }
            $hay = $true
            Write-DiagLog " - $($d.FriendlyName) | $($d.MediaType) | $($d.BusType) | $([math]::Round($d.Size / 1GB, 0)) GB | Salud: $($d.HealthStatus)"
            if ($info -and "$($info.Numero)" -eq "$($d.DeviceId)") { Escribir-InfoDisco -Info $info }
            Escribir-VidaSSD -Disco $d
        }
    } catch { Write-DiagLog "No se pudo consultar los discos fisicos." }
    if (-not $hay) { Write-DiagLog "No se pudo identificar el disco fisico de la unidad $uSel." }
}

# ---------------------------- CPU ----------------------------

$Script:TipoCpuCheckListo = $false
function Ensure-TipoCpuCheck {
    if ($Script:TipoCpuCheckListo) { return }
    $codigo = @"
using System;
using System.Threading;
public static class DragonCpuCheck {
    static volatile bool detener;
    static long errores;
    static long vueltas;
    static ulong referencia;
    static Thread[] hilos;
    static ulong Calcular() {
        ulong h = 1469598103934665603UL; double x = 1.5; long e = 7;
        for (int i = 1; i <= 3000; i++) {
            x = Math.Sqrt(x * x + i) * 1.0000001;
            e = (e * 6364136223846793005L + 1442695040888963407L);
            h ^= (ulong)BitConverter.DoubleToInt64Bits(x) ^ (ulong)e;
            h *= 1099511628211UL;
            h = (h << 13) | (h >> 51);
        }
        return h;
    }
    static void Trabajo() {
        long malos = 0, n = 0;
        while (!detener) {
            if (Calcular() != referencia) malos++;
            n++;
        }
        Interlocked.Add(ref errores, malos);
        Interlocked.Add(ref vueltas, n);
    }
    public static void Iniciar(int cantidad) {
        detener = false; errores = 0; vueltas = 0; referencia = Calcular();
        hilos = new Thread[cantidad];
        for (int i = 0; i < cantidad; i++) { hilos[i] = new Thread(Trabajo); hilos[i].IsBackground = true; hilos[i].Start(); }
    }
    public static long Detener() { detener = true; foreach (Thread t in hilos) t.Join(); return errores; }
    public static long Vueltas { get { return vueltas; } }
}
"@
    Add-Type -TypeDefinition $codigo -ErrorAction Stop
    $Script:TipoCpuCheckListo = $true
}

function Accion-CpuInformacion {
    Write-DiagLog "=== PROCESADOR: INFORMACION, FRECUENCIAS Y CARACTERISTICAS ==="
    try {
        foreach ($cpu in @(Get-CimInstance Win32_Processor -ErrorAction Stop)) {
            Write-DiagLog " - $("$($cpu.Name)".Trim())"
            Write-DiagLog "     Fabricante: $($cpu.Manufacturer) | Socket: $($cpu.SocketDesignation) | Arquitectura: $(@{0='x86';5='ARM';9='x64';12='ARM64'}[[int]$cpu.Architecture])"
            Write-DiagLog "     Nucleos: $($cpu.NumberOfCores) | Hilos: $($cpu.NumberOfLogicalProcessors) | Cache L2: $([math]::Round($cpu.L2CacheSize / 1024, 1)) MB | Cache L3: $([math]::Round($cpu.L3CacheSize / 1024, 1)) MB"
            Write-DiagLog "     Frecuencia: actual $($cpu.CurrentClockSpeed) MHz | maxima $($cpu.MaxClockSpeed) MHz | uso instantaneo: $($cpu.LoadPercentage) %"
            $virt = if ($cpu.VirtualizationFirmwareEnabled) { 'activada' } else { 'desactivada o no disponible (BIOS)' }
            Write-DiagLog "     Virtualizacion en BIOS: $virt"
            if ($cpu.MaxClockSpeed -gt 0 -and $cpu.CurrentClockSpeed -gt 0) {
                $rel = [math]::Round(100 * $cpu.CurrentClockSpeed / $cpu.MaxClockSpeed, 0)
                if ($rel -lt 40 -and [int]$cpu.LoadPercentage -gt 60) { Diag-Aviso "La CPU trabaja al $rel % de su frecuencia maxima con carga alta: posible limitacion por temperatura, plan de energia o bateria." }
                else { Diag-Ok "Frecuencia de la CPU coherente con su carga ($rel % de la maxima)." }
            }
            if ([int]$cpu.NumberOfLogicalProcessors -le 2) { Write-DiagLog "     Procesador de pocos hilos: puede notarse lento con Windows 10/11 y navegadores modernos." }
        }
    } catch { Write-DiagLog "No se pudo leer la informacion del procesador: $($_.Exception.Message)" }
    try {
        $plan = (powercfg /getactivescheme 2>$null) -join ' '
        if ($plan -match ':\s*[0-9a-f-]+\s*\((.+?)\)') { Write-DiagLog " - Plan de energia activo: $($Matches[1])" ; if ($Matches[1] -match '(?i)ahorr|saver') { Diag-Aviso "El plan de energia es de ahorro: limita el rendimiento de la CPU. Cambia a 'Equilibrado' o 'Alto rendimiento'." } }
    } catch { }
    $t = Get-TemperaturaCPUC
    if ($null -ne $t) { Write-DiagLog " - Temperatura actual: $t °C" } else { Write-DiagLog " - Temperatura: Windows no la expone en este equipo." }
}

function Accion-CpuUsoNucleos {
    Write-DiagLog "=== PROCESADOR: USO POR NUCLEO Y PROCESOS (8 segundos) ==="
    try {
        $muestras = 8
        $nucleos = @{}
        $procs = @{}
        $totales = New-Object System.Collections.Generic.List[double]
        $nCpu = [math]::Max(1, [Environment]::ProcessorCount)
        for ($i = 1; $i -le $muestras; $i++) {
            Diag-Progreso -Pct (($i - 1) / $muestras * 100) -Texto "Midiendo uso de la CPU... ($i/$muestras)"
            try {
                foreach ($c in @(Get-CimInstance Win32_PerfFormattedData_PerfOS_Processor -ErrorAction Stop)) {
                    if ($c.Name -eq '_Total') { $totales.Add([double]$c.PercentProcessorTime) }
                    else {
                        if (-not $nucleos.ContainsKey($c.Name)) { $nucleos[$c.Name] = New-Object System.Collections.Generic.List[double] }
                        $nucleos[$c.Name].Add([double]$c.PercentProcessorTime)
                    }
                }
            } catch { }
            try {
                foreach ($p in @(Get-CimInstance Win32_PerfFormattedData_PerfProc_Process -ErrorAction Stop)) {
                    $nm = ("$($p.Name)" -replace '#\d+$', '')
                    if ($nm -in '_Total', 'Idle') { continue }
                    if (-not $procs.ContainsKey($nm)) { $procs[$nm] = 0.0 }
                    $procs[$nm] += [double]$p.PercentProcessorTime / $nCpu / $muestras
                }
            } catch { }
            Wait-UI -Milisegundos 700
        }
        Diag-Progreso -Pct 100 -Texto "Analizando resultados..."
        if ($totales.Count -eq 0) { Write-DiagLog "Windows no entrego los contadores de uso de CPU en este equipo."; return }
        $prom = [math]::Round(($totales | Measure-Object -Average).Average, 1)
        $max = [math]::Round(($totales | Measure-Object -Maximum).Maximum, 0)
        Write-DiagLog " - Uso total de la CPU: promedio $prom % | pico $max %"
        foreach ($k in ($nucleos.Keys | Sort-Object { [int]$_ })) {
            $a = [math]::Round(($nucleos[$k] | Measure-Object -Average).Average, 0)
            $barra = ('█' * [int][math]::Round($a / 10)) + ('░' * (10 - [int][math]::Round($a / 10)))
            Write-DiagLog ("     Nucleo/hilo {0,-3} [{1}] {2,3} %" -f $k, $barra, $a)
        }
        $top = @($procs.GetEnumerator() | Sort-Object Value -Descending | Select-Object -First 5 | Where-Object { $_.Value -ge 0.5 })
        if ($top.Count) {
            Write-DiagLog " - Procesos que mas CPU usan:"
            foreach ($t in $top) { Write-DiagLog ("     {0,-32} {1,5} %" -f $t.Key, [math]::Round($t.Value, 1)) }
        }
        if ($prom -ge 85) { Diag-Aviso "La CPU esta saturada ($prom % de promedio). Cierra programas o revisa el proceso que mas consume." }
        elseif ($prom -ge 60) { Diag-Aviso "Uso de CPU alto ($prom %) en reposo. Revisa los procesos de arriba, el antivirus o programas de inicio." }
        else { Diag-Ok "Uso de CPU normal ($prom % de promedio)." }
        if ($top.Count -and $top[0].Value -ge 40) { Diag-Aviso "El proceso '$($top[0].Key)' consume el $([math]::Round($top[0].Value, 0)) % de la CPU." }
    } catch { Write-DiagLog "No se pudo medir el uso por nucleo: $($_.Exception.Message)" }
}

function Accion-CpuEstabilidad {
    Write-DiagLog "=== PROCESADOR: ESTABILIDAD Y THROTTLING BAJO CARGA (30 segundos) ==="
    try {
        Ensure-TipoCpuBench
        $hilos = [Environment]::ProcessorCount
        $segmentos = 6; $dur = 5
        $res = New-Object System.Collections.Generic.List[object]
        $t0 = Get-TemperaturaCPUC
        Write-DiagLog "Cargando los $hilos hilos al maximo durante $($segmentos * $dur) s y midiendo rendimiento, frecuencia y temperatura..."
        for ($s = 1; $s -le $segmentos; $s++) {
            [DragonCpuBench]::Iniciar($hilos)
            $cron = [System.Diagnostics.Stopwatch]::StartNew()
            $mhz = $null
            while ($cron.Elapsed.TotalSeconds -lt $dur) {
                Diag-Progreso -Pct ((($s - 1) * $dur + $cron.Elapsed.TotalSeconds) / ($segmentos * $dur) * 100) -Texto "Carga maxima... segmento $s de $segmentos"
                if ($null -eq $mhz -and $cron.Elapsed.TotalSeconds -gt ($dur - 1.5)) { try { $mhz = [int](Get-CimInstance Win32_Processor -ErrorAction Stop | Select-Object -First 1).CurrentClockSpeed } catch { $mhz = 0 } }
                Wait-UI -Milisegundos 100
            }
            $n = [DragonCpuBench]::Detener(); $seg = $cron.Elapsed.TotalSeconds
            $temp = Get-TemperaturaCPUC
            $res.Add([PSCustomObject]@{ N = $s; Mops = [math]::Round($n / $seg / 1e6, 1); Mhz = $mhz; Temp = $temp })
        }
        foreach ($r in $res) {
            $extra = @()
            if ($r.Mhz) { $extra += "$($r.Mhz) MHz" }
            if ($null -ne $r.Temp) { $extra += "$($r.Temp) °C" }
            Write-DiagLog ("     Segmento {0}: {1,7} M ops/s   {2}" -f $r.N, $r.Mops, ($extra -join ' | '))
        }
        $primero = $res[0].Mops; $ultimo = $res[$res.Count - 1].Mops
        $mejor = ($res | Measure-Object Mops -Maximum).Maximum
        $caida = if ($mejor -gt 0) { [math]::Round(100 * (1 - $ultimo / $mejor), 1) } else { 0 }
        Write-DiagLog " - Rendimiento final respecto al mejor segmento: -$caida %"
        if ($caida -ge 25) { Diag-Aviso "La CPU pierde el $caida % de rendimiento bajo carga sostenida (throttling por temperatura o energia). Limpia ventiladores/disipador y cambia la pasta termica." }
        elseif ($caida -ge 12) { Diag-Aviso "La CPU baja el $caida % bajo carga sostenida: refrigeracion justa." }
        else { Diag-Ok "Rendimiento estable bajo carga sostenida (variacion de $caida %)." }
        $tFin = $res[$res.Count - 1].Temp
        if ($null -ne $tFin) {
            if ($tFin -ge 95) { Diag-Aviso "Temperatura critica bajo carga ($tFin °C)." }
            elseif ($tFin -ge 85) { Diag-Aviso "Temperatura alta bajo carga ($tFin °C)." }
            else { Diag-Ok "Temperatura bajo carga sostenida correcta ($tFin °C)." }
        }
        $m1 = $res[0].Mhz; $m6 = $res[$res.Count - 1].Mhz
        if ($m1 -and $m6 -and $m6 -lt ($m1 * 0.8)) { Diag-Aviso "La frecuencia cayo de $m1 a $m6 MHz durante la prueba (limitacion termica o de energia)." }
    } catch {
        try { [DragonCpuBench]::Detener() | Out-Null } catch { }
        Write-DiagLog "No se pudo completar la prueba de estabilidad: $($_.Exception.Message)"
    }
}

function Accion-CpuIntegridad {
    Write-DiagLog "=== PROCESADOR: INTEGRIDAD DE CALCULO (15 segundos) ==="
    try {
        Ensure-TipoCpuCheck
        $hilos = [Environment]::ProcessorCount
        Write-DiagLog "Cada hilo repite el mismo calculo y compara el resultado; cualquier diferencia indica inestabilidad (overclock, voltaje, RAM o CPU defectuosa)."
        [DragonCpuCheck]::Iniciar($hilos)
        $cron = [System.Diagnostics.Stopwatch]::StartNew()
        while ($cron.Elapsed.TotalSeconds -lt 15) { Diag-Progreso -Pct ($cron.Elapsed.TotalSeconds / 15 * 100) -Texto "Verificando calculos en $hilos hilos..."; Wait-UI -Milisegundos 100 }
        $errores = [DragonCpuCheck]::Detener()
        $vueltas = [DragonCpuCheck]::Vueltas
        Write-DiagLog " - Calculos verificados: $('{0:N0}' -f $vueltas) en $hilos hilos | Resultados incorrectos: $errores"
        if ($errores -gt 0) { Diag-Aviso "Se detectaron $errores resultado(s) incorrecto(s): el procesador es inestable. Quita overclock/undervolt, revisa temperatura, fuente de poder y prueba la RAM." }
        else { Diag-Ok "El procesador calculo sin errores durante toda la prueba." }
    } catch {
        try { [DragonCpuCheck]::Detener() | Out-Null } catch { }
        Write-DiagLog "No se pudo ejecutar la prueba de integridad: $($_.Exception.Message)"
    }
}

# ---------------------------- Wi-Fi ----------------------------

function Accion-WifiAdaptador {
    Write-DiagLog "=== WI-FI: ADAPTADOR, DRIVER Y CAPACIDADES ==="
    $hallado = $false
    try {
        $ads = @(Get-NetAdapter -ErrorAction Stop | Where-Object { $_.InterfaceDescription -match '(?i)wi-?fi|wireless|802\.11|wlan|centrino|killer|dual band' -or $_.PhysicalMediaType -match '802\.11' })
        foreach ($a in $ads) {
            $hallado = $true
            Write-DiagLog " - $($a.Name): $($a.InterfaceDescription)"
            Write-DiagLog "     Estado: $($a.Status) | Velocidad del enlace: $($a.LinkSpeed) | MAC: $($a.MacAddress)"
            $drv = "$($a.DriverVersionString)"; $fd = $null
            try { $fd = [datetime]$a.DriverDate } catch { }
            Write-DiagLog "     Driver: $drv | Fecha: $(if ($fd) { $fd.ToString('yyyy-MM-dd') } else { 'desconocida' }) | Proveedor: $($a.DriverProvider)"
            if ("$($a.Status)" -eq 'Disabled') { Diag-Aviso "El adaptador Wi-Fi esta deshabilitado en Windows." }
            elseif ("$($a.Status)" -eq 'Up') { Diag-Ok "Adaptador Wi-Fi activo y conectado." }
            else { Write-DiagLog "     (Adaptador sin conexion en este momento.)" }
            if ($fd -and ((Get-Date) - $fd).TotalDays -gt 1095) { Diag-Aviso "El driver Wi-Fi tiene mas de 3 años: actualizalo desde el fabricante del equipo/adaptador." }
            try {
                $pm = Get-NetAdapterPowerManagement -Name $a.Name -ErrorAction Stop
                if ("$($pm.AllowComputerToTurnOffDevice)" -eq 'Enabled') { Write-DiagLog "     Ahorro de energia: Windows puede apagar el adaptador (si hay cortes de Wi-Fi, desactiva esa opcion en las propiedades del adaptador)." }
            } catch { }
        }
    } catch { }
    if (-not $hallado) { Write-DiagLog "No se detecto ningun adaptador Wi-Fi (equipo de escritorio sin Wi-Fi, adaptador apagado o sin driver)."; }
    try {
        $drv = @(netsh wlan show drivers 2>$null)
        $radio = $drv | Where-Object { $_ -match '(?i)(Tipos de radio admitidos|Radio types supported)' } | Select-Object -First 1
        if ($radio) {
            $tipos = ($radio -split ':', 2)[1].Trim()
            Write-DiagLog " - Estandares Wi-Fi soportados: $tipos"
            if ($tipos -match '802\.11ax') { Diag-Ok "Soporta Wi-Fi 6 (802.11ax)." }
            elseif ($tipos -match '802\.11ac') { Write-DiagLog "   Soporta Wi-Fi 5 (802.11ac), banda de 5 GHz." }
            elseif ($tipos -match '802\.11n') { Write-DiagLog "   Solo Wi-Fi 4 (802.11n): velocidad limitada frente a routers modernos." }
        }
        $bandas = $drv | Where-Object { $_ -match '(?i)(Bandas admitidas|Bands? supported)' } | Select-Object -First 1
        if ($bandas) { Write-DiagLog " - $($bandas.Trim())" }
    } catch { }
    try {
        $svc = Get-Service WlanSvc -ErrorAction Stop
        if ($svc.Status -ne 'Running') { Diag-Aviso "El servicio 'Configuracion automatica de WLAN' esta detenido: el Wi-Fi no funcionara." } else { Write-DiagLog " - Servicio WLAN AutoConfig: en ejecucion." }
    } catch { }
}

function Accion-WifiRedes {
    Write-DiagLog "=== WI-FI: REDES CERCANAS Y SATURACION DE CANALES ==="
    try {
        $actual = $null; $canalActual = $null
        $inter = @(netsh wlan show interfaces 2>$null)
        foreach ($l in $inter) {
            if ($l -match '^\s*SSID\s*:\s*(.+)$') { $actual = $Matches[1].Trim() }
            if ($l -match '^\s*(Canal|Channel)\s*:\s*(\d+)') { $canalActual = [int]$Matches[2] }
        }
        $sal = @(netsh wlan show networks mode=bssid 2>$null)
        $redes = New-Object System.Collections.Generic.List[object]
        $ssid = ''; $auth = ''; $cif = ''; $cur = $null
        foreach ($l in $sal) {
            if ($l -match '^\s*SSID\s+\d+\s*:\s*(.*)$') { $ssid = $Matches[1].Trim(); $auth = ''; $cif = ''; continue }
            if ($l -match '^\s*(Autenticaci.n|Authentication)\s*:\s*(.+)$') { $auth = $Matches[2].Trim(); continue }
            if ($l -match '^\s*(Cifrado|Encryption)\s*:\s*(.+)$') { $cif = $Matches[2].Trim(); continue }
            if ($l -match '^\s*BSSID\s+\d+\s*:') { $cur = [PSCustomObject]@{ Ssid = $ssid; Auth = $auth; Cifrado = $cif; Senal = 0; Canal = 0 }; $redes.Add($cur); continue }
            if ($cur -and $l -match '^\s*(Se.al|Signal)\s*:\s*(\d+)\s*%') { $cur.Senal = [int]$Matches[2]; continue }
            if ($cur -and $l -match '^\s*(Canal|Channel)\s*:\s*(\d+)') { $cur.Canal = [int]$Matches[2]; continue }
        }
        if ($redes.Count -eq 0) {
            Write-DiagLog "No se pudieron listar redes. Causas comunes: Wi-Fi apagado, sin adaptador, o Windows sin permiso de ubicacion (Configuracion > Privacidad > Ubicacion)."
            return
        }
        $lista = @($redes | Where-Object { $_.Canal -gt 0 } | Sort-Object Senal -Descending)
        Write-DiagLog " - Puntos de acceso detectados: $($lista.Count) (redes distintas: $(@($lista | Select-Object -ExpandProperty Ssid -Unique).Count))"
        foreach ($r in ($lista | Select-Object -First 12)) {
            $banda = if ($r.Canal -le 14) { '2.4 GHz' } else { '5 GHz' }
            $nom = if ($r.Ssid) { $r.Ssid } else { '(oculta)' }
            $marca = if ($actual -and $r.Ssid -eq $actual) { ' <- tu red' } else { '' }
            Write-DiagLog ("     {0,-26} senal {1,3} %  canal {2,-3} {3,-8} {4}{5}" -f $nom, $r.Senal, $r.Canal, $banda, $r.Auth, $marca)
        }
        if ($canalActual) {
            $mismos = @($lista | Where-Object { $_.Canal -eq $canalActual -and $_.Senal -ge 30 }).Count - 1
            if ($canalActual -le 14) { $solapa = @($lista | Where-Object { $_.Canal -le 14 -and $_.Canal -ne $canalActual -and [math]::Abs($_.Canal - $canalActual) -le 4 -and $_.Senal -ge 30 }).Count } else { $solapa = 0 }
            Write-DiagLog " - Tu red usa el canal ${canalActual}: otras $([math]::Max(0, $mismos)) red(es) fuertes en el mismo canal y $solapa en canales que se solapan."
            if (($mismos + $solapa) -ge 4) { Diag-Aviso "El canal $canalActual esta muy saturado ($($mismos + $solapa) redes interfieren). Cambia el canal del router (en 2.4 GHz usa 1, 6 u 11) o usa la banda de 5 GHz." }
            else { Diag-Ok "El canal de tu red no esta saturado." }
            if ($canalActual -le 14 -and @($lista | Where-Object { $_.Canal -gt 14 }).Count -gt 0) { Write-DiagLog "   Hay redes de 5 GHz disponibles: si el router lo permite, conectate a esa banda para mas velocidad." }
        }
        $inseguras = @($lista | Where-Object { $_.Ssid -eq $actual -and ($_.Auth -match '(?i)abiert|open' -or $_.Cifrado -match '(?i)wep|tkip') } | Select-Object -First 1)
        if ($actual -and $inseguras.Count) { Diag-Aviso "Tu red '$actual' usa seguridad debil ($($inseguras[0].Auth) / $($inseguras[0].Cifrado)). Configura WPA2 o WPA3 con AES en el router." }
    } catch { Write-DiagLog "No se pudo escanear las redes Wi-Fi: $($_.Exception.Message)" }
}

function Global:Medir-PingLista {
    param([string]$Destino, [int]$Tiempo = 1000)
    try {
        $p = New-Object System.Net.NetworkInformation.Ping
        $r = $p.Send($Destino, $Tiempo)
        if ($r.Status -eq 'Success') { return [double]$r.RoundtripTime }
    } catch { }
    return -1.0
}

function Accion-WifiEstabilidad {
    Write-DiagLog "=== WI-FI: ESTABILIDAD, PERDIDA DE PAQUETES Y LATENCIA (20 segundos) ==="
    try {
        $gw = $null
        try { $gw = (Get-NetRoute -DestinationPrefix '0.0.0.0/0' -ErrorAction Stop | Sort-Object RouteMetric | Select-Object -First 1).NextHop } catch { }
        if (-not $gw) { $gw = ((Get-NetIPConfiguration -ErrorAction Stop | Where-Object { $_.IPv4DefaultGateway } | Select-Object -First 1).IPv4DefaultGateway.NextHop) }
        $destinos = @()
        if ($gw) { $destinos += [PSCustomObject]@{ Nombre = "Router ($gw)"; Ip = $gw; Datos = (New-Object System.Collections.Generic.List[double]); Perdidos = 0 } }
        $destinos += [PSCustomObject]@{ Nombre = "Internet (1.1.1.1)"; Ip = '1.1.1.1'; Datos = (New-Object System.Collections.Generic.List[double]); Perdidos = 0 }
        if (-not $gw) { Write-DiagLog "No se encontro la puerta de enlace (router): se mide solo Internet." }
        $n = 20
        for ($i = 1; $i -le $n; $i++) {
            Diag-Progreso -Pct (($i - 1) / $n * 100) -Texto "Enviando paquetes de prueba... ($i/$n)"
            foreach ($d in $destinos) {
                $ms = Medir-PingLista -Destino $d.Ip
                if ($ms -lt 0) { $d.Perdidos++ } else { $d.Datos.Add($ms) }
            }
            Wait-UI -Milisegundos 800
        }
        foreach ($d in $destinos) {
            $perd = [math]::Round(100 * $d.Perdidos / $n, 0)
            if ($d.Datos.Count -eq 0) { Write-DiagLog " - $($d.Nombre): sin respuesta (100 % perdido)"; Diag-Aviso "No hay respuesta de $($d.Nombre)."; continue }
            $arr = $d.Datos.ToArray()
            $prom = [math]::Round(($arr | Measure-Object -Average).Average, 1)
            $max = [math]::Round(($arr | Measure-Object -Maximum).Maximum, 0)
            $min = [math]::Round(($arr | Measure-Object -Minimum).Minimum, 0)
            $jit = 0.0
            if ($arr.Length -gt 1) { $s = 0.0; for ($k = 1; $k -lt $arr.Length; $k++) { $s += [math]::Abs($arr[$k] - $arr[$k - 1]) }; $jit = [math]::Round($s / ($arr.Length - 1), 1) }
            Write-DiagLog " - $($d.Nombre): perdidos $perd % | latencia min/prom/max: $min / $prom / $max ms | variacion (jitter): $jit ms"
            if ($perd -ge 5) { Diag-Aviso "Perdida de paquetes del $perd % hacia $($d.Nombre): conexion inestable (señal, interferencia o cable)." }
            elseif ($perd -gt 0) { Write-DiagLog "   Perdida minima ($perd %): aceptable." }
            if ($d.Nombre -like 'Router*') {
                if ($prom -gt 30) { Diag-Aviso "Latencia alta hacia el router ($prom ms): Wi-Fi congestionado o señal debil." }
                elseif ($perd -lt 5) { Diag-Ok "Conexion con el router estable ($prom ms)." }
            } else {
                if ($prom -gt 120) { Diag-Aviso "Latencia alta hacia Internet ($prom ms)." }
                elseif ($perd -lt 5) { Diag-Ok "Conexion a Internet estable ($prom ms)." }
            }
            if ($jit -gt 40) { Diag-Aviso "Variacion de latencia alta ($jit ms): se notara en videollamadas y juegos." }
        }
        try {
            $cron = [System.Diagnostics.Stopwatch]::StartNew()
            [void][System.Net.Dns]::GetHostAddresses('www.microsoft.com')
            $cron.Stop()
            Write-DiagLog " - Resolucion DNS: $([math]::Round($cron.Elapsed.TotalMilliseconds, 0)) ms"
            if ($cron.Elapsed.TotalMilliseconds -gt 500) { Diag-Aviso "El DNS tarda $([math]::Round($cron.Elapsed.TotalMilliseconds, 0)) ms: las paginas tardan en abrir. Prueba DNS 1.1.1.1 o 8.8.8.8." }
        } catch { Diag-Aviso "No se pudo resolver un nombre de dominio (DNS): revisa la conexion o el DNS configurado." }
    } catch { Write-DiagLog "No se pudo completar la prueba de estabilidad: $($_.Exception.Message)" }
}

function Accion-WifiSeguridadEventos {
    Write-DiagLog "=== WI-FI: SEGURIDAD DE LA CONEXION Y DESCONEXIONES (7 dias) ==="
    try {
        $inter = @(netsh wlan show interfaces 2>$null)
        $auth = ''; $cif = ''; $ssid = ''
        foreach ($l in $inter) {
            if ($l -match '^\s*SSID\s*:\s*(.+)$') { $ssid = $Matches[1].Trim() }
            if ($l -match '^\s*(Autenticaci.n|Authentication)\s*:\s*(.+)$') { $auth = $Matches[2].Trim() }
            if ($l -match '^\s*(Cifrado|Cipher)\s*:\s*(.+)$') { $cif = $Matches[2].Trim() }
        }
        if ($ssid) {
            Write-DiagLog " - Red conectada: $ssid | Autenticacion: $auth | Cifrado: $cif"
            if ($auth -match '(?i)abiert|open' -or $cif -match '(?i)wep|none|ning') { Diag-Aviso "La red '$ssid' no esta protegida o usa cifrado debil. Usa WPA2/WPA3." }
            elseif ($auth -match '(?i)WPA3') { Diag-Ok "Seguridad excelente (WPA3)." }
            elseif ($auth -match '(?i)WPA2') { Diag-Ok "Seguridad correcta (WPA2)." }
            elseif ($auth -match '(?i)WPA\b') { Diag-Aviso "La red usa WPA (antiguo). Cambia a WPA2/WPA3 en el router." }
        } else { Write-DiagLog " - No hay una red Wi-Fi conectada ahora mismo." }
    } catch { }
    try {
        $perf = @(netsh wlan show profiles 2>$null | Where-Object { $_ -match ':\s*\S' -and $_ -match '(?i)perfil|profile' })
        if ($perf.Count) { Write-DiagLog " - Redes guardadas en el equipo: $($perf.Count)" }
    } catch { }
    try {
        $ev = @(Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-WLAN-AutoConfig/Operational'; Id = 8001, 8002, 8003, 11006; StartTime = (Get-Date).AddDays(-7) } -ErrorAction Stop)
        $con = @($ev | Where-Object { $_.Id -eq 8001 }).Count
        $fallos = @($ev | Where-Object { $_.Id -in 8002, 11006 })
        $desc = @($ev | Where-Object { $_.Id -eq 8003 }).Count
        Write-DiagLog " - Ultimos 7 dias: conexiones $con | desconexiones $desc | intentos fallidos $($fallos.Count)"
        foreach ($f in ($fallos | Select-Object -First 3)) {
            $m = ("$($f.Message)" -split "`n")[0].Trim()
            Write-DiagLog "     $($f.TimeCreated.ToString('yyyy-MM-dd HH:mm')): $m"
        }
        if ($desc -ge 30) { Diag-Aviso "Hay $desc desconexiones Wi-Fi en 7 dias: el adaptador, el driver o la señal fallan con frecuencia." }
        elseif ($fallos.Count -ge 5) { Diag-Aviso "Hay $($fallos.Count) intentos de conexion fallidos en 7 dias: revisa la clave, el router o el driver." }
        else { Diag-Ok "Pocas desconexiones o fallos de Wi-Fi en los ultimos 7 dias." }
    } catch { Write-DiagLog " - No hay registro de eventos Wi-Fi disponible (registro desactivado o sin permisos)." }
}

# ---------------------------- Mouse / touchpad ----------------------------

function Accion-MouseDispositivos {
    Write-DiagLog "=== MOUSE / TOUCHPAD: DISPOSITIVOS Y AJUSTES ==="
    $hayTouch = $false
    try {
        $dev = @(Get-CimInstance Win32_PointingDevice -ErrorAction Stop)
        if ($dev.Count -eq 0) { Write-DiagLog "Windows no detecta ningun dispositivo señalador." }
        foreach ($d in $dev) {
            $esTouch = ("$($d.Name) $($d.Description)" -match '(?i)touch|synaptics|elan|trackpad|precision|clickpad')
            if ($esTouch) { $hayTouch = $true }
            $tipo = if ($esTouch) { 'Touchpad' } else { 'Mouse' }
            Write-DiagLog " - [$tipo] $($d.Name) | Fabricante: $($d.Manufacturer) | Botones: $($d.NumberOfButtons) | Estado: $($d.Status)"
            if ([int]$d.ConfigManagerErrorCode -ne 0) { Diag-Aviso "'$($d.Name)' tiene un problema en el Administrador de dispositivos (codigo $($d.ConfigManagerErrorCode)). Reinstala o actualiza su controlador." }
            else { Diag-Ok "$tipo '$($d.Name)' funciona correctamente segun Windows." }
            try {
                $id = ("$($d.PNPDeviceID)").Replace('\', '\\')
                $drv = Get-CimInstance Win32_PnPSignedDriver -Filter "DeviceID='$id'" -ErrorAction Stop | Select-Object -First 1
                if ($drv) {
                    $fd = $null; try { $fd = [datetime]$drv.DriverDate } catch { }
                    Write-DiagLog "     Driver: $($drv.DriverVersion) | Fecha: $(if ($fd) { $fd.ToString('yyyy-MM-dd') } else { 'desconocida' }) | $($drv.DriverProviderName)"
                }
            } catch { }
        }
        if (-not $hayTouch) { Write-DiagLog " - No se detecto touchpad (equipo de escritorio o solo mouse externo)." }
    } catch { Write-DiagLog "No se pudo consultar los dispositivos señaladores: $($_.Exception.Message)" }
    try {
        if (Test-Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\PrecisionTouchPad') { Write-DiagLog " - Touchpad de precision de Windows: configuracion presente." }
    } catch { }
    try {
        $m = Get-ItemProperty 'HKCU:\Control Panel\Mouse' -ErrorAction Stop
        $vel = [int]$m.MouseSensitivity
        Write-DiagLog " - Velocidad del puntero: $vel/20 | Doble clic: $($m.DoubleClickSpeed) ms | Precision del puntero mejorada: $(if ("$($m.MouseSpeed)" -ne '0') { 'si' } else { 'no' }) | Lineas por rueda: $([System.Windows.SystemParameters]::WheelScrollLines)"
        if ("$($m.SwapMouseButtons)" -eq '1') { Write-DiagLog "   Los botones izquierdo y derecho estan invertidos (normal si el usuario es zurdo; si no, cambialo en Configuracion > Mouse)." }
        if ($vel -le 3 -or $vel -ge 19) { Write-DiagLog "   La velocidad del puntero esta en un extremo: puede sentirse muy lento o impreciso." }
    } catch { }
    try {
        $prob = @(Get-PnpDevice -Class Mouse, HIDClass -ErrorAction Stop | Where-Object { $_.Status -in 'Error', 'Degraded', 'Unknown' -and $_.FriendlyName -match '(?i)mouse|touch|pointer|hid-compliant' })
        foreach ($p in ($prob | Select-Object -First 4)) { Diag-Aviso "Dispositivo '$($p.FriendlyName)' con estado $($p.Status) en Windows." }
    } catch { }
}

function Global:Marcar-PruebaMouse {
    param([string]$Clave)
    try {
        if (-not $Global:_pmEstado) { return }
        if ($Global:_pmEstado.ContainsKey($Clave)) {
            $Global:_pmEstado[$Clave] = $true
            $tb = $Global:_pmUi[$Clave]
            if ($tb) { $tb.Text = "✔ " + $tb.Tag; $tb.Foreground = [System.Windows.Media.Brushes]::LimeGreen }
        }
    } catch { }
}

function Show-PruebaBotonesMouse {
    Write-DiagLog "=== MOUSE / TOUCHPAD: PRUEBA DE BOTONES Y GESTOS ==="
    try {
        [xml]$xamlBm = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Prueba de botones del mouse/touchpad - The Dragon Tool" Height="560" Width="760" WindowStartupLocation="CenterScreen" Background="#10141D">
  <Window.Resources>$($Global:RecursosNeonXaml)</Window.Resources>
  <DockPanel Margin="14">
    <Button x:Name="BtnVolverVentana" DockPanel.Dock="Top" Content="⬅  Volver" Width="110" Height="34" HorizontalAlignment="Left" Margin="0,0,0,10"/>
    <TextBlock DockPanel.Dock="Top" Text="Realiza cada accion dentro del recuadro azul. Cada prueba se marca con ✔ al detectarla." Foreground="White" TextWrapping="Wrap" Margin="0,0,0,8"/>
    <StackPanel DockPanel.Dock="Bottom" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,10,0,0">
      <Button x:Name="BtnFinBm" Content="Terminar y guardar resultado" Width="220"/>
    </StackPanel>
    <UniformGrid DockPanel.Dock="Right" Columns="1" Width="250" Margin="12,0,0,0">
      <TextBlock x:Name="CkIzq" Foreground="#8FA3C7" FontSize="14" VerticalAlignment="Center"/>
      <TextBlock x:Name="CkDer" Foreground="#8FA3C7" FontSize="14" VerticalAlignment="Center"/>
      <TextBlock x:Name="CkMed" Foreground="#8FA3C7" FontSize="14" VerticalAlignment="Center"/>
      <TextBlock x:Name="CkDoble" Foreground="#8FA3C7" FontSize="14" VerticalAlignment="Center"/>
      <TextBlock x:Name="CkArrastre" Foreground="#8FA3C7" FontSize="14" VerticalAlignment="Center"/>
      <TextBlock x:Name="CkArriba" Foreground="#8FA3C7" FontSize="14" VerticalAlignment="Center"/>
      <TextBlock x:Name="CkAbajo" Foreground="#8FA3C7" FontSize="14" VerticalAlignment="Center"/>
      <TextBlock x:Name="CkZoom" Foreground="#8FA3C7" FontSize="14" VerticalAlignment="Center"/>
    </UniformGrid>
    <Border x:Name="ZonaBm" BorderBrush="#2F7CF6" BorderThickness="2" CornerRadius="12" Background="#151B27">
      <TextBlock x:Name="TxtZonaBm" Text="Zona de prueba&#10;(clic izquierdo, derecho, medio, doble clic, arrastrar, rueda, Ctrl + rueda / pellizco)" Foreground="#4C6595" FontSize="16" TextAlignment="Center" TextWrapping="Wrap" VerticalAlignment="Center" HorizontalAlignment="Center" IsHitTestVisible="False" Margin="20"/>
    </Border>
  </DockPanel>
</Window>
"@
        $readerBm = New-Object System.Xml.XmlNodeReader $xamlBm
        $winBm = [Windows.Markup.XamlReader]::Load($readerBm)
        Iniciar-EfectosNeon -Ventana $winBm
        $etq = [ordered]@{ Izq = 'Clic izquierdo'; Der = 'Clic derecho'; Med = 'Clic medio (rueda)'; Doble = 'Doble clic'; Arrastre = 'Arrastrar con clic sostenido'; Arriba = 'Rueda / 2 dedos hacia arriba'; Abajo = 'Rueda / 2 dedos hacia abajo'; Zoom = 'Ctrl + rueda (pellizco)' }
        $Global:_pmEstado = @{}; $Global:_pmUi = @{}; $Global:_pmDown = $null
        foreach ($k in $etq.Keys) {
            $tb = $winBm.FindName("Ck$k")
            $tb.Tag = $etq[$k]; $tb.Text = "○ " + $etq[$k]
            $Global:_pmEstado[$k] = $false; $Global:_pmUi[$k] = $tb
        }
        $zona = $winBm.FindName("ZonaBm")
        $zona.Add_MouseLeftButtonDown({ param($s, $e) Marcar-PruebaMouse 'Izq'; if ($e.ClickCount -ge 2) { Marcar-PruebaMouse 'Doble' }; $Global:_pmDown = $e.GetPosition($s) })
        $zona.Add_MouseLeftButtonUp({ $Global:_pmDown = $null })
        $zona.Add_MouseRightButtonDown({ Marcar-PruebaMouse 'Der' })
        $zona.Add_MouseDown({ param($s, $e) if ($e.ChangedButton -eq [System.Windows.Input.MouseButton]::Middle) { Marcar-PruebaMouse 'Med' } })
        $zona.Add_MouseMove({
            param($s, $e)
            if ($e.LeftButton -eq [System.Windows.Input.MouseButtonState]::Pressed -and $Global:_pmDown) {
                $p = $e.GetPosition($s)
                if (([math]::Abs($p.X - $Global:_pmDown.X) + [math]::Abs($p.Y - $Global:_pmDown.Y)) -gt 80) { Marcar-PruebaMouse 'Arrastre' }
            }
        })
        $zona.Add_MouseWheel({
            param($s, $e)
            if ([System.Windows.Input.Keyboard]::Modifiers -band [System.Windows.Input.ModifierKeys]::Control) { Marcar-PruebaMouse 'Zoom' }
            elseif ($e.Delta -gt 0) { Marcar-PruebaMouse 'Arriba' } else { Marcar-PruebaMouse 'Abajo' }
        })
        $winBm.FindName("BtnFinBm").Add_Click({ $winBm.Close() })
        $winBm.ShowDialog() | Out-Null
        $hechos = @($Global:_pmEstado.Keys | Where-Object { $Global:_pmEstado[$_] })
        $faltan = @($Global:_pmEstado.Keys | Where-Object { -not $Global:_pmEstado[$_] })
        foreach ($k in $etq.Keys) {
            if ($Global:_pmEstado[$k]) { Diag-Ok "$($etq[$k]): funciona." }
        }
        foreach ($k in $faltan) {
            if ($k -in 'Izq', 'Der') { Diag-Aviso "$($etq[$k]) no respondio durante la prueba: el boton o el touchpad puede estar fallando." }
            else { Write-DiagLog "   - $($etq[$k]): no se detecto durante la prueba (no probado o no responde)." }
        }
        Write-DiagLog "Prueba de botones finalizada: $($hechos.Count) de $($etq.Count) acciones detectadas."
    } catch { Write-DiagLog "No se pudo abrir la prueba de botones: $($_.Exception.Message)" }
}

function Global:Nueva-RondaPrecision {
    try {
        $c = $Global:_ppCanvas
        $w = [double]$c.ActualWidth; $h = [double]$c.ActualHeight
        if ($w -lt 120) { $w = 600 }; if ($h -lt 120) { $h = 320 }
        $r = $Global:_ppRadio
        $x = $r + $Global:_ppRnd.NextDouble() * ($w - 2 * $r)
        $y = $r + $Global:_ppRnd.NextDouble() * ($h - 2 * $r)
        $Global:_ppObj.Width = 2 * $r; $Global:_ppObj.Height = 2 * $r
        [System.Windows.Controls.Canvas]::SetLeft($Global:_ppObj, $x - $r)
        [System.Windows.Controls.Canvas]::SetTop($Global:_ppObj, $y - $r)
        $Global:_ppCentro = New-Object System.Windows.Point($x, $y)
        $Global:_ppObj.Visibility = 'Visible'
        $Global:_ppTxt.Text = "Objetivo $($Global:_ppRonda) de $($Global:_ppTotal)  |  Aciertos: $($Global:_ppAciertos)  |  Fallos: $($Global:_ppFallos)"
        $Global:_ppCron.Restart()
    } catch { }
}

function Show-PruebaPrecisionMouse {
    Write-DiagLog "=== MOUSE / TOUCHPAD: PRUEBA DE PRECISION Y RESPUESTA ==="
    try {
        [xml]$xamlPp = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Prueba de precision del puntero - The Dragon Tool" Height="560" Width="760" WindowStartupLocation="CenterScreen" Background="#10141D">
  <Window.Resources>$($Global:RecursosNeonXaml)</Window.Resources>
  <DockPanel Margin="14">
    <Button x:Name="BtnVolverVentana" DockPanel.Dock="Top" Content="⬅  Volver" Width="110" Height="34" HorizontalAlignment="Left" Margin="0,0,0,10"/>
    <TextBlock DockPanel.Dock="Top" Text="Haz clic en el circulo verde cada vez que aparezca, lo mas rapido y centrado que puedas (12 objetivos)." Foreground="White" TextWrapping="Wrap" Margin="0,0,0,6"/>
    <TextBlock x:Name="TxtPp" DockPanel.Dock="Top" Foreground="#66AEFF" FontWeight="Bold" Margin="0,0,0,8" Text="Preparando..."/>
    <Border BorderBrush="#2F7CF6" BorderThickness="2" CornerRadius="12" Background="#151B27">
      <Canvas x:Name="CanvasPp" Background="Transparent" ClipToBounds="True"/>
    </Border>
  </DockPanel>
</Window>
"@
        $readerPp = New-Object System.Xml.XmlNodeReader $xamlPp
        $winPp = [Windows.Markup.XamlReader]::Load($readerPp)
        Iniciar-EfectosNeon -Ventana $winPp
        $canvas = $winPp.FindName("CanvasPp")
        $Global:_ppCanvas = $canvas; $Global:_ppTxt = $winPp.FindName("TxtPp")
        $Global:_ppRnd = New-Object System.Random
        $Global:_ppRadio = 24.0; $Global:_ppTotal = 12; $Global:_ppRonda = 1; $Global:_ppAciertos = 0; $Global:_ppFallos = 0
        $Global:_ppTiempos = New-Object System.Collections.Generic.List[double]
        $Global:_ppDistancias = New-Object System.Collections.Generic.List[double]
        $Global:_ppCron = New-Object System.Diagnostics.Stopwatch
        $obj = New-Object System.Windows.Shapes.Ellipse
        $obj.Fill = [System.Windows.Media.Brushes]::LimeGreen
        $obj.Stroke = [System.Windows.Media.Brushes]::White; $obj.StrokeThickness = 2
        $obj.Visibility = 'Collapsed'
        [void]$canvas.Children.Add($obj)
        $Global:_ppObj = $obj
        $canvas.Add_MouseLeftButtonDown({
            param($s, $e)
            if (-not $Global:_ppCron.IsRunning) { return }
            $p = $e.GetPosition($Global:_ppCanvas)
            $d = [math]::Sqrt([math]::Pow($p.X - $Global:_ppCentro.X, 2) + [math]::Pow($p.Y - $Global:_ppCentro.Y, 2))
            if ($d -le $Global:_ppRadio) {
                $Global:_ppAciertos++
                $Global:_ppTiempos.Add($Global:_ppCron.Elapsed.TotalSeconds)
                $Global:_ppDistancias.Add($d)
                $Global:_ppRonda++
                if ($Global:_ppRonda -gt $Global:_ppTotal) { $Global:_ppCron.Stop(); $Global:_ppObj.Visibility = 'Collapsed'; $Global:_ppTxt.Text = "Prueba completada. Cierra la ventana para ver el resultado."; $Global:_ppVentana.Close() }
                else { Nueva-RondaPrecision }
            } else {
                $Global:_ppFallos++
                $Global:_ppTxt.Text = "Objetivo $($Global:_ppRonda) de $($Global:_ppTotal)  |  Aciertos: $($Global:_ppAciertos)  |  Fallos: $($Global:_ppFallos)"
            }
        })
        $Global:_ppVentana = $winPp
        $winPp.Add_ContentRendered({ Nueva-RondaPrecision })
        $winPp.ShowDialog() | Out-Null
        if ($Global:_ppAciertos -eq 0) { Write-DiagLog "Prueba de precision cancelada sin aciertos."; return }
        $tp = [math]::Round(($Global:_ppTiempos | Measure-Object -Average).Average, 2)
        $dp = [math]::Round(($Global:_ppDistancias | Measure-Object -Average).Average, 1)
        Write-DiagLog " - Aciertos: $($Global:_ppAciertos) de $($Global:_ppTotal) | Fallos (clics fuera del objetivo): $($Global:_ppFallos)"
        Write-DiagLog " - Tiempo promedio por objetivo: $tp s | Distancia media al centro: $dp px"
        if ($Global:_ppAciertos -lt $Global:_ppTotal) { Write-DiagLog "   (Prueba terminada antes de completar los $($Global:_ppTotal) objetivos.)" }
        if ($Global:_ppFallos -ge 5) { Diag-Aviso "Hubo $($Global:_ppFallos) clics fuera del objetivo: el puntero puede ser impreciso o saltar (limpia el sensor/touchpad y revisa el driver)." }
        else { Diag-Ok "Precision del puntero correcta ($($Global:_ppFallos) fallo(s))." }
        if ($tp -gt 2.5) { Write-DiagLog "   El tiempo promedio es alto: puede deberse a un puntero lento o a poca costumbre con el touchpad." }
    } catch { Write-DiagLog "No se pudo abrir la prueba de precision: $($_.Exception.Message)" }
}

# Ejecuta un paso del diagnostico completo sin que un fallo en uno detenga todos los demas
function Global:Diag-Paso {
    param([string]$Nombre, [scriptblock]$Bloque)
    try { & $Bloque } catch {
        Write-DiagLog "   ⚠ ATENCION: no se pudo completar el paso '$Nombre': $($_.Exception.Message)"
        $Script:DiagAdvertencias++
        if ($Global:DiagStats) { $Global:DiagStats.Aviso++ }
    }
}

function Accion-DiagnosticoCompletoEquipo {
    $Script:DiagAdvertencias = 0
    Write-DiagLog "========================================"
    Write-DiagLog "   DIAGNOSTICO COMPLETO DEL EQUIPO"
    Write-DiagLog "========================================"
    Diag-Progreso -Pct 0 -Texto 'Paso 1 de 26: Informacion del hardware'
    Diag-Paso -Nombre 'Accion-InfoHardwareCompleta' -Bloque { Accion-InfoHardwareCompleta }
    Diag-Progreso -Pct 3 -Texto 'Paso 2 de 26: Tarjeta grafica'
    Diag-Paso -Nombre 'Accion-ProbarGraficaDiag' -Bloque { Accion-ProbarGraficaDiag }
    Diag-Progreso -Pct 7 -Texto 'Paso 3 de 26: Detalles de pantalla'
    Diag-Paso -Nombre 'Accion-VerDetallesPantalla' -Bloque { Accion-VerDetallesPantalla }
    Diag-Progreso -Pct 11 -Texto 'Paso 4 de 26: Salud del almacenamiento'
    Diag-Paso -Nombre 'Accion-ProbarAlmacenamiento' -Bloque { Accion-ProbarAlmacenamiento }
    Diag-Progreso -Pct 15 -Texto 'Paso 5 de 26: Detalle fisico del disco'
    Diag-Paso -Nombre 'Accion-DiscoDetalleFisico' -Bloque { Accion-DiscoDetalleFisico }
    Diag-Progreso -Pct 19 -Texto 'Paso 6 de 26: Particiones'
    Diag-Paso -Nombre 'Accion-DiscoParticiones' -Bloque { Accion-DiscoParticiones }
    Diag-Progreso -Pct 23 -Texto 'Paso 7 de 26: Atributos S.M.A.R.T.'
    Diag-Paso -Nombre 'Accion-DiscoSmartAtributos' -Bloque { Accion-DiscoSmartAtributos }
    Diag-Progreso -Pct 26 -Texto 'Paso 8 de 26: Eventos de disco'
